const LINUX_PATH_MAX: u64 = 4096;
const LINUX_SYMLINK_TARGET_MAX: u64 = LINUX_PATH_MAX - 1;
const BTRFS_COMPRESSED_EXTENT_BYTE_LIMIT: usize = 128 * 1024 * 1024;
/// btrfs LZO segment framing aligns segment headers to the filesystem sector
/// size (kernel `fs/btrfs/lzo.c`). FrankenFS assumes the default 4 KiB sector
/// (the same assumption already baked into the per-segment output cap).
const BTRFS_LZO_SECTOR_SIZE: usize = 4096;
thread_local! {
    static BTRFS_ZSTD_DECOMPRESSOR: std::cell::RefCell<Option<zstd::bulk::Decompressor<'static>>> =
        const { std::cell::RefCell::new(None) };
    // Per-thread reusable zlib inflate context (bd-4tw2n sibling), shared by BOTH
    // deflate readers — btrfs `compress=zlib` extents and ext4 e2compr gzip
    // clusters — so the ~32 KiB inflate window is allocated + zeroed once per
    // worker instead of once per extent/cluster (as the fresh `ZlibDecoder::new`
    // per call did, and as the zstd arm did before its own thread-local reuse).
    static ZLIB_INFLATE_CTX: std::cell::RefCell<Option<flate2::Decompress>> =
        const { std::cell::RefCell::new(None) };
    // Per-thread reusable zlib DEFLATE context for e2compr gzip WRITES, keyed by
    // compression level (e2compr methods map to fixed levels). Reusing it avoids
    // allocating the deflate state (window + hash chains, larger than the inflate
    // window) per cluster. Byte-identical to a fresh `ZlibEncoder` at the same
    // level (bench `zlib_encode_reuse_4k` asserts it), so on-disk bytes are unchanged.
    static ZLIB_DEFLATE_CTX: std::cell::RefCell<Option<(u32, flate2::Compress)>> =
        const { std::cell::RefCell::new(None) };
}

