    /// Encode a `name_to_handle_at(2)`-style file handle for `ino`.
    ///
    /// Returns the `file_handle::FILE_HANDLE_LEN`-byte handle that pairs
    /// the inode number with its current NFS generation cookie. A future
    /// [`Self::open_by_handle`] call will reject the handle with `ESTALE`
    /// if the inode has since been freed and reused (its generation will
    /// have been bumped).
    pub fn encode_file_handle(
        &self,
        cx: &Cx,
        ino: InodeNumber,
    ) -> ffs_error::Result<[u8; file_handle::FILE_HANDLE_LEN]> {
        let attr = self.getattr(cx, ino)?;
        let generation = u32::try_from(attr.generation).unwrap_or(u32::MAX);
        Ok(file_handle::encode(attr.ino, generation))
    }

    /// Resolve a previously-issued file handle, returning the inode's
    /// current attributes.
    ///
    /// Returns [`FfsError::Io`] with `EINVAL` if the buffer is the wrong
    /// length, `ESTALE` if the inode's generation has moved on, or
    /// propagates the underlying lookup error if the inode has been
    /// freed entirely.
    pub fn open_by_handle(&self, cx: &Cx, handle: &[u8]) -> ffs_error::Result<InodeAttr> {
        let (ino, handle_gen) = file_handle::decode(handle).map_err(FfsError::from)?;
        let attr = self.getattr(cx, ino)?;
        let live_gen = u32::try_from(attr.generation).unwrap_or(u32::MAX);
        file_handle::verify(ino, handle_gen, live_gen).map_err(FfsError::from)?;
        Ok(attr)
    }

    pub fn fallocate(
        &self,
        cx: &Cx,
        ino: InodeNumber,
        offset: u64,
        length: u64,
        mode: i32,
    ) -> ffs_error::Result<()> {
        self.handle_ext4_write_result(
            "fallocate",
            self.with_latest_scope(|scope| {
                <Self as FsOps>::fallocate(self, cx, scope, ino, offset, length, mode)
            }),
        )
    }

    /// Flush ALL committed MVCC block versions to the underlying image device,
    /// making everything written this session durable on disk — the persist step
    /// a real mount performs at sync/umount. Without this, writes and creates
    /// committed to the in-memory MVCC overlay are lost on close (a re-open or
    /// kernel mount sees nothing), so a benchmark/tool that needs a PERSISTED,
    /// kernel-comparable result must call it after its mutations. Read-only
    /// mounts return `ReadOnly`.
    pub fn sync_all_to_device(&self, cx: &Cx) -> ffs_error::Result<()> {
        if !self.is_writable() {
            return Err(FfsError::ReadOnly);
        }
        let base_dev = self.direct_block_device_adapter();
        self.flush_mvcc_versions_to_device(cx, &base_dev)?;
        self.clear_ext4_writable_group_desc_cache();
        // When GDT persistence is deferred (bd-cc-gdt-defer), write every group
        // descriptor here from the authoritative in-memory GroupStats — the
        // per-op GDT write was skipped to avoid the ~80k version-chain on the
        // one shared GDT block (~2.3x create). Must run on THIS path too:
        // sync_all_to_device is the CLI / create-bench durability boundary.
        self.ext4_flush_group_descriptors(cx)?;
        // Sync the superblock free-block/free-inode TOTALS from the in-memory
        // alloc state so a device snapshot is e2fsck-consistent (bd-wvud1): the
        // per-group descriptors + bitmaps are kept current during writes, but
        // nothing updates the superblock totals s_free_blocks_count /
        // s_free_inodes_count on this flush path. `flush_mvcc_to_device` already
        // does this; `sync_all_to_device` (the CLI / create-bench durability
        // boundary) omitted it, leaving every persisted image reporting
        // "Free inodes count wrong" off by exactly the number of created files.
        // No-op for btrfs / read-only ext4.
        self.ext4_sync_superblock_free_totals(cx)?;
        Ok(())
    }

