    /// Build a minimal Ext4Superblock for unit tests.
    fn make_test_superblock() -> Ext4Superblock {
        let mut sb_buf = vec![0_u8; EXT4_SUPERBLOCK_SIZE];
        sb_buf[0x38..0x3A].copy_from_slice(&EXT4_SUPER_MAGIC.to_le_bytes());
        sb_buf[0x18..0x1C].copy_from_slice(&2_u32.to_le_bytes()); // log_block_size=2 → 4K
        sb_buf[0x00..0x04].copy_from_slice(&1024_u32.to_le_bytes()); // inodes_count
        sb_buf[0x04..0x08].copy_from_slice(&4096_u32.to_le_bytes()); // blocks_count
        sb_buf[0x20..0x24].copy_from_slice(&4096_u32.to_le_bytes()); // blocks_per_group
        sb_buf[0x28..0x2C].copy_from_slice(&1024_u32.to_le_bytes()); // inodes_per_group
        sb_buf[0x58..0x5A].copy_from_slice(&256_u16.to_le_bytes()); // inode_size
        Ext4Superblock::parse_superblock_region(&sb_buf).expect("test superblock")
    }

    /// Build a minimal inode buffer with mode and device encoding in i_block.
    fn make_test_inode(mode: u16, block0: u32, block1: u32) -> Ext4Inode {
        let mut buf = [0_u8; 128];
        buf[0x00..0x02].copy_from_slice(&mode.to_le_bytes());
        buf[0x28..0x2C].copy_from_slice(&block0.to_le_bytes());
        buf[0x2C..0x30].copy_from_slice(&block1.to_le_bytes());
        Ext4Inode::parse_from_bytes(&buf).expect("test inode")
    }

    /// bd-j6ljg: a stamped inode's extent-cache namespace is STABLE across
    /// extent-tree mutation (the drift the old content hash suffered), is exact
    /// per inode, and disambiguates inode-number reuse via the generation. An
    /// unstamped inode (number == 0) falls back to the content hash.
    #[test]
    fn extent_cache_namespace_stable_for_stamped_inode_bd_j6ljg() {
        let mut inode = make_test_inode(0o100_644, 0, 0);
        inode.number = 42;
        inode.generation = 7;

        let ns = extent_cache_namespace(&inode);

        // Mutating the extent root bytes must NOT shift the namespace — this is
        // exactly the drift that orphaned cached entries under the old scheme.
        let mut mutated = inode.clone();
        mutated.extent_bytes.push(0xAB);
        if let Some(first) = mutated.extent_bytes.first_mut() {
            *first ^= 0xFF;
        }
        assert_eq!(
            ns,
            extent_cache_namespace(&mutated),
            "stable key drifted on extent mutation"
        );

        // Distinct inode number → distinct namespace (exact per-inode scoping).
        let mut other = inode.clone();
        other.number = 43;
        assert_ne!(ns, extent_cache_namespace(&other));

        // Same number, bumped generation (free + realloc) → distinct namespace.
        let mut reborn = inode.clone();
        reborn.generation = 8;
        assert_ne!(ns, extent_cache_namespace(&reborn));

        // Unstamped inode uses the content-hash fallback (preserves old behavior).
        let mut unstamped = inode.clone();
        unstamped.number = 0;
        assert_eq!(
            extent_cache_namespace(&unstamped),
            extent_root_namespace(&unstamped)
        );
    }

    /// A truncate-down now clears only the truncated inode's extent-cache
    /// namespace (safe with the stable (ino,generation) key, bd-j6ljg) instead
    /// of nuking the whole cache, so a DIFFERENT inode's cached extent mapping
    /// stays warm across the free. Single-inode correctness is covered by the
    /// random write/truncate proptests; this pins the warmth property.
    #[test]
    fn ext4_truncate_keeps_other_inode_extent_cache_warm() {
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let a = fs
            .create(&cx, root, OsStr::new("keep.bin"), 0o644, 0, 0)
            .expect("create A");
        fs.write(&cx, a.ino, 0, &vec![0xA1_u8; 8192])
            .expect("write A");
        let b = fs
            .create(&cx, root, OsStr::new("drop.bin"), 0o644, 0, 0)
            .expect("create B");
        fs.write(&cx, b.ino, 0, &vec![0xB2_u8; 8192])
            .expect("write B");

        // Warm A's extent mapping into the cache by reading it back.
        let _ = fs.read(&cx, a.ino, 0, 8192).expect("read A");
        assert!(
            fs.extent_cache_stats().entries > 0,
            "reading A must cache its extent mapping"
        );

        // Truncate B to zero (frees B's blocks). The scoped invalidation must
        // NOT evict A's cached mapping — the old invalidate_all dropped the
        // whole cache here.
        fs.setattr(
            &cx,
            b.ino,
            &SetAttrRequest {
                size: Some(0),
                ..Default::default()
            },
        )
        .expect("truncate B to zero");
        assert!(
            fs.extent_cache_stats().entries > 0,
            "truncating B must keep A's cached extent mapping warm"
        );

        // A's data stays intact (the scoped invalidation introduces no staleness).
        let a_data = fs.read(&cx, a.ino, 0, 8192).expect("re-read A");
        assert!(
            a_data.iter().all(|&x| x == 0xA1),
            "A's data must be intact after B's truncate"
        );
    }

    /// Exercises the legacy ext4 indirect-block addressing
    /// (`resolve_indirect_block`) across all three indirection levels plus
    /// sparse (zero-pointer) holes. This untrusted-input read path had no
    /// direct test coverage; the build helper only produces extent-mapped
    /// inodes. Pointer blocks are crafted at small block numbers and the
    /// logical block is set past each level's threshold, so no large file
    /// needs to be materialised.
    #[test]
    fn resolve_indirect_block_single_double_triple_levels() {
        const BS: usize = 4096;
        const PPB: u32 = 1024; // pointers per 4K block

        let mut image = build_ext4_image_with_extents();
        // Write a u32 pointer at slot `idx` within block `blk` (blocks 20..=32
        // are free in the 64-block image; 0..=4 and 13 are in use).
        let put = |image: &mut [u8], blk: u32, idx: u32, val: u32| {
            let off = blk as usize * BS + idx as usize * 4;
            image[off..off + 4].copy_from_slice(&val.to_le_bytes());
        };
        // Single indirect: ind block 20, slot 0 → data block 30.
        put(&mut image, 20, 0, 30);
        // Double indirect: dind 21[0] → ind 22; ind 22[0] → data 31.
        put(&mut image, 21, 0, 22);
        put(&mut image, 22, 0, 31);
        // Triple indirect: tind 23[0] → dind 24; dind 24[0] → ind 25; ind 25[0] → data 32.
        put(&mut image, 23, 0, 24);
        put(&mut image, 24, 0, 25);
        put(&mut image, 25, 0, 32);

        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(image)),
            &OpenOptions::default(),
        )
        .expect("open crafted ext4 image");
        let scope = RequestScope::empty();

        // Non-extent inode: 15 u32 pointers, with the indirect roots set.
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        let mut ptrs = vec![0_u8; 15 * 4];
        ptrs[12 * 4..12 * 4 + 4].copy_from_slice(&20_u32.to_le_bytes()); // i_block[12] = single
        ptrs[13 * 4..13 * 4 + 4].copy_from_slice(&21_u32.to_le_bytes()); // i_block[13] = double
        ptrs[14 * 4..14 * 4 + 4].copy_from_slice(&23_u32.to_le_bytes()); // i_block[14] = triple
        inode.extent_bytes = ptrs.into();

        // First logical block reached via each indirection level.
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 12).unwrap(),
            Some(30),
            "single indirect (logical block 12)"
        );
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 12 + PPB)
                .unwrap(),
            Some(31),
            "double indirect (logical block 12 + ppb)"
        );
        let triple_lb = 12 + PPB + PPB * PPB;
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, triple_lb)
                .unwrap(),
            Some(32),
            "triple indirect (logical block 12 + ppb + ppb^2)"
        );

        // Sparse holes resolve to None, not a bogus physical block.
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 13).unwrap(),
            None,
            "unset single-indirect slot is a hole"
        );
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 0).unwrap(),
            None,
            "unset direct pointer is a hole"
        );
    }

    #[test]
    fn resolve_indirect_block_returns_none_for_indirect_root_holes() {
        // resolve_indirect_block_single_double_triple_levels covers direct and
        // single-indirect-slot holes but keeps all three indirection roots
        // present. This pins the root-hole short-circuits: when i_block[12/13/14]
        // are themselves zero (a fully sparse file), each level must resolve to a
        // hole (None), never physical block 0 / the superblock.
        const PPB: u32 = 1024;
        let cx = Cx::for_testing();
        let image = build_ext4_image_with_extents();
        let fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(image)),
            &OpenOptions::default(),
        )
        .expect("open crafted ext4 image");
        let scope = RequestScope::empty();

        // Every block pointer is zero, so each indirection root short-circuits
        // without any device read.
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        inode.extent_bytes = vec![0_u8; 15 * 4].into();

        // Direct-level hole: a zero pointer in i_block[0..12] resolves to a hole
        // (None), never physical block 0 (which would read the superblock as file
        // data). Pins the direct branch alongside the indirection roots (bd-xmh5g.323).
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 0).unwrap(),
            None
        );
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 11).unwrap(),
            None
        );

        // Single / double / triple indirect roots are all zero -> holes.
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 12).unwrap(),
            None
        );
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, 12 + PPB)
                .unwrap(),
            None
        );
        let triple_lb = 12 + PPB + PPB * PPB;
        assert_eq!(
            fs.resolve_indirect_block(&cx, &scope, &inode, triple_lb)
                .unwrap(),
            None
        );
    }

    /// Complements `resolve_indirect_block_single_double_triple_levels` by
    /// exercising `read_ext4_indirect`'s byte assembly on the legacy
    /// indirect-mapped path: a mapped block must read through verbatim while a
    /// sparse hole (zero pointer) must zero-fill. Only the addressing was
    /// covered before; the read/assemble + hole-fill loop was not.
    #[test]
    fn read_ext4_indirect_assembles_data_and_zero_fills_holes() {
        const BS: usize = 4096;

        let mut image = build_ext4_image_with_extents();
        // Fill free data block 30 with a recognizable, non-trivial pattern.
        let pattern: Vec<u8> = (0..BS)
            .map(|i| u8::try_from(i % 251).expect("pattern byte fits u8"))
            .collect();
        image[30 * BS..31 * BS].copy_from_slice(&pattern);

        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(image)),
            &OpenOptions::default(),
        )
        .expect("open crafted ext4 image");
        let scope = RequestScope::empty();

        // Non-extent inode, 2 logical blocks: block 0 → data(30), block 1 → hole.
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        let mut ptrs = vec![0_u8; 15 * 4];
        ptrs[0..4].copy_from_slice(&30_u32.to_le_bytes()); // i_block[0] = data block 30
        // i_block[1] left zero → sparse hole.
        inode.extent_bytes = ptrs.into();
        inode.size = (2 * BS) as u64;

        let out = fs
            .read_ext4_indirect(
                &cx,
                &scope,
                &inode,
                0,
                u32::try_from(2 * BS).expect("test read length fits u32"),
            )
            .expect("indirect read");
        assert_eq!(out.len(), 2 * BS, "reads the full file size");
        assert_eq!(
            &out[..BS],
            &pattern[..],
            "mapped block reads through verbatim"
        );
        assert!(
            out[BS..].iter().all(|&b| b == 0),
            "sparse hole must zero-fill"
        );
    }

    #[test]
    fn read_ext4_indirect_into_zero_fills_reused_buffer_holes() {
        const BS: usize = 4096;

        let mut image = build_ext4_image_with_extents();
        let pattern: Vec<u8> = (0..BS)
            .map(|i| u8::try_from((i * 17) % 251).expect("pattern byte fits u8"))
            .collect();
        image[30 * BS..31 * BS].copy_from_slice(&pattern);

        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(image)),
            &OpenOptions::default(),
        )
        .expect("open crafted ext4 image");
        let scope = RequestScope::empty();

        // Non-extent inode, 3 logical blocks:
        // block 0 -> hole, block 1 -> data(30), block 2 -> trailing partial hole.
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        let mut ptrs = vec![0_u8; 15 * 4];
        ptrs[4..8].copy_from_slice(&30_u32.to_le_bytes());
        inode.extent_bytes = ptrs.into();
        inode.size = (2 * BS + 123) as u64;

        let read_len = 2 * BS + 123;
        let mut dst = vec![0xA5; read_len + 19];
        let written = fs
            .read_ext4_indirect_into(
                &cx,
                &scope,
                &inode,
                0,
                u32::try_from(read_len).expect("test read length fits u32"),
                &mut dst,
            )
            .expect("indirect read into reused buffer");

        assert_eq!(written, read_len, "reads the requested live file bytes");
        assert!(
            dst[..BS].iter().all(|&b| b == 0),
            "leading full-block hole must overwrite stale buffer bytes"
        );
        assert_eq!(
            &dst[BS..2 * BS],
            &pattern[..],
            "mapped block reads through verbatim"
        );
        assert!(
            dst[2 * BS..read_len].iter().all(|&b| b == 0),
            "trailing partial hole must overwrite stale buffer bytes"
        );
        assert!(
            dst[read_len..].iter().all(|&b| b == 0xA5),
            "bytes outside the read window must not be touched"
        );
    }

    /// bd-laay3 increment 1: a legacy indirect-block-mapped (non-extent) file
    /// supports in-place OVERWRITE of its already-mapped blocks — full-block and
    /// partial (sub-block RMW) — and persists across a re-read, while growth and
    /// hole-fill (later increments) are cleanly rejected with UnsupportedFeature.
    ///
    /// The fixture creates a normal extent file, writes one block to allocate a
    /// real data block, then re-stamps the inode as indirect (clear
    /// EXTENT_FL, i_block[0] -> that physical block). Uses a real mkfs.ext4
    /// image so the inode/data blocks are fully valid; skips if mkfs is absent.
    #[test]
    fn ext4_indirect_overwrite_in_place_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;

        // Create an extent file and write one full block so a data block is
        // allocated on disk.
        let ino = fs
            .create(&cx, root, OsStr::new("legacy.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        let original = vec![0xAA_u8; bs];
        assert_eq!(
            fs.write(&cx, ino, 0, &original).expect("extent write") as usize,
            bs
        );

        // Locate the allocated physical block for logical block 0.
        let inode = fs.read_inode(&cx, ino).expect("read inode");
        let extents = fs.collect_extents(&cx, &inode).expect("extents");
        let phys = extents
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("logical block 0 mapped");

        // Re-stamp the inode as a legacy indirect file: clear EXTENT_FL and map
        // logical block 0 -> phys via i_block[0].
        let mut indirect = inode.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut ptrs = vec![0_u8; 15 * 4];
        ptrs[0..4].copy_from_slice(&u32::try_from(phys).expect("phys fits u32").to_le_bytes());
        indirect.extent_bytes = ptrs.into();
        indirect.size = bs as u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect inode");

        // Sanity: the indirect read path returns the original bytes.
        assert_eq!(
            fs.read(&cx, ino, 0, bs as u32).expect("indirect read"),
            original,
            "indirect read of the mapped block"
        );

        // Full-block in-place overwrite (the bd-laay3 increment-1 path).
        let updated = vec![0x5C_u8; bs];
        assert_eq!(
            fs.write(&cx, ino, 0, &updated).expect("indirect overwrite") as usize,
            bs,
            "full-block overwrite writes every byte"
        );
        assert_eq!(
            fs.read(&cx, ino, 0, bs as u32).expect("read back"),
            updated,
            "indirect in-place overwrite must persist"
        );

        // Partial (sub-block) overwrite: read-modify-write must touch only the
        // patched byte range.
        let patch = vec![0x11_u8; 100];
        assert_eq!(
            fs.write(&cx, ino, 50, &patch).expect("partial overwrite"),
            100
        );
        let post = fs.read(&cx, ino, 0, bs as u32).expect("read back partial");
        assert_eq!(&post[50..150], &patch[..], "patch lands at the offset");
        assert_eq!(
            &post[0..50],
            &updated[0..50],
            "bytes before patch unchanged"
        );
        assert_eq!(&post[150..], &updated[150..], "bytes after patch unchanged");

        // Growth past EOF (bd-laay3 increment 2): writing block 1 must allocate,
        // extend size, and persist.
        let grow = vec![0x22_u8; bs];
        assert_eq!(
            fs.write(&cx, ino, bs as u64, &grow).expect("grow write") as usize,
            bs
        );
        let grown = fs.read_inode(&cx, ino).expect("inode after grow");
        assert_eq!(grown.size, (2 * bs) as u64, "size must extend to 2 blocks");
        assert_eq!(
            fs.read(&cx, ino, bs as u64, bs as u32)
                .expect("read grown block"),
            grow,
            "newly grown block must persist"
        );
    }

    /// bd-laay3 increment 2: growth of a legacy indirect-block file — extend past
    /// EOF across a single-indirect boundary, fill a sparse hole, and verify
    /// i_blocks accounting counts the allocated indirect-metadata block.
    #[test]
    fn ext4_indirect_growth_and_hole_fill_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;
        let ptrs_per_block = bs / 4;

        // Create an extent file with one block, then re-stamp it indirect so it
        // maps logical block 0 only (rest are holes).
        let ino = fs
            .create(&cx, root, OsStr::new("grow.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        let b0 = vec![0x01_u8; bs];
        fs.write(&cx, ino, 0, &b0).expect("seed block 0");
        let seeded = fs.read_inode(&cx, ino).expect("inode");
        let phys0 = fs
            .collect_extents(&cx, &seeded)
            .expect("extents")
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("block 0 mapped");

        let mut indirect = seeded.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut iblock = vec![0_u8; 15 * 4];
        iblock[0..4].copy_from_slice(&u32::try_from(phys0).unwrap().to_le_bytes());
        indirect.extent_bytes = iblock.into();
        indirect.size = bs as u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect");

        // Grow across the single-indirect boundary: write logical block
        // (12 + ptrs_per_block) lands in the DOUBLE-indirect region, forcing
        // write_block_ptr to allocate indirect-metadata blocks (counted in
        // i_blocks). Everything between block 0 and there stays a hole.
        let far_lb = 12 + ptrs_per_block; // first double-indirect logical block
        let far_off = (far_lb * bs) as u64;
        let far = vec![0x07_u8; bs];
        assert_eq!(
            fs.write(&cx, ino, far_off, &far).expect("grow far block") as usize,
            bs
        );

        let after = fs.read_inode(&cx, ino).expect("inode after grow");
        assert_eq!(
            after.size,
            far_off + bs as u64,
            "size extends to the far block's end"
        );
        // i_blocks must exceed a single data block's worth: block 0 + the far
        // data block + the double-indirect root + its level-1 block.
        let sectors_per_block = u64::from(fs.block_size() / EXT4_SECTOR_SIZE);
        assert!(
            after.blocks >= 4 * sectors_per_block,
            "i_blocks must count data + indirect-metadata blocks, got {} sectors",
            after.blocks
        );

        // Original block survived, the gap reads as a zero-filled hole, and the
        // far block holds the new data.
        assert_eq!(
            fs.read(&cx, ino, 0, bs as u32).expect("b0"),
            b0,
            "block 0 intact"
        );
        assert!(
            fs.read(&cx, ino, bs as u64, bs as u32)
                .expect("hole")
                .iter()
                .all(|&b| b == 0),
            "untouched gap block reads as a zero hole"
        );
        assert_eq!(
            fs.read(&cx, ino, far_off, bs as u32).expect("far"),
            far,
            "far grown block holds the new data"
        );
    }

    /// bd-laay3 increment 3: truncating a legacy indirect-block file frees the
    /// data blocks AND the now-empty indirect-metadata blocks beyond the new EOF,
    /// clears the freed pointer slots, decrements i_blocks, and zeroes the tail of
    /// the surviving partial block (no data leakage).
    #[test]
    fn ext4_indirect_truncate_frees_chain_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;
        let spb = u64::from(fs.block_size() / EXT4_SECTOR_SIZE);

        // Build an indirect file with block 0 (direct), then grow into the
        // single-indirect region (logical block 12) so a single-indirect
        // metadata block is allocated.
        let ino = fs
            .create(&cx, root, OsStr::new("trunc.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        let b0 = vec![0x01_u8; bs];
        fs.write(&cx, ino, 0, &b0).expect("seed block 0");
        let seeded = fs.read_inode(&cx, ino).expect("inode");
        let phys0 = fs
            .collect_extents(&cx, &seeded)
            .expect("extents")
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("block 0 mapped");
        let mut indirect = seeded.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut iblock = vec![0_u8; 15 * 4];
        iblock[0..4].copy_from_slice(&u32::try_from(phys0).unwrap().to_le_bytes());
        indirect.extent_bytes = iblock.into();
        indirect.size = bs as u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect");

        let lb12_off = (12 * bs) as u64;
        fs.write(&cx, ino, lb12_off, &vec![0x0C_u8; bs])
            .expect("grow into single-indirect region");

        let before = fs.read_inode(&cx, ino).expect("inode before trunc");
        assert_eq!(
            before.size,
            lb12_off + bs as u64,
            "grew to logical block 12"
        );
        // i_block[12] is the single-indirect root pointer (offset 12*4 = 48).
        let root_before = u32::from_le_bytes(before.extent_bytes[48..52].try_into().unwrap());
        assert_ne!(root_before, 0, "single-indirect metadata block allocated");
        let blocks_before = before.blocks;

        // Truncate into block 0's interior: frees the block-12 data block AND the
        // single-indirect metadata block (2 blocks total).
        let new_size = (bs / 2) as u64;
        let attrs = SetAttrRequest {
            size: Some(new_size),
            ..SetAttrRequest::default()
        };
        fs.setattr(&cx, ino, &attrs).expect("indirect truncate");

        let after = fs.read_inode(&cx, ino).expect("inode after trunc");
        assert_eq!(after.size, new_size, "size shrunk");
        let root_after = u32::from_le_bytes(after.extent_bytes[48..52].try_into().unwrap());
        assert_eq!(root_after, 0, "freed single-indirect root pointer cleared");
        assert_eq!(
            blocks_before - after.blocks,
            2 * spb,
            "i_blocks must drop by 2 fs blocks (data + indirect metadata)"
        );

        // The surviving prefix reads back intact (clamped to the new size).
        let read = fs.read(&cx, ino, 0, bs as u32).expect("read after trunc");
        assert_eq!(read.len(), new_size as usize, "read clamped to new size");
        assert!(read.iter().all(|&b| b == 0x01), "surviving prefix intact");

        // The underlying block 0 must have its tail (>= new_size) zeroed on disk.
        let raw0 = fs
            .read_block_with_scope(&cx, &RequestScope::empty(), BlockNumber(phys0))
            .expect("raw block 0");
        assert!(
            raw0[new_size as usize..].iter().all(|&b| b == 0),
            "partial-block tail must be zeroed (no data leakage past EOF)"
        );
        assert!(
            raw0[..new_size as usize].iter().all(|&b| b == 0x01),
            "kept bytes of the partial block are unchanged"
        );
    }

    /// bd-laay3 increment 4: fallocate on a legacy indirect-block file —
    /// default preallocation (extends size), KEEP_SIZE (allocates without
    /// extending), ZERO_RANGE (zeros mapped bytes), PUNCH_HOLE (frees + reads
    /// zero, keeps size), and COLLAPSE/INSERT rejection (extent-only).
    #[test]
    fn ext4_indirect_fallocate_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;
        let spb = u64::from(fs.block_size() / EXT4_SECTOR_SIZE);

        // Build an indirect file mapping logical block 0 only.
        let ino = fs
            .create(&cx, root, OsStr::new("falloc.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        let b0 = vec![0x01_u8; bs];
        fs.write(&cx, ino, 0, &b0).expect("seed block 0");
        let seeded = fs.read_inode(&cx, ino).expect("inode");
        let phys0 = fs
            .collect_extents(&cx, &seeded)
            .expect("extents")
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("block 0 mapped");
        let mut indirect = seeded.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut iblock = vec![0_u8; 15 * 4];
        iblock[0..4].copy_from_slice(&u32::try_from(phys0).unwrap().to_le_bytes());
        indirect.extent_bytes = iblock.into();
        indirect.size = bs as u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect");

        // (1) Default fallocate: preallocate blocks 1..4 and extend size to 4 blocks.
        fs.fallocate(&cx, ino, bs as u64, (3 * bs) as u64, 0)
            .expect("default fallocate");
        let a = fs.read_inode(&cx, ino).expect("inode after default");
        assert_eq!(a.size, (4 * bs) as u64, "default fallocate extends size");
        assert!(a.blocks >= 4 * spb, "blocks 0..4 allocated");
        let read = fs.read(&cx, ino, 0, (4 * bs) as u32).expect("read");
        assert_eq!(&read[0..bs], &b0[..], "block 0 intact");
        assert!(
            read[bs..].iter().all(|&b| b == 0),
            "preallocated blocks read zero"
        );
        let blocks_after_default = a.blocks;

        // (2) KEEP_SIZE: allocate logical block 5 without changing the size.
        fs.fallocate(&cx, ino, (5 * bs) as u64, bs as u64, 0x01)
            .expect("keep_size fallocate");
        let b = fs.read_inode(&cx, ino).expect("inode after keep_size");
        assert_eq!(b.size, (4 * bs) as u64, "KEEP_SIZE must not change size");
        assert!(b.blocks > blocks_after_default, "KEEP_SIZE still allocates");

        // (3) ZERO_RANGE over the first half of block 0.
        fs.fallocate(&cx, ino, 0, (bs / 2) as u64, 0x10)
            .expect("zero_range fallocate");
        let z = fs
            .read(&cx, ino, 0, bs as u32)
            .expect("read after zero_range");
        assert!(
            z[..bs / 2].iter().all(|&b| b == 0),
            "zero_range zeroed first half"
        );
        assert!(
            z[bs / 2..].iter().all(|&b| b == 0x01),
            "rest of block 0 unchanged"
        );

        // (4) PUNCH_HOLE block 1 (KEEP_SIZE required): frees it, keeps size.
        let blocks_before_punch = fs.read_inode(&cx, ino).expect("inode").blocks;
        fs.fallocate(&cx, ino, bs as u64, bs as u64, 0x02 | 0x01)
            .expect("punch_hole fallocate");
        let c = fs.read_inode(&cx, ino).expect("inode after punch");
        assert_eq!(c.size, (4 * bs) as u64, "punch keeps size");
        assert_eq!(
            blocks_before_punch - c.blocks,
            spb,
            "punch frees exactly one data block"
        );
        assert!(
            fs.read(&cx, ino, bs as u64, bs as u32)
                .expect("read punched")
                .iter()
                .all(|&b| b == 0),
            "punched block reads as a zero hole"
        );

        // (5) COLLAPSE_RANGE / INSERT_RANGE are extent-only → rejected.
        assert!(
            matches!(
                fs.fallocate(&cx, ino, 0, bs as u64, 0x08),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "collapse_range must be rejected on an indirect file"
        );
        assert!(
            matches!(
                fs.fallocate(&cx, ino, 0, bs as u64, 0x20),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "insert_range must be rejected on an indirect file"
        );
    }

    /// bd-laay3 hardening: exercise the DEEPEST pointer-chain path end-to-end —
    /// the triple-indirect region (i_block[14]). A single sparse write there
    /// allocates the data block plus three metadata levels (triple root +
    /// double-indirect + single-indirect); a truncate back must free all four and
    /// clear i_block[14]. This validates write_block_ptr / resolve_indirect_block
    /// / free_indirect_subtree at level 3, which the other tests never reach.
    #[test]
    fn ext4_indirect_triple_indirect_grow_and_truncate_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;
        let bs_u64 = bs as u64;
        let spb = u64::from(fs.block_size() / EXT4_SECTOR_SIZE);
        let ppb = bs_u64 / 4;

        // Build an indirect file mapping logical block 0.
        let ino = fs
            .create(&cx, root, OsStr::new("triple.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        let b0 = vec![0x01_u8; bs];
        fs.write(&cx, ino, 0, &b0).expect("seed block 0");
        let seeded = fs.read_inode(&cx, ino).expect("inode");
        let phys0 = fs
            .collect_extents(&cx, &seeded)
            .expect("extents")
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("block 0 mapped");
        let mut indirect = seeded.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut iblock = vec![0_u8; 15 * 4];
        iblock[0..4].copy_from_slice(&u32::try_from(phys0).unwrap().to_le_bytes());
        indirect.extent_bytes = iblock.into();
        indirect.size = bs_u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect");

        // First logical block of the triple-indirect region:
        //   12 (direct) + ppb (single) + ppb*ppb (double).
        let triple_lb = 12 + ppb + ppb * ppb;
        let triple_off = triple_lb * bs_u64;
        let payload = vec![0x77_u8; bs];

        let blocks_before = fs.read_inode(&cx, ino).expect("inode").blocks;
        fs.write(&cx, ino, triple_off, &payload)
            .expect("sparse write into triple-indirect region");

        let after_grow = fs.read_inode(&cx, ino).expect("inode after grow");
        assert_eq!(
            after_grow.size,
            triple_off + bs_u64,
            "size extends to triple block"
        );
        // i_block[14] (triple root) is at offset 14*4 = 56.
        let tind_root = u32::from_le_bytes(after_grow.extent_bytes[56..60].try_into().unwrap());
        assert_ne!(tind_root, 0, "triple-indirect root allocated");
        // Allocated exactly 4 blocks: data + triple root + double-indirect + single-indirect.
        assert_eq!(
            after_grow.blocks - blocks_before,
            4 * spb,
            "triple-indirect write allocates data + 3 metadata levels"
        );

        // Read back: block 0 intact, the gap is a zero hole, the triple block holds data.
        assert_eq!(
            fs.read(&cx, ino, 0, bs as u32).expect("b0"),
            b0,
            "block 0 intact"
        );
        assert_eq!(
            fs.read(&cx, ino, triple_off, bs as u32).expect("triple"),
            payload,
            "triple-indirect block holds the written data"
        );

        // Truncate back to one block: must free the data block AND all three
        // metadata levels, clearing i_block[14].
        let attrs = SetAttrRequest {
            size: Some(bs_u64),
            ..SetAttrRequest::default()
        };
        fs.setattr(&cx, ino, &attrs).expect("truncate");
        let after_trunc = fs.read_inode(&cx, ino).expect("inode after trunc");
        assert_eq!(after_trunc.size, bs_u64, "size shrunk to one block");
        let tind_root_after =
            u32::from_le_bytes(after_trunc.extent_bytes[56..60].try_into().unwrap());
        assert_eq!(tind_root_after, 0, "triple-indirect root pointer cleared");
        assert_eq!(
            blocks_before, after_trunc.blocks,
            "truncate frees all 4 triple-indirect-path blocks (i_blocks restored)"
        );
        // Block 0 still readable after the deep free.
        assert_eq!(
            fs.read(&cx, ino, 0, bs as u32).expect("b0 after"),
            b0,
            "block 0 survives"
        );
    }

    /// bd-laay3 hardening: PARTIAL multi-level free. Earlier truncate/fallocate
    /// tests only freed sub-trees that emptied completely (root cleared). This
    /// covers the harder case: a truncate that frees one level-1 block under a
    /// double-indirect root while a SIBLING level-1 block and the root itself
    /// survive — exactly where a range off-by-one in free_indirect_subtree's
    /// `[free_lo, free_hi)` intersection logic would corrupt the tree.
    #[test]
    fn ext4_indirect_partial_double_indirect_free_keeps_siblings_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;
        let bs_u64 = bs as u64;
        let spb = u64::from(fs.block_size() / EXT4_SECTOR_SIZE);
        let ppb = bs_u64 / 4;

        // Indirect file mapping logical block 0.
        let ino = fs
            .create(&cx, root, OsStr::new("partial.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        let b0 = vec![0x01_u8; bs];
        fs.write(&cx, ino, 0, &b0).expect("seed block 0");
        let seeded = fs.read_inode(&cx, ino).expect("inode");
        let phys0 = fs
            .collect_extents(&cx, &seeded)
            .expect("extents")
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("block 0 mapped");
        let mut indirect = seeded.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut iblock = vec![0_u8; 15 * 4];
        iblock[0..4].copy_from_slice(&u32::try_from(phys0).unwrap().to_le_bytes());
        indirect.extent_bytes = iblock.into();
        indirect.size = bs_u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect");

        // Double-indirect region base = 12 + ppb. Place two data blocks under the
        // SAME double root but in DIFFERENT level-1 sub-blocks:
        //   A at dind-index1 = 0 (logical base)
        //   B at dind-index1 = 1 (logical base + ppb)
        let dind_base = 12 + ppb;
        let a_lb = dind_base; // idx1 = 0
        let b_lb = dind_base + ppb; // idx1 = 1
        let a_payload = vec![0xAA_u8; bs];
        let b_payload = vec![0xBB_u8; bs];
        fs.write(&cx, ino, a_lb * bs_u64, &a_payload)
            .expect("write A");
        fs.write(&cx, ino, b_lb * bs_u64, &b_payload)
            .expect("write B");

        let before = fs.read_inode(&cx, ino).expect("inode before trunc");
        // i_block[13] (double-indirect root) at offset 13*4 = 52.
        let dind_root = u32::from_le_bytes(before.extent_bytes[52..56].try_into().unwrap());
        assert_ne!(dind_root, 0, "double-indirect root allocated");
        let blocks_before = before.blocks;

        // Truncate so B is freed but A is kept: cutoff strictly between a_lb+1 and
        // b_lb. A block-aligned size at (a_lb + 1) blocks frees everything from
        // logical a_lb+1 onward, i.e. B (and its level-1 block), keeping A.
        let new_size = (a_lb + 1) * bs_u64;
        let attrs = SetAttrRequest {
            size: Some(new_size),
            ..SetAttrRequest::default()
        };
        fs.setattr(&cx, ino, &attrs).expect("partial truncate");

        let after = fs.read_inode(&cx, ino).expect("inode after trunc");
        assert_eq!(after.size, new_size, "size shrunk");
        // The double-indirect root MUST survive (A's level-1 block still hangs off it).
        let dind_root_after = u32::from_le_bytes(after.extent_bytes[52..56].try_into().unwrap());
        assert_eq!(
            dind_root_after, dind_root,
            "double-indirect root must survive a partial free (sibling still mapped)"
        );
        // Exactly two blocks freed: B's data block + B's now-empty level-1 block.
        assert_eq!(
            blocks_before - after.blocks,
            2 * spb,
            "partial free releases only B's data + its level-1 block"
        );
        // A still reads its data; B's region is now a zero hole.
        assert_eq!(
            fs.read(&cx, ino, a_lb * bs_u64, bs as u32).expect("read A"),
            a_payload,
            "sibling block A survives the partial free"
        );
        assert!(
            fs.read(&cx, ino, b_lb * bs_u64, bs as u32)
                .map(|v| v.is_empty())
                .unwrap_or(true),
            "B is beyond the new EOF (reads nothing)"
        );
        // Block 0 intact.
        assert_eq!(
            fs.read(&cx, ino, 0, bs as u32).expect("b0"),
            b0,
            "block 0 survives"
        );
    }

    /// Regression: deleting a legacy indirect-block-mapped file must FREE its
    /// data + indirect-metadata blocks. delete_inode previously freed blocks only
    /// for extent-mapped inodes, so unlinking an indirect file leaked every block
    /// (left allocated in the bitmap with no referencing inode — e2fsck-dirty).
    /// Verified against the authoritative bitmap counts AND the group-descriptor
    /// counts (they must stay consistent).
    #[test]
    fn ext4_indirect_unlink_frees_all_blocks_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;

        // Build an indirect file: block 0 (direct) + a grow into the
        // single-indirect region (1 data block + 1 indirect-metadata block) =
        // three filesystem blocks total.
        let ino = fs
            .create(&cx, root, OsStr::new("leak.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        fs.write(&cx, ino, 0, &vec![0x01_u8; bs])
            .expect("seed block 0");
        let seeded = fs.read_inode(&cx, ino).expect("inode");
        let phys0 = fs
            .collect_extents(&cx, &seeded)
            .expect("extents")
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("block 0 mapped");
        let mut indirect = seeded.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut iblock = vec![0_u8; 15 * 4];
        iblock[0..4].copy_from_slice(&u32::try_from(phys0).unwrap().to_le_bytes());
        indirect.extent_bytes = iblock.into();
        indirect.size = bs as u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect");
        // Logical block 12 is the first single-indirect block: allocates one
        // data block plus the single-indirect metadata block.
        fs.write(&cx, ino, 12 * bs as u64, &vec![0x0C_u8; bs])
            .expect("grow into single-indirect region");

        // The file now holds exactly 3 blocks (block 0 + grown data + its
        // single-indirect metadata block). Flush so the on-disk group
        // descriptors reflect the allocations before sampling them — under
        // GDT-persistence deferral (bd-cc-gdt-defer) the descriptor free counts
        // are a durability-boundary quantity; the bitmap is eager either way
        // (no-op flush in eager mode).
        fs.flush_mvcc_to_device(&cx).expect("flush before");
        let before = fs.free_space_summary(&cx).expect("free space before");

        fs.unlink(&cx, root, OsStr::new("leak.bin"))
            .expect("unlink");

        fs.flush_mvcc_to_device(&cx).expect("flush after");
        let after = fs.free_space_summary(&cx).expect("free space after");
        assert_eq!(
            after.free_blocks_total - before.free_blocks_total,
            3,
            "unlink must free all 3 indirect-file blocks (bitmap), not leak them"
        );
        assert_eq!(
            after.gd_free_blocks_total - before.gd_free_blocks_total,
            3,
            "group-descriptor free count must match the bitmap after the free"
        );
    }

    /// Capstone (W17-24): the FULL indirect-file lifecycle leaks ZERO blocks.
    /// create -> (restamp indirect) -> grow across the double-indirect boundary
    /// -> truncate back -> delete must leave the free-block count EXACTLY at the
    /// pre-creation baseline (and bitmap == group-descriptor throughout). Any
    /// reintroduced leak in write/grow/truncate/delete fails this loudly.
    #[test]
    fn ext4_indirect_full_lifecycle_leaks_no_blocks_bd_laay3() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let bs = fs.block_size() as usize;
        let bs_u64 = bs as u64;
        let ppb = bs_u64 / 4;

        // Baseline free space BEFORE the file exists. Flush first so the on-disk
        // group descriptors are sampled at a durability boundary in both this and
        // the final read — under GDT-persistence deferral (bd-cc-gdt-defer) the
        // descriptor free counts only reconcile with the eager bitmap at a flush
        // (no-op in eager mode); the bitmap-based `free_blocks_total` assertion
        // below is exact regardless.
        fs.flush_mvcc_to_device(&cx).expect("flush baseline");
        let baseline = fs.free_space_summary(&cx).expect("baseline");

        // create + seed block 0, then re-stamp as a legacy indirect file.
        let ino = fs
            .create(&cx, root, OsStr::new("life.bin"), 0o644, 0, 0)
            .expect("create")
            .ino;
        fs.write(&cx, ino, 0, &vec![0x01_u8; bs]).expect("seed");
        let seeded = fs.read_inode(&cx, ino).expect("inode");
        let phys0 = fs
            .collect_extents(&cx, &seeded)
            .expect("extents")
            .iter()
            .find(|e| e.logical_block == 0)
            .map(|e| e.physical_start)
            .expect("block 0 mapped");
        let mut indirect = seeded.clone();
        indirect.flags &= !ffs_types::EXT4_EXTENTS_FL;
        let mut iblock = vec![0_u8; 15 * 4];
        iblock[0..4].copy_from_slice(&u32::try_from(phys0).unwrap().to_le_bytes());
        indirect.extent_bytes = iblock.into();
        indirect.size = bs_u64;
        fs.persist_ext4_inode_for_testing(&cx, ino, &indirect)
            .expect("persist indirect");

        // Grow across the double-indirect boundary (allocates data + double-root +
        // a level-1 indirect block), and a single-indirect block too.
        fs.write(&cx, ino, 12 * bs_u64, &vec![0x0C_u8; bs])
            .expect("grow single-indirect");
        fs.write(&cx, ino, (12 + ppb) * bs_u64, &vec![0x0D_u8; bs])
            .expect("grow double-indirect");

        // Truncate back to a single block (frees most of the chain).
        let attrs = SetAttrRequest {
            size: Some(bs_u64),
            ..SetAttrRequest::default()
        };
        fs.setattr(&cx, ino, &attrs).expect("truncate");

        // Delete the file.
        fs.unlink(&cx, root, OsStr::new("life.bin"))
            .expect("remove");

        // Every block the file ever held must be back: zero net leak. Flush so
        // the on-disk descriptors reflect the truncate+unlink frees before
        // sampling (bd-cc-gdt-defer durability boundary; no-op in eager mode).
        fs.flush_mvcc_to_device(&cx).expect("flush final");
        let end = fs.free_space_summary(&cx).expect("final");
        assert_eq!(
            end.free_blocks_total, baseline.free_blocks_total,
            "full indirect lifecycle must leak zero blocks (bitmap)"
        );
        assert_eq!(
            end.gd_free_blocks_total, baseline.gd_free_blocks_total,
            "full indirect lifecycle must leak zero blocks (group descriptors)"
        );
    }

    #[test]
    fn ext4_indirect_read_coalesces_contiguous_blocks_bd_bov9c() {
        const BS: usize = 4096;
        let mut image = build_ext4_image_with_extents();
        // Four contiguous data blocks (30..34), each a distinct pattern.
        for b in 30..34_usize {
            let pat = vec![u8::try_from(b).expect("block index fits u8"); BS];
            image[b * BS..(b + 1) * BS].copy_from_slice(&pat);
        }

        let dev = VectoredCountingDevice::new(TestDevice::from_vec(image));
        let scalar = Arc::clone(&dev.scalar_reads);
        let vectored = Arc::clone(&dev.vectored_reads);
        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(&cx, Box::new(dev), &OpenOptions::default()).unwrap();
        let scope = RequestScope::empty();

        // Legacy indirect inode: 4 direct pointers → contiguous blocks 30..34.
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        let mut ptrs = vec![0_u8; 15 * 4];
        for i in 0..4_usize {
            let blk = u32::try_from(30 + i).expect("block fits u32");
            ptrs[i * 4..i * 4 + 4].copy_from_slice(&blk.to_le_bytes());
        }
        inode.extent_bytes = ptrs.into();
        inode.size = (4 * BS) as u64;

        scalar.store(0, AtomicOrdering::SeqCst);
        vectored.store(0, AtomicOrdering::SeqCst);
        let out = fs
            .read_ext4_indirect(&cx, &scope, &inode, 0, u32::try_from(4 * BS).unwrap())
            .expect("indirect read");

        // ISOMORPHISM: each block reads through verbatim.
        assert_eq!(out.len(), 4 * BS);
        for b in 0..4_usize {
            assert!(
                out[b * BS..(b + 1) * BS]
                    .iter()
                    .all(|&x| x == u8::try_from(30 + b).unwrap()),
                "block {b} reads its pattern"
            );
        }

        // SCORE (bd-bov9c/bd-xfdjk): the 4 contiguous data blocks are served by
        // exactly ONE ranged device op — `read_contiguous_into` reads the whole
        // run in one `read_exact_at` straight into the output buffer (no
        // per-block buffers, no vectored scatter). Pre-coalescing this was 4
        // scalar reads.
        assert_eq!(
            scalar.load(AtomicOrdering::SeqCst),
            1,
            "4 contiguous indirect data blocks collapse to one ranged device op; \
             got {} scalar + {} vectored",
            scalar.load(AtomicOrdering::SeqCst),
            vectored.load(AtomicOrdering::SeqCst),
        );
        assert_eq!(
            vectored.load(AtomicOrdering::SeqCst),
            0,
            "the ranged read into the output buffer uses no vectored device op"
        );
    }

    #[test]
    fn ext4_indirect_large_run_chunks_default_bd_xmh5g() {
        const BS: usize = 4096;
        const DATA_START: usize = 30;
        const INDIRECT_BLOCK: usize = 20;
        const RUN_BLOCKS: usize = 129;

        let mut image = build_ext4_image_with_extents();
        image.resize((DATA_START + RUN_BLOCKS + 1) * BS, 0);
        let blocks_count = u32::try_from(image.len() / BS).expect("test image block count fits");
        let sb_off = EXT4_SUPERBLOCK_OFFSET;
        image[sb_off + 0x04..sb_off + 0x08].copy_from_slice(&blocks_count.to_le_bytes());
        image[sb_off + 0x20..sb_off + 0x24].copy_from_slice(&blocks_count.to_le_bytes());

        for b in 0..RUN_BLOCKS {
            let pat = u8::try_from(DATA_START + b).expect("block pattern fits u8");
            let phys = DATA_START + b;
            image[phys * BS..(phys + 1) * BS].fill(pat);
        }
        let indirect_off = INDIRECT_BLOCK * BS;
        for i in 0..RUN_BLOCKS - 12 {
            let phys = u32::try_from(DATA_START + 12 + i).expect("physical block fits u32");
            image[indirect_off + i * 4..indirect_off + i * 4 + 4]
                .copy_from_slice(&phys.to_le_bytes());
        }

        let dev = VectoredCountingDevice::new(TestDevice::from_vec(image));
        let scalar = Arc::clone(&dev.scalar_reads);
        let vectored = Arc::clone(&dev.vectored_reads);
        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(&cx, Box::new(dev), &OpenOptions::default()).unwrap();
        let scope = RequestScope::empty();

        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        let mut ptrs = vec![0_u8; 15 * 4];
        for i in 0..12_usize {
            let phys = u32::try_from(DATA_START + i).expect("physical block fits u32");
            ptrs[i * 4..i * 4 + 4].copy_from_slice(&phys.to_le_bytes());
        }
        ptrs[12 * 4..13 * 4].copy_from_slice(
            &u32::try_from(INDIRECT_BLOCK)
                .expect("indirect block fits u32")
                .to_le_bytes(),
        );
        inode.extent_bytes = ptrs.into();
        inode.size = (RUN_BLOCKS * BS) as u64;

        scalar.store(0, AtomicOrdering::SeqCst);
        vectored.store(0, AtomicOrdering::SeqCst);
        let out = fs
            .read_ext4_indirect(
                &cx,
                &scope,
                &inode,
                0,
                u32::try_from(RUN_BLOCKS * BS).unwrap(),
            )
            .expect("large indirect read");

        assert_eq!(out.len(), RUN_BLOCKS * BS);
        for b in 0..RUN_BLOCKS {
            let pat = u8::try_from(DATA_START + b).expect("block pattern fits u8");
            assert!(
                out[b * BS..(b + 1) * BS].iter().all(|&x| x == pat),
                "block {b} reads its pattern"
            );
        }

        if std::env::var_os("FFS_INDIRECT_READ_CHUNK_BLOCKS").is_none()
            && std::env::var_os("FFS_READ_CHUNK_BLOCKS").is_none()
        {
            assert_eq!(
                scalar.load(AtomicOrdering::SeqCst),
                3,
                "129 contiguous indirect data blocks should use one cached metadata read \
                 plus two data reads at the 128-block default; got {} scalar + {} vectored",
                scalar.load(AtomicOrdering::SeqCst),
                vectored.load(AtomicOrdering::SeqCst),
            );
        }
        assert_eq!(
            vectored.load(AtomicOrdering::SeqCst),
            0,
            "indirect chunk reads use read_contiguous_into, not vectored scatter"
        );
    }

    fn malformed_inline_data_xattr_ibody() -> Vec<u8> {
        let mut ibody = Vec::new();
        ibody.extend_from_slice(&ffs_types::EXT4_XATTR_MAGIC.to_le_bytes());
        ibody.push(4); // e_name_len
        ibody.push(7); // EXT4_XATTR_INDEX_SYSTEM
        ibody.extend_from_slice(&4_u16.to_le_bytes()); // e_value_offs overlaps entry table
        ibody.extend_from_slice(&0_u32.to_le_bytes()); // e_value_block
        ibody.extend_from_slice(&4_u32.to_le_bytes()); // e_value_size
        ibody.extend_from_slice(&0_u32.to_le_bytes()); // e_hash
        ibody.extend_from_slice(b"data");
        ibody
    }

    #[test]
    fn ext4_inline_data_rejects_malformed_ibody_xattr() {
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        inode.flags = ffs_types::EXT4_INLINE_DATA_FL;
        inode.size = 64;
        inode.extent_bytes = (0_u8..60).collect();
        inode.xattr_ibody = malformed_inline_data_xattr_ibody();

        let err = OpenFs::read_ext4_inline_data(&inode, 0, 64)
            .expect_err("malformed inline-data ibody xattr should fail");
        assert!(
            matches!(err, FfsError::Format(ref detail) if detail.contains("xattr_value")),
            "unexpected inline-data xattr error: {err:?}"
        );
    }

    /// bd-vpypn: the fits-in-i_block fast path must agree with the assembling
    /// path everywhere it applies, including the boundary.
    ///
    /// The shortcut skips the ibody xattr parse AND the capacity check, so the
    /// thing worth testing is not that it is fast but that it is not observable:
    /// every offset/size of a file that fits in i_block must return exactly what
    /// the general path returns for the same inode with a continuation present.
    #[test]
    fn ext4_inline_data_i_block_fast_path_is_byte_identical_bd_vpypn() {
        let head = b"0123456789abcdefghijklmnopqrstuv".to_vec();
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        inode.flags = ffs_types::EXT4_INLINE_DATA_FL;
        inode.extent_bytes = head.clone().into();

        // Every size that fits entirely in i_block, at every offset within it.
        for file_size in [0_u64, 1, 5, head.len() as u64 - 1, head.len() as u64] {
            inode.size = file_size;
            for offset in 0..=file_size {
                for size in [0_u32, 1, 4, 64] {
                    let got = OpenFs::read_ext4_inline_data(&inode, offset, size)
                        .expect("a file that fits in i_block must read");
                    let want_len =
                        usize::try_from((file_size - offset).min(u64::from(size))).unwrap();
                    let start = usize::try_from(offset).unwrap();
                    assert_eq!(
                        got.as_slice(),
                        &head[start..start + want_len],
                        "size={file_size} offset={offset} read={size}"
                    );
                }
            }
        }

        // Reading at or past EOF is empty, and must stay empty on the fast path.
        inode.size = 4;
        assert!(
            OpenFs::read_ext4_inline_data(&inode, 4, 16)
                .unwrap()
                .is_empty(),
            "a read starting at EOF returns nothing"
        );
        assert!(
            OpenFs::read_ext4_inline_data(&inode, 99, 16)
                .unwrap()
                .is_empty(),
            "a read starting past EOF returns nothing"
        );

        // ONE BYTE OVER and the fast path must NOT engage: the file no longer fits
        // in i_block, so the continuation is required and its absence is the
        // corruption the general path exists to catch.
        inode.size = head.len() as u64 + 1;
        let err = OpenFs::read_ext4_inline_data(&inode, 0, 8).unwrap_err();
        assert!(
            matches!(err, FfsError::Corruption { .. }),
            "a file larger than i_block with no continuation must still be rejected, got {err:?}"
        );
    }

    #[test]
    fn ext4_inline_data_allows_i_block_without_ibody_xattrs() {
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        inode.flags = ffs_types::EXT4_INLINE_DATA_FL;
        inode.size = 4;
        inode.extent_bytes = b"data".to_vec().into();

        let bytes = OpenFs::read_ext4_inline_data(&inode, 0, 4)
            .expect("i_block-only inline data should not require ibody xattrs");
        assert_eq!(bytes, b"data");
    }

    #[test]
    fn ext4_inline_data_rejects_size_beyond_inline_capacity() {
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        inode.flags = ffs_types::EXT4_INLINE_DATA_FL;
        inode.size = 61;
        inode.extent_bytes = (0_u8..60).collect();

        let err = OpenFs::read_ext4_inline_data(&inode, 0, 61)
            .expect_err("oversized inline-data inode should fail closed");
        assert!(
            matches!(err, FfsError::Corruption { ref detail, .. } if detail.contains("exceeds inline capacity")),
            "unexpected oversized inline-data error: {err:?}"
        );
    }

    #[test]
    fn ext4_inode_to_attr_maps_each_timestamp_field_distinctly() {
        let sb = make_test_superblock();
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        // Distinct per-field seconds (extras zeroed) so any swapped *_system_time
        // call maps the wrong on-disk time into a field and fails.
        inode.atime = 1_000;
        inode.atime_extra = 0;
        inode.mtime = 2_000;
        inode.mtime_extra = 0;
        inode.ctime = 3_000;
        inode.ctime_extra = 0;
        inode.crtime = 4_000;
        inode.crtime_extra = 0;
        let attr = inode_to_attr(&sb, InodeNumber(100), &inode);
        let secs =
            |t: std::time::SystemTime| t.duration_since(std::time::UNIX_EPOCH).unwrap().as_secs();
        assert_eq!(secs(attr.atime), 1_000, "atime");
        assert_eq!(secs(attr.mtime), 2_000, "mtime");
        assert_eq!(secs(attr.ctime), 3_000, "ctime");
        assert_eq!(secs(attr.crtime), 4_000, "crtime");
    }

    #[test]
    fn ext4_move_ext_effective_len_clamps_to_both_file_bounds() {
        let req = |orig_start, donor_start, len| Ext4MoveExtRequest {
            ino: InodeNumber(1),
            donor_fd: 0,
            orig_start,
            donor_start,
            len,
        };
        // Within both files (each 10 blocks): the full requested length.
        assert_eq!(OpenFs::ext4_move_ext_effective_len(req(0, 0, 4), 10, 10), 4);
        // Source-limited: orig has 2 blocks left from start 8.
        assert_eq!(OpenFs::ext4_move_ext_effective_len(req(8, 0, 4), 10, 10), 2);
        // Donor-limited: donor has 1 block left from start 9.
        assert_eq!(OpenFs::ext4_move_ext_effective_len(req(0, 9, 4), 10, 10), 1);
        // Source start at/past EOF -> no exchange.
        assert_eq!(
            OpenFs::ext4_move_ext_effective_len(req(10, 0, 4), 10, 10),
            0
        );
        // Donor start at/past EOF -> no exchange.
        assert_eq!(
            OpenFs::ext4_move_ext_effective_len(req(0, 10, 4), 10, 10),
            0
        );
    }

    #[test]
    fn inode_to_attr_block_device_rdev() {
        use ffs_types::{S_IFBLK, S_IFCHR};

        let sb = make_test_superblock();

        // Block device: major=8, minor=1 → /dev/sda1 (new format in i_block[1])
        let inode = make_test_inode(S_IFBLK | 0o660, 0, 0x0801);
        let attr = inode_to_attr(&sb, InodeNumber(100), &inode);
        assert_eq!(attr.kind, FileType::BlockDevice);
        assert_eq!(attr.rdev, 0x0801);
        assert_eq!(attr.perm, 0o660);

        // Char device: major=1, minor=3 → /dev/null (old format in i_block[0])
        let inode = make_test_inode(S_IFCHR | 0o666, 0x0103, 0);
        let attr = inode_to_attr(&sb, InodeNumber(101), &inode);
        assert_eq!(attr.kind, FileType::CharDevice);
        assert_eq!(attr.rdev, 0x0103);
        assert_eq!(attr.perm, 0o666);
    }

    #[test]
    fn inode_to_attr_huge_file_scales_blocks_to_512_sectors() {
        let sb = make_test_superblock(); // block_size = 4096
        let mut inode = make_test_inode(ffs_types::S_IFREG | 0o644, 0, 0);
        inode.blocks = 8;

        // Without HUGE_FILE, i_blocks is already in 512-byte sectors -> passthrough.
        let attr = inode_to_attr(&sb, InodeNumber(100), &inode);
        assert_eq!(attr.blocks, 8);

        // With HUGE_FILE, i_blocks is in filesystem blocks -> scale to 512-byte
        // sectors (block_size/512). At 4K blocks that is 8 sectors per block.
        inode.flags |= ffs_types::EXT4_HUGE_FILE_FL;
        let attr = inode_to_attr(&sb, InodeNumber(100), &inode);
        let sectors_per_block = u64::from(sb.block_size / 512);
        assert!(
            sectors_per_block > 1,
            "test needs block_size > 512 to be meaningful"
        );
        assert_eq!(attr.blocks, 8 * sectors_per_block);
    }

    #[test]
    fn inode_to_attr_regular_file_rdev_zero() {
        use ffs_types::S_IFREG;

        let sb = make_test_superblock();
        let inode = make_test_inode(S_IFREG | 0o644, 0, 0);
        let attr = inode_to_attr(&sb, InodeNumber(11), &inode);
        assert_eq!(attr.kind, FileType::RegularFile);
        assert_eq!(attr.rdev, 0);
        assert_eq!(attr.perm, 0o644);
        assert_eq!(attr.uid, 0);
        assert_eq!(attr.gid, 0);
    }

    #[test]
    fn inode_file_type_maps_symlink_fifo_socket_and_unknown() {
        use ffs_types::{S_IFIFO, S_IFLNK, S_IFSOCK};

        let with_mode = |mode: u16| make_test_inode(mode, 0, 0);
        assert_eq!(
            inode_file_type(&with_mode(S_IFLNK | 0o777)),
            FileType::Symlink
        );
        assert_eq!(inode_file_type(&with_mode(S_IFIFO | 0o644)), FileType::Fifo);
        assert_eq!(
            inode_file_type(&with_mode(S_IFSOCK | 0o644)),
            FileType::Socket
        );
        // An undefined S_IFMT value (0o030000) matches no predicate and falls
        // back to RegularFile.
        assert_eq!(
            inode_file_type(&with_mode(0o030_000 | 0o644)),
            FileType::RegularFile
        );
    }

    #[test]
    fn inode_file_type_maps_directory_regular_and_devices() {
        // Complements inode_file_type_maps_symlink_fifo_socket_and_unknown by
        // pinning the common formats directly (they were only hit indirectly).
        let with_mode = |mode: u16| make_test_inode(mode, 0, 0);
        assert_eq!(
            inode_file_type(&with_mode(ffs_types::S_IFREG | 0o644)),
            FileType::RegularFile
        );
        assert_eq!(
            inode_file_type(&with_mode(ffs_types::S_IFDIR | 0o755)),
            FileType::Directory
        );
        assert_eq!(
            inode_file_type(&with_mode(ffs_types::S_IFBLK | 0o644)),
            FileType::BlockDevice
        );
        assert_eq!(
            inode_file_type(&with_mode(ffs_types::S_IFCHR | 0o644)),
            FileType::CharDevice
        );
    }

    #[test]
    fn ext4_flags_to_xflags_projects_each_flag_exactly() {
        use ffs_types::{
            EXT4_APPEND_FL, EXT4_IMMUTABLE_FL, EXT4_NOATIME_FL, EXT4_NODUMP_FL,
            EXT4_PROJINHERIT_FL, EXT4_SYNC_FL,
        };

        // No flags -> 0, and in particular no HASATTR.
        assert_eq!(ext4_flags_to_xflags(0), 0);

        // Each flag projects to exactly its xflag plus HASATTR.
        let hasattr = xflags::FS_XFLAG_HASATTR;
        assert_eq!(
            ext4_flags_to_xflags(EXT4_IMMUTABLE_FL),
            xflags::FS_XFLAG_IMMUTABLE | hasattr
        );
        assert_eq!(
            ext4_flags_to_xflags(EXT4_APPEND_FL),
            xflags::FS_XFLAG_APPEND | hasattr
        );
        assert_eq!(
            ext4_flags_to_xflags(EXT4_SYNC_FL),
            xflags::FS_XFLAG_SYNC | hasattr
        );
        assert_eq!(
            ext4_flags_to_xflags(EXT4_NOATIME_FL),
            xflags::FS_XFLAG_NOATIME | hasattr
        );
        assert_eq!(
            ext4_flags_to_xflags(EXT4_NODUMP_FL),
            xflags::FS_XFLAG_NODUMP | hasattr
        );
        assert_eq!(
            ext4_flags_to_xflags(EXT4_PROJINHERIT_FL),
            xflags::FS_XFLAG_PROJINHERIT | hasattr
        );

        // All flags together project to the union plus HASATTR.
        let all = EXT4_IMMUTABLE_FL
            | EXT4_APPEND_FL
            | EXT4_SYNC_FL
            | EXT4_NOATIME_FL
            | EXT4_NODUMP_FL
            | EXT4_PROJINHERIT_FL;
        assert_eq!(
            ext4_flags_to_xflags(all),
            xflags::FS_XFLAG_IMMUTABLE
                | xflags::FS_XFLAG_APPEND
                | xflags::FS_XFLAG_SYNC
                | xflags::FS_XFLAG_NOATIME
                | xflags::FS_XFLAG_NODUMP
                | xflags::FS_XFLAG_PROJINHERIT
                | hasattr
        );

        // An ext4 flag with no xflag mapping projects to nothing.
        assert_eq!(ext4_flags_to_xflags(ffs_types::EXT4_EXTENTS_FL), 0);
    }

    #[test]
    fn xflags_to_ext4_flags_validates_preserves_and_clears() {
        use ffs_types::{EXT4_APPEND_FL, EXT4_EXTENTS_FL, EXT4_IMMUTABLE_FL};

        // The output-only HASATTR bit may not be set by userspace -> EINVAL.
        let err = xflags_to_ext4_flags(xflags::FS_XFLAG_HASATTR, 0).unwrap_err();
        assert_eq!(err.to_errno(), libc::EINVAL);

        // An xflag ext4 does not support (NODEFRAG) -> EOPNOTSUPP.
        let err = xflags_to_ext4_flags(xflags::FS_XFLAG_NODEFRAG, 0).unwrap_err();
        assert_eq!(err.to_errno(), libc::EOPNOTSUPP);

        // Non-user-settable current flags (EXTENTS) are preserved when applying
        // xflags — clobbering them would make the extent tree uninterpretable.
        let result = xflags_to_ext4_flags(xflags::FS_XFLAG_IMMUTABLE, EXT4_EXTENTS_FL).unwrap();
        assert_eq!(result, EXT4_EXTENTS_FL | EXT4_IMMUTABLE_FL);

        // A user-settable flag (APPEND) present in current_flags but absent from
        // the new xflags is cleared, while EXTENTS is still preserved.
        let result =
            xflags_to_ext4_flags(xflags::FS_XFLAG_IMMUTABLE, EXT4_EXTENTS_FL | EXT4_APPEND_FL)
                .unwrap();
        assert_eq!(result, EXT4_EXTENTS_FL | EXT4_IMMUTABLE_FL);
    }

