    #[test]
    fn ext4_expand_posix_acl_xattr_value_passes_through_userspace_format() {
        // A value already in the POSIX_ACL_XATTR userspace layout (version
        // 0x0002) is returned verbatim — no compact-to-userspace expansion.
        let mut value = POSIX_ACL_XATTR_VERSION.to_le_bytes().to_vec();
        value.extend_from_slice(&[0xAA_u8; 16]); // arbitrary already-expanded body
        let expanded =
            ext4_expand_posix_acl_xattr_value(&value).expect("userspace-format ACL passes through");
        assert_eq!(
            expanded, value,
            "an already-userspace ACL must be returned unchanged"
        );
    }

    #[test]
    fn ext4_expand_posix_acl_xattr_value_rejects_malformed() {
        // Shorter than the 4-byte version header.
        assert!(matches!(
            ext4_expand_posix_acl_xattr_value(&[0, 1, 2]),
            Err(FfsError::Format(_))
        ));
        // Unsupported version.
        assert!(matches!(
            ext4_expand_posix_acl_xattr_value(&0x9999_u32.to_le_bytes()),
            Err(FfsError::Format(_))
        ));
        // Storage version with a truncated entry header (2 trailing bytes, need 4).
        let mut truncated_entry = EXT4_POSIX_ACL_STORAGE_VERSION.to_le_bytes().to_vec();
        truncated_entry.extend_from_slice(&[0, 0]);
        assert!(matches!(
            ext4_expand_posix_acl_xattr_value(&truncated_entry),
            Err(FfsError::Format(_))
        ));
        // Storage version, a USER entry whose 4-byte id is truncated.
        let mut truncated_id = EXT4_POSIX_ACL_STORAGE_VERSION.to_le_bytes().to_vec();
        truncated_id.extend_from_slice(&POSIX_ACL_TAG_USER.to_le_bytes());
        truncated_id.extend_from_slice(&0_u16.to_le_bytes());
        assert!(matches!(
            ext4_expand_posix_acl_xattr_value(&truncated_id),
            Err(FfsError::Format(_))
        ));
    }

    #[test]
    fn ext4_getxattr_expands_posix_acl_access_to_userspace_format() {
        const ACL_USER_OBJ_TAG: u16 = 0x0001;
        const ACL_GROUP_OBJ_TAG: u16 = 0x0004;
        const ACL_OTHER_TAG: u16 = 0x0020;

        let stored = build_test_stored_posix_acl(&[
            (ACL_USER_OBJ_TAG, 0o6),
            (ACL_GROUP_OBJ_TAG, 0o4),
            (ACL_OTHER_TAG, 0),
        ]);
        let expected = ext4_expand_posix_acl_xattr_value(&stored).expect("expand compact ACL");
        let image = build_ext4_image_with_posix_acl_xattr(
            &stored,
            ffs_types::EXT4_XATTR_INDEX_POSIX_ACL_ACCESS,
        );
        let dev = TestDevice::from_vec(image);
        let cx = Cx::for_testing();

        let fs = OpenFs::from_device(&cx, Box::new(dev), &OpenOptions::default()).unwrap();
        let value = fs
            .getxattr(&cx, InodeNumber(11), "system.posix_acl_access")
            .expect("getxattr should succeed")
            .expect("ACL xattr should be present");

        assert_eq!(value, expected);
        assert_eq!(
            value,
            [
                0x02, 0x00, 0x00, 0x00, 0x01, 0x00, 0x06, 0x00, 0xff, 0xff, 0xff, 0xff, 0x04, 0x00,
                0x04, 0x00, 0xff, 0xff, 0xff, 0xff, 0x20, 0x00, 0x00, 0x00, 0xff, 0xff, 0xff, 0xff,
            ]
        );
    }

