    #[test]
    fn btrfs_read_coalesces_contiguous_block_reads_into_one_ranged_op() {
        // bd-a384r/bd-dy41g behaviour proof: a multi-block contiguous file read
        // must be served by a single coalesced device op, not one read per
        // block — and remain byte-identical. `read_contiguous_into` reads the
        // whole contiguous run in one ranged `read_exact_at` straight into the
        // output buffer (no per-block buffer allocation, no vectored scatter).
        let mut image = build_btrfs_fsops_image();
        let expected: Vec<u8> = (0..16_384)
            .map(|i| u8::try_from(i % 251).expect("value should fit in u8"))
            .collect();
        set_btrfs_test_file_size(&mut image, expected.len() as u64);
        set_btrfs_test_extent_lengths(&mut image, expected.len() as u64);
        write_btrfs_test_file_data(&mut image, &expected);

        let dev = VectoredCountingDevice::new(TestDevice::from_vec(image));
        let scalar = Arc::clone(&dev.scalar_reads);
        let vectored = Arc::clone(&dev.vectored_reads);
        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(&cx, Box::new(dev), &OpenOptions::default()).unwrap();
        let ops: &dyn FsOps = &fs;

        // Warm the parsed-node (metadata) cache so the measured read performs no
        // extent-tree device reads — only the file-data read remains. File data
        // is never cached, so it always hits the device.
        let warm = ops
            .read(&cx, &mut RequestScope::empty(), InodeNumber(257), 0, 16_384)
            .unwrap();
        assert_eq!(warm, expected, "coalesced read must be byte-identical");

        scalar.store(0, AtomicOrdering::SeqCst);
        vectored.store(0, AtomicOrdering::SeqCst);

        let data = ops
            .read(&cx, &mut RequestScope::empty(), InodeNumber(257), 0, 16_384)
            .unwrap();

        assert_eq!(data, expected, "coalesced read must be byte-identical");
        // Quantified syscall reduction: with metadata served from the warm
        // node cache, the 4 contiguous data blocks are served by exactly ONE
        // ranged device read (one `read_exact_at` spanning the run) — pre-
        // coalescing this path issued 4 scalar reads (4 pread). No vectored op
        // and no per-block buffer is used.
        assert_eq!(
            scalar.load(AtomicOrdering::SeqCst),
            1,
            "4 contiguous data blocks must collapse to one ranged device op; \
             got {} scalar + {} vectored",
            scalar.load(AtomicOrdering::SeqCst),
            vectored.load(AtomicOrdering::SeqCst),
        );
        assert_eq!(
            vectored.load(AtomicOrdering::SeqCst),
            0,
            "the ranged read into the output buffer uses no vectored device op",
        );
    }

    #[test]
    fn durability_autopilot_prefers_more_redundancy_when_failures_observed() {
        let candidates = [1.03, 1.05, 1.10];

        let mut clean = DurabilityAutopilot::new();
        clean.observe_scrub(10_000, 0);
        let clean_decision = clean.choose_overhead(&candidates);
        assert!((clean_decision.repair_overhead - 1.03).abs() < 1e-12);

        let mut dirty = DurabilityAutopilot::new();
        dirty.observe_scrub(10_000, 300);
        let dirty_decision = dirty.choose_overhead(&candidates);
        assert!(dirty_decision.repair_overhead >= 1.05);
    }

    // ── Math helper tests ───────────────────────────────────────────────

    #[test]
    fn erfc_approx_known_values() {
        // erfc(0) = 1.0
        let val = erfc_approx(0.0);
        assert!((val - 1.0).abs() < 1e-6, "erfc(0) = {val}, expected 1.0");

        // erfc(large) → 0
        let val = erfc_approx(5.0);
        assert!(val < 1e-6, "erfc(5) = {val}, expected ~0");

        // erfc(-large) → 2
        let val = erfc_approx(-5.0);
        assert!((val - 2.0).abs() < 1e-6, "erfc(-5) = {val}, expected ~2");

        // erfc(1) ≈ 0.1573 (known value)
        let val = erfc_approx(1.0);
        assert!(
            (val - 0.1573).abs() < 0.001,
            "erfc(1) = {val}, expected ~0.1573",
        );
    }

    #[test]
    fn ln_gamma_known_values() {
        // Γ(1) = 1, ln(1) = 0
        let val = ln_gamma(1.0);
        assert!(val.abs() < 1e-10, "ln_gamma(1) = {val}, expected 0");

        // Γ(2) = 1, ln(1) = 0
        let val = ln_gamma(2.0);
        assert!(val.abs() < 1e-10, "ln_gamma(2) = {val}, expected 0");

        // Γ(5) = 24, ln(24) ≈ 3.1781
        let val = ln_gamma(5.0);
        let expected = 24.0_f64.ln();
        assert!(
            (val - expected).abs() < 1e-8,
            "ln_gamma(5) = {val}, expected {expected}",
        );

        // Γ(0.5) = √π ≈ 1.7725, ln(√π) ≈ 0.5724
        let val = ln_gamma(0.5);
        let expected = std::f64::consts::PI.sqrt().ln();
        assert!(
            (val - expected).abs() < 1e-6,
            "ln_gamma(0.5) = {val}, expected {expected}",
        );

        // Γ(10) = 9! = 362880
        let val = ln_gamma(10.0);
        let expected = 362_880.0_f64.ln();
        assert!(
            (val - expected).abs() < 1e-6,
            "ln_gamma(10) = {val}, expected {expected}",
        );
    }

    #[test]
    fn ln_gamma_zero_and_negative() {
        assert!(ln_gamma(0.0).is_infinite());
        assert!(ln_gamma(-1.0).is_infinite());
    }

    #[test]
    fn ln_beta_known_values() {
        // B(1,1) = 1, ln(1) = 0
        let val = ln_beta(1.0, 1.0);
        assert!(val.abs() < 1e-10, "ln_beta(1,1) = {val}, expected 0");

        // B(1,2) = 1/2, ln(1/2) ≈ -0.6931
        let val = ln_beta(1.0, 2.0);
        let expected = 0.5_f64.ln();
        assert!(
            (val - expected).abs() < 1e-8,
            "ln_beta(1,2) = {val}, expected {expected}",
        );

        // B(2,2) = 1/6, ln(1/6) ≈ -1.7918
        let val = ln_beta(2.0, 2.0);
        let expected = (1.0 / 6.0_f64).ln();
        assert!(
            (val - expected).abs() < 1e-8,
            "ln_beta(2,2) = {val}, expected {expected}",
        );
    }

