    #[test]
    fn resolve_duplicate_btrfs_snapshot_mount_selection_reports_format_error() {
        let source_id = BTRFS_FIRST_FREE_OBJECTID;
        let first_snapshot_id = source_id + 1;
        let second_snapshot_id = source_id + 2;
        let source_uuid = [3_u8; 16];
        let first_snapshot_uuid = [4_u8; 16];
        let second_snapshot_uuid = [5_u8; 16];
        let root_tree_items = vec![
            btrfs_test_root_item(source_id, 256, 0x5_000, source_uuid, [0; 16]),
            btrfs_test_root_item(
                first_snapshot_id,
                888,
                0x6_000,
                first_snapshot_uuid,
                source_uuid,
            ),
            btrfs_test_root_item(
                second_snapshot_id,
                999,
                0x7_000,
                second_snapshot_uuid,
                source_uuid,
            ),
            btrfs_test_root_ref(source_id, first_snapshot_id, "snap-dup"),
            btrfs_test_root_ref(source_id, second_snapshot_id, "snap-dup"),
        ];

        let err = OpenFs::resolve_btrfs_mount_selection(
            &root_tree_items,
            &BtrfsMountSelection::Snapshot("snap-dup".to_owned()),
            999,
        )
        .expect_err("duplicate snapshot names should error");

        assert!(
            matches!(&err, FfsError::Format(message) if message.contains("multiple btrfs snapshots named `snap-dup`")),
            "unexpected error: {err:?}"
        );
    }

    #[test]
    fn open_fs_from_btrfs_image() {
        let image = build_btrfs_image();
        let dev = TestDevice::from_vec(image);
        let cx = Cx::for_testing();

        let fs = OpenFs::from_device(&cx, Box::new(dev), &OpenOptions::default()).unwrap();
        assert!(fs.is_btrfs());
        assert!(!fs.is_ext4());
        assert_eq!(fs.block_size(), 4096);
        assert!(fs.ext4_geometry.is_none());
        assert!(fs.btrfs_context.is_some());

        let ctx = fs.btrfs_context().unwrap();
        assert_eq!(ctx.nodesize, 4096);
        assert_eq!(ctx.chunks.len(), 1);
    }

    #[test]
    fn btrfs_verify_file_data_csums_clean_then_detects_corruption_bd_x3fcu() {
        let cx = Cx::for_testing();
        let image = build_btrfs_csum_image();

        // The datasum file (objectid 257) has a matching EXTENT_CSUM -> verifies clean.
        let fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(image.clone())),
            &OpenOptions::default(),
        )
        .expect("open csum image");
        fs.btrfs_verify_file_data_csums(&cx, InodeNumber(257))
            .expect("uncorrupted datasum file must verify clean");

        // Flip a byte in the file's on-disk data sector -> the recomputed crc32c
        // no longer matches the csum tree, so verification reports corruption
        // (the kernel returns EIO here).
        let mut corrupt = image;
        corrupt[BTRFS_TEST_FILE_DATA_LOGICAL + 5] ^= 0xFF;
        let fs2 = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(corrupt)),
            &OpenOptions::default(),
        )
        .expect("open corrupted csum image");
        let err = fs2
            .btrfs_verify_file_data_csums(&cx, InodeNumber(257))
            .expect_err("corrupted data must be detected");
        assert!(
            matches!(err, FfsError::Corruption { .. }),
            "expected a corruption error, got {err:?}"
        );
    }

    #[test]
    fn btrfs_verify_uses_seeded_in_memory_csum_tree_when_writable_bd_x3fcu() {
        // With writes enabled, the alloc state seeds an in-memory csum tree from
        // the on-disk csum tree at mount; the verify path must consume it (not
        // re-walk the disk) and reach the same clean/corrupt verdicts.
        let cx = Cx::for_testing();
        let image = build_btrfs_csum_image();
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };

        let mut fs = OpenFs::from_device(&cx, Box::new(TestDevice::from_vec(image.clone())), &opts)
            .expect("open csum image");
        fs.enable_writes(&cx)
            .expect("enable writes seeds the csum tree");
        fs.btrfs_verify_file_data_csums(&cx, InodeNumber(257))
            .expect("clean file verifies via the seeded in-memory csum tree");

        let mut corrupt = image;
        corrupt[BTRFS_TEST_FILE_DATA_LOGICAL + 7] ^= 0xFF;
        let mut fs2 = OpenFs::from_device(&cx, Box::new(TestDevice::from_vec(corrupt)), &opts)
            .expect("open corrupted csum image");
        fs2.enable_writes(&cx).expect("enable writes");
        let err = fs2
            .btrfs_verify_file_data_csums(&cx, InodeNumber(257))
            .expect_err("corruption detected via the seeded csum tree");
        assert!(
            matches!(err, FfsError::Corruption { .. }),
            "expected a corruption error, got {err:?}"
        );
    }

    #[test]
    fn btrfs_write_captures_data_csums_for_datasum_inode_bd_x3fcu() {
        let cx = Cx::for_testing();
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(build_btrfs_csum_image())),
            &opts,
        )
        .expect("open csum image");
        fs.enable_writes(&cx).expect("enable writes");

        let count_csums = |fs: &OpenFs| -> usize {
            let alloc = fs.btrfs_alloc_state.as_ref().unwrap().read();
            let lo = BtrfsKey {
                objectid: 0,
                item_type: 0,
                offset: 0,
            };
            let hi = BtrfsKey {
                objectid: u64::MAX,
                item_type: u8::MAX,
                offset: u64::MAX,
            };
            alloc
                .csum_tree
                .range(&lo, &hi)
                .expect("range csum tree")
                .len()
        };

        let before = count_csums(&fs);
        // Append a 3-sector payload to the datasum file (objectid 257); the
        // write path must record an EXTENT_CSUM item for the new extent.
        let payload = vec![0xAB_u8; 9000];
        let fs_ops: &dyn FsOps = &fs;
        fs_ops
            .write(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(257),
                16384,
                &payload,
            )
            .expect("datasum write");
        let after = count_csums(&fs);
        assert!(
            after > before,
            "datasum write must record EXTENT_CSUM items ({before} -> {after})"
        );

        // The captured checksums verify against the bytes actually on disk.
        fs.btrfs_verify_file_data_csums(&cx, InodeNumber(257))
            .expect("captured csums verify clean");
    }

    #[test]
    fn btrfs_commit_persists_csum_tree_across_remount_bd_x3fcu() {
        let cx = Cx::for_testing();
        let dev = TestDevice::from_vec(build_btrfs_csum_image());
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };
        let mut fs =
            OpenFs::from_device(&cx, Box::new(dev.clone()), &opts).expect("open csum image");
        fs.enable_writes(&cx).expect("enable writes");

        // Append to the datasum file so the transaction is non-trivial and the
        // capture adds a fresh EXTENT_CSUM alongside the seeded one.
        let payload = vec![0x5C_u8; 9000];
        let fs_ops: &dyn FsOps = &fs;
        fs_ops
            .write(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(257),
                16384,
                &payload,
            )
            .expect("datasum write");

        // Persist the transaction: serializes the csum tree to disk and creates
        // its CSUM_TREE ROOT_ITEM in the committed root tree.
        fs.btrfs_full_transaction_commit(&cx, "csum-commit-roundtrip-test")
            .expect("full transaction commit");

        // Re-mount the committed image: the mount-time seed reloads the csum
        // tree from disk. The checksum recorded for the file's original data
        // sector (at 0x12000, in the untouched reserved region) must survive the
        // commit and match that sector's crc32c — proving the csum tree was
        // persisted in a form FrankenFS reads back.
        let committed = dev.snapshot_bytes();
        let mut fs2 = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(committed.clone())),
            &opts,
        )
        .expect("remount committed image");
        fs2.enable_writes(&cx).expect("re-seed csum tree from disk");

        let csum_items: Vec<(BtrfsKey, Vec<u8>)> = {
            let alloc = fs2.btrfs_alloc_state.as_ref().unwrap().read();
            let lo = BtrfsKey {
                objectid: 0,
                item_type: 0,
                offset: 0,
            };
            let hi = BtrfsKey {
                objectid: u64::MAX,
                item_type: u8::MAX,
                offset: u64::MAX,
            };
            alloc
                .csum_tree
                .range(&lo, &hi)
                .expect("range remounted csum tree")
        };
        let data_bytenr = BTRFS_TEST_FILE_DATA_LOGICAL as u64;
        let expected = ffs_types::crc32c(
            &committed[BTRFS_TEST_FILE_DATA_LOGICAL..BTRFS_TEST_FILE_DATA_LOGICAL + 4096],
        );
        assert_eq!(
            lookup_data_block_csum(
                &csum_items,
                data_bytenr,
                4096,
                ffs_btrfs::BTRFS_CRC32C_CSUM_SIZE
            ),
            Some(&expected.to_le_bytes()[..]),
            "committed csum tree must persist the data sector's checksum across remount"
        );
    }

    /// bd-tm48j increment 1: a newly-created subvolume fs-tree staged in
    /// `BtrfsAllocState.extra_subvol_trees` is committed as its OWN tree with a
    /// ROOT_ITEM created in the root tree pointing at it, and survives remount.
    /// Validates the multi-tree commit machinery (the foundation for
    /// create_subvolume) by seeding a minimal subvol tree, committing,
    /// remounting, and resolving the subvolume's ROOT_ITEM to its persisted
    /// tree-root bytenr (distinct from the default FS_TREE).
    #[test]
    fn btrfs_commit_persists_extra_subvol_tree_bd_tm48j() {
        // A real (mkfs) image so the metadata block group has room for a whole
        // extra tree; the hand-crafted in-memory image has only a tiny one.
        let Some((fs, dev, _tmp, _image)) = open_writable_btrfs_mkfs(256) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();
        let subvol_id = 1000_u64;

        {
            let alloc_mutex = fs.require_btrfs_alloc_state().expect("alloc state");
            let mut alloc = alloc_mutex.write();
            // A minimal subvol fs-tree: one INODE_ITEM for its root dir (inode
            // 256). The tree only needs to be non-empty so the commit serializes
            // it and assigns a bytenr; this validation reads the ROOT_ITEM, not
            // the subvol's contents.
            let max_items = ((alloc.nodesize as usize).saturating_sub(101) / 25).max(3);
            let mut subvol_tree = InMemoryCowBtrfsTree::new(max_items).expect("new subvol tree");
            let root_dir_inode = BtrfsInodeItem {
                generation: alloc.generation,
                size: 0,
                nbytes: 0,
                nlink: 2,
                uid: 0,
                gid: 0,
                mode: 0o040_755,
                rdev: 0,
                flags: 0,
                atime_sec: 0,
                atime_nsec: 0,
                ctime_sec: 0,
                ctime_nsec: 0,
                mtime_sec: 0,
                mtime_nsec: 0,
                otime_sec: 0,
                otime_nsec: 0,
            };
            subvol_tree
                .insert(
                    BtrfsKey {
                        objectid: u64::from(BTRFS_FIRST_FREE_OBJECTID),
                        item_type: BTRFS_ITEM_INODE_ITEM,
                        offset: 0,
                    },
                    &root_dir_inode.to_bytes(),
                )
                .expect("insert subvol root-dir inode");
            alloc.extra_subvol_trees.push((subvol_id, subvol_tree));
        }

        fs.btrfs_full_transaction_commit(&cx, "subvol-commit-roundtrip-test")
            .expect("full transaction commit with an extra subvol tree");

        // Re-mount the committed image and resolve the subvolume's ROOT_ITEM.
        let committed = dev.snapshot_bytes();
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };
        let mut fs2 = OpenFs::from_device(&cx, Box::new(TestDevice::from_vec(committed)), &opts)
            .expect("remount committed image");
        fs2.enable_writes(&cx).expect("enable writes on remount");

        let subvol_root = fs2
            .btrfs_fs_tree_root_bytenr(&cx, subvol_id)
            .expect("subvolume ROOT_ITEM must resolve after commit+remount");
        let fs_tree_root = fs2
            .btrfs_fs_tree_root_bytenr(&cx, BTRFS_FS_TREE_OBJECTID)
            .expect("default FS_TREE ROOT_ITEM must resolve");
        assert_ne!(
            subvol_root, 0,
            "committed subvolume tree must have a non-zero root bytenr"
        );
        assert_ne!(
            subvol_root, fs_tree_root,
            "the subvolume is a SEPARATE tree from the default FS_TREE"
        );
    }

    /// bd-tm48j increment 3a: the production btrfs_create_subvolume builds a new
    /// subvolume (its own fs-tree with a root-dir inode + a registered ROOT_ITEM)
    /// that commits and is resolvable by objectid after remount — end-to-end
    /// through the increment-1 multi-tree commit machinery.
    #[test]
    fn btrfs_create_subvolume_persists_and_resolves_bd_tm48j() {
        let Some((fs, dev, _tmp, _image)) = open_writable_btrfs_mkfs(256) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();
        let parent = InodeNumber(u64::from(BTRFS_FIRST_FREE_OBJECTID));

        let subvol_id = fs
            .create_subvolume(&cx, parent, b"mysubvol", 0, 0)
            .expect("create_subvolume");
        assert!(
            subvol_id >= u64::from(BTRFS_FIRST_FREE_OBJECTID),
            "subvolume root objectid must be a user objectid"
        );

        fs.btrfs_full_transaction_commit(&cx, "create-subvol-roundtrip-test")
            .expect("commit the new subvolume");

        let committed = dev.snapshot_bytes();
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };
        let mut fs2 = OpenFs::from_device(&cx, Box::new(TestDevice::from_vec(committed)), &opts)
            .expect("remount committed image");
        fs2.enable_writes(&cx).expect("enable writes on remount");

        let subvol_root = fs2
            .btrfs_fs_tree_root_bytenr(&cx, subvol_id)
            .expect("created subvolume ROOT_ITEM must resolve after commit+remount");
        let fs_tree_root = fs2
            .btrfs_fs_tree_root_bytenr(&cx, BTRFS_FS_TREE_OBJECTID)
            .expect("default FS_TREE ROOT_ITEM must resolve");
        assert_ne!(subvol_root, 0, "created subvolume tree must persist");
        assert_ne!(
            subvol_root, fs_tree_root,
            "the created subvolume is a SEPARATE tree from the default FS_TREE"
        );

        // Name linkage (3b): the committed ROOT_ITEM + ROOT_REF make the
        // subvolume enumerable by name from the remounted root tree.
        let root_entries: Vec<ffs_btrfs::BtrfsLeafEntry> = {
            let alloc = fs2.btrfs_alloc_state.as_ref().unwrap().read();
            let lo = BtrfsKey {
                objectid: 0,
                item_type: 0,
                offset: 0,
            };
            let hi = BtrfsKey {
                objectid: u64::MAX,
                item_type: u8::MAX,
                offset: u64::MAX,
            };
            alloc
                .root_tree
                .range(&lo, &hi)
                .unwrap()
                .into_iter()
                .map(|(key, data)| ffs_btrfs::BtrfsLeafEntry { key, data })
                .collect()
        };
        let subvols = ffs_btrfs::enumerate_subvolumes(&root_entries);
        let created = subvols
            .iter()
            .find(|s| s.id == subvol_id)
            .expect("created subvolume must be enumerated from the root tree");
        assert_eq!(
            created.name, "mysubvol",
            "subvolume is listed by its ROOT_REF name"
        );
        assert_eq!(
            created.parent_id, BTRFS_FS_TREE_OBJECTID,
            "subvolume parent is the default FS_TREE"
        );
    }

    #[test]
    fn btrfs_datasum_write_survives_commit_remount_and_reverifies_bd_x3fcu() {
        // End-to-end: a datasum write's DATA and its checksum both persist
        // through a commit and re-verify after remount. The data is written via
        // the MVCC-buffered block device, so flush_mvcc_to_device must run
        // before snapshotting (a real fsync flushes data before the metadata
        // commit); otherwise the byte-device snapshot misses the data.
        let cx = Cx::for_testing();
        let dev = TestDevice::from_vec(build_btrfs_csum_image());
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };
        let mut fs =
            OpenFs::from_device(&cx, Box::new(dev.clone()), &opts).expect("open csum image");
        fs.enable_writes(&cx).expect("enable writes");

        // Append a fresh 3-sector datasum extent (allocated outside the reserved
        // region), capturing its checksums.
        let payload = vec![0x5C_u8; 9000];
        let fs_ops: &dyn FsOps = &fs;
        fs_ops
            .write(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(257),
                16384,
                &payload,
            )
            .expect("datasum write");

        // Flush data to the byte device, then commit metadata (real fsync order).
        fs.flush_mvcc_to_device(&cx).expect("flush data to device");
        fs.btrfs_full_transaction_commit(&cx, "datasum-e2e")
            .expect("full transaction commit");

        // Re-mount the committed image and verify the file's data against the
        // persisted csum tree — the freshly written extent's data survived and
        // re-verifies, alongside the original.
        let committed = dev.snapshot_bytes();
        let fs2 = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(committed)),
            &OpenOptions::default(),
        )
        .expect("remount committed image");
        fs2.btrfs_verify_file_data_csums(&cx, InodeNumber(257))
            .expect("datasum data + checksums verify after commit and remount");
    }

    #[test]
    fn btrfs_verify_data_on_read_detects_corruption_bd_tkv2n() {
        let cx = Cx::for_testing();
        let image = build_btrfs_csum_image();
        assert!(OpenOptions::default().btrfs_verify_data_on_read);
        let opts_on = OpenOptions {
            btrfs_verify_data_on_read: true,
            ..OpenOptions::default()
        };

        // With verify-on-read enabled, a clean datasum file reads back fine.
        let fs = OpenFs::from_device(&cx, Box::new(TestDevice::from_vec(image.clone())), &opts_on)
            .expect("open csum image");
        let ops: &dyn FsOps = &fs;
        let data = ops
            .read(&cx, &mut RequestScope::empty(), InodeNumber(257), 0, 22)
            .expect("clean datasum read verifies");
        assert_eq!(data.len(), 22);

        // Corrupt the file's data sector: with verify-on-read, the read fails
        // with a corruption error (the kernel returns EIO here).
        let mut corrupt = image;
        corrupt[BTRFS_TEST_FILE_DATA_LOGICAL + 3] ^= 0xFF;
        let fs_c = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(corrupt.clone())),
            &opts_on,
        )
        .expect("open corrupted image");
        let ops_c: &dyn FsOps = &fs_c;
        let err = ops_c
            .read(&cx, &mut RequestScope::empty(), InodeNumber(257), 0, 22)
            .expect_err("corrupted datasum read must fail");
        assert!(
            matches!(err, FfsError::Corruption { .. }),
            "expected a corruption error, got {err:?}"
        );

        // With verify-on-read explicitly OFF, the same corrupt read returns data.
        //
        // This arm must CONSTRUCT the flag rather than lean on OpenOptions::default().
        // It used to say `&OpenOptions::default()` with the comment "OFF (default)",
        // which was true when the test was written and silently stopped being true
        // when the product default flipped to on (bd-6kpp4): the arm then opened with
        // verification ON and no longer tested the opt-out at all. The opt-out is
        // exactly what the still-unmeasured verify-cost delta will be measured
        // against, so it needs coverage that a default flip cannot move.
        let opts_off = OpenOptions {
            btrfs_verify_data_on_read: false,
            ..OpenOptions::default()
        };
        assert!(
            !opts_off.btrfs_verify_data_on_read,
            "the verify-off arm must be off regardless of the product default"
        );
        let fs_off = OpenFs::from_device(&cx, Box::new(TestDevice::from_vec(corrupt)), &opts_off)
            .expect("open corrupted image (verify off)");
        let ops_off: &dyn FsOps = &fs_off;
        let data_off = ops_off
            .read(&cx, &mut RequestScope::empty(), InodeNumber(257), 0, 22)
            .expect("read with verify off returns data unverified");
        assert_eq!(data_off.len(), 22);
    }

    #[allow(clippy::significant_drop_tightening)]
    fn csum_lookup_in_alloc(fs: &OpenFs, bytenr: u64) -> Option<u32> {
        let alloc = fs.btrfs_alloc_state.as_ref().unwrap().read();
        let lo = BtrfsKey {
            objectid: 0,
            item_type: 0,
            offset: 0,
        };
        let hi = BtrfsKey {
            objectid: u64::MAX,
            item_type: u8::MAX,
            offset: u64::MAX,
        };
        let items = alloc.csum_tree.range(&lo, &hi).expect("range csum tree");
        // These fixtures are crc32c images; `items` is a local, so narrow the
        // borrowed digest to an owned u32 before it goes out of scope.
        lookup_data_block_csum(&items, bytenr, 4096, ffs_btrfs::BTRFS_CRC32C_CSUM_SIZE)
            .and_then(|csum| csum.try_into().ok())
            .map(u32::from_le_bytes)
    }

    #[test]
    fn btrfs_remove_extent_csums_drops_items_in_range_bd_x3fcu() {
        let cx = Cx::for_testing();
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(build_btrfs_csum_image())),
            &opts,
        )
        .expect("open csum image");
        fs.enable_writes(&cx).expect("enable writes");

        let data_bytenr = BTRFS_TEST_FILE_DATA_LOGICAL as u64;
        let before_bytenr = data_bytenr - 4096;
        let next_bytenr = data_bytenr + 4096;
        let after_bytenr = data_bytenr + 8192;
        {
            let mut alloc = fs.btrfs_alloc_state.as_ref().unwrap().write();
            for bytenr in [before_bytenr, next_bytenr, after_bytenr] {
                alloc
                    .csum_tree
                    .upsert(
                        BtrfsKey {
                            objectid: ffs_btrfs::BTRFS_EXTENT_CSUM_OBJECTID,
                            item_type: ffs_btrfs::BTRFS_ITEM_EXTENT_CSUM,
                            offset: bytenr,
                        },
                        &u32::try_from(bytenr).unwrap_or_default().to_le_bytes(),
                    )
                    .expect("seed adjacent checksum item");
            }
        }
        assert!(
            csum_lookup_in_alloc(&fs, data_bytenr).is_some(),
            "seeded checksum present before removal"
        );
        {
            let mut alloc = fs.btrfs_alloc_state.as_ref().unwrap().write();
            OpenFs::btrfs_remove_extent_csums(&mut alloc, data_bytenr, 8192)
                .expect("remove csums for the freed range");
        }
        assert!(
            csum_lookup_in_alloc(&fs, data_bytenr).is_none(),
            "checksum for the freed range must be gone"
        );
        let alloc = fs.btrfs_alloc_state.as_ref().unwrap().read();
        let lo = BtrfsKey {
            objectid: ffs_btrfs::BTRFS_EXTENT_CSUM_OBJECTID,
            item_type: ffs_btrfs::BTRFS_ITEM_EXTENT_CSUM,
            offset: before_bytenr,
        };
        let hi = BtrfsKey {
            offset: after_bytenr,
            ..lo
        };
        let offsets = alloc
            .csum_tree
            .range(&lo, &hi)
            .expect("scan adjacent checksum items")
            .into_iter()
            .map(|(key, _)| key.offset)
            .collect::<Vec<_>>();
        assert_eq!(offsets, vec![before_bytenr, after_bytenr]);
    }

    /// bd-btrfs-orphaned-csum-items-bmksa: one `EXTENT_CSUM` item covers up to
    /// ~4064 sectors and is keyed by the first sector it covers, so freeing an
    /// extent in the MIDDLE of an item must truncate and re-key that item, not
    /// skip it (which orphans the freed range's checksums) and not delete it
    /// whole (which throws away the neighbours'). The sibling test above only
    /// ever builds single-sector items, which is why this went unnoticed until
    /// `btrfs check` reported "csum exists for 13631488-14684160 but there is
    /// no extent record" after a mounted overwrite.
    #[test]
    fn btrfs_remove_extent_csums_splits_a_multi_sector_item_bd_orphaned_csums() {
        let cx = Cx::for_testing();
        let opts = OpenOptions {
            btrfs_rw_ephemeral_ok: true,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(build_btrfs_csum_image())),
            &opts,
        )
        .expect("open csum image");
        fs.enable_writes(&cx).expect("enable writes");

        let base = BTRFS_TEST_FILE_DATA_LOGICAL as u64;
        let sector = 4096_u64;
        // One item covering four consecutive sectors, each with a checksum that
        // identifies its sector so a mis-slice is visible rather than silent.
        let csums: [[u8; 4]; 4] = [
            [0xA0, 0xA1, 0xA2, 0xA3],
            [0xB0, 0xB1, 0xB2, 0xB3],
            [0xC0, 0xC1, 0xC2, 0xC3],
            [0xD0, 0xD1, 0xD2, 0xD3],
        ];
        let key = BtrfsKey {
            objectid: ffs_btrfs::BTRFS_EXTENT_CSUM_OBJECTID,
            item_type: ffs_btrfs::BTRFS_ITEM_EXTENT_CSUM,
            offset: base,
        };
        {
            let mut alloc = fs.btrfs_alloc_state.as_ref().unwrap().write();
            alloc
                .csum_tree
                .upsert(key, &csums.concat())
                .expect("seed one four-sector checksum item");
        }

        // Free the two middle sectors: an interior hole, which forces both a
        // truncate of the prefix and a re-key of the suffix.
        {
            let mut alloc = fs.btrfs_alloc_state.as_ref().unwrap().write();
            OpenFs::btrfs_remove_extent_csums(&mut alloc, base + sector, 2 * sector)
                .expect("remove csums for the freed interior range");
        }

        let alloc = fs.btrfs_alloc_state.as_ref().unwrap().read();
        let lo = BtrfsKey { offset: 0, ..key };
        let hi = BtrfsKey {
            offset: u64::MAX,
            ..key
        };
        let items = alloc.csum_tree.range(&lo, &hi).expect("scan csum tree");
        let found: Vec<(u64, Vec<u8>)> = items
            .into_iter()
            .filter(|(k, _)| k.offset >= base && k.offset < base + 4 * sector)
            .map(|(k, v)| (k.offset, v))
            .collect();

        assert_eq!(
            found,
            vec![
                (base, csums[0].to_vec()),
                (base + 3 * sector, csums[3].to_vec()),
            ],
            "the untouched first and last sectors must keep their checksums, at \
             their own keys, and the two freed sectors must keep none"
        );
    }

    #[test]
    fn btrfs_read_logical_rejects_physical_offset_overflow_before_io() {
        let image = build_btrfs_fsops_image();
        let dev = TestDevice::from_vec(image);
        let cx = Cx::for_testing();
        let mut fs = OpenFs::from_device(&cx, Box::new(dev), &OpenOptions::default())
            .expect("open btrfs image");
        fs.btrfs_context.as_mut().expect("btrfs context").chunks[0].stripes[0].offset =
            u64::MAX - 1;

        let mut out = vec![0_u8; 4];
        let err = fs
            .btrfs_read_logical_into(&cx, 0, &mut out)
            .expect_err("overflowing physical span should fail before block I/O");

        assert!(
            matches!(&err, FfsError::Corruption { detail, .. } if detail == "btrfs physical address overflow"),
            "unexpected error: {err:?}"
        );
    }

