    #[test]
    fn btrfs_readdir_lookup_consistency() {
        // Every entry returned by readdir should be lookable.
        let image = build_btrfs_fsops_image();
        let dev = TestDevice::from_vec(image);
        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(&cx, Box::new(dev), &OpenOptions::default()).unwrap();

        let ops: &dyn FsOps = &fs;
        let entries = ops
            .readdir(&cx, &mut RequestScope::empty(), InodeNumber(1), 0)
            .unwrap();

        for entry in &entries {
            if entry.name == b"." || entry.name == b".." {
                continue;
            }
            let name = OsStr::new(std::str::from_utf8(&entry.name).unwrap());
            let attr = ops
                .lookup(&cx, &mut RequestScope::empty(), InodeNumber(1), name)
                .unwrap();
            assert_eq!(
                attr.ino,
                entry.ino,
                "lookup inode mismatch for {:?}",
                entry.name_str()
            );
            assert_eq!(
                attr.kind,
                entry.kind,
                "lookup type mismatch for {:?}",
                entry.name_str()
            );
        }
    }

