    #[test]
    fn fsops_default_write_methods_return_read_only() {
        let fs = MinimalFsOpsFixture;
        let cx = Cx::for_testing();
        let root = InodeNumber(1);

        let err = fs
            .create(
                &cx,
                &mut RequestScope::empty(),
                root,
                OsStr::new("x"),
                0o644,
                0,
                0,
            )
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .mkdir(
                &cx,
                &mut RequestScope::empty(),
                root,
                OsStr::new("d"),
                0o755,
                0,
                0,
            )
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .unlink(&cx, &mut RequestScope::empty(), root, OsStr::new("x"))
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .rmdir(&cx, &mut RequestScope::empty(), root, OsStr::new("d"))
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .fsync(&cx, &mut RequestScope::empty(), root, 0, false)
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .fsyncdir(&cx, &mut RequestScope::empty(), root, 0, false)
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        fs.flush(&cx, &mut RequestScope::empty(), root, 0, 0)
            .expect("flush default no-op");

        let err = fs
            .rename(
                &cx,
                &mut RequestScope::empty(),
                root,
                OsStr::new("a"),
                root,
                OsStr::new("b"),
            )
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .write(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(11),
                0,
                b"hello",
            )
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .setattr(
                &cx,
                &mut RequestScope::empty(),
                root,
                &SetAttrRequest::default(),
            )
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .setxattr(
                &cx,
                &mut RequestScope::empty(),
                root,
                "user.test",
                b"value",
                XattrSetMode::Set,
            )
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);

        let err = fs
            .removexattr(&cx, &mut RequestScope::empty(), root, "user.test")
            .unwrap_err();
        assert_eq!(err.to_errno(), libc::EROFS);
    }

