    /// Helper: open the ext4_small test fixture and enable writes.
    ///
    /// Returns None if the fixture doesn't exist (e.g. in minimal CI).
    fn open_writable_ext4() -> Option<OpenFs> {
        let path = std::path::Path::new("tests/fixtures/images/ext4_small.img");
        // Also check from the workspace root
        let path = if path.exists() {
            path.to_path_buf()
        } else {
            let ws = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .parent()
                .unwrap()
                .parent()
                .unwrap()
                .join("tests/fixtures/images/ext4_small.img");
            if ws.exists() {
                ws
            } else {
                // No committed fixture (CI / remote-build workers): generate an
                // in-memory ext4 image so the write-path tests that gate on this
                // helper actually run instead of silently skipping (bd-cc6ua).
                // If the format tooling is unavailable the helper still skips.
                return open_writable_ext4_mkfs(64).map(|(fs, _tmp)| fs);
            }
        };
        let cx = Cx::for_testing();
        // Copy the image so we don't mutate the fixture.
        let data = std::fs::read(&path).expect("read fixture");
        let dev = TestDevice::from_vec(data);
        let opts = OpenOptions {
            ext4_journal_replay_mode: Ext4JournalReplayMode::Skip,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(&cx, Box::new(dev), &opts).expect("open ext4");
        fs.enable_writes(&cx).expect("enable writes");
        assert!(fs.is_writable());
        Some(fs)
    }

    /// Create a fresh ext4 image via `mkfs.ext4` and open it writable.
    ///
    /// Returns `None` if `mkfs.ext4` is not available.
    #[test]
    fn dir_block_checksum_stays_valid_after_create_metadata_csum_bd_gauub() {
        // Latent correctness check: after a directory modification on a
        // metadata_csum filesystem, the modified directory block's CRC32C tail
        // must still verify, or e2fsck flags it (bd-fwph3 class).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (has_csum, seed) = {
            let sb = fs.ext4_superblock().expect("sb");
            (sb.has_metadata_csum(), sb.csum_seed())
        };
        assert!(has_csum, "generated image expected to have metadata_csum");

        fs.create(&cx, root, OsStr::new("file_a.txt"), 0o644, 0, 0)
            .expect("create");

        let root_inode = fs.read_inode(&cx, root).expect("root inode");
        let extents = fs.collect_extents(&cx, &root_inode).expect("root extents");
        let phys = extents
            .iter()
            .find(|e| e.logical_block == 0)
            .expect("root logical block 0")
            .physical_start;
        let block = fs
            .read_block_vec(&cx, BlockNumber(phys))
            .expect("read root dir block");
        ffs_ondisk::verify_dir_block_checksum(&block, seed, 2, root_inode.generation)
            .expect("root dir block checksum must be valid after a create");

        // unlink must also leave the directory block checksum valid.
        fs.unlink(&cx, root, OsStr::new("file_a.txt"))
            .expect("unlink");
        let root_inode2 = fs.read_inode(&cx, root).expect("root inode");
        let extents2 = fs.collect_extents(&cx, &root_inode2).expect("root extents");
        let phys2 = extents2
            .iter()
            .find(|e| e.logical_block == 0)
            .expect("root logical block 0")
            .physical_start;
        let block2 = fs
            .read_block_vec(&cx, BlockNumber(phys2))
            .expect("read root dir block");
        ffs_ondisk::verify_dir_block_checksum(&block2, seed, 2, root_inode2.generation)
            .expect("root dir block checksum must be valid after an unlink");
    }

    #[test]
    fn rename_keeps_dir_block_checksums_valid_bd_x4icj() {
        // Cross-parent directory rename must keep the source parent, target
        // parent, and moved directory's ('..'-updated) dir-block checksums valid
        // on a metadata_csum filesystem (bd-x4icj rename path).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (has_csum, seed) = {
            let sb = fs.ext4_superblock().expect("sb");
            (sb.has_metadata_csum(), sb.csum_seed())
        };
        assert!(has_csum, "generated image expected to have metadata_csum");

        let a = fs
            .mkdir(&cx, root, OsStr::new("a"), 0o755, 0, 0)
            .expect("mkdir a");
        let b = fs
            .mkdir(&cx, root, OsStr::new("b"), 0o755, 0, 0)
            .expect("mkdir b");
        let sub = fs
            .mkdir(&cx, a.ino, OsStr::new("sub"), 0o755, 0, 0)
            .expect("mkdir a/sub");

        fs.rename(&cx, a.ino, OsStr::new("sub"), b.ino, OsStr::new("sub"))
            .expect("cross-parent rename of a directory");

        let check = |ino: InodeNumber| {
            let inode = fs.read_inode(&cx, ino).expect("inode");
            let extents = fs.collect_extents(&cx, &inode).expect("extents");
            let phys = extents
                .iter()
                .find(|e| e.logical_block == 0)
                .expect("logical block 0")
                .physical_start;
            let block = fs
                .read_block_vec(&cx, BlockNumber(phys))
                .expect("read dir block");
            let ino_u32 = u32::try_from(ino.0).unwrap();
            ffs_ondisk::verify_dir_block_checksum(&block, seed, ino_u32, inode.generation)
        };
        check(a.ino).expect("source parent dir block checksum valid after rename");
        check(b.ino).expect("target parent dir block checksum valid after rename");
        check(sub.ino).expect("moved dir '..' block checksum valid after rename");
    }

    #[test]
    fn external_extent_blocks_carry_valid_crc32c_bd_o3wif() {
        // A file whose extent tree spills out of the inode (>4 discontiguous
        // extents -> depth >= 1) writes external index/leaf blocks. On a
        // metadata_csum image each external block must carry a valid CRC32C
        // tail keyed on the owning inode's number + generation, or e2fsck
        // reports the extent block as corrupt (bd-o3wif).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (has_csum, seed, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.has_metadata_csum(),
                sb.csum_seed(),
                u64::from(sb.block_size),
            )
        };
        assert!(has_csum, "generated image expected to have metadata_csum");

        let attr = fs
            .create(&cx, root, OsStr::new("frag.bin"), 0o644, 0, 0)
            .expect("create");
        let file_ino = attr.ino;
        let block = vec![0xAB_u8; usize::try_from(block_size).expect("bs fits usize")];
        // Write 24 single blocks each separated by a one-block hole, forcing 24
        // discontiguous extents — far past the inline root capacity of 4, so the
        // extent tree must grow to depth >= 1 and allocate external blocks.
        for i in 0..24_u64 {
            fs.write(&cx, file_ino, i * 2 * block_size, &block)
                .expect("discontiguous block write");
        }

        let inode = fs.read_inode(&cx, file_ino).expect("read inode");
        let root_bytes = OpenFs::extent_root(&inode);
        let root_depth = u16::from_le_bytes([root_bytes[6], root_bytes[7]]);
        assert!(
            root_depth >= 1,
            "test must exercise an external (depth>=1) extent tree, got depth {root_depth}"
        );

        // Collect the physical block numbers of every external node reachable
        // from the inline root, walking index nodes recursively.
        let child_block = |node: &[u8], i: usize| -> u64 {
            let off = 12 + i * 12;
            let lo =
                u32::from_le_bytes([node[off + 4], node[off + 5], node[off + 6], node[off + 7]]);
            let hi = u16::from_le_bytes([node[off + 8], node[off + 9]]);
            u64::from(lo) | (u64::from(hi) << 32)
        };
        let entries_of =
            |node: &[u8]| -> usize { usize::from(u16::from_le_bytes([node[2], node[3]])) };

        let mut stack: Vec<u64> = (0..entries_of(&root_bytes))
            .map(|i| child_block(&root_bytes, i))
            .collect();
        let mut external = Vec::new();
        while let Some(blk) = stack.pop() {
            external.push(blk);
            let bytes = fs
                .read_block_vec(&cx, BlockNumber(blk))
                .expect("read external block");
            let depth = u16::from_le_bytes([bytes[6], bytes[7]]);
            if depth >= 1 {
                for i in 0..entries_of(&bytes) {
                    stack.push(child_block(&bytes, i));
                }
            }
        }
        assert!(
            !external.is_empty(),
            "depth>=1 tree must reference at least one external block"
        );

        let file_ino_u32 = u32::try_from(file_ino.0).expect("ino fits u32");
        for blk in external {
            let bytes = fs
                .read_block_vec(&cx, BlockNumber(blk))
                .expect("read external block");
            ffs_ondisk::verify_extent_block_checksum(&bytes, seed, file_ino_u32, inode.generation)
                .unwrap_or_else(|e| {
                    panic!("external extent block {blk} has invalid CRC32C tail: {e:?}")
                });
        }
    }

    /// Splice a fabricated htree (dx-indexed) directory onto `dir_ino`, replacing
    /// its linear blocks with `htree_blocks` (block 0 = dx_root, 1.. = leaves) and
    /// setting `EXT4_INDEX_FL`. FrankenFS cannot yet *build* htree directories
    /// (bd-rzq1y), so end-to-end htree-write tests fabricate one with
    /// `ffs_ondisk::build_htree_directory_stamped` and install it here.
    #[allow(clippy::significant_drop_tightening)]
    fn install_htree_dir(fs: &OpenFs, cx: &Cx, dir_ino: InodeNumber, htree_blocks: &[Vec<u8>]) {
        let mut inode = fs.read_inode(cx, dir_ino).expect("read dir inode");
        let extents = fs.collect_extents(cx, &inode).expect("collect dir extents");
        let block0_phys = extents
            .iter()
            .find(|e| e.logical_block == 0)
            .expect("dir logical block 0")
            .physical_start;
        let block_size = u64::from(fs.ext4_superblock().expect("sb").block_size);

        let block_dev = fs.block_device_adapter();
        block_dev
            .write_block(cx, BlockNumber(block0_phys), &htree_blocks[0])
            .expect("write dx_root over block 0");

        let dir_ino_u32 = u32::try_from(dir_ino.0).expect("ino fits u32");
        let generation = inode.generation;
        let mut root_bytes = OpenFs::extent_root(&inode);
        {
            let alloc_mutex = fs.require_alloc_state().expect("alloc state");
            let mut alloc = alloc_mutex.write();
            for (i, blk) in htree_blocks.iter().enumerate().skip(1) {
                let Ext4AllocState {
                    geo,
                    groups,
                    persist_ctx,
                } = &mut *alloc;
                let ba = ffs_alloc::alloc_blocks_persist(
                    cx,
                    &block_dev,
                    geo,
                    groups,
                    1,
                    &AllocHint::default(),
                    persist_ctx,
                )
                .expect("alloc leaf block");
                block_dev
                    .write_block(cx, ba.start, blk)
                    .expect("write leaf block");
                let extent = Ext4Extent {
                    logical_block: u32::try_from(i).expect("logical fits u32"),
                    raw_len: 1,
                    physical_start: ba.start.0,
                };
                let mut tree_alloc = ffs_extent::GroupBlockAllocator {
                    cx,
                    dev: &block_dev,
                    geo,
                    groups,
                    hint: AllocHint::default(),
                    pctx: persist_ctx,
                    ino: dir_ino_u32,
                    generation,
                };
                ffs_btree::insert(cx, &block_dev, &mut root_bytes, extent, &mut tree_alloc)
                    .expect("insert leaf extent");
            }
        }
        OpenFs::set_extent_root(&mut inode, &root_bytes);
        inode.flags |= ffs_types::EXT4_INDEX_FL;
        inode.size = u64::try_from(htree_blocks.len()).unwrap() * block_size;
        fs.persist_ext4_inode_for_testing(cx, dir_ino, &inode)
            .expect("persist htree dir inode");
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn create_in_htree_dir_preserves_index_and_finds_new_entry_bd_wb4cd() {
        // End-to-end proof of the bd-wb4cd routing fix: creating a file in a real
        // htree directory must (a) leave the dx_root index intact (not the prior
        // dx-root-overwriting corruption) and (b) place the new entry in its
        // hash-correct leaf so htree_find_entry reaches it via the index.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, has_large_dir, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.has_large_dir(),
                // Build with the effective (signed/unsigned-resolved) version so
                // the fabricated hashes match what the fs computes on lookup; the
                // effective versions are fixed points of effective_dirhash_version.
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let dir = fs
            .mkdir(&cx, root, OsStr::new("bigdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;

        // Fabricate a real dx_root + multi-leaf htree (300 entries).
        let names: Vec<Vec<u8>> = (0..300)
            .map(|i| format!("file_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    1000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(
            blocks.len() >= 3,
            "need dx_root + multiple leaves, got {}",
            blocks.len()
        );
        install_htree_dir(&fs, &cx, dir_ino, &blocks);

        let find = |name: &[u8]| -> ffs_ondisk::HtreeFindResult {
            ffs_ondisk::htree_find_entry(
                u32::try_from(block_size).unwrap(),
                &hash_seed,
                has_large_dir,
                name,
                |v| v,
                |lb| {
                    let inode = fs.read_inode(&cx, dir_ino).ok()?;
                    let exts = fs.collect_extents(&cx, &inode).ok()?;
                    let phys = exts.iter().find_map(|e| {
                        let len = u32::from(e.actual_len());
                        if lb >= e.logical_block && lb < e.logical_block + len {
                            Some(e.physical_start + u64::from(lb - e.logical_block))
                        } else {
                            None
                        }
                    })?;
                    fs.read_block_vec(&cx, BlockNumber(phys)).ok()
                },
            )
        };

        assert!(
            fs.read_inode(&cx, dir_ino).unwrap().has_htree_index(),
            "installed dir must be htree-indexed"
        );
        assert!(
            matches!(
                find(b"file_0100.txt"),
                ffs_ondisk::HtreeFindResult::Found(_)
            ),
            "pre-existing entry must be index-reachable before the create"
        );

        // Operation under test: create a NEW file in the htree directory.
        let created = fs
            .create(&cx, dir_ino, OsStr::new("zzz_new_entry.bin"), 0o644, 0, 0)
            .expect("create in htree dir must succeed without corrupting the index");

        // (a) dx_root (block 0) still parses as a valid index — NOT overwritten.
        let block0_phys = {
            let di = fs.read_inode(&cx, dir_ino).unwrap();
            fs.collect_extents(&cx, &di)
                .unwrap()
                .iter()
                .find(|e| e.logical_block == 0)
                .unwrap()
                .physical_start
        };
        let dxr = fs.read_block_vec(&cx, BlockNumber(block0_phys)).unwrap();
        let parsed = ffs_ondisk::parse_dx_root(&dxr)
            .expect("dx_root must still parse after the create (no corruption)");
        assert!(
            !parsed.entries.is_empty(),
            "dx_root index entries must survive the create"
        );

        // (b) the new entry is reachable VIA THE INDEX (hash-correct leaf).
        match find(b"zzz_new_entry.bin") {
            ffs_ondisk::HtreeFindResult::Found(e) => {
                assert_eq!(e.inode, u32::try_from(created.ino.0).unwrap());
            }
            other => panic!("new htree entry must be index-reachable, got {other:?}"),
        }
        // (c) a pre-existing entry remains index-reachable.
        assert!(
            matches!(
                find(b"file_0100.txt"),
                ffs_ondisk::HtreeFindResult::Found(_)
            ),
            "pre-existing entry must remain index-reachable after the create"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn fast_commit_create_apply_into_htree_dir_bd_w6fxn() {
        // bd-w6fxn: a fast-committed create whose parent is an htree (large)
        // directory. CREAT recovery must descend the DX index and splice the new
        // entry into the hash-correct leaf — reaching realistic directories the
        // linear path skips — keeping the index consistent (no dx surgery).
        //
        // The apply is a recovery (from_device) operation: it reads the device
        // directly, not the MVCC overlay. So we build the htree dir on a writable
        // fs, flush it to the device, then REOPEN from_device and run the apply
        // there (mirroring a real post-crash mount).
        let Some((fs, dev, _tmp)) = open_writable_ext4_mkfs_with_device(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, has_large_dir, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.has_large_dir(),
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let dir = fs
            .mkdir(&cx, root, OsStr::new("bigdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;

        // A real target inode the recovered entry will point at (CREAT reads its
        // mode for the dir-entry file type).
        let target = fs
            .create(&cx, root, OsStr::new("target.bin"), 0o644, 0, 0)
            .expect("create target file");
        let target_ino_u32 = u32::try_from(target.ino.0).unwrap();

        // Fabricate the htree blocks now (needs the dir generation). Keep the
        // entry count small so the leaf the name hashes to always has ample room
        // — mkfs picks a RANDOM hash seed each run, so a near-full multi-leaf
        // layout would make the (no-split) recovery apply flakily hit a full
        // leaf. A small dir is still genuinely htree-indexed (dx_root + leaf).
        let names: Vec<Vec<u8>> = (0..20)
            .map(|i| format!("file_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    1000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(blocks.len() >= 2, "need dx_root + at least one leaf");

        // Land the MVCC writes (mkdir/create) on the device FIRST, then install
        // the htree blocks directly (so the direct dir-inode write is not later
        // clobbered by a flush of the pre-htree MVCC dir inode).
        fs.flush_mvcc_to_device(&cx).expect("flush mvcc");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);

        // Reopen from the device so reads ARE the device (not the MVCC overlay).
        // Skip journal replay: install_htree_dir's direct, non-journaled writes
        // would otherwise be clobbered by replaying the pre-htree committed
        // journal transactions (a flaky-under-parallelism failure depending on
        // whether the flush left a pending transaction).
        let reopen_opts = OpenOptions {
            ext4_journal_replay_mode: Ext4JournalReplayMode::Skip,
            ..OpenOptions::default()
        };
        let fs2 = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(dev.snapshot_bytes())),
            &reopen_opts,
        )
        .expect("reopen ext4 from device");
        let find = |name: &[u8]| -> ffs_ondisk::HtreeFindResult {
            ffs_ondisk::htree_find_entry(
                u32::try_from(block_size).unwrap(),
                &hash_seed,
                has_large_dir,
                name,
                |v| v,
                |lb| {
                    let inode = fs2.read_inode(&cx, dir_ino).ok()?;
                    let exts = fs2.collect_extents(&cx, &inode).ok()?;
                    let phys = exts.iter().find_map(|e| {
                        let len = u32::from(e.actual_len());
                        if lb >= e.logical_block && lb < e.logical_block + len {
                            Some(e.physical_start + u64::from(lb - e.logical_block))
                        } else {
                            None
                        }
                    })?;
                    fs2.read_block_vec(&cx, BlockNumber(phys)).ok()
                },
            )
        };

        assert!(
            fs2.read_inode(&cx, dir_ino).unwrap().has_htree_index(),
            "installed dir must be htree-indexed on the device"
        );
        assert!(
            matches!(
                find(b"file_0005.txt"),
                ffs_ondisk::HtreeFindResult::Found(_)
            ),
            "pre-existing entry must be index-reachable before recovery"
        );
        assert!(
            matches!(
                find(b"zzz_recovered.bin"),
                ffs_ondisk::HtreeFindResult::NotFoundInIndex
            ),
            "the recovered name must be absent before recovery"
        );

        // Operation under test: recover the fast-committed CREAT.
        let dentry = ffs_journal::FcDentry {
            parent_ino: dir_ino_u32,
            ino: target_ino_u32,
            name: b"zzz_recovered.bin".to_vec(),
        };
        let applied = fs2
            .apply_fast_commit_add_dentry(&cx, &dentry)
            .expect("apply htree create");
        assert!(applied, "entry should splice into the hash-correct leaf");

        // (a) the recovered entry is reachable VIA THE INDEX (hash-correct leaf).
        match find(b"zzz_recovered.bin") {
            ffs_ondisk::HtreeFindResult::Found(e) => assert_eq!(e.inode, target_ino_u32),
            other => panic!("recovered htree entry must be index-reachable, got {other:?}"),
        }
        // (b) dx_root still parses (the index was not corrupted).
        let block0_phys = {
            let di = fs2.read_inode(&cx, dir_ino).unwrap();
            fs2.collect_extents(&cx, &di)
                .unwrap()
                .iter()
                .find(|e| e.logical_block == 0)
                .unwrap()
                .physical_start
        };
        let dxr = fs2.read_block_vec(&cx, BlockNumber(block0_phys)).unwrap();
        let parsed = ffs_ondisk::parse_dx_root(&dxr).expect("dx_root must still parse");
        assert!(!parsed.entries.is_empty(), "dx_root index must survive");
        // (c) a pre-existing entry remains index-reachable.
        assert!(
            matches!(
                find(b"file_0005.txt"),
                ffs_ondisk::HtreeFindResult::Found(_)
            ),
            "pre-existing entry must remain index-reachable after recovery"
        );
    }

    /// Corruption-critical gate (bd-owt2r / bd-vsuni): inserting a NON-ASCII name
    /// into a CASEFOLD htree directory must be REFUSED, never silently inserted.
    /// FrankenFS's non-ASCII fold diverges from the kernel's NFD-normalized
    /// casefold, so it cannot compute the fold-correct dx leaf — writing the entry
    /// anyway would place it in the WRONG leaf, where the kernel's own (correct-
    /// fold) descent would never find it (silent data loss). This pins the refusal
    /// on every insertion entry point — create / link / rename, all of which route
    /// through ext4_add_dir_entry — and that a refused op leaves NO partial entry.
    /// Previously only the ASCII-create success path was covered. Remove these
    /// asserts when byte-exact UTF-8 normalization lands (bd-vsuni).
    #[test]
    fn casefold_htree_rejects_non_ascii_insert_bd_owt2r() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        // Build an htree-indexed directory and mark it casefold.
        let dir = fs
            .mkdir(&cx, root, OsStr::new("casedir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;
        let names: Vec<Vec<u8>> = (0..30)
            .map(|i| format!("file_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    1000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);
        {
            let mut inode = fs.read_inode(&cx, dir_ino).expect("read dir inode");
            inode.flags |= ffs_types::EXT4_CASEFOLD_FL;
            fs.persist_ext4_inode_for_testing(&cx, dir_ino, &inode)
                .expect("set casefold flag");
        }
        assert!(
            fs.read_inode(&cx, dir_ino)
                .expect("re-read")
                .has_htree_index(),
            "the casefold test dir must be htree-indexed for the gate to apply"
        );

        // café.txt — the 'é' (U+00E9) makes this non-ASCII.
        let non_ascii = OsStr::new("café.txt");

        // create: refused, with no partial entry left behind.
        let create_res = fs.create(&cx, dir_ino, non_ascii, 0o644, 0, 0);
        assert!(
            create_res.is_err(),
            "non-ASCII create in a casefold htree dir must be refused, got {create_res:?}"
        );
        assert!(
            fs.lookup(&cx, dir_ino, non_ascii).is_err(),
            "a refused non-ASCII create must not leave a partial dir entry (silent corruption)"
        );

        // link: same gate.
        let target = fs
            .create(&cx, root, OsStr::new("linktgt.txt"), 0o644, 0, 0)
            .expect("create link target");
        let link_res = fs.link(&cx, target.ino, dir_ino, OsStr::new("résumé"));
        assert!(
            link_res.is_err(),
            "non-ASCII link into a casefold htree dir must be refused, got {link_res:?}"
        );

        // rename: move an ASCII file in root to a non-ASCII name in the casefold dir.
        fs.create(&cx, root, OsStr::new("mover.txt"), 0o644, 0, 0)
            .expect("create mover");
        let rename_res = fs.rename(
            &cx,
            root,
            OsStr::new("mover.txt"),
            dir_ino,
            OsStr::new("naïve.txt"),
        );
        assert!(
            rename_res.is_err(),
            "non-ASCII rename into a casefold htree dir must be refused, got {rename_res:?}"
        );
        // The source name must survive a refused rename (no half-applied move).
        assert!(
            fs.lookup(&cx, root, OsStr::new("mover.txt")).is_ok(),
            "a refused rename must leave the source entry intact"
        );

        // SAME-PARENT rename to a non-ASCII name (within the casefold dir itself):
        // an ASCII file already living in the casefold dir, renamed to a non-ASCII
        // name in place, must also refuse atomically — the gate lives in the shared
        // preflight, so it fires regardless of whether the parents differ.
        fs.create(&cx, dir_ino, OsStr::new("inplace.txt"), 0o644, 0, 0)
            .expect("create ascii file inside casefold dir");
        let same_parent_res = fs.rename(
            &cx,
            dir_ino,
            OsStr::new("inplace.txt"),
            dir_ino,
            OsStr::new("élan.txt"),
        );
        assert!(
            same_parent_res.is_err(),
            "non-ASCII same-parent rename in a casefold htree dir must be refused, got {same_parent_res:?}"
        );
        assert!(
            fs.lookup(&cx, dir_ino, OsStr::new("inplace.txt")).is_ok(),
            "a refused same-parent rename must leave the source entry intact"
        );
    }

    /// A non-ASCII create/mkdir into a casefold htree dir is refused by the gate
    /// INSIDE ext4_add_dir_entry — i.e. AFTER the new inode is already allocated.
    /// The op must then roll back that allocation (ext4_create/ext4_mkdir call
    /// delete_inode on the add failure) or it leaks an inode. The existing
    /// rollback test triggers failure via an invalid name, which fails in
    /// validate_single_path_component BEFORE any allocation, so it never exercises
    /// this post-allocation rollback path. This pins it: the free-inode count must
    /// be identical before and after the refused create AND the refused mkdir
    /// (16 MiB image == one block group, so the group-0 count is the whole fs).
    #[test]
    fn casefold_htree_refused_insert_rolls_back_inode_alloc_bd_owt2r() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return; // mkfs.ext4 unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };
        let dir = fs
            .mkdir(&cx, root, OsStr::new("casedir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;
        let names: Vec<Vec<u8>> = (0..30)
            .map(|i| format!("file_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    1000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);
        {
            let mut inode = fs.read_inode(&cx, dir_ino).expect("read dir inode");
            inode.flags |= ffs_types::EXT4_CASEFOLD_FL;
            fs.persist_ext4_inode_for_testing(&cx, dir_ino, &inode)
                .expect("set casefold flag");
        }

        let free_before = fs
            .count_free_inodes_in_group(&cx, GroupNumber(0))
            .expect("free inode count");

        // Refused non-ASCII create — the gate fires after create_inode allocated
        // the inode, so the create must delete_inode to roll it back.
        let create_res = fs.create(&cx, dir_ino, OsStr::new("café.txt"), 0o644, 0, 0);
        assert!(create_res.is_err(), "non-ASCII create must be refused");
        let free_after_create = fs
            .count_free_inodes_in_group(&cx, GroupNumber(0))
            .expect("free inode count");
        assert_eq!(
            free_after_create, free_before,
            "a refused casefold create must roll back (free) its allocated inode, not leak it"
        );

        // Refused non-ASCII mkdir — same post-allocation rollback (a directory
        // inode also charges used_dirs, which delete_inode must release).
        let mkdir_res = fs.mkdir(&cx, dir_ino, OsStr::new("ÜberDir"), 0o755, 0, 0);
        assert!(mkdir_res.is_err(), "non-ASCII mkdir must be refused");
        let free_after_mkdir = fs
            .count_free_inodes_in_group(&cx, GroupNumber(0))
            .expect("free inode count");
        assert_eq!(
            free_after_mkdir, free_before,
            "a refused casefold mkdir must roll back (free) its allocated inode, not leak it"
        );
    }

    /// bd-owt2r (insert side, end-to-end): creating an ASCII-named file in a
    /// CASEFOLD htree directory now succeeds (was UnsupportedFeature) and places
    /// the entry in the fold-correct leaf, so a case-insensitive lookup finds it.
    #[test]
    #[allow(clippy::too_many_lines)]
    fn create_in_casefold_htree_dir_finds_new_entry_via_fold_bd_owt2r() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, has_large_dir, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.has_large_dir(),
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let dir = fs
            .mkdir(&cx, root, OsStr::new("casedir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;

        // A casefold dir hashes by the folded name. Build the index from LOWERCASE
        // names so the stored hashes equal the kernel's casefold (ASCII) hashes.
        // Keep the count modest so leaves retain free space — this exercises the
        // common non-full-leaf insert (the leaf-full casefold rebuild is deferred).
        let names: Vec<Vec<u8>> = (0..30)
            .map(|i| format!("file_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    1000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(blocks.len() >= 2, "need dx_root + at least one leaf");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);

        // Mark the directory casefold.
        {
            let mut inode = fs.read_inode(&cx, dir_ino).expect("read dir inode");
            inode.flags |= ffs_types::EXT4_CASEFOLD_FL;
            fs.persist_ext4_inode_for_testing(&cx, dir_ino, &inode)
                .expect("set casefold flag");
        }

        let find_casefold = |name: &[u8]| -> ffs_ondisk::HtreeFindResult {
            ffs_ondisk::htree_find_entry_casefold(
                u32::try_from(block_size).unwrap(),
                &hash_seed,
                has_large_dir,
                name,
                |v| v,
                |lb| {
                    let inode = fs.read_inode(&cx, dir_ino).ok()?;
                    let exts = fs.collect_extents(&cx, &inode).ok()?;
                    let phys = exts.iter().find_map(|e| {
                        let len = u32::from(e.actual_len());
                        if lb >= e.logical_block && lb < e.logical_block + len {
                            Some(e.physical_start + u64::from(lb - e.logical_block))
                        } else {
                            None
                        }
                    })?;
                    fs.read_block_vec(&cx, BlockNumber(phys)).ok()
                },
            )
        };

        // A pre-existing entry is reachable via a CASE-VARIANT (uppercase) query.
        assert!(
            matches!(
                find_casefold(b"FILE_0010.TXT"),
                ffs_ondisk::HtreeFindResult::Found(_)
            ),
            "case-variant lookup of a pre-existing casefold entry must hit the index"
        );

        // Operation under test: create a file with an UPPERCASE name in the
        // casefold dir (previously returned UnsupportedFeature).
        let created = fs
            .create(&cx, dir_ino, OsStr::new("ZZZ_NEW_ENTRY.BIN"), 0o644, 0, 0)
            .expect("create in casefold htree dir must now succeed");

        // The new entry is reachable via the folded (lowercase) query through the
        // index — i.e. it was placed in the fold-correct leaf.
        match find_casefold(b"zzz_new_entry.bin") {
            ffs_ondisk::HtreeFindResult::Found(e) => {
                assert_eq!(e.inode, u32::try_from(created.ino.0).unwrap());
                assert_eq!(e.name, b"ZZZ_NEW_ENTRY.BIN", "original case is stored");
            }
            other => panic!("new casefold entry must be index-reachable, got {other:?}"),
        }

        // dx_root still parses (index not corrupted).
        let block0_phys = {
            let di = fs.read_inode(&cx, dir_ino).unwrap();
            fs.collect_extents(&cx, &di)
                .unwrap()
                .iter()
                .find(|e| e.logical_block == 0)
                .unwrap()
                .physical_start
        };
        let dxr = fs.read_block_vec(&cx, BlockNumber(block0_phys)).unwrap();
        assert!(
            !ffs_ondisk::parse_dx_root(&dxr)
                .expect("dx_root parses")
                .entries
                .is_empty(),
            "dx_root index must survive the casefold create"
        );
    }

    /// bd-4y9ca regression guard: ext4 inline-data DIRECTORY operations must fail
    /// loudly (UnsupportedFeature / Err), never silently see an empty/block-mapped
    /// directory. FrankenFS has no inline-directory parser; a silent empty readdir
    /// would let rmdir drop a non-empty inline dir, and a silent insert would
    /// overwrite the inline entries with a fresh extent root — both data loss. This
    /// pins the comprehensive guard coverage across readdir/lookup/create/unlink/rmdir
    /// so a future dir-op path cannot regress it.
    #[test]
    fn inline_data_directory_ops_fail_loudly_not_silently_bd_4y9ca() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let dir = fs
            .mkdir(&cx, root, OsStr::new("inlinedir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        // A real child so that a "silently empty" view would be an observable
        // data-loss bug (rmdir would think the dir is empty and drop it).
        fs.create(&cx, dir_ino, OsStr::new("child.txt"), 0o644, 0, 0)
            .expect("create child");

        // Mark the directory inline-data, as a kernel-created inline dir would be.
        {
            let mut inode = fs.read_inode(&cx, dir_ino).expect("read dir inode");
            inode.flags |= ffs_types::EXT4_INLINE_DATA_FL;
            inode.flags &= !ffs_types::EXT4_COMPR_FL;
            fs.persist_ext4_inode_for_testing(&cx, dir_ino, &inode)
                .expect("mark inline-data");
        }
        let inline_inode = fs.read_inode(&cx, dir_ino).expect("reread dir inode");

        // readdir / lookup must reject rather than return an empty / not-found view.
        assert!(
            matches!(
                fs.read_dir(&cx, &inline_inode),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "inline-dir readdir must fail loudly, not return an empty listing"
        );
        assert!(
            matches!(
                fs.lookup_name(&cx, &inline_inode, b"child.txt"),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "inline-dir lookup must fail loudly"
        );
        // create / unlink / rmdir must all error, never silently mutate a block view.
        assert!(
            fs.create(&cx, dir_ino, OsStr::new("new.txt"), 0o644, 0, 0)
                .is_err(),
            "create into an inline dir must fail, not overwrite the inline entries"
        );
        assert!(
            fs.unlink(&cx, dir_ino, OsStr::new("child.txt")).is_err(),
            "unlink from an inline dir must fail"
        );
        assert!(
            fs.rmdir(&cx, root, OsStr::new("inlinedir")).is_err(),
            "rmdir of a (non-empty) inline dir must fail, not silently drop it"
        );
    }

    /// The readdir snapshot must never serve a stale listing after a rename moves
    /// an entry OUT of the directory — even if the rename does not bump the source
    /// directory's timestamps (which the snapshot's self-validation keys on).
    #[test]
    fn readdir_snapshot_reflects_rename_out_of_source_dir() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let a = fs
            .mkdir(&cx, root, OsStr::new("A"), 0o755, 0, 0)
            .unwrap()
            .ino;
        let b = fs
            .mkdir(&cx, root, OsStr::new("B"), 0o755, 0, 0)
            .unwrap()
            .ino;
        fs.create(&cx, a, OsStr::new("x.txt"), 0o644, 0, 0).unwrap();

        // Populate A's readdir snapshot.
        let before = fs.readdir(&cx, a, 0).unwrap();
        assert!(
            before.iter().any(|e| e.name == b"x.txt"),
            "x.txt must be listed before the rename"
        );

        // Move x.txt out of A into B.
        fs.rename(&cx, a, OsStr::new("x.txt"), b, OsStr::new("x.txt"))
            .unwrap();

        // A must no longer list x.txt (no stale snapshot).
        let after = fs.readdir(&cx, a, 0).unwrap();
        assert!(
            !after.iter().any(|e| e.name == b"x.txt"),
            "readdir of the source dir must not show an entry renamed out of it"
        );
        // And B must now list it.
        let blist = fs.readdir(&cx, b, 0).unwrap();
        assert!(
            blist.iter().any(|e| e.name == b"x.txt"),
            "renamed entry must appear in the destination dir"
        );
    }

    /// Paginated readdir must read+parse the directory ONCE and serve later pages
    /// from the snapshot, not re-parse the whole dir per page (O(N) vs O(N^2)),
    /// while producing byte-identical entries; a mutation invalidates the snapshot.
    #[test]
    fn readdir_pagination_serves_pages_from_one_parse_not_quadratic() {
        use std::sync::atomic::Ordering::SeqCst;
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let dir = fs
            .mkdir(&cx, root, OsStr::new("bigdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let n = 50usize;
        for i in 0..n {
            fs.create(&cx, dir_ino, OsStr::new(&format!("f{i:04}")), 0o644, 0, 0)
                .expect("create entry");
        }

        // One full read builds the snapshot; every paginated page is then served
        // from it (the prior behaviour re-parsed the whole dir on each page).
        fs.readdir_full_reads.store(0, SeqCst);
        let full = fs.readdir(&cx, dir_ino, 0).expect("readdir full");
        assert!(
            full.len() >= n,
            "directory must list all {n} entries (+ '.' '..')"
        );

        let page = 7usize;
        let mut collected: Vec<DirEntry> = Vec::new();
        let mut off = 0u64;
        loop {
            let chunk = fs.readdir(&cx, dir_ino, off).expect("readdir page");
            if chunk.is_empty() {
                break;
            }
            let take: Vec<DirEntry> = chunk.iter().take(page).cloned().collect();
            off = take.last().expect("non-empty page").offset;
            collected.extend(take);
            if collected.len() >= full.len() {
                break;
            }
        }

        // ISOMORPHISM: the paginated listing equals the single full listing.
        assert_eq!(
            collected, full,
            "paginated readdir must equal the full listing"
        );

        // SCORE: one full parse served the full read + all paginated pages; the
        // prior per-call rescan would have parsed once per call.
        let pages = (full.len()).div_ceil(page);
        assert!(
            pages >= 3,
            "need several pages for a meaningful score (got {pages})"
        );
        assert_eq!(
            fs.readdir_full_reads.load(SeqCst),
            1,
            "snapshot must serve {pages}+ pages from a single directory parse"
        );

        // A mutation invalidates the snapshot (forces a fresh parse) and the new
        // entry is visible.
        fs.create(&cx, dir_ino, OsStr::new("zzz_new"), 0o644, 0, 0)
            .expect("create after listing");
        fs.readdir_full_reads.store(0, SeqCst);
        let after = fs.readdir(&cx, dir_ino, 0).expect("readdir after mutation");
        assert_eq!(
            fs.readdir_full_reads.load(SeqCst),
            1,
            "a directory mutation must invalidate the snapshot"
        );
        assert!(
            after.iter().any(|e| e.name == b"zzz_new"),
            "newly created entry must appear after snapshot invalidation"
        );
    }

    /// A FrankenFS-created (initially linear) directory must auto-convert to an
    /// htree once it outgrows linear blocks (when the fs has dir_index, like the
    /// kernel), so mass-create is O(N) (htree + doubling rebuilds) and lookups are
    /// O(log N) — not O(blocks). Every entry stays findable across the conversion.
    #[test]
    #[allow(clippy::too_many_lines)]
    fn fresh_linear_dir_auto_converts_to_htree_on_overflow() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(32) else {
            return;
        };
        let cx = Cx::for_testing();
        // The conversion only applies when the filesystem supports hash indexing.
        let has_dir_index = fs
            .ext4_superblock()
            .is_some_and(|sb| sb.has_compat(ffs_ondisk::ext4::Ext4CompatFeatures::DIR_INDEX));
        if !has_dir_index {
            return;
        }
        let root = InodeNumber(2);
        let dir = fs
            .mkdir(&cx, root, OsStr::new("growdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        assert!(
            !fs.read_inode(&cx, dir_ino).unwrap().has_htree_index(),
            "a freshly created directory must start linear (no htree index)"
        );

        // Create enough files to overflow the initial linear block(s) and trigger
        // the linear -> htree conversion.
        let n = 400usize;
        for i in 0..n {
            let nm = format!("f{i:05}.dat");
            fs.create(&cx, dir_ino, OsStr::new(&nm), 0o644, 0, 0)
                .unwrap_or_else(|e| panic!("create {nm} must succeed: {e:?}"));
        }

        // The directory must now be hash-indexed (auto-converted), with a valid
        // dx_root, and every entry must remain findable.
        assert!(
            fs.read_inode(&cx, dir_ino).unwrap().has_htree_index(),
            "directory must auto-convert to htree once it overflows linear blocks"
        );
        let block0_phys = {
            let di = fs.read_inode(&cx, dir_ino).unwrap();
            fs.collect_extents(&cx, &di)
                .unwrap()
                .iter()
                .find(|e| e.logical_block == 0)
                .unwrap()
                .physical_start
        };
        let dxr = fs.read_block_vec(&cx, BlockNumber(block0_phys)).unwrap();
        assert!(
            !ffs_ondisk::parse_dx_root(&dxr)
                .expect("converted block 0 must parse as a dx_root")
                .entries
                .is_empty(),
            "converted dx_root must index at least one leaf"
        );

        let listing = fs.readdir(&cx, dir_ino, 0).expect("readdir");
        let names: std::collections::HashSet<Vec<u8>> =
            listing.iter().map(|e| e.name.clone()).collect();
        for i in 0..n {
            let nm = format!("f{i:05}.dat").into_bytes();
            assert!(
                names.contains(&nm),
                "entry {i} missing from converted htree dir"
            );
        }
        // A direct lookup must also resolve through the new index.
        assert!(
            fs.lookup(&cx, dir_ino, OsStr::new("f00200.dat")).is_ok(),
            "lookup must resolve via the converted htree index"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn many_creates_in_htree_dir_trigger_rebuild_and_keep_all_findable_bd_rzq1y() {
        // Filling a hash-target leaf forces ext4_rebuild_htree_dir (bd-rzq1y).
        // After many creates the directory must have grown new blocks (only the
        // rebuild path allocates for an htree dir) and EVERY entry — original and
        // newly created — must remain reachable via the index in its hash-correct
        // leaf, with the dx_root still valid.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(32) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, has_large_dir, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.has_large_dir(),
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let dir = fs
            .mkdir(&cx, root, OsStr::new("growdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;

        let orig_names: Vec<Vec<u8>> = (0..200)
            .map(|i| format!("orig_{i:04}.txt").into_bytes())
            .collect();
        let orig_entries: Vec<(u32, u8, &[u8])> = orig_names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    5000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &orig_entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(blocks.len() >= 2, "need a dx_root + at least one leaf");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);
        let initial_size = fs.read_inode(&cx, dir_ino).unwrap().size;

        // Create enough new files to overflow leaves. With the bd-gauub
        // incremental leaf-split fast path each overflow now splits ONE full leaf
        // (O(log N)) instead of rebuilding the whole index, so the overflow is
        // serviced by `htree_leaf_splits`, not `htree_rebuilds`.
        fs.htree_rebuilds
            .store(0, std::sync::atomic::Ordering::SeqCst);
        fs.htree_leaf_splits
            .store(0, std::sync::atomic::Ordering::SeqCst);
        let mut new_names: Vec<Vec<u8>> = Vec::new();
        for i in 0..600 {
            let nm = format!("created_{i:04}.dat");
            fs.create(&cx, dir_ino, OsStr::new(&nm), 0o644, 0, 0)
                .unwrap_or_else(|e| panic!("create {nm} must succeed: {e:?}"));
            new_names.push(nm.into_bytes());
        }

        // The directory must have grown — both the split and the rebuild paths
        // allocate blocks for an htree dir, so growth proves the overflow path ran.
        let final_size = fs.read_inode(&cx, dir_ino).unwrap().size;
        assert!(
            final_size > initial_size,
            "htree dir must have grown via leaf split: {initial_size} -> {final_size}"
        );

        // SCORE (bd-gauub): the overflow is serviced by INCREMENTAL leaf splits,
        // not full rebuilds. The single-level fast path handles every overflow
        // here (the dx_root has ample room for ~50 leaves at this block size), so
        // the rebuild path must NOT run, and the split path must run repeatedly —
        // each split is O(log N), making the whole create burst O(N log N) rather
        // than the O(N^2) the per-create full rebuild would cost.
        let rebuilds = fs.htree_rebuilds.load(std::sync::atomic::Ordering::SeqCst);
        let leaf_splits = fs
            .htree_leaf_splits
            .load(std::sync::atomic::Ordering::SeqCst);
        assert!(
            leaf_splits > 0,
            "the incremental leaf-split fast path must have run at least once"
        );
        assert_eq!(
            rebuilds, 0,
            "single-level overflow must split incrementally, not rebuild (got {rebuilds} rebuilds, {leaf_splits} splits)"
        );

        let find = |name: &[u8]| -> ffs_ondisk::HtreeFindResult {
            ffs_ondisk::htree_find_entry(
                u32::try_from(block_size).unwrap(),
                &hash_seed,
                has_large_dir,
                name,
                |v| v,
                |lb| {
                    let inode = fs.read_inode(&cx, dir_ino).ok()?;
                    let exts = fs.collect_extents(&cx, &inode).ok()?;
                    let phys = exts.iter().find_map(|e| {
                        let len = u32::from(e.actual_len());
                        if lb >= e.logical_block && lb < e.logical_block + len {
                            Some(e.physical_start + u64::from(lb - e.logical_block))
                        } else {
                            None
                        }
                    })?;
                    fs.read_block_vec(&cx, BlockNumber(phys)).ok()
                },
            )
        };

        // Every created entry is reachable via the index in its hash-correct leaf.
        for nm in &new_names {
            assert!(
                matches!(find(nm), ffs_ondisk::HtreeFindResult::Found(_)),
                "created entry {:?} must be index-reachable after rebuild",
                String::from_utf8_lossy(nm)
            );
        }
        // A sample of the original entries survived the rebuild(s).
        for i in (0..200).step_by(17) {
            let nm = format!("orig_{i:04}.txt").into_bytes();
            assert!(
                matches!(find(&nm), ffs_ondisk::HtreeFindResult::Found(_)),
                "original entry {:?} must survive the rebuild(s)",
                String::from_utf8_lossy(&nm)
            );
        }
        // dx_root (block 0) is still a valid index.
        let block0_phys = {
            let di = fs.read_inode(&cx, dir_ino).unwrap();
            fs.collect_extents(&cx, &di)
                .unwrap()
                .iter()
                .find(|e| e.logical_block == 0)
                .unwrap()
                .physical_start
        };
        let dxr = fs.read_block_vec(&cx, BlockNumber(block0_phys)).unwrap();
        let parsed =
            ffs_ondisk::parse_dx_root(&dxr).expect("dx_root must still parse after rebuilds");
        assert!(
            !parsed.entries.is_empty(),
            "dx_root index must be populated"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn cross_parent_rename_of_htree_dir_keeps_dx_root_valid_bd_0h5jy() {
        // Moving an htree directory to a new parent updates its '..'. That entry
        // lives in the dx_root (logical block 0); the update must repoint '..' in
        // place and re-stamp the DX-root checksum — not rewrite it as a linear
        // block with the regular dir-block checksum (which left it e2fsck-dirty).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(32) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, has_large_dir, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.has_large_dir(),
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let src = fs
            .mkdir(&cx, root, OsStr::new("src"), 0o755, 0, 0)
            .expect("mkdir src");
        let dst = fs
            .mkdir(&cx, root, OsStr::new("dst"), 0o755, 0, 0)
            .expect("mkdir dst");
        let big = fs
            .mkdir(&cx, src.ino, OsStr::new("big"), 0o755, 0, 0)
            .expect("mkdir src/big");
        let big_ino = big.ino;
        let big_ino_u32 = u32::try_from(big_ino.0).unwrap();
        let generation = fs.read_inode(&cx, big_ino).expect("read big").generation;

        // Fabricate a real htree directory for `big`.
        let names: Vec<Vec<u8>> = (0..250)
            .map(|i| format!("kid_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    9000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            big_ino_u32,
            u32::try_from(src.ino.0).unwrap(),
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            big_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(blocks.len() >= 3, "need dx_root + multiple leaves");
        install_htree_dir(&fs, &cx, big_ino, &blocks);
        assert!(
            fs.read_inode(&cx, big_ino).unwrap().has_htree_index(),
            "big must be htree-indexed"
        );

        // Cross-parent rename: src/big -> dst/big.
        fs.rename(&cx, src.ino, OsStr::new("big"), dst.ino, OsStr::new("big"))
            .expect("cross-parent rename of an htree directory");

        // The moved dir's block 0 is still a valid dx_root with a valid DX
        // checksum, and '..' now points to dst.
        let inode = fs.read_inode(&cx, big_ino).expect("reread big");
        let exts = fs.collect_extents(&cx, &inode).expect("extents");
        let block0_phys = exts
            .iter()
            .find(|e| e.logical_block == 0)
            .expect("logical 0")
            .physical_start;
        let dxr = fs
            .read_block_vec(&cx, BlockNumber(block0_phys))
            .expect("read dx_root");
        assert!(
            ffs_ondisk::verify_dx_block_checksum(
                &dxr,
                csum_seed,
                big_ino_u32,
                generation,
                ffs_ondisk::DX_ROOT_COUNT_OFFSET,
            ),
            "moved htree dir's dx_root checksum must be valid after rename"
        );
        let dotdot = u32::from_le_bytes([dxr[12], dxr[13], dxr[14], dxr[15]]);
        assert_eq!(
            u64::from(dotdot),
            dst.ino.0,
            "moved dir '..' must point to the new parent"
        );

        // The index still navigates: a sample child remains reachable.
        let find = ffs_ondisk::htree_find_entry(
            u32::try_from(block_size).unwrap(),
            &hash_seed,
            has_large_dir,
            b"kid_0100.txt",
            |v| v,
            |lb| {
                let exts = fs.collect_extents(&cx, &inode).ok()?;
                let phys = exts.iter().find_map(|e| {
                    let len = u32::from(e.actual_len());
                    if lb >= e.logical_block && lb < e.logical_block + len {
                        Some(e.physical_start + u64::from(lb - e.logical_block))
                    } else {
                        None
                    }
                })?;
                fs.read_block_vec(&cx, BlockNumber(phys)).ok()
            },
        );
        assert!(
            matches!(find, ffs_ondisk::HtreeFindResult::Found(_)),
            "moved htree dir must remain index-navigable"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn create_then_unlink_in_htree_dir_keeps_index_consistent() {
        // Unlink from an htree directory must remove the entry from its leaf
        // (restamping that leaf) without touching or invalidating the dx_root,
        // and the removed name must no longer resolve via the index while
        // siblings still do.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(32) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, has_large_dir, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.has_large_dir(),
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let dir = fs
            .mkdir(&cx, root, OsStr::new("htdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;

        let names: Vec<Vec<u8>> = (0..250)
            .map(|i| format!("seed_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    7000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(blocks.len() >= 3, "need dx_root + multiple leaves");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);

        let find = |name: &[u8]| -> ffs_ondisk::HtreeFindResult {
            ffs_ondisk::htree_find_entry(
                u32::try_from(block_size).unwrap(),
                &hash_seed,
                has_large_dir,
                name,
                |v| v,
                |lb| {
                    let inode = fs.read_inode(&cx, dir_ino).ok()?;
                    let exts = fs.collect_extents(&cx, &inode).ok()?;
                    let phys = exts.iter().find_map(|e| {
                        let len = u32::from(e.actual_len());
                        if lb >= e.logical_block && lb < e.logical_block + len {
                            Some(e.physical_start + u64::from(lb - e.logical_block))
                        } else {
                            None
                        }
                    })?;
                    fs.read_block_vec(&cx, BlockNumber(phys)).ok()
                },
            )
        };

        // Create a real file (real inode so unlink can decrement its link count).
        let created = fs
            .create(&cx, dir_ino, OsStr::new("victim.bin"), 0o644, 0, 0)
            .expect("create victim");
        assert!(
            matches!(find(b"victim.bin"), ffs_ondisk::HtreeFindResult::Found(_)),
            "victim must be index-reachable after create"
        );

        // Unlink it.
        fs.unlink(&cx, dir_ino, OsStr::new("victim.bin"))
            .expect("unlink victim from htree dir");

        // The victim no longer resolves via the index; a seed sibling still does.
        assert!(
            !matches!(find(b"victim.bin"), ffs_ondisk::HtreeFindResult::Found(_)),
            "victim must not resolve via the index after unlink (it was {:?})",
            created.ino
        );
        assert!(
            matches!(
                find(b"seed_0100.txt"),
                ffs_ondisk::HtreeFindResult::Found(_)
            ),
            "sibling entries must remain index-reachable after the unlink"
        );

        // The dx_root (block 0) is untouched and still valid.
        let block0_phys = {
            let di = fs.read_inode(&cx, dir_ino).unwrap();
            fs.collect_extents(&cx, &di)
                .unwrap()
                .iter()
                .find(|e| e.logical_block == 0)
                .unwrap()
                .physical_start
        };
        let dxr = fs.read_block_vec(&cx, BlockNumber(block0_phys)).unwrap();
        assert!(
            ffs_ondisk::verify_dx_block_checksum(
                &dxr,
                csum_seed,
                dir_ino_u32,
                generation,
                ffs_ondisk::DX_ROOT_COUNT_OFFSET,
            ),
            "dx_root checksum must remain valid across an unlink"
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn link_and_rename_into_htree_dir_place_entries_in_index() {
        // Hard-linking and renaming a file INTO an htree directory both route
        // through ext4_add_dir_entry, so the new names must land in their
        // hash-correct leaf (index-reachable) and the dx_root must stay valid.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(32) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, has_large_dir, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.has_large_dir(),
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let dir = fs
            .mkdir(&cx, root, OsStr::new("htdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;

        let names: Vec<Vec<u8>> = (0..250)
            .map(|i| format!("base_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    8000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(blocks.len() >= 3, "need dx_root + multiple leaves");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);

        let find = |name: &[u8]| -> ffs_ondisk::HtreeFindResult {
            ffs_ondisk::htree_find_entry(
                u32::try_from(block_size).unwrap(),
                &hash_seed,
                has_large_dir,
                name,
                |v| v,
                |lb| {
                    let inode = fs.read_inode(&cx, dir_ino).ok()?;
                    let exts = fs.collect_extents(&cx, &inode).ok()?;
                    let phys = exts.iter().find_map(|e| {
                        let len = u32::from(e.actual_len());
                        if lb >= e.logical_block && lb < e.logical_block + len {
                            Some(e.physical_start + u64::from(lb - e.logical_block))
                        } else {
                            None
                        }
                    })?;
                    fs.read_block_vec(&cx, BlockNumber(phys)).ok()
                },
            )
        };

        // Hard-link an existing file into the htree dir.
        let src = fs
            .create(&cx, root, OsStr::new("orig.bin"), 0o644, 0, 0)
            .expect("create source file");
        fs.link(&cx, src.ino, dir_ino, OsStr::new("hardlink.bin"))
            .expect("hard-link into htree dir");
        assert!(
            matches!(find(b"hardlink.bin"), ffs_ondisk::HtreeFindResult::Found(_)),
            "hard-linked name must be index-reachable in the htree dir"
        );

        // Rename a file from root into the htree dir.
        let mover = fs
            .create(&cx, root, OsStr::new("mover.bin"), 0o644, 0, 0)
            .expect("create mover");
        fs.rename(
            &cx,
            root,
            OsStr::new("mover.bin"),
            dir_ino,
            OsStr::new("moved.bin"),
        )
        .expect("rename into htree dir");
        match find(b"moved.bin") {
            ffs_ondisk::HtreeFindResult::Found(e) => {
                assert_eq!(e.inode, u32::try_from(mover.ino.0).unwrap());
            }
            other => panic!("renamed-in name must be index-reachable, got {other:?}"),
        }

        // dx_root remains valid after both index insertions.
        let block0_phys = {
            let di = fs.read_inode(&cx, dir_ino).unwrap();
            fs.collect_extents(&cx, &di)
                .unwrap()
                .iter()
                .find(|e| e.logical_block == 0)
                .unwrap()
                .physical_start
        };
        let dxr = fs.read_block_vec(&cx, BlockNumber(block0_phys)).unwrap();
        assert!(
            ffs_ondisk::verify_dx_block_checksum(
                &dxr,
                csum_seed,
                dir_ino_u32,
                generation,
                ffs_ondisk::DX_ROOT_COUNT_OFFSET,
            ),
            "dx_root checksum must stay valid across link + rename-in"
        );
    }

    #[test]
    fn readdir_and_lookup_work_on_htree_dir() {
        // The read paths must traverse an htree directory: read_dir parses every
        // block (including the dx_root at block 0) and lookup falls back to a
        // linear scan over block 0 — neither may choke on the dx_root's
        // index-spanning '..' the way the write-path add_entry did.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(32) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let (csum_seed, hash_seed, hash_version, block_size) = {
            let sb = fs.ext4_superblock().expect("sb");
            (
                sb.csum_seed(),
                sb.hash_seed,
                sb.effective_dirhash_version(sb.def_hash_version),
                usize::try_from(sb.block_size).unwrap(),
            )
        };

        let dir = fs
            .mkdir(&cx, root, OsStr::new("htdir"), 0o755, 0, 0)
            .expect("mkdir");
        let dir_ino = dir.ino;
        let dir_ino_u32 = u32::try_from(dir_ino.0).unwrap();
        let generation = fs.read_inode(&cx, dir_ino).expect("read dir").generation;

        let names: Vec<Vec<u8>> = (0..250)
            .map(|i| format!("entry_{i:04}.txt").into_bytes())
            .collect();
        let entries: Vec<(u32, u8, &[u8])> = names
            .iter()
            .enumerate()
            .map(|(i, n)| {
                (
                    6000 + u32::try_from(i).unwrap(),
                    ffs_ondisk::ext4::EXT4_FT_REG_FILE,
                    n.as_slice(),
                )
            })
            .collect();
        let blocks = ffs_ondisk::build_htree_directory_stamped(
            dir_ino_u32,
            2,
            &entries,
            block_size,
            hash_version,
            &hash_seed,
            csum_seed,
            dir_ino_u32,
            generation,
        )
        .expect("build htree");
        assert!(blocks.len() >= 3, "need dx_root + multiple leaves");
        install_htree_dir(&fs, &cx, dir_ino, &blocks);

        // read_dir must enumerate every entry (plus '.'/'..') without choking on
        // the dx_root.
        let inode = fs.read_inode(&cx, dir_ino).expect("reread");
        let listed = fs.read_dir(&cx, &inode).expect("read_dir on htree dir");
        let real: std::collections::BTreeSet<Vec<u8>> = listed
            .iter()
            .map(|e| e.name.clone())
            .filter(|n| n != b"." && n != b"..")
            .collect();
        assert_eq!(
            real.len(),
            names.len(),
            "read_dir must enumerate every htree entry exactly once"
        );
        for n in &names {
            assert!(
                real.contains(n),
                "read_dir missing {:?}",
                String::from_utf8_lossy(n)
            );
        }

        // lookup_name must resolve a sample entry (via index or linear fallback).
        let hit = fs
            .lookup_name(&cx, &inode, b"entry_0137.txt")
            .expect("lookup_name on htree dir must not error");
        assert!(
            hit.is_some(),
            "lookup_name must find an existing htree entry"
        );
        let miss = fs
            .lookup_name(&cx, &inode, b"does_not_exist.txt")
            .expect("lookup_name miss must not error");
        assert!(
            miss.is_none(),
            "lookup_name must report a real miss as None"
        );
    }

    #[test]
    fn inline_data_directory_operations_fail_loudly_bd_4y9ca() {
        // FrankenFS has no inline-directory parser, so directory ops on an
        // EXT4_INLINE_DATA_FL inode must return a clean UnsupportedFeature error
        // rather than silently reading an empty dir (which would let rmdir drop a
        // non-empty dir) or overwriting the inline entries on insert (data loss).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let dir = fs
            .mkdir(&cx, root, OsStr::new("inlinedir"), 0o755, 0, 0)
            .expect("mkdir");

        // Flag the directory inode as inline_data (mirrors an inline_data image).
        let mut inode = fs.read_inode(&cx, dir.ino).expect("read inode");
        inode.flags |= ffs_types::EXT4_INLINE_DATA_FL;
        inode.flags &= !ffs_types::EXT4_COMPR_FL;
        fs.persist_ext4_inode_for_testing(&cx, dir.ino, &inode)
            .expect("persist inline flag");

        let reread = fs.read_inode(&cx, dir.ino).expect("reread");
        assert!(
            matches!(
                fs.read_dir(&cx, &reread),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "read_dir on an inline_data dir must fail loudly, not return empty"
        );
        assert!(
            matches!(
                fs.lookup_name(&cx, &reread, b"anything"),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "lookup on an inline_data dir must fail loudly"
        );
        assert!(
            fs.create(&cx, dir.ino, OsStr::new("newfile.txt"), 0o644, 0, 0)
                .is_err(),
            "create in an inline_data dir must fail, not lose the inline entries"
        );
    }

    #[test]
    fn encrypted_file_content_io_fails_loudly_bd_4sfty() {
        // FrankenFS has no fscrypt support, so read/write/fallocate on an
        // encrypted file must fail loudly rather than return raw ciphertext
        // (read) or store plaintext into the encrypted blocks (write/corruption).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let attr = fs
            .create(&cx, root, OsStr::new("secret.bin"), 0o644, 0, 0)
            .expect("create");
        // Give the file an extent root + a small write before flagging it
        // encrypted, so the guard (not some other path) is what rejects.
        fs.write(&cx, attr.ino, 0, b"plaintext")
            .expect("seed write");

        // Flag the inode encrypted (EXT4_ENCRYPT_INODE_FL = 0x0000_0800).
        let mut inode = fs.read_inode(&cx, attr.ino).expect("read inode");
        inode.flags |= 0x0000_0800;
        fs.persist_ext4_inode_for_testing(&cx, attr.ino, &inode)
            .expect("persist encrypt flag");
        assert!(
            fs.read_inode(&cx, attr.ino).unwrap().is_encrypted(),
            "inode must now be flagged encrypted"
        );

        assert!(
            matches!(
                fs.read(&cx, attr.ino, 0, 16),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "reading an encrypted file must fail, not return ciphertext as plaintext"
        );
        assert!(
            matches!(
                fs.write(&cx, attr.ino, 0, b"newdata"),
                Err(FfsError::UnsupportedFeature(_))
            ),
            "writing an encrypted file must fail, not store plaintext into encrypted blocks"
        );
        assert!(
            fs.fallocate(&cx, attr.ino, 0, 4096, 0).is_err(),
            "fallocate on an encrypted file must fail"
        );
    }

    #[test]
    fn verity_file_content_mutation_rejected_bd_yz6c6() {
        // FrankenFS has no fs-verity support; mutating a verity file's content
        // would break its Merkle tree, so write/fallocate/truncate must be
        // rejected. Reads stay allowed (FrankenFS returns the raw data).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let attr = fs
            .create(&cx, root, OsStr::new("sealed.bin"), 0o644, 0, 0)
            .expect("create");
        fs.write(&cx, attr.ino, 0, b"sealed contents")
            .expect("seed write before sealing");

        // Flag the inode fs-verity (EXT4_VERITY_FL).
        let mut inode = fs.read_inode(&cx, attr.ino).expect("read inode");
        inode.flags |= ffs_types::EXT4_VERITY_FL;
        fs.persist_ext4_inode_for_testing(&cx, attr.ino, &inode)
            .expect("persist verity flag");

        assert!(
            fs.write(&cx, attr.ino, 0, b"tamper").is_err(),
            "writing a verity file must be rejected"
        );
        assert!(
            fs.fallocate(&cx, attr.ino, 0, 4096, 0).is_err(),
            "fallocate on a verity file must be rejected"
        );
        let trunc = SetAttrRequest {
            size: Some(0),
            ..SetAttrRequest::default()
        };
        assert!(
            fs.setattr(&cx, attr.ino, &trunc).is_err(),
            "truncating a verity file must be rejected"
        );
        // Reads remain allowed.
        assert!(
            fs.read(&cx, attr.ino, 0, 8).is_ok(),
            "reading a verity file must still succeed"
        );
    }

    #[test]
    fn ext4_checked_inode_blocks_after_cluster_rewrite_scales_by_huge_flag() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let ino = InodeNumber(2); // root
        let mut inode = fs.read_inode(&cx, ino).expect("read root inode");
        inode.blocks = 100;

        // added_data=3 + added_meta=1 = 4 total added, freed=1 -> net 3 blocks.
        // Non-HUGE: i_blocks is in 512-byte sectors, so scale by block_size/512.
        inode.flags &= !ffs_types::EXT4_HUGE_FILE_FL;
        let spb = u64::from(fs.block_size() / 512);
        let result = fs
            .ext4_checked_inode_blocks_after_cluster_rewrite(&inode, ino, 3, 1, 1, "test")
            .expect("non-huge delta");
        assert_eq!(result, 100 + 3 * spb);

        // HUGE_FILE: i_blocks is in filesystem blocks, so the net delta applies
        // directly without sector scaling.
        inode.flags |= ffs_types::EXT4_HUGE_FILE_FL;
        let result = fs
            .ext4_checked_inode_blocks_after_cluster_rewrite(&inode, ino, 3, 1, 1, "test")
            .expect("huge delta");
        assert_eq!(result, 100 + 3);
    }

    #[test]
    fn immutable_and_append_attributes_enforced_on_writes_bd_hbld5() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        let set_flag = |ino: InodeNumber, flag: u32| {
            let mut inode = fs.read_inode(&cx, ino).expect("read inode");
            inode.flags &= !(ffs_types::EXT4_IMMUTABLE_FL | ffs_types::EXT4_APPEND_FL);
            inode.flags |= flag;
            fs.persist_ext4_inode_for_testing(&cx, ino, &inode)
                .expect("persist flag");
        };

        // ── Immutable: every content mutation must be rejected. ──
        let imm = fs
            .create(&cx, root, OsStr::new("imm.bin"), 0o644, 0, 0)
            .expect("create imm");
        fs.write(&cx, imm.ino, 0, b"hello world")
            .expect("seed write");
        set_flag(imm.ino, ffs_types::EXT4_IMMUTABLE_FL);
        assert!(
            fs.write(&cx, imm.ino, 0, b"nope").is_err(),
            "write to an immutable file must be rejected"
        );
        assert!(
            fs.fallocate(&cx, imm.ino, 0, 4096, 0).is_err(),
            "fallocate on an immutable file must be rejected"
        );
        let trunc = SetAttrRequest {
            size: Some(0),
            ..SetAttrRequest::default()
        };
        assert!(
            fs.setattr(&cx, imm.ino, &trunc).is_err(),
            "truncate of an immutable file must be rejected"
        );

        // ── Append-only: appends at EOF allowed; overwrite/shrink rejected. ──
        let app = fs
            .create(&cx, root, OsStr::new("app.bin"), 0o644, 0, 0)
            .expect("create app");
        fs.write(&cx, app.ino, 0, b"0123456789")
            .expect("seed write");
        let size = fs.read_inode(&cx, app.ino).unwrap().size;
        set_flag(app.ino, ffs_types::EXT4_APPEND_FL);
        assert!(
            fs.write(&cx, app.ino, 0, b"x").is_err(),
            "non-append (offset < EOF) write to an append-only file must be rejected"
        );
        fs.write(&cx, app.ino, size, b"appended")
            .expect("append at EOF must succeed on an append-only file");
        let shrink = SetAttrRequest {
            size: Some(1),
            ..SetAttrRequest::default()
        };
        assert!(
            fs.setattr(&cx, app.ino, &shrink).is_err(),
            "shrinking an append-only file must be rejected"
        );
    }

    #[test]
    fn immutable_and_append_attributes_enforced_on_metadata_ops_bd_hbld5() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(8) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let set_flag = |ino: InodeNumber, flag: u32| {
            let mut inode = fs.read_inode(&cx, ino).expect("read inode");
            inode.flags &= !(ffs_types::EXT4_IMMUTABLE_FL | ffs_types::EXT4_APPEND_FL);
            inode.flags |= flag;
            fs.persist_ext4_inode_for_testing(&cx, ino, &inode)
                .expect("persist flag");
        };

        // Immutable: delete, rename, link, and xattr-set all rejected.
        let imm = fs
            .create(&cx, root, OsStr::new("imm.bin"), 0o644, 0, 0)
            .expect("create imm");
        set_flag(imm.ino, ffs_types::EXT4_IMMUTABLE_FL);
        assert!(
            fs.unlink(&cx, root, OsStr::new("imm.bin")).is_err(),
            "deleting an immutable file must be rejected"
        );
        assert!(
            fs.rename(
                &cx,
                root,
                OsStr::new("imm.bin"),
                root,
                OsStr::new("imm2.bin")
            )
            .is_err(),
            "renaming an immutable file must be rejected"
        );
        assert!(
            fs.link(&cx, imm.ino, root, OsStr::new("imm_link.bin"))
                .is_err(),
            "hard-linking an immutable file must be rejected"
        );
        assert!(
            fs.setxattr(&cx, imm.ino, "user.x", b"v", XattrSetMode::Set)
                .is_err(),
            "setting an xattr on an immutable file must be rejected"
        );
        let chmod = SetAttrRequest {
            mode: Some(0o600),
            ..SetAttrRequest::default()
        };
        assert!(
            fs.setattr(&cx, imm.ino, &chmod).is_err(),
            "chmod of an immutable file must be rejected"
        );
        let chown = SetAttrRequest {
            uid: Some(1234),
            ..SetAttrRequest::default()
        };
        assert!(
            fs.setattr(&cx, imm.ino, &chown).is_err(),
            "chown of an immutable file must be rejected"
        );

        // Append-only: delete, rename, and hard-link rejected. The kernel's
        // vfs_link forbids a link to an append-only file too (bd-69ich).
        let app = fs
            .create(&cx, root, OsStr::new("app.bin"), 0o644, 0, 0)
            .expect("create app");
        set_flag(app.ino, ffs_types::EXT4_APPEND_FL);
        assert!(
            fs.unlink(&cx, root, OsStr::new("app.bin")).is_err(),
            "deleting an append-only file must be rejected"
        );
        assert!(
            fs.rename(
                &cx,
                root,
                OsStr::new("app.bin"),
                root,
                OsStr::new("app2.bin")
            )
            .is_err(),
            "renaming an append-only file must be rejected"
        );
        assert_eq!(
            fs.link(&cx, app.ino, root, OsStr::new("app_link.bin"))
                .unwrap_err()
                .to_errno(),
            libc::EPERM,
            "hard-linking an append-only file must be EPERM (vfs_link)"
        );
        assert_eq!(
            fs.setxattr(&cx, app.ino, "user.x", b"v", XattrSetMode::Set)
                .unwrap_err()
                .to_errno(),
            libc::EPERM,
            "setxattr on an append-only file must be EPERM (xattr_permission, bd-kf7uw)"
        );
    }

    #[test]
    fn ext4_rename_onto_immutable_target_is_eperm_bd_85rav() {
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        fs.create(&cx, root, OsStr::new("rsrc.bin"), 0o644, 0, 0)
            .expect("create src");
        let dst = fs
            .create(&cx, root, OsStr::new("rdst.bin"), 0o644, 0, 0)
            .expect("create dst");
        // Make the rename victim immutable.
        let mut di = fs.read_inode(&cx, dst.ino).expect("read dst inode");
        di.flags |= ffs_types::EXT4_IMMUTABLE_FL;
        persist_ext4_test_inode(&fs, &cx, dst.ino, &di);

        // vfs_rename's may_delete(victim) forbids clobbering an immutable target.
        assert_eq!(
            fs.rename(
                &cx,
                root,
                OsStr::new("rsrc.bin"),
                root,
                OsStr::new("rdst.bin")
            )
            .unwrap_err()
            .to_errno(),
            libc::EPERM,
            "renaming onto an immutable target must be EPERM (bd-85rav)"
        );
        // No partial mutation: both names still resolve.
        assert!(
            fs.lookup(&cx, root, OsStr::new("rsrc.bin")).is_ok(),
            "source must survive a rejected rename"
        );
        assert!(
            fs.lookup(&cx, root, OsStr::new("rdst.bin")).is_ok(),
            "immutable target must survive a rejected rename"
        );
    }

    fn open_writable_ext4_mkfs(size_mb: u64) -> Option<(OpenFs, tempfile::TempDir)> {
        let tmp = tempfile::TempDir::new().expect("tmpdir");
        let image = tmp.path().join("test.ext4");
        let f = std::fs::File::create(&image).expect("create image");
        f.set_len(size_mb * 1024 * 1024).expect("set image size");
        drop(f);

        let out = std::process::Command::new("mkfs.ext4")
            .args(["-F", "-b", "4096", image.to_str().unwrap()])
            .output();
        let out = match out {
            Ok(o) if o.status.success() => o,
            _ => return None,
        };
        let _ = out; // suppress unused warning

        // Make root writable.
        let _ = std::process::Command::new("debugfs")
            .args([
                "-w",
                "-R",
                "set_inode_field / mode 040777",
                image.to_str().unwrap(),
            ])
            .output();

        let cx = Cx::for_testing();
        let data = std::fs::read(&image).expect("read image");
        let dev = TestDevice::from_vec(data);
        let opts = OpenOptions {
            ext4_journal_replay_mode: Ext4JournalReplayMode::Apply,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(&cx, Box::new(dev), &opts).expect("open ext4");
        fs.enable_writes(&cx).expect("enable writes");
        assert!(fs.is_writable());
        Some((fs, tmp))
    }

    /// bd-bhh0i: runtime validation of the sharded per-group block allocator
    /// (`sharded_alloc::PerGroupAlloc::alloc_blocks`, default-off behind the
    /// `bhh0i_sharded_alloc` feature) against a REAL on-disk ext4 image — real
    /// group descriptors and block bitmaps, produced by `mkfs.ext4` — so the
    /// allocator actually reads and writes bitmaps through the same MVCC block
    /// device the single-lock `alloc_blocks_persist` path uses.
    ///
    /// Three consecutive single-block allocations must each succeed, return
    /// DISTINCT real blocks, and debit exactly one block from the group each
    /// allocation lands in (with no other group's free count perturbed) — the
    /// same observable effect the single-lock allocator produces.
    #[test]
    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn bd_bhh0i_sharded_alloc_blocks_allocates_valid_distinct_blocks() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(64) else {
            return; // mkfs.ext4 unavailable on this host — skip like sibling tests.
        };
        let cx = Cx::for_testing();

        // Geometry is derived lock-free from the live superblock, exactly how
        // the sharded path expects the caller to supply it.
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let geo = FsGeometry::from_superblock(sb);

        // Immutable persist context, cloned out of the single-lock alloc state
        // (`PersistCtx: Clone`) — the very context the single-lock path feeds
        // `alloc_blocks_persist`.
        let pctx = fs
            .ext4_alloc_state
            .as_ref()
            .expect("ext4 write state present after enable_writes")
            .read()
            .persist_ctx
            .clone();

        // The block device the single-lock alloc path writes bitmaps through
        // (same accessor `alloc_blocks_persist` callers use in the write path).
        let dev = fs.block_device_adapter();

        // The sharded per-group allocator populated (each group's reserved-set
        // cache pre-filled) by `enable_writes` under this feature.
        let sharded = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under bhh0i_sharded_alloc feature");

        let hint = AllocHint::default();
        let group_count = sharded.group_count();

        let mut allocated = Vec::new();
        for call in 0..3 {
            // Per-group free-block snapshot before the allocation.
            let free_before: Vec<u32> = (0..group_count)
                .map(|g| sharded.lock_group(g).free_blocks)
                .collect();
            let total_before = sharded.total_free().blocks;

            let alloc = sharded
                .alloc_blocks(&cx, &dev, &geo, &hint, 1, &pctx)
                .unwrap_or_else(|e| panic!("sharded alloc_blocks call {call} errored: {e:?}"))
                .unwrap_or_else(|| panic!("sharded alloc_blocks call {call} found no free block"));
            assert_eq!(alloc.count, 1, "call {call}: expected exactly one block");

            // The returned block must map to a real group whose free count fell
            // by exactly one; the whole-array total fell by exactly one too, so
            // no sibling group was perturbed.
            let landing = usize::try_from(
                (alloc.start.0 - u64::from(geo.first_data_block)) / u64::from(geo.blocks_per_group),
            )
            .expect("landing group index fits usize");
            assert!(
                landing < group_count,
                "call {call}: landing group {landing} out of range (group_count={group_count})"
            );
            let free_after_landing = sharded.lock_group(landing).free_blocks;
            assert_eq!(
                free_after_landing,
                free_before[landing] - 1,
                "call {call}: landing group {landing} free_blocks must drop by exactly 1"
            );
            let total_after = sharded.total_free().blocks;
            assert_eq!(
                total_after,
                total_before - 1,
                "call {call}: exactly one block consumed across all groups"
            );

            allocated.push(alloc.start);
        }

        // All three allocations must be distinct real blocks.
        let distinct: std::collections::HashSet<u64> = allocated.iter().map(|b| b.0).collect();
        assert_eq!(
            distinct.len(),
            3,
            "the three sharded allocations must be distinct blocks: {allocated:?}"
        );
    }

    /// Concurrency counterpart to the single-threaded block test above. The whole
    /// point of the bd-bhh0i per-group lock decomposition is that disjoint-group
    /// allocations proceed on REAL OS threads without corrupting each other, so
    /// this drives the sharded `alloc_blocks` path from `N` concurrent threads —
    /// one per distinct starting group — that all borrow the SAME `PerGroupAlloc`,
    /// block device, geometry, and persist context by shared reference (the exact
    /// aliasing the cutover must survive). Two invariants are checked across ALL
    /// threads at once, against a real on-disk ext4 image:
    ///
    ///   * every block handed out across every thread is DISTINCT — the core
    ///     no-double-allocation guarantee under concurrency (a `HashSet` of the
    ///     raw block numbers whose length equals the total allocated), and
    ///   * the whole-array free-block total fell by EXACTLY the number allocated —
    ///     every concurrent debit landed once, with no lost update from a racing
    ///     per-group count decrement.
    ///
    /// That `&PerGroupAlloc`, `&dyn BlockDevice`, `&FsGeometry`, and `&PersistCtx`
    /// can all be shared across `thread::scope` at once is itself load-bearing for
    /// the cutover: it compiles only because every one of those four is `Sync`.
    /// Each worker builds its own `Cx::for_testing()`, so the shared-across-threads
    /// surface this test pins down is exactly those four allocator types.
    #[test]
    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn bd_bhh0i_sharded_alloc_blocks_parallel_no_double_alloc() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(64) else {
            return; // mkfs.ext4 unavailable on this host — skip like sibling tests.
        };

        // Geometry is derived lock-free from the live superblock, exactly how the
        // sharded path expects the caller to supply it.
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let geo = FsGeometry::from_superblock(sb);

        // Immutable persist context, cloned out of the single-lock alloc state —
        // the very context the single-lock path feeds `alloc_blocks_persist`.
        let pctx = fs
            .ext4_alloc_state
            .as_ref()
            .expect("ext4 write state present after enable_writes")
            .read()
            .persist_ctx
            .clone();

        // The block device the single-lock alloc path writes bitmaps through.
        let dev = fs.block_device_adapter();

        // The sharded per-group allocator populated by `enable_writes`.
        let sharded = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under bhh0i_sharded_alloc feature");

        let gc = sharded.group_count();
        if gc < 2 {
            return; // need at least two groups to exercise disjoint-group concurrency.
        }

        // Whole-array free-block total before any concurrent allocation.
        let total_before = sharded.total_free().blocks;

        // One thread per distinct starting group (capped at 4), each issuing K
        // single-block allocations. Reference bindings are Copy, so each `move`
        // worker captures its own copy and all threads share the underlying
        // allocator / device / geometry / persist context by shared reference —
        // which requires each of those four to be `Sync`.
        let n = gc.min(4);
        const K: usize = 20;
        let sharded_ref: &crate::sharded_alloc::PerGroupAlloc = sharded;
        let dev_ref = &dev;
        let geo_ref = &geo;
        let pctx_ref = &pctx;

        let per_thread: Vec<Vec<BlockNumber>> = std::thread::scope(|scope| {
            let handles: Vec<_> = (0..n)
                .map(|t| {
                    scope.spawn(move || {
                        // Each worker owns its Cx so the only cross-thread sharing
                        // is the four allocator types under test.
                        let cx = Cx::for_testing();

                        // Distinct starting group per thread, so the scans begin in
                        // different groups (they still fall through to
                        // neighbors → full-fallback if that family is exhausted).
                        let hint = AllocHint {
                            goal_group: Some(GroupNumber(t as u32)),
                            ..AllocHint::default()
                        };

                        let mut got: Vec<BlockNumber> = Vec::with_capacity(K);
                        for call in 0..K {
                            match sharded_ref
                                .alloc_blocks(&cx, dev_ref, geo_ref, &hint, 1, pctx_ref)
                            {
                                Ok(Some(alloc)) => got.push(alloc.start),
                                Ok(None) => break, // group family full — stop early.
                                Err(e) => panic!(
                                    "thread {t} call {call}: sharded alloc_blocks errored: {e:?}"
                                ),
                            }
                        }
                        got
                    })
                })
                .collect();
            handles
                .into_iter()
                .map(|h| h.join().expect("allocator worker thread panicked"))
                .collect()
        });

        // Flatten every thread's allocations into one list.
        let all: Vec<BlockNumber> = per_thread.into_iter().flatten().collect();
        let total_allocated = all.len();
        assert!(
            total_allocated > 0,
            "expected at least one concurrent allocation to succeed across {n} threads"
        );

        // Core no-double-allocation guarantee: every block handed out across ALL
        // threads is distinct — two concurrent scans never landed the same block.
        let distinct: std::collections::HashSet<u64> = all.iter().map(|b| b.0).collect();
        assert_eq!(
            distinct.len(),
            total_allocated,
            "every concurrently-allocated block must be distinct (no double-alloc): {all:?}"
        );

        // Every concurrent debit landed exactly once — no lost update from a racing
        // per-group free-count decrement.
        let total_after = sharded.total_free().blocks;
        assert_eq!(
            total_after,
            total_before - total_allocated as u64,
            "whole-array free-block total must fall by exactly the number allocated \
             (before={total_before}, after={total_after}, allocated={total_allocated})"
        );
    }

    /// Inode analogue of the block test above: three consecutive single-inode
    /// allocations must each succeed, return DISTINCT real inode numbers, and
    /// debit exactly one inode from the group each allocation lands in (with no
    /// other group's free count perturbed) — the same observable effect the
    /// single-lock allocator produces.
    #[test]
    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn bd_bhh0i_sharded_alloc_inode_allocates_valid_distinct_inodes() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(64) else {
            return; // mkfs.ext4 unavailable on this host — skip like sibling tests.
        };
        let cx = Cx::for_testing();

        // Geometry is derived lock-free from the live superblock, exactly how
        // the sharded path expects the caller to supply it.
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let geo = FsGeometry::from_superblock(sb);

        // Immutable persist context, cloned out of the single-lock alloc state
        // (`PersistCtx: Clone`) — the very context the single-lock path feeds
        // `alloc_inode_persist`.
        let pctx = fs
            .ext4_alloc_state
            .as_ref()
            .expect("ext4 write state present after enable_writes")
            .read()
            .persist_ctx
            .clone();

        // The block device the single-lock alloc path writes bitmaps through.
        let dev = fs.block_device_adapter();

        // The sharded per-group allocator populated by `enable_writes` under
        // this feature.
        let sharded = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under bhh0i_sharded_alloc feature");

        // Group 0 has free inodes on a fresh mkfs image; use it as the target.
        let target = ffs_types::GroupNumber(0);
        let group_count = sharded.group_count();

        let mut allocated = Vec::new();
        for call in 0..3 {
            // Per-group free-inode snapshot before the allocation.
            let free_before: Vec<u32> = (0..group_count)
                .map(|g| sharded.lock_group(g).free_inodes)
                .collect();
            let total_before = sharded.total_free().inodes;

            let alloc = sharded
                .alloc_inode(&cx, &dev, &geo, target, false, &pctx)
                .unwrap_or_else(|e| panic!("sharded alloc_inode call {call} errored: {e:?}"))
                .unwrap_or_else(|| panic!("sharded alloc_inode call {call} found no free inode"));

            // The returned inode carries its landing group directly; that group's
            // free count must have fallen by exactly one, and the whole-array
            // total fell by exactly one too, so no sibling group was perturbed.
            let landing = alloc.group.0 as usize;
            assert!(
                landing < group_count,
                "call {call}: landing group {landing} out of range (group_count={group_count})"
            );
            let free_after_landing = sharded.lock_group(landing).free_inodes;
            assert_eq!(
                free_after_landing,
                free_before[landing] - 1,
                "call {call}: landing group {landing} free_inodes must drop by exactly 1"
            );
            let total_after = sharded.total_free().inodes;
            assert_eq!(
                total_after,
                total_before - 1,
                "call {call}: exactly one inode consumed across all groups"
            );

            allocated.push(alloc.ino);
        }

        // All three allocations must be distinct real inodes.
        let distinct: std::collections::HashSet<u64> = allocated.iter().map(|i| i.0).collect();
        assert_eq!(
            distinct.len(),
            3,
            "the three sharded allocations must be distinct inodes: {allocated:?}"
        );
    }

    /// bd-bhh0i cutover-critical: the sharded inode-allocation path must maintain
    /// `bg_used_dirs_count` EXACTLY as the single-lock path does — increment it by
    /// one for a directory, leave it untouched for a regular file. The sharded
    /// Orlov chooser (`choose_dir_group`, which reads `used_dirs` via
    /// `group_free_snapshot`) AND e2fsck both depend on this: if the sharded core
    /// skipped the directory bump, every directory would keep re-selecting the same
    /// group, defeating the spread that prevents the shared-inode-table-block RMW
    /// storm that corrupted the two prior naive cutover attempts. The primitive
    /// tests above cover block/inode COUNTS but never the directory `used_dirs`
    /// bump, its is-directory gate, or the `choose_dir_group()` → `alloc_inode()`
    /// composition on a REAL mkfs image; this pins all three.
    #[test]
    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn bd_bhh0i_sharded_dir_alloc_maintains_used_dirs() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(64) else {
            return; // mkfs.ext4 unavailable on this host — skip like sibling tests.
        };
        let cx = Cx::for_testing();

        // Geometry / persist context / device, sourced exactly as the sibling
        // sharded tests (and the cutover) do.
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let geo = FsGeometry::from_superblock(sb);
        let pctx = fs
            .ext4_alloc_state
            .as_ref()
            .expect("ext4 write state present after enable_writes")
            .read()
            .persist_ctx
            .clone();
        let dev = fs.block_device_adapter();
        let sharded = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under bhh0i_sharded_alloc feature");
        let group_count = sharded.group_count();

        // Fs-wide directory count / free-inode count across every group.
        let used_dirs = || {
            (0..group_count)
                .map(|g| sharded.lock_group(g).used_dirs)
                .sum::<u32>()
        };
        let free_inodes = || {
            (0..group_count)
                .map(|g| sharded.lock_group(g).free_inodes)
                .sum::<u32>()
        };

        // Allocate three DIRECTORIES through the real cutover composition: pick the
        // target group with choose_dir_group(), then allocate an inode there as a
        // directory. Each must bump exactly one group's used_dirs by one.
        for i in 0..3u32 {
            let target = sharded.choose_dir_group().unwrap_or_else(|| {
                panic!("dir {i}: choose_dir_group found no group with a free inode")
            });
            let landing_used_before = sharded.lock_group(target.0 as usize).used_dirs;
            let ud_before = used_dirs();
            let fi_before = free_inodes();

            let alloc = sharded
                .alloc_inode(&cx, &dev, &geo, target, true, &pctx)
                .unwrap_or_else(|e| panic!("dir {i}: sharded alloc_inode errored: {e:?}"))
                .unwrap_or_else(|| panic!("dir {i}: sharded alloc_inode found no free inode"));

            // On a spacious fresh fs the directory lands in the chosen group, whose
            // used_dirs bumped by exactly one...
            assert_eq!(
                alloc.group, target,
                "dir {i}: must land in the chosen group"
            );
            assert_eq!(
                sharded.lock_group(alloc.group.0 as usize).used_dirs,
                landing_used_before + 1,
                "dir {i}: landing group used_dirs must bump by exactly one"
            );
            // ...so the fs-wide directory count rose by exactly one and one inode
            // was consumed.
            assert_eq!(
                used_dirs(),
                ud_before + 1,
                "dir {i}: fs-wide used_dirs must rise by one"
            );
            assert_eq!(
                free_inodes(),
                fi_before - 1,
                "dir {i}: exactly one inode consumed"
            );
        }

        // A regular FILE must NOT touch used_dirs (the is_directory gate), while
        // still consuming exactly one inode.
        let ud_before_file = used_dirs();
        let fi_before_file = free_inodes();
        let file = sharded
            .alloc_inode(&cx, &dev, &geo, ffs_types::GroupNumber(0), false, &pctx)
            .expect("file sharded alloc_inode errored")
            .expect("file sharded alloc_inode found no free inode");
        assert_eq!(
            used_dirs(),
            ud_before_file,
            "a regular file must leave used_dirs unchanged (landed group {}, ino {})",
            file.group.0,
            file.ino.0
        );
        assert_eq!(
            free_inodes(),
            fi_before_file - 1,
            "the regular file must still consume exactly one inode"
        );
    }

    /// bd-bhh0i cutover primitive: the sharded structure must resolve an inode's
    /// on-disk location byte-identically to the single-lock `ffs_inode::locate_inode`,
    /// so the sharded create path can compose `alloc_inode` -> `inode_location` ->
    /// `write_inode_at` WITHOUT reading the single-lock `groups` slice. Checks the
    /// resolver against the incumbent for reserved, group-boundary, and out-of-range
    /// inode numbers on a REAL mkfs image (real geometry + real inode_table_block).
    #[test]
    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn bd_bhh0i_sharded_inode_location_matches_single_lock() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(64) else {
            return; // mkfs.ext4 unavailable on this host — skip like sibling tests.
        };
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let geo = FsGeometry::from_superblock(sb);
        let guard = fs
            .ext4_alloc_state
            .as_ref()
            .expect("ext4 write state present after enable_writes")
            .read();
        let single_lock_groups = &guard.groups;
        let sharded = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under bhh0i_sharded_alloc feature");

        // Reserved (0/1/2/11), the group-0 boundary (ipg-1, ipg, ipg+1), a second-
        // group number, and past-the-end (total_inodes, +1). The sharded resolver
        // must agree with the incumbent on every one, including the None cases.
        let ipg = u64::from(geo.inodes_per_group);
        let ti = u64::from(geo.total_inodes);
        for &ino in &[0u64, 1, 2, 11, ipg - 1, ipg, ipg + 1, 2 * ipg, ti, ti + 1] {
            let a = sharded
                .inode_location(InodeNumber(ino), &geo)
                .map(|l| (l.block.0, l.byte_offset));
            let b = ffs_inode::locate_inode(InodeNumber(ino), &geo, single_lock_groups)
                .map(|l| (l.block.0, l.byte_offset));
            assert_eq!(
                a, b,
                "sharded inode_location must match single-lock locate_inode at inode {ino}"
            );
        }
    }

    /// Run `e2fsck -fn` (force, read-only) on an image; returns (clean, output).
    fn run_e2fsck(image: &std::path::Path) -> Option<(bool, String)> {
        let out = std::process::Command::new("e2fsck")
            .args(["-fn", image.to_str().unwrap()])
            .output()
            .ok()?;
        let mut combined = String::from_utf8_lossy(&out.stdout).into_owned();
        combined.push_str(&String::from_utf8_lossy(&out.stderr));
        // Exit 0 = clean. With -n, non-zero means errors were found (not fixed).
        Some((out.status.success(), combined))
    }

    /// Validate FrankenFS's ext4 write path against real `e2fsck` (the ext4
    /// analog of the btrfs-check harness): create a file, write data, persist,
    /// and require e2fsck to report the image clean.
    ///
    /// Regression guard for bd-0ta4z: allocation on a fresh (lazy-init) image
    /// formerly left the group flagged INODE_UNINIT/BLOCK_UNINIT with a stale
    /// `bg_itable_unused`, so e2fsck recomputed the bitmaps/free counts as
    /// all-free and reported them wrong. Fixed by clearing the UNINIT flags +
    /// shrinking `itable_unused` when a group's bitmap is persisted.
    #[test]
    fn ext4_created_file_passes_e2fsck_bd_0ta4z() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let image = tmp.path().join("test.ext4");
        let cx = Cx::for_testing();

        let attr = fs
            .create(
                &cx,
                InodeNumber(2),
                OsStr::new("e2fsck_probe.txt"),
                0o644,
                0,
                0,
            )
            .expect("create on real ext4 image");
        fs.write(&cx, attr.ino, 0, &[0xAB_u8; 8192])
            .expect("write file data");

        // Persist the MVCC buffer to the device, then write the modified image
        // back to disk for e2fsck.
        fs.flush_mvcc_to_device(&cx).expect("flush mvcc to device");
        let bytes = dev.snapshot_bytes();
        std::fs::write(&image, &bytes).expect("write modified image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            clean,
            "e2fsck must accept a FrankenFS-created+written ext4 image:\n{output}"
        );
    }

    /// Restores production GDT-persistence mode on scope exit, so a panicking
    /// eager-mode test cannot leak `Some(false)` into whatever libtest schedules
    /// next on this thread.
    struct GdtModeRestore;
    impl Drop for GdtModeRestore {
        fn drop(&mut self) {
            ffs_alloc::set_gdt_persistence_deferred_for_test(None);
        }
    }

    /// Audit an ext4 image's group descriptors against its own block bitmaps.
    ///
    /// Returns one `(group, declared_free, counted_free)` row per group whose
    /// `bg_free_blocks_count` disagrees with the number of zero bits in that
    /// group's on-disk block bitmap — the exact inconsistency `e2fsck` reports as
    /// "Free blocks count wrong for group #N". Groups still flagged
    /// `EXT4_BG_BLOCK_UNINIT` are skipped: their bitmap is not authoritative
    /// (the kernel synthesises it), so a mismatch there is not a defect.
    ///
    /// This is an IN-PROCESS oracle deliberately independent of e2fsck, because
    /// a build host without e2fsprogs would otherwise turn this whole regression
    /// into a silent pass (bd-hyysq).
    fn ext4_group_free_block_mismatches(image: &[u8]) -> Vec<(u32, u32, u32)> {
        let sb = ffs_ondisk::ext4::Ext4Superblock::parse_from_image(image)
            .expect("parse ext4 superblock from image bytes");
        let block_size = sb.block_size as usize;
        let bpg = sb.blocks_per_group;
        let desc_size = sb.desc_size.max(32);
        let group_count = u32::try_from(
            sb.blocks_count
                .saturating_sub(u64::from(sb.first_data_block))
                .div_ceil(u64::from(bpg)),
        )
        .expect("group count fits u32");
        // The GDT starts in the block after the one holding the superblock.
        let gdt_block = if block_size == 1024 { 2 } else { 1 };
        let gdt_off = gdt_block * block_size;

        let mut mismatches = Vec::new();
        for g in 0..group_count {
            let off = gdt_off + (g as usize) * usize::from(desc_size);
            let Ok(gd) = ffs_ondisk::ext4::Ext4GroupDesc::parse_from_bytes(
                &image[off..off + usize::from(desc_size)],
                desc_size,
            ) else {
                continue;
            };
            if gd.flags & ffs_ondisk::ext4::EXT4_BG_BLOCK_UNINIT != 0 {
                continue; // bitmap not authoritative for an uninitialised group
            }
            // Blocks this group actually owns (the last group is short).
            let first = u64::from(sb.first_data_block) + u64::from(g) * u64::from(bpg);
            let owned = u32::try_from((sb.blocks_count - first).min(u64::from(bpg)))
                .expect("blocks per group fits u32");
            let bm_off = (gd.block_bitmap as usize) * block_size;
            if bm_off + block_size > image.len() {
                continue;
            }
            let bitmap = &image[bm_off..bm_off + block_size];
            let counted = (0..owned)
                .filter(|b| {
                    let i = *b as usize;
                    bitmap[i / 8] & (1u8 << (i % 8)) == 0
                })
                .count();
            let counted = u32::try_from(counted).expect("free count fits u32");
            if counted != gd.free_blocks_count {
                mismatches.push((g, gd.free_blocks_count, counted));
            }
        }
        mismatches
    }

    /// bd-hyysq (P0): an ALLOCATING workload must leave the group descriptors
    /// consistent with the bitmaps under BOTH GDT-persistence modes.
    ///
    /// The defect: `ext4_flush_group_descriptors` opened with
    /// `if !gdt_persistence_deferred() { return Ok(()); }`, so in eager mode the
    /// durability boundary persisted NOTHING, on the assumption that a per-op
    /// eager write had already covered every allocation. It had not — a create
    /// storm left `bg_free_blocks_count` stale by exactly the blocks the workload
    /// consumed, and `e2fsck -fn` returned rc=4 with "Free blocks count wrong for
    /// group #0". Measured 2/2 on the mounted repro that filed this bead.
    ///
    /// ⚠ SCOPE: this test does NOT reproduce that mounted failure — see
    /// `ext4_eager_per_op_writes_alone_are_self_sufficient_here_bd_hyysq`, which
    /// measured zero mismatches even with the boundary flush skipped entirely.
    /// So this is a REGRESSION GATE on eager mode, not the bead's repro, and the
    /// accompanying source change (making the boundary flush unconditional) is
    /// hardening whose necessity is argued from the code rather than demonstrated
    /// by a red test. Said plainly so nobody later reads a green run here as
    /// evidence that bd-hyysq's trigger was found.
    ///
    /// What it does establish: in eager mode an allocating workload leaves an
    /// image that real `e2fsck -fn` accepts, checked first through the in-process
    /// oracle above (works on any host, so a builder without e2fsprogs cannot
    /// turn this into a silent pass) and then through e2fsck itself, with a
    /// planted-negative arm proving both checks actually bite.
    #[test]
    fn ext4_eager_gdt_allocating_workload_is_consistent_bd_hyysq() {
        let _restore = GdtModeRestore;
        ffs_alloc::set_gdt_persistence_deferred_for_test(Some(false));
        assert!(
            !ffs_alloc::gdt_persistence_deferred(),
            "this test must run in the EAGER mode that bd-hyysq broke"
        );

        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        // The workload from the bead: create+write+unlink PAIRS, not creates
        // alone. A create-only workload does NOT reproduce this (measured: the
        // 32-file create+write version of this test passed on the unfixed tree),
        // because every allocation it performs goes through a path that does an
        // eager per-op descriptor write. The pairs matter for two reasons: they
        // exercise the FREE paths as well as the alloc paths, and 512 entries
        // grow the root directory past its first block, so the directory's own
        // block allocations — which the create+write workload never triggered —
        // are in the mix. The bead's mounted repro used 1000 pairs and found
        // group #0 off by exactly 8 blocks.
        for i in 0..512u32 {
            let name = format!("hyysq_{i}.bin");
            let attr = fs
                .create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                .expect("create on real ext4 image");
            fs.write(&cx, attr.ino, 0, &[0xAB_u8; 4096])
                .expect("write file data");
            fs.unlink(&cx, root, OsStr::new(&name))
                .expect("unlink on real ext4 image");
        }
        // …and leave a residue of live files so the directory keeps the blocks it
        // grew into and the final state is not trivially "everything freed".
        for i in 0..32u32 {
            let name = format!("hyysq_live_{i}.bin");
            let attr = fs
                .create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                .expect("create live file");
            fs.write(&cx, attr.ino, 0, &[0xCD_u8; 8192])
                .expect("write live file data");
        }

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc to device");
        let bytes = dev.snapshot_bytes();

        let mismatches = ext4_group_free_block_mismatches(&bytes);
        assert!(
            mismatches.is_empty(),
            "eager-mode allocating workload left stale group-descriptor free-block \
             counts (group, declared, counted): {mismatches:?}"
        );

        // Planted negative: the oracle must actually bite. Corrupt group 0's
        // declared free-block count and require the audit to report it — a green
        // audit on a knowingly-wrong image would mean the check proves nothing.
        {
            let mut corrupt = bytes.clone();
            let sb = ffs_ondisk::ext4::Ext4Superblock::parse_from_image(&corrupt)
                .expect("parse superblock");
            let bs = sb.block_size as usize;
            let gdt_off = if bs == 1024 { 2 * bs } else { bs };
            // bg_free_blocks_count lo lives at descriptor offset 0x0C.
            let declared = u16::from_le_bytes([corrupt[gdt_off + 0x0C], corrupt[gdt_off + 0x0D]]);
            let wrong = declared.wrapping_add(8).to_le_bytes();
            corrupt[gdt_off + 0x0C] = wrong[0];
            corrupt[gdt_off + 0x0D] = wrong[1];
            let planted = ext4_group_free_block_mismatches(&corrupt);
            assert!(
                planted.iter().any(|&(g, _, _)| g == 0),
                "the free-count audit must flag a deliberately corrupted group 0"
            );
        }

        // Real e2fsck where e2fsprogs exists, including the planted negative.
        let image = tmp.path().join("hyysq.ext4");
        std::fs::write(&image, &bytes).expect("write image for e2fsck");
        let e2fsck_ran = run_e2fsck(&image).is_some();
        eprintln!("bd-hyysq: e2fsck_available={e2fsck_ran}");
        if let Some((clean, output)) = run_e2fsck(&image) {
            assert!(
                clean,
                "e2fsck -fn must accept an image written by an eager-mode \
                 allocating workload:\n{output}"
            );

            let corrupt_image = tmp.path().join("hyysq_corrupt.ext4");
            let mut corrupt = bytes.clone();
            let bs = ffs_ondisk::ext4::Ext4Superblock::parse_from_image(&corrupt)
                .expect("parse superblock")
                .block_size as usize;
            let gdt_off = if bs == 1024 { 2 * bs } else { bs };
            let declared = u16::from_le_bytes([corrupt[gdt_off + 0x0C], corrupt[gdt_off + 0x0D]]);
            let wrong = declared.wrapping_add(8).to_le_bytes();
            corrupt[gdt_off + 0x0C] = wrong[0];
            corrupt[gdt_off + 0x0D] = wrong[1];
            std::fs::write(&corrupt_image, &corrupt).expect("write corrupt image");
            let (corrupt_clean, corrupt_output) =
                run_e2fsck(&corrupt_image).expect("e2fsck available for the negative arm too");
            assert!(
                !corrupt_clean,
                "e2fsck must REJECT an image whose group-0 free-block count was \
                 deliberately falsified — a green run here would mean the rc=0 \
                 assertion above proves nothing:\n{corrupt_output}"
            );
        }
    }

    /// bd-hyysq MEASURED NEGATIVE — this workload does NOT reproduce the bead,
    /// and the number recorded here is why.
    ///
    /// The hypothesis under test was that the eager per-op descriptor writes are
    /// insufficient on their own, which would make the now-unconditional
    /// boundary flush load-bearing. It is FALSE for this workload. Running the
    /// same 512 create+write+unlink pairs in eager mode and stopping after
    /// `flush_mvcc_versions_to_device` — exactly the state the defective code
    /// reached, since `ext4_flush_group_descriptors` early-returned in eager mode
    /// and contributed nothing — leaves **zero** group-descriptor/bitmap
    /// mismatches. Measured on worker hz3, 2026-08-30.
    ///
    /// So the in-process create/write/unlink path is NOT the trigger for the
    /// mounted `FFS_SKIP_GDT=0` failure the bead reports (e2fsck rc=4, group #0
    /// declared 28125 free vs counted 28117 — 8 blocks allocated whose descriptor
    /// update never landed). The trigger is somewhere this harness does not
    /// reach; candidates not yet excluded are the mounted FUSE dispatch path, the
    /// clean-unmount boundary rather than `flush_mvcc_to_device`, and directory
    /// or flex_bg metadata allocations.
    ///
    /// Kept as a CHARACTERISATION test rather than deleted: it pins the fact that
    /// eager per-op persistence is self-sufficient here, so if that ever stops
    /// being true this goes red and the next person learns it immediately instead
    /// of re-deriving it. It asserts the measurement, not the hypothesis.
    #[test]
    fn ext4_eager_per_op_writes_alone_are_self_sufficient_here_bd_hyysq() {
        let _restore = GdtModeRestore;
        ffs_alloc::set_gdt_persistence_deferred_for_test(Some(false));

        let Some((fs, dev, _tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        for i in 0..512u32 {
            let name = format!("hyysq_ctl_{i}.bin");
            let attr = fs
                .create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                .expect("create on real ext4 image");
            fs.write(&cx, attr.ino, 0, &[0xAB_u8; 4096])
                .expect("write file data");
            fs.unlink(&cx, root, OsStr::new(&name))
                .expect("unlink on real ext4 image");
        }
        for i in 0..32u32 {
            let name = format!("hyysq_ctl_live_{i}.bin");
            let attr = fs
                .create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                .expect("create live file");
            fs.write(&cx, attr.ino, 0, &[0xCD_u8; 8192])
                .expect("write live file data");
        }

        // Versions only — deliberately NOT the descriptor pass, superblock
        // totals, or anything else the durability boundary does.
        let base_dev = fs.direct_block_device_adapter();
        fs.flush_mvcc_versions_to_device(&cx, &base_dev)
            .expect("flush mvcc versions");
        let bytes = dev.snapshot_bytes();

        let mismatches = ext4_group_free_block_mismatches(&bytes);
        eprintln!("bd-hyysq: mismatches without the boundary flush = {mismatches:?}");
        assert!(
            mismatches.is_empty(),
            "MEASUREMENT CHANGED: the eager per-op descriptor writes used to be \
             self-sufficient for this workload (0 mismatches, hz3 2026-08-30) and \
             now leave {} group(s) stale: {mismatches:?}. That is new information \
             about bd-hyysq — it means this harness has finally reached the \
             mounted repro's trigger. Investigate before touching this assertion.",
            mismatches.len()
        );
    }

    /// Special-file inodes — a character device node, a block device node, and a
    /// FIFO — must leave an ext4 image e2fsck-clean. Existing mknod tests only
    /// round-trip the rdev back through FrankenFS's own getattr (internal
    /// consistency); this is the only check that the ON-DISK device inode is
    /// kernel-valid: a device/FIFO inode carries no data (i_size 0, i_blocks 0,
    /// no EXTENTS_FL), and the rdev lives in i_block[0] (old encoding) or
    /// i_block[1] (new), with the rest of i_block zero. A stray EXTENTS flag,
    /// allocated block, or non-zero size on these inodes would surface here.
    #[test]
    fn ext4_special_files_pass_e2fsck() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let image = tmp.path().join("test.ext4");
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        fs.mknod(
            &cx,
            root,
            OsStr::new("cdev"),
            (libc::S_IFCHR as u16) | 0o644,
            259, // makedev(1, 3), e.g. /dev/null
            0,
            0,
        )
        .expect("mknod character device");
        fs.mknod(
            &cx,
            root,
            OsStr::new("bdev"),
            (libc::S_IFBLK as u16) | 0o644,
            2048, // makedev(8, 0), e.g. /dev/sda
            0,
            0,
        )
        .expect("mknod block device");
        fs.mknod(
            &cx,
            root,
            OsStr::new("fifo"),
            (libc::S_IFIFO as u16) | 0o644,
            0,
            0,
            0,
        )
        .expect("mknod FIFO");
        // A large device number (minor >= 256, so it does not fit the 16-bit old
        // encoding) exercises the NEW rdev encoding stored in i_block[1] with
        // i_block[0] zero — a separate code path from the three nodes above.
        fs.mknod(
            &cx,
            root,
            OsStr::new("bigdev"),
            (libc::S_IFCHR as u16) | 0o644,
            1_050_668, // makedev(8, 300): minor 300 forces the new (i_block[1]) form
            0,
            0,
        )
        .expect("mknod large-rdev character device");

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc to device");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write modified image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            clean,
            "e2fsck must accept FrankenFS-written ext4 device nodes (old + new rdev encoding) and a FIFO:\n{output}"
        );
    }

    /// Both ext4 symlink forms must leave the image e2fsck-clean. A FAST symlink
    /// (< 60-byte target) stores the target inline in i_block with no data block
    /// (i_size = target length, i_blocks = 0). A SLOW symlink (longer target)
    /// allocates a data block holding the target (i_size = target length,
    /// i_blocks accounting for that block, an extent mapping it). The existing
    /// symlink tests only round-trip the target back through readlink — internal
    /// consistency — and never validate the on-disk i_size/i_blocks/extent
    /// encoding, where a wrong block count or stray inline byte would surface
    /// only under e2fsck.
    #[test]
    fn ext4_symlinks_pass_e2fsck() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let image = tmp.path().join("test.ext4");
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        let fast_target = "short/target.txt";
        assert!(fast_target.len() < ffs_types::EXT4_FAST_SYMLINK_MAX);
        fs.symlink(
            &cx,
            root,
            OsStr::new("fastlink"),
            Path::new(fast_target),
            0,
            0,
        )
        .expect("create fast symlink");

        let slow_target = "/var/lib/frankenfs/some/really/long/path/exceeding/sixty/bytes/for/the/slow/symlink-target.txt";
        assert!(slow_target.len() > ffs_types::EXT4_FAST_SYMLINK_MAX);
        let slow = fs
            .symlink(
                &cx,
                root,
                OsStr::new("slowlink"),
                Path::new(slow_target),
                0,
                0,
            )
            .expect("create slow symlink");
        assert!(
            !fs.read_inode(&cx, slow.ino)
                .expect("read slow symlink inode")
                .is_fast_symlink(),
            "the long target must be a slow (block-mapped) symlink"
        );

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc to device");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write modified image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            clean,
            "e2fsck must accept FrankenFS-written fast and slow ext4 symlinks:\n{output}"
        );
    }

    /// bd-zpe9s: when a file's extent tree grows past its inline 4-extent root
    /// (depth >= 1), ffs_btree::insert allocates on-disk index/leaf metadata
    /// blocks that must be charged to i_blocks alongside the data blocks, or
    /// e2fsck reports "i_blocks is X, should be Y". The fix snapshots the
    /// extent-tree metadata-block count at the start of each write/fallocate and
    /// applies the signed delta at the end, so it stays correct under both growth
    /// and the tree later shrinking via coalescing. Writes many discontiguous
    /// single-block extents (holes defeat coalescing) to force growth, then
    /// requires e2fsck clean.
    #[test]
    fn ext4_extent_tree_growth_counts_metadata_in_iblocks_bd_zpe9s() {
        let Some((fs, dev, _tmp, image)) = open_ext4_mke2fs(16, false) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let bs = u64::from(fs.ext4_superblock().expect("sb").block_size);
        let attr = fs
            .create(&cx, InodeNumber(2), OsStr::new("grow.bin"), 0o644, 0, 0)
            .expect("create");

        // 16 single blocks at even logical offsets: the holes between them defeat
        // extent coalescing, so the 16 discontiguous extents overflow the inline
        // 4-extent root and grow the tree to depth >= 1, allocating extent-tree
        // metadata blocks that must land in i_blocks.
        for k in 0..16u64 {
            fs.write(&cx, attr.ino, k * 2 * bs, &vec![0xCD_u8; bs as usize])
                .expect("discontiguous write");
        }

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        // The pre-fix bug surfaces specifically as an i_blocks mismatch; assert
        // on that directly (and on overall cleanliness) so the regression is
        // unambiguous even if e2fsck emits unrelated optimization notices.
        assert!(
            !output.contains("i_blocks"),
            "e2fsck must not report an i_blocks mismatch after extent-tree growth:\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept a file whose extent tree grew to depth >= 1:\n{output}"
        );
    }

    /// metadata_csum companion to bd-zpe9s: when a file's extent tree grows past
    /// the inline 4-extent root, the newly allocated external leaf/index blocks
    /// each carry an `ext4_extent_tail` CRC32C keyed on the fs csum seed + the
    /// owning inode's number + generation. That tail is stamped via the block
    /// allocator's `finalize_node` hook (GroupBlockAllocator), which `write_node`
    /// invokes on every grow/rewrite. bd-zpe9s exercises growth only on a
    /// `^metadata_csum` image (isolating the i_blocks accounting), so it would not
    /// catch a missing or mis-keyed extent-block checksum — the extent-tree analog
    /// of the empty-directory tail gap (bd-bribi). This pins the end-to-end
    /// stamping: grow the tree on a metadata_csum image and require real e2fsck to
    /// find no extent-checksum damage.
    #[test]
    fn ext4_extent_tree_growth_stamps_block_csum_passes_e2fsck() {
        let Some((fs, dev, _tmp, image)) = open_ext4_mke2fs(16, true) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let bs = u64::from(fs.ext4_superblock().expect("sb").block_size);
        let attr = fs
            .create(
                &cx,
                InodeNumber(2),
                OsStr::new("grow_csum.bin"),
                0o644,
                0,
                0,
            )
            .expect("create");

        // 16 discontiguous single-block writes (holes defeat coalescing) overflow
        // the inline 4-extent root and grow the tree to depth >= 1, allocating
        // external extent blocks that must be checksum-stamped on metadata_csum.
        for k in 0..16u64 {
            fs.write(&cx, attr.ino, k * 2 * bs, &vec![0xCD_u8; bs as usize])
                .expect("discontiguous write");
        }

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            clean,
            "e2fsck must accept a metadata_csum file whose extent tree grew to depth >= 1 \
             (an unstamped/mis-keyed ext4_extent_tail would surface here):\n{output}"
        );
    }

    /// bd-kyp2q: the directory-mapping paths (`ext4_add_dir_entry` linear growth
    /// and `ext4_rebuild_htree_dir`) insert into a directory's extent tree via
    /// direct `ffs_btree::insert` calls. Once that tree grows past its inline
    /// 4-extent root the allocated index/leaf metadata blocks must be charged to
    /// the directory `i_blocks`, or e2fsck reports "i_blocks is X, should be Y"
    /// — the directory analog of the file-write gap (bd-zpe9s).
    ///
    /// Uses a `^dir_index` image so the directory stays LINEAR and grows one
    /// block at a time through the `ext4_add_dir_entry` insert (an htree rebuild
    /// would re-pack the directory into fresh, possibly-contiguous blocks and
    /// hide the fragmentation). A 4 KiB file write per entry occupies the block
    /// the directory's contiguity hint would otherwise reuse, so the directory
    /// blocks fragment across the disk: >4 discontiguous extents overflow the
    /// inline root and force the extent tree to depth >= 1.
    #[test]
    fn ext4_dir_extent_tree_growth_counts_metadata_in_iblocks_bd_kyp2q() {
        let Some((fs, dev, _tmp, image)) =
            open_ext4_mke2fs_features(16, "extent,fast_commit,^metadata_csum,^dir_index")
        else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        // At a 1 KiB block size a linear directory needs many blocks for 300
        // entries; the 4 KiB file write between each create occupies the blocks
        // the directory's contiguity hint would reuse, so the directory blocks
        // scatter. The resulting >4 discontiguous extents overflow the inline
        // root and grow the extent tree to depth >= 1, allocating index/leaf
        // metadata blocks that must land in the directory i_blocks.
        for i in 0..300u32 {
            let name = format!("entry_{i:04}.dat");
            let attr = fs
                .create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                .expect("create entry");
            fs.write(&cx, attr.ino, 0, &[0xAB_u8; 4096])
                .expect("write file data");
        }

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        // The pre-fix bug surfaces as an i_blocks mismatch on the directory
        // inode; assert on that directly (and on overall cleanliness).
        assert!(
            !output.contains("i_blocks"),
            "e2fsck must not report an i_blocks mismatch after directory extent-tree growth:\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept a directory whose extent tree grew to depth >= 1:\n{output}"
        );
    }

    /// Broader e2fsck stress (bd-0ta4z follow-on): exercise many ext4 write-path
    /// mutations — multi-block file writes, a subdirectory, an unlink (free
    /// path), a rename, and a fallocate — then require the image to be
    /// e2fsck-clean. Catches accounting regressions the single-create test
    /// cannot (free paths, used_dirs, multi-group allocation).
    #[test]
    fn ext4_many_mutations_pass_e2fsck_bd_0ta4z() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let image = tmp.path().join("test.ext4");
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        // 20 files, 4 blocks (16 KiB) each — exercises inode + block allocation.
        for i in 0..20 {
            let name = format!("file_{i:02}.dat");
            let attr = fs
                .create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                .expect("create");
            fs.write(&cx, attr.ino, 0, &[0xCD_u8; 16384])
                .expect("write");
        }
        // A subdirectory with a file inside (exercises used_dirs + nested dirs).
        let dir = fs
            .mkdir(&cx, root, OsStr::new("subdir"), 0o755, 0, 0)
            .expect("mkdir");
        let inner = fs
            .create(&cx, dir.ino, OsStr::new("inner.txt"), 0o644, 0, 0)
            .expect("create inner");
        fs.write(&cx, inner.ino, 0, &[0xEE_u8; 4096])
            .expect("write inner");
        // Unlink (inode + block free path) and rename.
        fs.unlink(&cx, root, OsStr::new("file_05.dat"))
            .expect("unlink");
        fs.rename(
            &cx,
            root,
            OsStr::new("file_06.dat"),
            root,
            OsStr::new("renamed.dat"),
        )
        .expect("rename");
        // Preallocate beyond the file's data.
        fs.fallocate(&cx, inner.ino, 0, 8192, libc::FALLOC_FL_KEEP_SIZE)
            .expect("fallocate");

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc to device");
        let bytes = dev.snapshot_bytes();
        std::fs::write(&image, &bytes).expect("write modified image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            clean,
            "e2fsck must accept a multi-mutation FrankenFS ext4 image:\n{output}"
        );
    }

    /// bd-bribi: an EMPTY directory created on a metadata_csum filesystem must
    /// leave its data block's CRC32C tail correctly stamped. The mkdir path
    /// initialized the new dir block (`.`/`..` + a zeroed checksum tail) and wrote
    /// it WITHOUT stamping — only the add_entry paths restamp — so a directory
    /// that never receives an entry reached disk with a zero checksum and e2fsck
    /// pass 2 reported "directory passes checks but fails checksum". (A subdir
    /// that later gets a file appeared clean because the add restamps the block,
    /// which is why the single-subdir bd-0ta4z stress did not catch it.) Minimal
    /// repro from the namespace-churn proptest: two empty sibling subdirs (pa, pb)
    /// plus a single create in root.
    #[test]
    fn ext4_empty_dir_block_csum_stamped_passes_e2fsck_bd_bribi() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let image = tmp.path().join("test.ext4");
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        // Two empty sibling subdirectories — neither ever receives an entry, so
        // their blocks are never restamped by an add_entry on the writable path.
        fs.mkdir(&cx, root, OsStr::new("pa"), 0o755, 0, 0)
            .expect("mkdir pa");
        fs.mkdir(&cx, root, OsStr::new("pb"), 0o755, 0, 0)
            .expect("mkdir pb");
        // A single create in root (the minimal churn op from the proptest).
        fs.create(&cx, root, OsStr::new("f0"), 0o644, 0, 0)
            .expect("create f0");

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc to device");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write modified image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("fails checksum"),
            "empty-directory data block must carry a correct metadata_csum tail (bd-bribi):\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept empty sibling subdirectories on a metadata_csum image (bd-bribi):\n{output}"
        );
    }

    /// Renaming a directory into a DIFFERENT parent on a metadata_csum image
    /// exercises two paths no other e2fsck test covers: (1) the in-place `..`
    /// repoint of the moved directory's block 0 and its subsequent re-stamp
    /// (lib.rs ~16790: dx_root vs linear keyed on the moved dir's own inode +
    /// generation), and (2) the parent link-count deltas (old parent loses the
    /// child's `..` backlink, new parent gains one). A wrong `..` checksum would
    /// surface as "directory passes checks but fails checksum" (the bd-bribi
    /// failure mode) and a wrong link count as "Inode N ref count is M, should be
    /// K". The namespace-churn proptest renames among parents but defers e2fsck;
    /// bd-0ta4z renames a plain file, not a directory. This pins the directory
    /// cross-parent rename deterministically.
    #[test]
    fn ext4_dir_rename_across_parents_passes_e2fsck() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // format tool unavailable
        };
        let image = tmp.path().join("test.ext4");
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        let a = fs
            .mkdir(&cx, root, OsStr::new("a"), 0o755, 0, 0)
            .expect("mkdir a");
        let b = fs
            .mkdir(&cx, root, OsStr::new("b"), 0o755, 0, 0)
            .expect("mkdir b");
        // A subdirectory inside `a`, itself holding a file, so the move shifts a
        // non-trivial subtree and its `..` backlink between parents.
        let sub = fs
            .mkdir(&cx, a.ino, OsStr::new("sub"), 0o755, 0, 0)
            .expect("mkdir a/sub");
        let inner = fs
            .create(&cx, sub.ino, OsStr::new("inner.txt"), 0o644, 0, 0)
            .expect("create a/sub/inner.txt");
        fs.write(&cx, inner.ino, 0, &[0x5A_u8; 1024])
            .expect("write inner");

        // Move the directory `a/sub` -> `b/sub`: repoints sub's `..` from a to b
        // and adjusts both parents' link counts.
        fs.rename(&cx, a.ino, OsStr::new("sub"), b.ino, OsStr::new("sub"))
            .expect("rename a/sub -> b/sub");

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc to device");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write modified image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("fails checksum"),
            "moved directory's '..' block must carry a correct metadata_csum tail:\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept a directory renamed across parents on a metadata_csum image:\n{output}"
        );
    }

    /// bd-0y7jp: a block group's `bg_used_dirs_count` must stay correct as
    /// directory inodes are created and freed, or e2fsck reports "Directories
    /// count wrong for group #N". On the writable path the count was previously
    /// never maintained — `alloc_inode_persist` used the `is_directory` hint only
    /// for Orlov target-group selection and `free_inode_persist` ignored it — so
    /// the persisted descriptor drifted from the actual directory count. The fix
    /// increments the owning group's `used_dirs` on directory-inode allocation
    /// and decrements it on free, in the same group-descriptor write.
    ///
    /// Uses a `^metadata_csum` image so the assertion isolates the directory-count
    /// accounting from the separate writable-path directory-block-checksum gap
    /// (bd-bribi). Creates many directories (Orlov spreads them across both 1 KiB
    /// block groups), removes half, and creates/unlinks a plain file (which must
    /// NOT touch `used_dirs`), then requires e2fsck to find no directory-count
    /// mismatch.
    #[test]
    fn ext4_dir_count_maintained_passes_e2fsck_bd_0y7jp() {
        let Some((fs, dev, _tmp, image)) = open_ext4_mke2fs(16, false) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        // 24 directories: Orlov dir-spreading places them across both block
        // groups, exercising the per-group used_dirs increment in each.
        for i in 0..24u32 {
            fs.mkdir(&cx, root, OsStr::new(&format!("d{i:02}")), 0o755, 0, 0)
                .expect("mkdir");
        }
        // Remove half (exercises the used_dirs decrement on the free path).
        for i in (0..24u32).step_by(2) {
            fs.rmdir(&cx, root, OsStr::new(&format!("d{i:02}")))
                .expect("rmdir");
        }
        // A plain file create+unlink must NOT change any group's used_dirs.
        let f = fs
            .create(&cx, root, OsStr::new("plain.txt"), 0o644, 0, 0)
            .expect("create");
        fs.write(&cx, f.ino, 0, &[0xAB_u8; 2048]).expect("write");
        fs.unlink(&cx, root, OsStr::new("plain.txt"))
            .expect("unlink");

        fs.flush_mvcc_to_device(&cx).expect("flush mvcc");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("Directories count wrong"),
            "e2fsck must not report a directory-count mismatch after dir create/rmdir churn (bd-0y7jp):\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept the image after directory create/rmdir churn:\n{output}"
        );
    }

    fn open_writable_ext4_mkfs_with_incompat_features(
        size_mb: u64,
        incompat_bits: u32,
    ) -> Option<(OpenFs, tempfile::TempDir)> {
        let tmp = tempfile::TempDir::new().expect("tmpdir");
        let image = tmp.path().join("test.ext4");
        let f = std::fs::File::create(&image).expect("create image");
        f.set_len(size_mb * 1024 * 1024).expect("set image size");
        drop(f);

        let out = std::process::Command::new("mkfs.ext4")
            .args(["-F", "-b", "4096", image.to_str().unwrap()])
            .output();
        let out = match out {
            Ok(o) if o.status.success() => o,
            _ => return None,
        };
        let _ = out;

        let _ = std::process::Command::new("debugfs")
            .args([
                "-w",
                "-R",
                "set_inode_field / mode 040777",
                image.to_str().unwrap(),
            ])
            .output();

        let mut data = std::fs::read(&image).expect("read image");
        let sb_off = EXT4_SUPERBLOCK_OFFSET;
        let incompat_off = sb_off + 0x60;
        let checksum_off = sb_off + EXT4_SB_CHECKSUM_OFFSET;
        let mut feature_incompat = u32::from_le_bytes(
            data[incompat_off..incompat_off + 4]
                .try_into()
                .expect("feature_incompat bytes"),
        );
        feature_incompat |= incompat_bits;
        data[incompat_off..incompat_off + 4].copy_from_slice(&feature_incompat.to_le_bytes());
        let checksum = ffs_ondisk::ext4::ext4_chksum_skip_zero_tail(
            !0u32,
            &data[sb_off..sb_off + EXT4_SB_CHECKSUM_OFFSET],
        );
        data[checksum_off..checksum_off + 4].copy_from_slice(&checksum.to_le_bytes());

        let cx = Cx::for_testing();
        let dev = TestDevice::from_vec(data);
        let opts = OpenOptions {
            ext4_journal_replay_mode: Ext4JournalReplayMode::Apply,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(&cx, Box::new(dev), &opts).expect("open ext4");
        fs.enable_writes(&cx).expect("enable writes");
        assert!(fs.is_writable());
        Some((fs, tmp))
    }

    /// Create a fresh ext4 image via `mkfs.ext4`, returning a clonable device
    /// handle so crash tests can snapshot in-memory bytes before reopening.
    fn open_writable_ext4_mkfs_with_device(
        size_mb: u64,
    ) -> Option<(OpenFs, TestDevice, tempfile::TempDir)> {
        let tmp = tempfile::TempDir::new().expect("tmpdir");
        let image = tmp.path().join("test.ext4");
        let f = std::fs::File::create(&image).expect("create image");
        f.set_len(size_mb * 1024 * 1024).expect("set image size");
        drop(f);

        let out = std::process::Command::new("mkfs.ext4")
            .args(["-F", "-b", "4096", image.to_str().unwrap()])
            .output();
        let out = match out {
            Ok(o) if o.status.success() => o,
            _ => return None,
        };
        let _ = out;

        let _ = std::process::Command::new("debugfs")
            .args([
                "-w",
                "-R",
                "set_inode_field / mode 040777",
                image.to_str().unwrap(),
            ])
            .output();

        let cx = Cx::for_testing();
        let data = std::fs::read(&image).expect("read image");
        let dev = TestDevice::from_vec(data);
        let snapshot = dev.clone();
        let opts = OpenOptions {
            ext4_journal_replay_mode: Ext4JournalReplayMode::Apply,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(&cx, Box::new(dev), &opts).expect("open ext4");
        fs.enable_writes(&cx).expect("enable writes");
        assert!(fs.is_writable());
        Some((fs, snapshot, tmp))
    }

    /// bd-y2t0r: the sharded delete routing must hold up under CONCURRENT
    /// create/delete from several threads, which is the workload the sharded
    /// allocator exists for.
    ///
    /// The 40-second mounted repro that validated the fix is SINGLE-THREADED, and
    /// "passes a single-threaded storm" is not "correct under the 8-thread
    /// parallel-metadata workload it was built for". `PerGroupAlloc::free_inode`
    /// locks only the group owning the inode — the intended design — so threads
    /// deleting inodes in different groups should not serialise and must not
    /// corrupt each other's counters.
    ///
    /// Each worker uses a PRIVATE subdirectory, mirroring the comparator's
    /// parallel-metadata-write shape, so the directory itself is not the
    /// contention point and the allocator is.
    ///
    /// Gated on the feature because the routing it exercises does not exist
    /// without it; the runtime toggle is set explicitly since it now defaults off
    /// (bd-pbyu0).
    /// ⛔ **STILL `#[ignore]`d, now because it is FLAKY rather than reliably red.**
    /// Measured across four full-suite runs after the third fix: 3 passed, 1
    /// failed. Three defects have been found and fixed and the failure has moved
    /// three times, but a 3-of-4 gate is not a gate.
    ///
    /// WHAT THE THIRD FIX ACTUALLY DID, stated by signature rather than by tally,
    /// because the tally alone would not distinguish "fixed" from "got luckier".
    /// Before it, every surviving conflict was on block 2085 with snapshot gaps of
    /// 77-178 commits. After it, the single failure was on block 39 with a gap of
    /// ONE. Those are different mechanisms: a wide gap means a transaction whose
    /// snapshot aged past a prune (the base-resolution class, now addressed by
    /// recording `staged_base` unconditionally), while a gap of one means two
    /// writers genuinely racing for the same block. The prune class appears to be
    /// gone and a contention residual remains. Four runs is a small sample and
    /// this reading should be re-checked, not trusted outright.
    ///
    /// WHAT IS LEFT: a residual FCW on an inode-table block under true
    /// contention, despite both writers declaring disjoint slots.
    ///
    /// ⛔ THE PROOF-DOWNGRADE EXPLANATION IS REFUTED — MEASURED, not argued. The
    /// suspect was a third writer staging an opaque whole-block write to that
    /// block in the same transaction, which would drag the accumulated proof down
    /// to `Unsafe`. `ffs_mvcc::proof_downgrade_count()` counts exactly that, and
    /// it reads ZERO across this workload on both the sharded and single-lock
    /// variants under full-suite load. No writer takes the plain path here at
    /// all, so the class cannot explain the residual and should not be
    /// re-proposed. That makes five hypotheses on this bead killed by
    /// measurement; the counter and its Drop-guard report stay so the sixth is
    /// cheaper to test.
    ///
    /// Whatever remains is therefore NOT a missing or lost proof. The untested
    /// direction is the merge itself: two writers with genuinely disjoint,
    /// correctly-declared slot ranges whose merge is nonetheless refused. That
    /// points at `check_write_mergeable_locked`'s inputs rather than at the
    /// staging paths — the `latest` resolution, or a range that is disjoint in
    /// the inode-slot sense but not in the byte sense (an inode straddling a
    /// boundary, or a checksum/padding region written outside the declared
    /// range). Measure before wiring: every previous diagnosis on this bead was
    /// wrong until measured.
    ///
    /// The three defects already fixed, all measured rather than inferred:
    ///
    /// 1. The parent-inode write. Every unlink writes its parent directory's
    ///    inode with `write_inode`, rewriting the parent's whole table block. Two
    ///    workers whose unrelated parents share a block then FCW-conflicted on
    ///    every unlink. Now staged slot-scoped.
    /// 2. Proof accumulation in `stage_rmw`. One transaction RMWs the same table
    ///    block twice (deleted child + parent), and the staged bytes accumulated
    ///    while the proof did not, so the second call declared a range narrower
    ///    than the bytes changed and the validator correctly rejected it. Ranges
    ///    are now unioned.
    /// 3. Unconditional `staged_base`. `stage_rmw` and the three
    ///    `FsMvccBlockDevice` RMW paths recorded a merge ancestor only when the
    ///    store held no version at the snapshot, trusting the version chain to
    ///    still hold it at commit. A concurrent `prune_after_commit_if_due` drops
    ///    it, the merge then resolves an EMPTY base, and a disjoint write aborts
    ///    on a spurious length mismatch. `rmw_commit_block_with_proof` already
    ///    recorded unconditionally for exactly this reason (bd-bhh0i's
    ///    inode-table pruning race); these four paths were left behind.
    ///
    /// THE FIRST DIAGNOSIS ON THIS BEAD WAS WRONG, which is why the layout dump
    /// below is permanent. The failure was attributed to the inode BITMAP lacking
    /// a clear-bits merge proof — inferred from the shape of the failure, never
    /// measured. Measuring it said otherwise:
    ///
    ///     group 0: block_bitmap=33 inode_bitmap=35 inode_table=37
    ///     group 1: block_bitmap=34 inode_bitmap=36 inode_table=2085
    ///     w0..w3 = inodes 13-16 -> table block 37
    ///     w4..w7 = inodes 17-20 -> table block 38
    ///
    /// Every conflict was on 37 or 38 — inode TABLE blocks — and each worker
    /// failed on ITS OWN parent directory's block. The bitmaps, 35 and 36, never
    /// appeared in one. A 4 KiB block holds 16 inodes at 256 bytes, so the eight
    /// per-worker directories, created consecutively, shared just two blocks.
    /// Both 37 and 38 are now silent; the surviving conflicts moved to 2085.
    ///
    /// This generalizes past the test: any parallel-metadata workload whose
    /// directories were created together collides the same way, which is exactly
    /// the shape the sharded allocator exists to serve.
    ///
    /// The `MergeProof::BitmapDelta` work from the wrong diagnosis was kept: the
    /// inode bitmap really did have no merge proof in either direction, so it
    /// would have conflicted as soon as this stopped masking it.
    ///
    /// The `..._under_single_lock_...` control beside this test runs the identical
    /// workload and must keep passing — without it a failure here would be
    /// unattributable between "the sharded routing is broken" and "concurrent
    /// removal was never supported at all".
    ///
    /// ⚠ The shipping default is still OFF (`bd-pbyu0`). This test green is
    /// necessary but NOT sufficient to flip it: the parallel-metadata comparator
    /// row that justifies the sharded path has not been re-measured with deletes
    /// routed, and bd-pbyu0 shipped a P0 precisely because a cutover was declared
    /// complete on partial evidence.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn concurrent_create_delete_under_sharded_alloc_keeps_counters_exact_bd_y2t0r() {
        concurrent_create_delete_counter_check_bd_y2t0r(true);
    }

    /// bd-y2t0r CONTROL: the identical concurrent workload on the SINGLE-LOCK
    /// path.
    ///
    /// Without this the sharded variant's result is unattributable — a failure
    /// could equally mean "the sharded delete routing breaks under concurrency"
    /// or "concurrent removal was never supported on this path at all". Running
    /// both distinguishes those, and neither answer is guessable from the code.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn concurrent_create_delete_under_single_lock_keeps_counters_exact_bd_y2t0r() {
        concurrent_create_delete_counter_check_bd_y2t0r(false);
    }

    /// bd-5vis3: DIRECT differential — every inode must resolve identically with
    /// the memo on and off, on a fixture large enough to span several leaves,
    /// queried in an order that is not the key order.
    ///
    /// This is the test that justifies shipping the memo enabled by default. The
    /// other two do not: the descent test catches a broken memo only because a
    /// wrong answer happens to make `getattr` FAIL there, and the concurrency
    /// test was proven by negative control not to guard the span check at all.
    /// Neither compares the memo's answers against the descent's.
    ///
    /// The scrambled order is the point. A sequential sweep stays inside one
    /// leaf, which is exactly the case an unguarded memo answers correctly by
    /// luck; stepping by a stride coprime to the entry count forces repeated
    /// crossings of leaf boundaries, where a wrong span check must diverge.
    #[test]
    fn btrfs_floor_memo_slots_from_value_parses_and_fails_safe_bd_2s8zy() {
        // Default when unset: the shipping size the counted 2.93x was measured on.
        assert_eq!(btrfs_floor_memo_slots_from_value(None), BTRFS_FLOOR_MEMO_SLOTS);
        // An explicit value is honoured, which is what makes a mounted A/B of the
        // sizing expressible from ONE ELF at all — a compile-time count cannot be
        // measured against the live kernel.
        assert_eq!(btrfs_floor_memo_slots_from_value(Some("4")), 4);
        assert_eq!(btrfs_floor_memo_slots_from_value(Some(" 32 ")), 32);
        // FAILS SAFE, and this is the half that matters. A zero-slot memo is not a
        // configuration anyone means; it is a silent ~2.9x increase in descent work.
        // Zero, empty, garbage and negatives all fall back to the default rather
        // than disabling the memo.
        assert_eq!(
            btrfs_floor_memo_slots_from_value(Some("0")),
            BTRFS_FLOOR_MEMO_SLOTS
        );
        assert_eq!(
            btrfs_floor_memo_slots_from_value(Some("")),
            BTRFS_FLOOR_MEMO_SLOTS
        );
        assert_eq!(
            btrfs_floor_memo_slots_from_value(Some("sixteen")),
            BTRFS_FLOOR_MEMO_SLOTS
        );
        assert_eq!(
            btrfs_floor_memo_slots_from_value(Some("-1")),
            BTRFS_FLOOR_MEMO_SLOTS
        );
    }

    #[test]
    fn btrfs_floor_memo_answers_match_the_descent_path_bd_5vis3() {
        let Some((fs, _files)) = open_populated_btrfs_readonly_bd_5vis3(4000) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(1);
        let mut inos: Vec<InodeNumber> = Vec::new();
        let mut names: Vec<Vec<u8>> = Vec::new();
        let mut offset = 0_u64;
        loop {
            let page = fs.readdir(&cx, root, offset).expect("readdir root");
            if page.is_empty() {
                break;
            }
            let next = page.last().map_or(offset + 1, |e| e.offset);
            for entry in &page {
                if entry.name != b"." && entry.name != b".." {
                    inos.push(entry.ino);
                    names.push(entry.name.clone());
                }
            }
            if next <= offset {
                break;
            }
            offset = next;
        }
        assert!(inos.len() >= 500, "fixture too small: {}", inos.len());

        // Stride coprime with the length: visits every entry exactly once while
        // jumping across leaves on every step.
        let n = inos.len();
        let stride = 977.min(n.saturating_sub(1)).max(1);
        let order: Vec<InodeNumber> = (0..n).map(|i| inos[(i * stride) % n]).collect();

        // Without this the FIRST sweep populates the read-only attr cache and the
        // SECOND is served from it, never reaching the memo — the differential
        // would compare the attr cache against itself and pass unconditionally.
        // Verified: with it left on, removing the span check entirely still left
        // this test green.
        fs.set_readonly_lookup_cache_disabled(true);
        let sweep = |disabled: bool| -> Vec<Option<(InodeNumber, u64, u64)>> {
            fs.set_btrfs_floor_memo_disabled(disabled);
            order
                .iter()
                .map(|ino| {
                    fs.getattr(&cx, *ino)
                        .ok()
                        .map(|a| (a.ino, a.size, a.blocks))
                })
                .collect()
        };

        // getattr is only ONE of four callers of the memoized descent. The others
        // are `btrfs_lookup_child` (name -> inode), `btrfs_read_file_into` (file
        // DATA via EXTENT_DATA) and `btrfs_fiemap_extent_items`. A memo defect on
        // the read path corrupts file CONTENT, which is far worse than a wrong
        // stat, and — measured — the entire rest of the ffs-core suite passes with
        // the span check removed, so nothing else guards those paths.
        let probe: Vec<&Vec<u8>> = names.iter().step_by(names.len().max(1) / 64 + 1).collect();
        let read_sweep = |disabled: bool| -> Vec<(Option<InodeNumber>, Option<Vec<u8>>)> {
            fs.set_btrfs_floor_memo_disabled(disabled);
            probe
                .iter()
                .map(|name| {
                    let child = fs
                        .lookup(&cx, root, std::ffi::OsStr::from_bytes(name))
                        .ok()
                        .map(|attr| attr.ino);
                    let data = child.and_then(|ino| fs.read(&cx, ino, 0, 4096).ok());
                    (child, data)
                })
                .collect()
        };
        let reads_without = read_sweep(true);
        let reads_with = read_sweep(false);
        assert!(
            reads_without
                .iter()
                .all(|(ino, data)| ino.is_some() && data.is_some()),
            "the descent path failed to look up or read a probe file — fixture or \
             walker broken, not the memo"
        );
        assert_eq!(
            reads_with, reads_without,
            "the floor-leaf memo changed a LOOKUP result or file CONTENT (bd-5vis3)"
        );

        let without = sweep(true);
        let with = sweep(false);
        assert!(
            without.iter().all(Option::is_some),
            "the descent path itself failed to resolve some inode — the fixture or \
             the walker is broken, not the memo"
        );
        assert_eq!(
            with, without,
            "the floor-leaf memo disagreed with the descent path on a scrambled \
             sweep across leaf boundaries (bd-5vis3)"
        );
    }

    /// Ground-truth row captured from the memo-disabled descent path: the inode
    /// number plus its `(ino, size, blocks)` attr triple.
    type BtrfsFloorAttrRow = (InodeNumber, Option<(InodeNumber, u64, u64)>);

    /// bd-5vis3: the floor-leaf memo must be correct under CONCURRENCY, because
    /// the mounted comparator row this bead owes is an 8-thread readdir+stat and
    /// the memo has only ever been exercised single-threaded.
    ///
    /// One memo is shared by every thread, so concurrent sweeps constantly evict
    /// each other's retained leaf. That is fine for throughput — a miss is just a
    /// descent — but it is exactly the shape that turns a subtly wrong span check
    /// into corrupt metadata under load and nothing under a single thread. The
    /// threads deliberately sweep in DIFFERENT orders so their spans disagree.
    ///
    /// Attribution: every thread must agree with the single-threaded answers
    /// captured before the threads start, WITH THE MEMO DISABLED, so the
    /// comparison is against the descent path rather than against the memo
    /// agreeing with itself.
    ///
    /// ⚠ WHAT THIS TEST DOES NOT COVER, established by negative control rather
    /// than assumed: it does NOT guard the span check. Removing that check
    /// entirely — the change that makes the memo serve leaves it does not own —
    /// leaves this test GREEN, at 64 entries and still at 3,000. The sweep here
    /// keeps landing in the leaf the previous descent reached, so an unguarded
    /// memo happens to answer correctly. The guard for the span check is
    /// `btrfs_stat_without_prewarm_...`, which fails loudly (7 of 48 entries
    /// resolving) because a wrong memo makes `getattr` FAIL rather than lie.
    ///
    /// So: this test covers concurrent access to a shared memo. It does not cover
    /// memo correctness. Do not treat it as the latter.
    #[test]
    fn btrfs_floor_memo_is_correct_under_concurrent_sweeps_bd_5vis3() {
        let Some((fs, _files)) = open_populated_btrfs_readonly_bd_5vis3(64) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(1);
        let listing = fs.readdir(&cx, root, 0).expect("readdir root");
        let inos: Vec<InodeNumber> = listing
            .iter()
            .filter(|e| e.name != b"." && e.name != b"..")
            .map(|e| e.ino)
            .collect();
        assert!(inos.len() >= 8, "fixture too small: {}", inos.len());

        // Ground truth must come from the memo-DISABLED path. Capturing it with
        // the memo active makes the comparison circular: a memo that is
        // systematically wrong agrees with itself, and the test passes while
        // metadata is corrupt. Verified by negative control — with the span check
        // removed, the circular version of this test still passed.
        fs.set_btrfs_floor_memo_disabled(true);
        let expected: Vec<BtrfsFloorAttrRow> = inos
            .iter()
            .map(|ino| {
                (
                    *ino,
                    fs.getattr(&cx, *ino)
                        .ok()
                        .map(|a| (a.ino, a.size, a.blocks)),
                )
            })
            .collect();
        assert!(
            expected.iter().all(|(_, attr)| attr.is_some()),
            "every entry must stat on the descent path before the memo is judged \
             against it"
        );
        fs.set_btrfs_floor_memo_disabled(false);

        let fs = std::sync::Arc::new(fs);
        let expected = std::sync::Arc::new(expected);
        std::thread::scope(|scope| {
            for worker in 0..8_usize {
                let fs = std::sync::Arc::clone(&fs);
                let expected = std::sync::Arc::clone(&expected);
                scope.spawn(move || {
                    let cx = Cx::for_testing();
                    let fs: &OpenFs = fs.as_ref();
                    for pass in 0..4 {
                        // Each worker walks a different rotation, and odd passes
                        // run backwards, so no two threads share a span pattern.
                        let rotate = worker * 7 + pass;
                        for step in 0..expected.len() {
                            let idx = if pass % 2 == 0 {
                                (step + rotate) % expected.len()
                            } else {
                                expected.len() - 1 - ((step + rotate) % expected.len())
                            };
                            let (ino, want) = &expected[idx];
                            let got = fs
                                .getattr(&cx, *ino)
                                .ok()
                                .map(|a| (a.ino, a.size, a.blocks));
                            assert_eq!(
                                &got, want,
                                "worker {worker} pass {pass} disagreed on inode {} — the \
                                 floor-leaf memo returned a different answer under \
                                 concurrency than a single-threaded sweep (bd-5vis3)",
                                ino.0
                            );
                        }
                    }
                });
            }
        });
    }

    /// bd-5vis3: the floor-leaf memo A/B on a fixture deep enough to matter.
    ///
    /// The landed measurement used 48 files, whose tree is shallow enough that
    /// only ~2 levels collapse. The quantity this bead promised was measured on a
    /// 32,770-entry directory, where a descent crosses more levels and there is
    /// correspondingly more to remove. This runs BOTH arms in one process against
    /// ONE image, toggling only the memo, so nothing but the memo differs.
    ///
    /// `#[ignore]`d because building the fixture costs real time; it is a
    /// measurement, not a gate. Run explicitly:
    ///   cargo test -p ffs-core --lib bd_5vis3_large -- --ignored --nocapture
    #[test]
    #[ignore = "bd-5vis3: measurement, not a gate — builds a large btrfs fixture"]
    fn btrfs_floor_memo_ab_on_a_large_fixture_bd_5vis3_large() {
        let Some((fs, files)) = open_populated_btrfs_readonly_bd_5vis3(20_000) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(1);
        // readdir returns ONE PAGE, so page through it. The 48-file test never
        // needed this because its listing fit in a single page; at 20k entries a
        // single call returns ~510 and silently under-samples the sweep.
        let mut inos: Vec<InodeNumber> = Vec::new();
        let mut offset = 0_u64;
        loop {
            let page = fs.readdir(&cx, root, offset).expect("readdir root");
            if page.is_empty() {
                break;
            }
            let next = page.last().map_or(offset + 1, |e| e.offset);
            for entry in &page {
                if entry.name != b"." && entry.name != b".." {
                    inos.push(entry.ino);
                }
            }
            if next <= offset {
                break;
            }
            offset = next;
        }
        assert!(
            inos.len() >= files / 2,
            "fixture under-populated: {} of {files}",
            inos.len()
        );

        // The read-only per-inode ATTR CACHE sits in front of the tree in
        // `btrfs_read_inode_attr`, so leaving it on means the second arm is served
        // from it and never reaches the memo at all — the two arms would differ by
        // cache warmth, not by the memo. Disable it so this measures what it says.
        fs.set_readonly_lookup_cache_disabled(true);
        let arm = |disabled: bool| {
            fs.set_btrfs_floor_memo_disabled(disabled);
            let (l0, h0) = crate::btrfs_node_cache_counters();
            let start = std::time::Instant::now();
            let mut ok = 0_u64;
            for ino in &inos {
                if fs.getattr(&cx, *ino).is_ok() {
                    ok += 1;
                }
            }
            let elapsed = start.elapsed();
            let (l1, h1) = crate::btrfs_node_cache_counters();
            (ok, elapsed, l1.saturating_sub(l0), h1.saturating_sub(h0))
        };

        // Memo OFF first so its arm is not handed a cache warmed by the other.
        let (ok_off, t_off, lookups_off, hits_off) = arm(true);
        let (ok_on, t_on, lookups_on, hits_on) = arm(false);
        assert_eq!(ok_off, ok_on, "both arms must stat the same inodes");

        println!(
            "bd-5vis3 SYNTHETIC SWEEP — NOT production-representative ({} inodes)\n  memo OFF: {t_off:?}  {lookups_off} lookups              ({:.2}/stat), {hits_off} hits\n  memo ON : {t_on:?}  {lookups_on} lookups              ({:.2}/stat), {hits_on} hits\n  lookups {:.2}x fewer, wall {:.3}x",
            ok_on,
            lookups_off as f64 / ok_off.max(1) as f64,
            lookups_on as f64 / ok_on.max(1) as f64,
            lookups_off as f64 / lookups_on.max(1) as f64,
            t_off.as_secs_f64() / t_on.as_secs_f64().max(f64::MIN_POSITIVE),
        );
        assert!(
            lookups_on < lookups_off,
            "the memo must reduce node lookups: on={lookups_on} off={lookups_off}"
        );
    }

    /// bd-5vis3: is the un-prewarmed btrfs stat cost per-inode DESCENT work over
    /// already-cached nodes, or is the 512-node cache THRASHING?
    ///
    /// Those have opposite fixes — a descent memo versus a bigger/smarter cache —
    /// and bd-3zx2x's 15.61x prewarm-on-versus-off measurement cannot tell them
    /// apart, because it only times the two arms. This counts what actually
    /// happens: node-cache lookups per stat and their hit rate.
    ///
    /// It also VALIDATES the counters added in 5ebd43b0, which until now had never
    /// been observed producing a number. `perf` is unavailable on this host
    /// (`perf_event_paranoid=4`), so counters are the instrument available.
    ///
    /// Skips cleanly when btrfs-progs is absent or cannot bake a populated image,
    /// matching every other fixture-dependent test here.
    #[test]
    fn btrfs_stat_without_prewarm_is_descent_work_not_cache_thrash_bd_5vis3() {
        let Some((fs, entries)) = open_populated_btrfs_readonly_bd_5vis3(48) else {
            return; // btrfs-progs unavailable, or no rootdir support
        };
        let cx = Cx::for_testing();
        assert!(
            entries >= 8,
            "fixture must hold enough inodes to be meaningful, got {entries}"
        );

        // Stat every entry with NO prewarm, so each getattr resolves its inode
        // through the fs-tree exactly as the FUSE mount does.
        let (lookups_before, hits_before) = crate::btrfs_node_cache_counters();
        let root = InodeNumber(1);
        let listing = fs.readdir(&cx, root, 0).expect("readdir root");
        let mut stats = 0_u64;
        for entry in &listing {
            if entry.name == b"." || entry.name == b".." {
                continue;
            }
            if fs.getattr(&cx, entry.ino).is_ok() {
                stats += 1;
            }
        }
        let (lookups_after, hits_after) = crate::btrfs_node_cache_counters();
        let lookups = lookups_after.saturating_sub(lookups_before);
        let hits = hits_after.saturating_sub(hits_before);
        // Every entry must resolve, not merely one. A wrong memo makes getattr
        // FAIL here rather than return bad data, so `stats > 0` passed while 41 of
        // 48 lookups were failing — measured via a negative control that removed
        // the span check.
        let expected_stats = listing
            .iter()
            .filter(|e| e.name != b"." && e.name != b"..")
            .count() as u64;
        assert_eq!(
            stats, expected_stats,
            "only {stats} of {expected_stats} entries stat'd — inode resolution is \
             failing, which is what a wrong floor-leaf memo looks like (bd-5vis3)"
        );
        assert!(
            lookups > 0,
            "the node-cache counters never moved across {stats} stats — the \
             instrument is not wired to the path it claims to measure (bd-5vis3)"
        );

        // ORDER-DIFFERENTIAL, the memo's specific failure mode. The memo serves
        // only when a target lands inside the retained leaf's span, so a reverse
        // sweep alternates in and out of that span in a different pattern than a
        // forward one. If the span check were wrong — serving a target the leaf
        // does not own — the two orders would disagree. Same inputs, two
        // traversal orders, identical answers required.
        let mut forward = Vec::with_capacity(listing.len());
        for entry in &listing {
            if entry.name == b"." || entry.name == b".." {
                continue;
            }
            forward.push((
                entry.ino,
                fs.getattr(&cx, entry.ino)
                    .ok()
                    .map(|a| (a.ino, a.size, a.blocks)),
            ));
        }
        let mut reverse = Vec::with_capacity(forward.len());
        for entry in listing.iter().rev() {
            if entry.name == b"." || entry.name == b".." {
                continue;
            }
            reverse.push((
                entry.ino,
                fs.getattr(&cx, entry.ino)
                    .ok()
                    .map(|a| (a.ino, a.size, a.blocks)),
            ));
        }
        reverse.reverse();
        assert_eq!(
            forward, reverse,
            "getattr disagreed between forward and reverse traversal — the floor-leaf              memo served a target outside the leaf it actually owns (bd-5vis3)"
        );

        let per_stat = lookups as f64 / stats as f64;
        let hit_rate = hits as f64 / lookups as f64;
        println!(
            "bd-5vis3: {stats} stats, {lookups} node lookups ({per_stat:.2}/stat), \
             {hits} hits ({:.1}%)",
            hit_rate * 100.0
        );

        // THE DISCRIMINATOR. A descent over cached nodes re-walks root+interior
        // per inode, so lookups/stat stays small and MOST resolve from cache. A
        // thrashing cache would show a hit rate collapsing toward zero, meaning
        // the fix is cache sizing rather than a descent memo. The bound is loose
        // on purpose: this asserts WHICH REGIME the path is in, not a number to
        // regress against, and a small fixture's first-touch misses are real.
        assert!(
            hit_rate > 0.25,
            "node-cache hit rate {:.1}% across {stats} stats ({per_stat:.2} \
             lookups/stat) — that is cache THRASHING, not descent-over-cached-nodes. \
             bd-5vis3's leaf-memo design targets the wrong mechanism if this holds \
             on a large fixture; re-check before implementing it.",
            hit_rate * 100.0
        );
    }

    /// bd-5vis3: the operator kill switch must actually parse, because the
    /// per-instance setter is reachable only from tests — as first shipped there
    /// was no way to disable this default-on read-path cache without a rebuild.
    #[test]
    fn btrfs_floor_memo_env_switch_parses_bd_5vis3() {
        // Parsing is asserted directly rather than through the environment: env
        // vars are process-global and a parallel test suite would race on them.
        for (raw, want_disabled) in [
            ("0", true),
            ("false", true),
            ("FALSE", true),
            ("off", true),
            ("Off", true),
            ("1", false),
            ("true", false),
            ("", false),
            ("yes", false),
        ] {
            let trimmed = raw.trim();
            let disabled = trimmed == "0"
                || trimmed.eq_ignore_ascii_case("false")
                || trimmed.eq_ignore_ascii_case("off");
            assert_eq!(
                disabled,
                want_disabled,
                "FFS_BTRFS_FLOOR_MEMO={raw:?} should {} the memo",
                if want_disabled {
                    "disable"
                } else {
                    "leave enabled"
                }
            );
        }
        // Unset means enabled: the default must stay on when nobody opts out.
        assert!(
            !std::env::var("FFS_BTRFS_FLOOR_MEMO_DEFINITELY_UNSET_KEY").is_ok_and(|_| true),
            "sanity: an unset variable must not read as set"
        );
    }

    /// bd-yu6jz: slot replacement must refresh a leaf IN PLACE before taking an
    /// empty slot — this is a regression test for a bug, not a style preference.
    ///
    /// The original order was empty-first, and it was wrong in the one case the
    /// four slots exist for. A floor descent returns the greatest key `<= target`,
    /// so a probe for a key BEYOND the reached leaf's last key — an absent
    /// XATTR_ITEM bucket, which is the usual answer for the capability probe —
    /// resolves to that leaf and retains a span that does not contain the target.
    /// Every repeat of the probe fails the span check, re-descends to the SAME
    /// leaf, and asks for a slot again. Empty-first deals that one leaf into every
    /// free slot and then evicts live neighbours: four slots collapse to one,
    /// exactly on the workload the widening was for.
    #[test]
    fn btrfs_floor_memo_refreshes_in_place_before_taking_an_empty_slot_bd_yu6jz() {
        let key = |objectid: u64| ffs_ondisk::btrfs::BtrfsKey {
            objectid,
            item_type: 1,
            offset: 0,
        };
        let root = 4096_u64;

        // THE REGRESSION. Slot 1 already holds this leaf while slots 0/2/3 are
        // empty. Empty-first answered 0 and duplicated the leaf; the contract is 1.
        let mut slots: [Option<(u64, ffs_ondisk::btrfs::BtrfsKey)>; BTRFS_FLOOR_MEMO_SLOTS] =
            [None; BTRFS_FLOOR_MEMO_SLOTS];
        slots[1] = Some((root, key(100)));
        assert_eq!(
            btrfs_floor_memo_reuse_slot(&slots, root, &key(100)),
            Some(1),
            "a slot already holding this leaf must be refreshed in place, never duplicated \
             into an empty slot"
        );

        // A leaf not present anywhere takes the FIRST empty slot.
        assert_eq!(
            btrfs_floor_memo_reuse_slot(&slots, root, &key(200)),
            Some(0),
            "an unseen leaf takes the lowest empty slot"
        );

        // Same first key but a different tree must NOT match — the two trees' key
        // spaces are unrelated, so this has to fall through to an empty slot.
        assert_eq!(
            btrfs_floor_memo_reuse_slot(&slots, root + 16384, &key(100)),
            Some(0),
            "identity is (root_logical, first_key); a different root is a different leaf"
        );

        // Full and no match: the caller must evict, which is signalled by None
        // rather than decided here.
        //
        // GENERATED from BTRFS_FLOOR_MEMO_SLOTS rather than written out. It used to
        // be four literals, with a note that changing the constant "stops
        // compiling, which is the right way to find out" — but what it actually
        // found out was a type error in an unrelated resize (bd-2s8zy took the
        // memo from 4 slots to 16), telling the reader nothing about the property
        // under test. The property is "full, and no slot matches", which holds at
        // any size; keying the fixture to the constant tests it at whatever the
        // constant is.
        let full: [Option<(u64, ffs_ondisk::btrfs::BtrfsKey)>; BTRFS_FLOOR_MEMO_SLOTS] =
            std::array::from_fn(|slot| {
                Some((
                    root,
                    key(10_u64.saturating_add(u64::try_from(slot).unwrap_or(0))),
                ))
            });
        assert_eq!(
            btrfs_floor_memo_reuse_slot(&full, root, &key(999)),
            None,
            "every slot live and none matching must ask the caller to evict"
        );
        // ...but a match in a FULL array still refreshes in place rather than evicting.
        assert_eq!(
            btrfs_floor_memo_reuse_slot(&full, root, &key(12)),
            Some(2),
            "a full memo must still refresh a leaf it already holds"
        );
    }

    /// bd-vpypn: windowed immutable-cache reads select a contiguous run and
    /// borrow inline payload bytes from their backing cache.
    #[test]
    fn btrfs_window_extent_selection_borrows_inline_payload_bd_vpypn() {
        let regular = |ram: u64| ffs_btrfs::BtrfsExtentData::Regular {
            generation: 1,
            ram_bytes: ram,
            extent_type: 1,
            compression: 0,
            disk_bytenr: 4096,
            disk_num_bytes: ram,
            extent_offset: 0,
            num_bytes: ram,
        };
        // Sorted, non-overlapping, with a gap between 8192 and 16384 so a read
        // landing in the hole exercises the lower-bound skip.
        let rows: Arc<[(u64, ffs_btrfs::BtrfsExtentData)]> = vec![
            (0, regular(4096)),
            (4096, regular(4096)),
            (16384, regular(4096)),
        ]
        .into();

        for (offset, end) in [
            (0_u64, 4096_u64), // exactly the first extent
            (0, 8192),         // both leading extents
            (2048, 6144),      // straddles the boundary
            (8192, 16384),     // entirely inside the hole
            (8192, 20480),     // hole then the third extent
            (16384, 20480),    // past the gap
            (99999, 100_000),  // beyond every extent
        ] {
            let indices = OpenFs::btrfs_window_extent_indices(&rows, offset, end).unwrap();
            let selected = BtrfsReadExtents::ReadPlan {
                rows: Arc::clone(&rows),
                indices: indices.clone(),
            };
            assert_eq!(
                indices.len(),
                selected.len(),
                "window [{offset}, {end}) selects a different count by index than by borrowed read"
            );
            for (i, (logical_start, extent)) in indices.iter().zip(selected.iter()) {
                assert_eq!(rows[*i].0, *logical_start);
                assert_eq!(
                    &rows[*i].1, extent,
                    "index and borrowed read disagree on the extent"
                );
            }
            // Selection must be a CONTIGUOUS run — that is what licenses stopping
            // the scan at the first extent past the window.
            for pair in indices.windows(2) {
                assert_eq!(pair[1], pair[0] + 1, "selected extents must be contiguous");
            }
        }

        // The performance contract: an Inline extent owns the file's bytes, so
        // the selected read must borrow them from the immutable cache, not clone
        // them before copying the requested bytes into the caller's output.
        let payload = vec![0xAB_u8; 2048];
        let inline_rows: Arc<[(u64, ffs_btrfs::BtrfsExtentData)]> = vec![(
            0,
            ffs_btrfs::BtrfsExtentData::Inline {
                generation: 1,
                ram_bytes: payload.len() as u64,
                compression: 0,
                data: payload.clone(),
            },
        )]
        .into();
        let selected = BtrfsReadExtents::ReadPlan {
            rows: Arc::clone(&inline_rows),
            indices: OpenFs::btrfs_window_extent_indices(&inline_rows, 0, 2048).unwrap(),
        };
        assert_eq!(selected.len(), 1);
        match (&inline_rows[0].1, selected.iter().next().unwrap().1) {
            (
                ffs_btrfs::BtrfsExtentData::Inline { data: original, .. },
                ffs_btrfs::BtrfsExtentData::Inline { data: borrowed, .. },
            ) => {
                assert_eq!(original, borrowed, "the borrowed payload must be faithful");
                assert_eq!(
                    original.as_ptr(),
                    borrowed.as_ptr(),
                    "the read-window iterator must retain the cache allocation"
                );
                let job = BtrfsReadJob::Inline {
                    idx: 0,
                    data: borrowed,
                    comp: 0,
                    ram: borrowed.len(),
                };
                let BtrfsReadJob::Inline { data, .. } = job else {
                    unreachable!("constructed inline job")
                };
                assert_eq!(
                    original.as_ptr(),
                    data.as_ptr(),
                    "the deferred inline read job must keep borrowing the cached payload"
                );
            }
            _ => panic!("expected two inline extents"),
        }
    }

    /// bd-5vis3: the memo's marginal cost must be the refcount, not the block.
    ///
    /// The bead requires added resident memory to be reported and names "a design
    /// that quietly regrows" as the failure it exists to catch. The claim that
    /// makes the memo cheap is that its leaves are the SAME `Arc`s the parsed-node
    /// cache already holds, so sharing must be measured rather than assumed — a
    /// shared leaf costs nothing extra, an exclusively-held one costs a whole
    /// block.
    #[test]
    fn btrfs_floor_memo_footprint_counts_sharing_bd_5vis3() {
        const NODESIZE: usize = 16384;
        let block = Arc::new(vec![0_u8; NODESIZE]);
        let leaf = BtrfsParsedNode::Leaf {
            block: Arc::clone(&block),
            items: Vec::new(),
        };
        // An empty item vec contributes nothing, so the block dominates and the
        // arithmetic is checkable exactly.
        assert_eq!(btrfs_parsed_node_heap_bytes(&leaf), NODESIZE);

        // An Internal node retains no block at all — it is pointers only, which is
        // why the memo deliberately retains LEAVES.
        let internal = BtrfsParsedNode::Internal { ptrs: Vec::new() };
        assert_eq!(btrfs_parsed_node_heap_bytes(&internal), 0);

        // Sole ownership vs shared, which is the distinction the accessor reports.
        let only = Arc::new(BtrfsParsedNode::Leaf {
            block: Arc::new(vec![0_u8; NODESIZE]),
            items: Vec::new(),
        });
        assert_eq!(Arc::strong_count(&only), 1, "a fresh Arc must be unshared");
        let shared = Arc::clone(&only);
        assert_eq!(
            Arc::strong_count(&only),
            2,
            "a second owner must make it shared, which is the case that costs the memo nothing"
        );
        drop(shared);
        assert_eq!(Arc::strong_count(&only), 1);
    }

    /// bd-5vis3: the memo is bounded BY CONSTRUCTION, and this pins that in a test
    /// rather than in a comment.
    ///
    /// The bead's whole objection to the read-plan index was memory proportional to
    /// the filesystem. The defence is that the memo is a fixed-size array, so it
    /// cannot grow with the image no matter how large the tree or how long the
    /// sweep. A future widening should have to change this number deliberately.
    #[test]
    fn btrfs_floor_memo_retention_is_bounded_bd_5vis3() {
        let entries: Vec<(&[u8], u64, u8, u32)> = vec![
            (b"aaa.txt", 257, ffs_btrfs::BTRFS_FT_REG_FILE, 0o100_644),
            (b"bbb.txt", 258, ffs_btrfs::BTRFS_FT_REG_FILE, 0o100_644),
            (b"ccc.txt", 259, ffs_btrfs::BTRFS_FT_REG_FILE, 0o100_644),
        ];
        let image = build_btrfs_readdir_image(&entries);
        let cx = Cx::for_testing();
        let fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(image)),
            &OpenOptions::default(),
        )
        .unwrap();

        // Nothing descended yet, so nothing is retained.
        let cold = fs.btrfs_floor_memo_footprint();
        assert_eq!(
            cold.retained_leaves, 0,
            "a mount that has not descended must retain no leaf"
        );
        assert_eq!(cold.upper_bound_bytes, 0);

        // Drive real descents through the ordinary read path.
        let ops: &dyn FsOps = &fs;
        let listing = ops
            .readdir(&cx, &mut RequestScope::empty(), InodeNumber(1), 0)
            .unwrap();
        for entry in &listing {
            let _ = ops.getattr(&cx, &mut RequestScope::empty(), entry.ino);
        }

        let warm = fs.btrfs_floor_memo_footprint();
        assert!(
            warm.retained_leaves <= BTRFS_FLOOR_MEMO_SLOTS,
            "the memo is a fixed {BTRFS_FLOOR_MEMO_SLOTS}-slot array and must never exceed it; \
             retained {}",
            warm.retained_leaves
        );
        assert!(
            warm.exclusive_bytes <= warm.upper_bound_bytes,
            "exclusive bytes are a subset of reachable bytes: {} > {}",
            warm.exclusive_bytes,
            warm.upper_bound_bytes
        );
    }

    /// bd-yu6jz: the floor-memo span rule is the correctness argument for answering a
    /// descent from memory, so it is checked directly rather than through a mount.
    ///
    /// A floor descent returns the greatest key `<= target`. A retained leaf may
    /// therefore answer ONLY for targets inside its own span: outside it, the leaf
    /// cannot prove what the neighbouring leaf holds, and serving from it would return
    /// a key that is not the true floor.
    #[test]
    fn btrfs_floor_memo_span_rule_bd_yu6jz() {
        let key = |objectid: u64, item_type: u8, offset: u64| ffs_ondisk::btrfs::BtrfsKey {
            objectid,
            item_type,
            offset,
        };
        let first = key(100, 1, 0);
        let last = key(200, 1, 0);
        let root = 4096_u64;

        // Inside the span, including both inclusive endpoints.
        for target in [key(100, 1, 0), key(150, 1, 0), key(200, 1, 0)] {
            assert!(
                btrfs_floor_memo_span_answers(root, &first, &last, root, &target),
                "target {target:?} is inside [{first:?}, {last:?}] and must be answerable"
            );
        }

        // Outside on either side: the leaf cannot prove the neighbour's contents.
        for target in [key(99, 1, 0), key(201, 1, 0)] {
            assert!(
                !btrfs_floor_memo_span_answers(root, &first, &last, root, &target),
                "target {target:?} is outside the span and MUST force a real descent"
            );
        }

        // A different tree root must never be served from this leaf, however well the
        // key happens to fall inside the span — the spans of two trees are unrelated.
        assert!(
            !btrfs_floor_memo_span_answers(root, &first, &last, root + 16384, &key(150, 1, 0)),
            "a slot from another tree root must not answer"
        );
    }

    /// bd-yu6jz: the getxattr fast-path kill switch must parse, and must default ON.
    ///
    /// This calls the REAL parser rather than restating its rule, so the test cannot
    /// drift from the code the way an inline copy can.
    #[test]
    fn btrfs_xattr_memo_env_switch_parses_bd_yu6jz() {
        for (raw, want_disabled) in [
            (Some("0"), true),
            (Some("false"), true),
            (Some("FALSE"), true),
            (Some("off"), true),
            (Some("Off"), true),
            (Some("  off  "), true),
            (Some("1"), false),
            (Some("true"), false),
            (Some("on"), false),
            (Some(""), false),
            (Some("yes"), false),
            (None, false),
        ] {
            assert_eq!(
                btrfs_xattr_memo_disabled_from_value(raw),
                want_disabled,
                "FFS_BTRFS_XATTR_MEMO={raw:?} should {} the getxattr fast path",
                if want_disabled {
                    "disable"
                } else {
                    "leave enabled"
                }
            );
        }
        // The load-bearing case: UNSET must leave the fast path on, so an environment
        // that never heard of this knob is byte-identical to the shipped behaviour.
        assert!(
            !btrfs_xattr_memo_disabled_from_value(None),
            "an unset FFS_BTRFS_XATTR_MEMO must leave the fast path ENABLED"
        );
    }

    /// bd-79li3: the miss-streak gate must be one-signed — invisible to a workload
    /// with locality, and bounded for one without.
    ///
    /// This drives the policy directly rather than through a btrfs image, because
    /// the property under test is the SCHEDULE of replacements, and a timed
    /// end-to-end arm cannot distinguish "the gate suppressed replacements" from
    /// "the machine was quiet". Timing lives in the ignored A/B arms; this asserts
    /// the mechanism those arms depend on.
    #[test]
    fn btrfs_floor_memo_miss_streak_gate_is_one_signed_bd_79li3() {
        let Some(fs) = open_empty_btrfs_for_floor_memo_policy_bd_79li3() else {
            return; // btrfs-progs unavailable
        };

        // A sweep: every miss is followed by hits (a leaf crossing, then a run
        // inside the new leaf). The streak never builds, so the gate must never
        // suppress — the 2.884x production win depends on replacing every time.
        for _ in 0..10_000 {
            assert!(
                fs.btrfs_floor_memo_should_replace(),
                "the gate suppressed a replacement on a workload that keeps hitting \
                 — this would silently cost the sweep case its win"
            );
            // Model the hit that follows: the real hit path resets the streak.
            fs.btrfs_floor_memo_consecutive_misses
                .store(0, std::sync::atomic::Ordering::Relaxed);
        }

        // A random stream: nothing ever hits, so nothing ever resets the streak.
        fs.btrfs_floor_memo_consecutive_misses
            .store(0, std::sync::atomic::Ordering::Relaxed);
        const PROBE: usize = 6_400;
        let replacements = (0..PROBE)
            .filter(|_| fs.btrfs_floor_memo_should_replace())
            .count();
        // 31 while the streak builds, then one probe per 64.
        let expected = 31 + (PROBE - 31).div_ceil(64);
        assert_eq!(
            replacements, expected,
            "miss-only stream did {replacements} replacements in {PROBE} descents, \
             expected {expected}"
        );
        // The point of the gate, stated as a bound rather than as an equality so a
        // future retune of the constants still has to keep the property.
        assert!(
            replacements * 20 < PROBE,
            "gate must cut the miss-path replacement cost by more than 20x; \
             {replacements}/{PROBE} is only {:.1}x",
            PROBE as f64 / replacements as f64
        );

        // And it must RE-ARM: a stream that regains locality gets the memo back.
        // One probe replacement lands a leaf; the hit that follows resets the
        // streak, and the very next descent replaces again.
        fs.btrfs_floor_memo_consecutive_misses
            .store(0, std::sync::atomic::Ordering::Relaxed);
        assert!(fs.btrfs_floor_memo_should_replace());

        // THE SUPPRESSION COUNTER MUST DISCRIMINATE (bd-79li3, 2026-08-24). The
        // integration arm `the_miss_streak_gate_does_not_fire_on_a_real_sweep_bd_79li3`
        // reports ZERO suppressions on a real readdir+stat sweep, which is the
        // gate's central claim finally checked against the workload it names. That
        // zero is only evidence if a non-zero is reachable, and this is the cheapest
        // place to prove it: the miss-only stream above is a true no-locality
        // stream, unlike a random ACCESS order over a small fixture, which still
        // retains enough leaf locality to reset the streak (measured: 6,000 entries
        // in stride order produced zero suppressions, so it cannot serve as the
        // control).
        //
        // Exact, not a bound: every descent in that stream either replaced or was
        // suppressed, so the two must sum to the stream length.
        let suppressions = fs.btrfs_floor_memo_suppressions();
        assert_eq!(
            suppressions,
            (PROBE - replacements) as u64,
            "the gate suppressed {replacements} of {PROBE} replacements but the counter \
             recorded {suppressions}; a counter that does not track the gate turns the \
             sweep arm's zero into an absence of measurement rather than a result"
        );
    }

    /// Smallest btrfs `OpenFs` that exercises the floor-memo policy (bd-79li3).
    /// The policy is filesystem-independent, so an empty image is enough and the
    /// test does not need to populate thousands of files to run in CI.
    fn open_empty_btrfs_for_floor_memo_policy_bd_79li3() -> Option<OpenFs> {
        let bytes = build_populated_btrfs_bytes_bd_5vis3(1)?;
        let cx = Cx::for_testing();
        OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(bytes)),
            &OpenOptions::default(),
        )
        .ok()
    }

    /// bd-3zx2x + bd-5vis3: THREE arms on ONE fixture — read-plan index, bounded
    /// memo, and neither.
    ///
    /// bd-3zx2x attributed the btrfs readdir+stat excess to the un-prewarmed
    /// per-inode descent, measured as a 15.61x gap between prewarm-on and
    /// prewarm-off. bd-5vis3 then built a bounded memo to remove that descent
    /// without the index's unbounded footprint. What has never been measured is
    /// the two against each other on the SAME fixture, which is the claim that
    /// actually matters: does one retained leaf capture what a
    /// whole-filesystem index buys?
    ///
    /// Cold fs per arm, attr cache disabled in all three so the comparison is
    /// between the three resolution strategies and nothing else.
    #[test]
    #[ignore = "bd-3zx2x/bd-5vis3: measurement, not a gate — builds a large btrfs fixture"]
    fn btrfs_index_versus_memo_versus_neither_bd_3zx2x() {
        let Some(bytes) = build_populated_btrfs_bytes_bd_5vis3(20_000) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();

        let arm = |prewarm: bool, memo: bool| -> (u64, std::time::Duration, u64) {
            let fs = OpenFs::from_device(
                &cx,
                Box::new(TestDevice::from_vec(bytes.clone())),
                &OpenOptions::default(),
            )
            .expect("open btrfs");
            fs.set_readonly_lookup_cache_disabled(true);
            fs.set_btrfs_floor_memo_disabled(!memo);
            if prewarm {
                fs.prewarm_btrfs_read_plan_index(&cx).expect("prewarm");
            }
            let root = InodeNumber(1);
            let mut inos: Vec<InodeNumber> = Vec::new();
            let mut offset = 0_u64;
            loop {
                let page = fs.readdir(&cx, root, offset).expect("readdir");
                if page.is_empty() {
                    break;
                }
                let next = page.last().map_or(offset + 1, |e| e.offset);
                for e in &page {
                    if e.name != b"." && e.name != b".." {
                        inos.push(e.ino);
                    }
                }
                if next <= offset {
                    break;
                }
                offset = next;
            }
            let (l0, _) = crate::btrfs_node_cache_counters();
            let start = std::time::Instant::now();
            let mut ok = 0_u64;
            for ino in &inos {
                if fs.getattr(&cx, *ino).is_ok() {
                    ok += 1;
                }
            }
            let elapsed = start.elapsed();
            let (l1, _) = crate::btrfs_node_cache_counters();
            (ok, elapsed, l1.saturating_sub(l0))
        };

        let (n0, t_neither, look_neither) = arm(false, false);
        let (n1, t_memo, look_memo) = arm(false, true);
        let (n2, t_index, look_index) = arm(true, false);
        assert_eq!(n0, n1);
        assert_eq!(n1, n2);
        println!(
            "bd-3zx2x THREE-ARM ({n0} inodes, attr cache off, cold fs each)\n               neither      : {t_neither:?}  {look_neither} lookups\n               memo (1 leaf): {t_memo:?}  {look_memo} lookups\n               index (whole): {t_index:?}  {look_index} lookups\n               memo vs neither {:.3}x, index vs neither {:.3}x, memo/index {:.3}x",
            t_neither.as_secs_f64() / t_memo.as_secs_f64().max(f64::MIN_POSITIVE),
            t_neither.as_secs_f64() / t_index.as_secs_f64().max(f64::MIN_POSITIVE),
            t_memo.as_secs_f64() / t_index.as_secs_f64().max(f64::MIN_POSITIVE),
        );
    }

    /// bd-5vis3: does the memo HURT a random-access workload?    /// bd-5vis3: does the memo HURT a random-access workload?    /// bd-5vis3: does the memo HURT a random-access workload?
    ///
    /// Every claim about this lever so far is a sequential sweep, where the memo
    /// hits constantly. The opposite case is the one that matters for shipping it
    /// enabled by default: on random access it mostly MISSES, and a miss is not
    /// free — it costs a mutex acquire and two key comparisons on every descent,
    /// paid before falling through to the walk it was trying to avoid.
    ///
    /// I have asserted "random access would see less benefit" repeatedly without
    /// checking it does not see a LOSS. This checks. A ratio meaningfully below
    /// 1.0 would mean the default-on setting taxes workloads that never benefit.
    ///
    /// Cold fs per arm, attr cache disabled so the memo is what is being measured
    /// rather than the cache in front of it.
    #[test]
    #[ignore = "bd-5vis3: measurement, not a gate — builds a large btrfs fixture"]
    fn btrfs_floor_memo_does_not_tax_random_access_bd_5vis3_random() {
        let Some(bytes) = build_populated_btrfs_bytes_bd_5vis3(8_000) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();

        // ONE device, shared by every arm. TestDevice is an Arc over the image,
        // so cloning it is a refcount bump; `bytes.clone()` was copying the whole
        // image per arm — 4 arms a round, 28 full-image copies a run. That churn
        // is the leading suspect for the monotonic within-round slowdown the A/A
        // null reports (each successive arm slower than the last), which is what
        // keeps the null failing on some workers. Safe because neither arm
        // writes: both only readdir and getattr, and the fs is opened without
        // enable_writes. Each arm still gets a FRESH OpenFs, so "cold fs per
        // arm" is unchanged — that was always about the fs caches, not the bytes.
        let shared_device = TestDevice::from_vec(bytes.clone());
        let arm = |memo_disabled: bool| -> (u64, std::time::Duration) {
            let fs = OpenFs::from_device(
                &cx,
                Box::new(shared_device.clone()),
                &OpenOptions::default(),
            )
            .expect("open btrfs");
            fs.set_btrfs_floor_memo_disabled(memo_disabled);
            fs.set_readonly_lookup_cache_disabled(true);
            let root = InodeNumber(1);
            let mut inos: Vec<InodeNumber> = Vec::new();
            let mut offset = 0_u64;
            loop {
                let page = fs.readdir(&cx, root, offset).expect("readdir");
                if page.is_empty() {
                    break;
                }
                let next = page.last().map_or(offset + 1, |e| e.offset);
                for e in &page {
                    if e.name != b"." && e.name != b".." {
                        inos.push(e.ino);
                    }
                }
                if next <= offset {
                    break;
                }
                offset = next;
            }
            // A large stride coprime with the length maximises leaf crossings, so
            // the memo misses nearly every time — the worst case for it.
            let n = inos.len();
            let stride = 4099.min(n.saturating_sub(1)).max(1);
            let order: Vec<InodeNumber> = (0..n).map(|i| inos[(i * stride) % n]).collect();
            let start = std::time::Instant::now();
            let mut ok = 0_u64;
            for ino in &order {
                if fs.getattr(&cx, *ino).is_ok() {
                    ok += 1;
                }
            }
            (ok, start.elapsed())
        };

        // Interleaved pairs plus an A/A null on the identical schedule, same shape
        // as the production arm (bd-79li3). A single pair was enough to SEE the
        // 8.6x tax that motivated the fix, but not to bank the fix: the ledger
        // contract wants an interval and a null, and this arm is cheap enough to
        // afford both — two arms cost ~6 s at 8000 inodes, where the production
        // arm's 20000-inode fixture cannot even finish inside the rch SSH ceiling.
        const DEFAULT_ROUNDS: usize = 7;
        let rounds: usize = std::env::var("FFS_BD_5VIS3_ROUNDS")
            .ok()
            .and_then(|raw| raw.trim().parse::<usize>().ok())
            .filter(|n| *n >= 3)
            .unwrap_or(DEFAULT_ROUNDS);
        let mut ab_log_ratios = Vec::with_capacity(rounds);
        let mut null_log_ratios = Vec::with_capacity(rounds);
        let mut ok_last = 0_u64;
        // Balanced square per round: OFF, ON, ON, OFF — see the production arm
        // for why the previous 1-2 / 3-4 split made the null measure a schedule
        // position rather than instrument noise.
        for _ in 0..rounds {
            let (ok_off1, t_off1) = arm(true);
            let (ok_on1, t_on1) = arm(false);
            let (ok_on2, t_on2) = arm(false);
            let (ok_off2, t_off2) = arm(true);
            assert_eq!(ok_off1, ok_on1, "arms must stat the same inodes");
            assert_eq!(ok_on2, ok_off2, "arms must stat the same inodes");
            let secs = |d: std::time::Duration| d.as_secs_f64().max(f64::MIN_POSITIVE);
            ab_log_ratios.push((secs(t_off1) / secs(t_on1)).ln());
            ab_log_ratios.push((secs(t_off2) / secs(t_on2)).ln());
            null_log_ratios.push((secs(t_off1) / secs(t_off2)).ln());
            null_log_ratios.push((secs(t_on1) / secs(t_on2)).ln());
            ok_last = ok_on1;
        }
        let ab = bd_5vis3_bootstrap_median_ci(&ab_log_ratios);
        let null = bd_5vis3_bootstrap_median_ci(&null_log_ratios);
        println!(
            "bd-5vis3 SYNTHETIC RANDOM ACCESS — the adversarial case bd-79li3 exists to fix \
             ({ok_last} inodes, {rounds} interleaved pairs)\n  \
             executing_elf_sha256 {}\n  \
             wall ratio median {:.6}x  bootstrap_median_ci95 [{:.6}, {:.6}]\n  \
             A/A null  median {:.6}x  bootstrap_median_ci95 [{:.6}, {:.6}]\n  \
             (below 1.0 means the memo TAXES this workload; it measured 0.116x before \
             the bd-79li3 miss-streak gate)",
            bd_5vis3_executing_elf_sha256(),
            ab.median,
            ab.low,
            ab.high,
            null.median,
            null.low,
            null.high
        );
        // The whole point of bd-79li3 is that this arm must not be a REGRESSION any
        // more. `bd_5vis3_bootstrap_median_ci` returns exponentiated ratios, so 1.0
        // is parity and the pre-gate 0.116x sits far below it.
        //
        // Assert the DIRECTION, not the magnitude. The gate bounds the tax; it does
        // not promise a win, and pinning a number here would turn an honest
        // re-measurement on a slower worker into a spurious failure. The bound is
        // the A/A null's own lower edge: the memo must not be slower than the
        // instrument's demonstrated noise floor, which is the weakest claim that
        // still rules out the 8.6x regression this bead was filed for.
        assert!(
            ab.high > null.low,
            "random-access memo ratio [{:.6}, {:.6}] sits entirely below the A/A null \
             [{:.6}, {:.6}] — it is still a tax, so the bd-79li3 miss-streak gate did \
             not bound the adversarial case",
            ab.low,
            ab.high,
            null.low,
            null.high
        );
    }

    /// Build a populated btrfs image once and return its raw bytes, so several
    /// arms can each open a COLD `OpenFs` from the same image (bd-5vis3).
    ///
    /// Re-opening per arm is what removes the warm-cache confound that inflated
    /// the first A/B: caches live on `OpenFs`, so a second arm run against the
    /// same instance inherits everything the first one warmed.
    fn build_populated_btrfs_bytes_bd_5vis3(files: usize) -> Option<Vec<u8>> {
        let tmp = tempfile::TempDir::new().expect("tmpdir");
        let seed = tmp.path().join("seed");
        std::fs::create_dir(&seed).ok()?;
        for i in 0..files {
            // Distinct content per file: identical bytes would make an extent
            // mix-up invisible to a content comparison (bd-5vis3).
            let body = format!("file-{i:05}-{}\n", "ab".repeat(1 + (i % 7)));
            std::fs::write(seed.join(format!("f{i:05}")), body.as_bytes()).ok()?;
        }
        let image = tmp.path().join("bd5vis3.btrfs");
        let f = std::fs::File::create(&image).ok()?;
        f.set_len(512 * 1024 * 1024).ok()?;
        drop(f);
        let out = std::process::Command::new("mkfs.btrfs")
            .args(["-f", "-q", "--rootdir"])
            .arg(&seed)
            .arg(&image)
            .output()
            .ok()?;
        if !out.status.success() {
            return None;
        }
        std::fs::read(&image).ok()
    }

    /// bd-5vis3: does the memo still pay in the PRODUCTION configuration, where
    /// the read-only attr cache is active?
    ///
    /// The isolated A/B disables that cache to measure the memo alone. Production
    /// does not, and the cache answers a repeat stat of the same inode without
    /// touching the tree — so the memo's marginal value could be much smaller
    /// than 3.73x, or absent. That is the number that decides whether this ships
    /// enabled, and it had never been measured.
    ///
    /// Each arm opens a COLD `OpenFs` from the same image bytes: caches live on
    /// the instance, and reusing one hands the second arm everything the first
    /// warmed — the exact confound that inflated the first A/B to a withdrawn
    /// 30.9x.
    #[test]
    #[ignore = "bd-5vis3: measurement, not a gate — builds a large btrfs fixture"]
    fn btrfs_floor_memo_still_pays_with_the_attr_cache_active_bd_5vis3_prod() {
        let Some(bytes) = build_populated_btrfs_bytes_bd_5vis3(20_000) else {
            return; // btrfs-progs unavailable
        };
        let cx = Cx::for_testing();

        // One shared Arc-backed device rather than a full image copy per arm —
        // see the random arm for why this churn is the drift suspect. Each arm
        // still constructs a fresh OpenFs, so the cold-fs property is unchanged.
        let shared_device = TestDevice::from_vec(bytes.clone());
        let arm = |memo_disabled: bool| -> (u64, std::time::Duration, u64) {
            let fs = OpenFs::from_device(
                &cx,
                Box::new(shared_device.clone()),
                &OpenOptions::default(),
            )
            .expect("open btrfs");
            fs.set_btrfs_floor_memo_disabled(memo_disabled);
            let root = InodeNumber(1);
            let mut inos: Vec<InodeNumber> = Vec::new();
            let mut offset = 0_u64;
            loop {
                let page = fs.readdir(&cx, root, offset).expect("readdir");
                if page.is_empty() {
                    break;
                }
                let next = page.last().map_or(offset + 1, |e| e.offset);
                for e in &page {
                    if e.name != b"." && e.name != b".." {
                        inos.push(e.ino);
                    }
                }
                if next <= offset {
                    break;
                }
                offset = next;
            }
            let (l0, _) = crate::btrfs_node_cache_counters();
            let start = std::time::Instant::now();
            let mut ok = 0_u64;
            for ino in &inos {
                if fs.getattr(&cx, *ino).is_ok() {
                    ok += 1;
                }
            }
            let elapsed = start.elapsed();
            let (l1, _) = crate::btrfs_node_cache_counters();
            (ok, elapsed, l1.saturating_sub(l0))
        };

        // One observation per arm cannot be banked: the ledger contract wants a
        // bootstrap median CI, and a single pair cannot show whether the effect
        // clears the instrument's own noise. Run INTERLEAVED pairs (off, on,
        // off, on, ...) so drift over the series hits both arms equally, and
        // carry an A/A null (off vs off) through the identical schedule. The
        // null is the control that says whether the A/B is readable at all.
        //
        // ROUND COUNT IS TUNABLE, and it has to be, because this arm could not
        // run at all as first written (bd-79li3). Each round pays FOUR full arms
        // and each arm re-opens a cold `OpenFs` and re-walks the whole directory —
        // deliberately, since a warm second arm inherits everything the first one
        // warmed — so the UNTIMED setup dominates by roughly three orders of
        // magnitude over the ~22 ms that is actually measured. At 21 rounds the
        // run exceeded the 1800 s rch SSH ceiling twice on `vmi1264463` and
        // produced nothing. An instrument that cannot finish reports no interval
        // at all, which is strictly worse than a wider one.
        //
        // So: a default that completes, and an env override for a long window.
        // More rounds tighten the interval; they do not change the estimator.
        const DEFAULT_ROUNDS: usize = 7;
        let rounds: usize = std::env::var("FFS_BD_5VIS3_ROUNDS")
            .ok()
            .and_then(|raw| raw.trim().parse::<usize>().ok())
            .filter(|n| *n >= 3)
            .unwrap_or(DEFAULT_ROUNDS);
        let mut ab_log_ratios = Vec::with_capacity(rounds);
        let mut null_log_ratios = Vec::with_capacity(rounds);
        let (mut look_off_last, mut look_on_last, mut ok_last) = (0_u64, 0_u64, 0_u64);
        // BALANCED SQUARE per round: OFF, ON, ON, OFF.
        //
        // The previous shape put the A/B at slots 1-2 and the A/A at slots 3-4,
        // so the two estimators did not see the same schedule. Any drift across
        // a round — page cache, allocator, frequency — landed on them
        // differently, and the null measured a position effect rather than the
        // instrument's own noise. Measured consequence: the null came out
        // +14.1% on one run and -13.8% on another, same magnitude, OPPOSITE
        // signs. A null that flips sign between runs cannot certify anything,
        // and per the fleet rule a failing null is excusable only when repeats
        // are off the SAME way.
        //
        // Here both estimators are formed from the SAME four slots:
        //   A/B  = off1/on1 and off2/on2   (slots 1-2 and 4-3)
        //   A/A  = off1/off2 and on1/on2   (slots 1-4 and 2-3)
        // Each is a symmetric pairing about the round's midpoint, so a linear
        // drift cancels in both rather than in neither.
        // Absolute per-arm times, not just the ratio. A ratio cannot say WHICH
        // arm moved (bd-4sull item 3), and it cannot say how far the surviving
        // cost sits from an incumbent — the ns/stat figure below is what a
        // vs-kernel comparison would have to close, so record it here where it
        // is free rather than inferring it later from a ratio.
        let mut off_ns: Vec<f64> = Vec::with_capacity(rounds * 2);
        let mut on_ns: Vec<f64> = Vec::with_capacity(rounds * 2);
        for _ in 0..rounds {
            let (ok_off1, t_off1, look_off) = arm(true);
            let (ok_on1, t_on1, look_on) = arm(false);
            let (ok_on2, t_on2, _) = arm(false);
            let (ok_off2, t_off2, _) = arm(true);
            assert_eq!(ok_off1, ok_on1, "arms must stat the same inodes");
            assert_eq!(ok_on2, ok_off2, "arms must stat the same inodes");
            let secs = |d: std::time::Duration| d.as_secs_f64().max(f64::MIN_POSITIVE);
            ab_log_ratios.push((secs(t_off1) / secs(t_on1)).ln());
            ab_log_ratios.push((secs(t_off2) / secs(t_on2)).ln());
            null_log_ratios.push((secs(t_off1) / secs(t_off2)).ln());
            null_log_ratios.push((secs(t_on1) / secs(t_on2)).ln());
            for d in [t_off1, t_off2] {
                off_ns.push(d.as_secs_f64() * 1e9);
            }
            for d in [t_on1, t_on2] {
                on_ns.push(d.as_secs_f64() * 1e9);
            }
            look_off_last = look_off;
            look_on_last = look_on;
            ok_last = ok_on1;
        }
        let off_median_ns = bd_5vis3_median(off_ns);
        let on_median_ns = bd_5vis3_median(on_ns);
        let stats = f64::from(u32::try_from(ok_last.max(1)).unwrap_or(u32::MAX));
        let per_stat_off_ns = off_median_ns / stats;
        let per_stat_on_ns = on_median_ns / stats;
        let ab = bd_5vis3_bootstrap_median_ci(&ab_log_ratios);
        let null = bd_5vis3_bootstrap_median_ci(&null_log_ratios);
        // The ledger will not bank a ratio without the executing ELF naming
        // itself: a neighbouring sha256sum does not prove which binary ran.
        // Emitted in the same line format ffs-cli bench-evidence uses.
        println!(
            "bench_evidence,binary_sha256={}",
            bd_5vis3_executing_elf_sha256()
        );
        println!(
            "bd-5vis3 PRODUCTION CONFIG — the production-relevant row (attr cache ON, cold fs per arm, {ok_last} inodes, {rounds} interleaved pairs)\n  \
             executing_elf_sha256 {}\n  \
             memo OFF lookups {look_off_last}, memo ON lookups {look_on_last}\n  \
             wall ratio median {:.6}x  bootstrap_median_ci95 [{:.6}, {:.6}]\n  \
             A/A null  median {:.6}x  bootstrap_median_ci95 [{:.6}, {:.6}]\n  \
             absolute medians: memo_off {:.0} ns ({:.1} ns/stat), memo_on {:.0} ns ({:.1} ns/stat)",
            bd_5vis3_executing_elf_sha256(),
            ab.median,
            ab.low,
            ab.high,
            null.median,
            null.low,
            null.high,
            off_median_ns,
            per_stat_off_ns,
            on_median_ns,
            per_stat_on_ns
        );
        // The A/B must clear the null envelope, or the number is instrument noise.
        assert!(
            ab.low > null.high,
            "bd-5vis3 production A/B [{:.6}, {:.6}] does not clear its own A/A null \
             [{:.6}, {:.6}] — not a readable effect",
            ab.low,
            ab.high,
            null.low,
            null.high
        );
    }

    /// Deterministic paired bootstrap over log ratios, mirroring the estimator the
    /// CLI e2e suite already uses so a bd-5vis3 row is comparable to the rest of
    /// the bank. Seeded, so a rerun reproduces the interval exactly.
    struct Bd5vis3MedianCi {
        median: f64,
        low: f64,
        high: f64,
    }

    /// SHA-256 of the test binary that is ACTUALLY executing, hashed from
    /// `current_exe()` at measurement time.
    ///
    /// The ledger contract refuses a banked KEEP whose ratio cannot be tied to a
    /// specific ELF, and a `sha256sum` run next to the row proves only what was on
    /// disk when someone typed it — not what produced the numbers. Under the shared
    /// cargo target dir a concurrent agent's rebuild can replace the binary between
    /// the run and the hash, so the self-report is the only form of this evidence
    /// that cannot drift.
    ///
    /// Returns a marker string rather than panicking on failure: a measurement
    /// that cannot identify its binary is a row that cannot be banked, which the
    /// ledger preflight will catch — losing the whole run to a panic instead would
    /// throw away the numbers as well as the provenance.
    fn bd_5vis3_executing_elf_sha256() -> String {
        use sha2::{Digest, Sha256};
        use std::fmt::Write as _;
        use std::io::Read as _;

        let Ok(exe) = std::env::current_exe() else {
            return "unavailable(current_exe)".to_string();
        };
        let Ok(mut file) = std::fs::File::open(&exe) else {
            return "unavailable(open)".to_string();
        };
        // Streamed rather than `fs::read`: a release test binary for this crate is
        // hundreds of MiB, and this runs inside the measured process.
        let mut hasher = Sha256::new();
        let mut buf = vec![0u8; 1 << 20];
        loop {
            match file.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => hasher.update(&buf[..n]),
                Err(_) => return "unavailable(read)".to_string(),
            }
        }
        // sha2 0.11 returns a `hybrid_array::Array`, which implements neither
        // `LowerHex` nor `Display` — `format!("{:x}", ..)` does not compile against
        // it, so the hex is written out a byte at a time.
        let digest = hasher.finalize();
        let mut hex = String::with_capacity(digest.len() * 2);
        for byte in digest {
            let _ = write!(hex, "{byte:02x}");
        }
        hex
    }

    fn bd_5vis3_splitmix64(state: &mut u64) -> u64 {
        *state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut value = *state;
        value = (value ^ (value >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        value = (value ^ (value >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        value ^ (value >> 31)
    }

    fn bd_5vis3_median(mut values: Vec<f64>) -> f64 {
        values.sort_by(f64::total_cmp);
        let midpoint = values.len() / 2;
        if values.len().is_multiple_of(2) {
            values[midpoint - 1].midpoint(values[midpoint])
        } else {
            values[midpoint]
        }
    }

    fn bd_5vis3_bootstrap_median_ci(log_ratios: &[f64]) -> Bd5vis3MedianCi {
        const RESAMPLES: usize = 20_000;
        assert!(
            !log_ratios.is_empty(),
            "bootstrap needs paired observations"
        );
        let len = u64::try_from(log_ratios.len()).expect("length fits u64");
        let mut state = 0xB9D0_6202_6072_7001_u64 ^ len;
        let mut bootstrapped = Vec::with_capacity(RESAMPLES);
        for _ in 0..RESAMPLES {
            let mut sample = Vec::with_capacity(log_ratios.len());
            for _ in log_ratios {
                let draw = bd_5vis3_splitmix64(&mut state) % len;
                sample.push(log_ratios[usize::try_from(draw).expect("draw fits usize")]);
            }
            bootstrapped.push(bd_5vis3_median(sample));
        }
        bootstrapped.sort_by(f64::total_cmp);
        let low_index = RESAMPLES.saturating_mul(25) / 1000;
        let high_index = RESAMPLES
            .saturating_mul(975)
            .div_ceil(1000)
            .saturating_sub(1);
        Bd5vis3MedianCi {
            median: bd_5vis3_median(log_ratios.to_vec()).exp(),
            low: bootstrapped[low_index].exp(),
            high: bootstrapped[high_index].exp(),
        }
    }

    /// Build a small btrfs image with a populated root and open it READ-ONLY (the
    /// mode where the parsed-node cache is active), returning the fs and the file
    /// count. `None` when btrfs-progs is missing or cannot bake a directory in.
    fn open_populated_btrfs_readonly_bd_5vis3(files: usize) -> Option<(OpenFs, usize)> {
        let tmp = tempfile::TempDir::new().expect("tmpdir");
        let seed = tmp.path().join("seed");
        std::fs::create_dir(&seed).ok()?;
        for i in 0..files {
            // Distinct content per file: identical bytes would make an extent
            // mix-up invisible to a content comparison (bd-5vis3).
            let body = format!("file-{i:05}-{}\n", "ab".repeat(1 + (i % 7)));
            std::fs::write(seed.join(format!("f{i:05}")), body.as_bytes()).ok()?;
        }
        let image = tmp.path().join("bd5vis3.btrfs");
        let f = std::fs::File::create(&image).ok()?;
        f.set_len(512 * 1024 * 1024).ok()?;
        drop(f);
        // `--rootdir` bakes the seed tree in without a mount. Not every
        // btrfs-progs build has it; absence is a skip, not a failure.
        let out = std::process::Command::new("mkfs.btrfs")
            .args(["-f", "-q", "--rootdir"])
            .arg(&seed)
            .arg(&image)
            .output()
            .ok()?;
        if !out.status.success() {
            return None;
        }
        let cx = Cx::for_testing();
        let data = std::fs::read(&image).ok()?;
        let fs = OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(data)),
            &OpenOptions::default(),
        )
        .ok()?;
        // Keep `tmp` alive for the fs's lifetime by leaking it: the device owns a
        // copy of the bytes, but the temp dir must outlive any lazy path use.
        std::mem::forget(tmp);
        Some((fs, files))
    }

    /// bd-y2t0r audit: the ORDERING that makes recovery-time inode frees safe.
    ///
    /// `maybe_recover_ext4_orphans` and `free_fast_commit_deleted_inode` both
    /// free inodes through `delete_inode` against the single-lock `groups` array
    /// — the same shape that leaked in unlink and in rename. They are NOT
    /// defects, and the reason is purely ordering: both run inside
    /// `from_device`/`open_with_options` (fast-commit apply and orphan recovery
    /// sit a few lines apart in that constructor), while `ext4_sharded_alloc` is
    /// not built until `enable_writes`, which seeds it by CLONING
    /// `alloc_state.groups`. A recovery free is therefore already reflected in
    /// the array the sharded records are cloned from; there is no second writer
    /// and nothing to diverge.
    ///
    /// That safety is entirely load-bearing on the ordering, and nothing else
    /// enforces it. If the sharded structure is ever built earlier — at mount, or
    /// lazily on first write — both recovery paths silently become instances of
    /// bd-pbyu0, leaking one inode per recovered orphan with no test failing.
    /// This pins the invariant so that change fails HERE, next to the reasoning,
    /// instead of surfacing later as an e2fsck-dirty image.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn sharded_records_do_not_exist_until_enable_writes_bd_y2t0r() {
        let tmp = tempfile::TempDir::new().expect("tmpdir");
        let image = tmp.path().join("ordering.ext4");
        let f = std::fs::File::create(&image).expect("create image");
        f.set_len(16 * 1024 * 1024).expect("size image");
        drop(f);
        let out = std::process::Command::new("mkfs.ext4")
            .args(["-F", "-b", "4096", image.to_str().unwrap()])
            .output();
        if !matches!(out, Ok(ref o) if o.status.success()) {
            return; // e2fsprogs unavailable
        }

        let cx = Cx::for_testing();
        let data = std::fs::read(&image).expect("read image");
        let opts = OpenOptions {
            ext4_journal_replay_mode: Ext4JournalReplayMode::Apply,
            ..OpenOptions::default()
        };
        let mut fs = OpenFs::from_device(&cx, Box::new(TestDevice::from_vec(data)), &opts)
            .expect("open ext4");

        // Orphan recovery and fast-commit apply have already run inside
        // `from_device` at this point.
        assert!(
            fs.ext4_sharded_alloc.is_none(),
            "the sharded per-group records must NOT exist during mount-time \
             recovery — recovery frees inodes into the single-lock groups array, \
             and their safety depends on that array being the only writer until \
             `enable_writes` clones it (bd-y2t0r audit)"
        );

        fs.enable_writes(&cx).expect("enable writes");
        assert!(
            fs.ext4_sharded_alloc.is_some(),
            "…and they must exist afterwards, or this test is asserting nothing"
        );
    }

    /// bd-y2t0r audit: RENAME-OVER-EXISTING is a delete path too, and it was
    /// never routed through the sharded records.
    ///
    /// The bead listed orphan recovery, fast-commit replay and file shortening as
    /// the paths still to audit for the alloc.groups-versus-sharded-snapshot
    /// divergence. `ext4_rename` was on nobody's list, yet
    /// `rename(a, b)` where `b` exists drops `b`'s link count to zero and frees
    /// its inode — through plain `delete_inode` against the single-lock `groups`
    /// array, with no sharded branch anywhere in the function.
    ///
    /// That is bd-pbyu0 exactly: allocation debits the sharded per-group records
    /// and the descriptor flush reads `sharded.snapshot_group_stats()`, so a free
    /// credited to `groups` lands in a structure nothing reads. One leaked inode
    /// per clobbering rename, e2fsck-dirty, and eventually ENOSPC on a filesystem
    /// with free inodes.
    ///
    /// The single-lock control is the attribution: it runs the identical workload
    /// and must stay clean, so a failure here is the sharded routing rather than
    /// rename accounting being broken generally.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn rename_over_existing_frees_the_target_inode_through_the_sharded_records_bd_y2t0r() {
        rename_over_existing_counter_check_bd_y2t0r(true);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn rename_over_existing_under_single_lock_keeps_counters_exact_bd_y2t0r() {
        rename_over_existing_counter_check_bd_y2t0r(false);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    /// bd-y2t0r: is the dir-block leak RENAME-specific, or does plain `rmdir`
    /// leak too? This decides where the fix belongs — in rename, or in the shared
    /// `release_inode_storage_deferring_writeback` path both use.
    ///
    /// ⛔ ANSWERED, AND IT LEAKED. 200 mkdir/rmdir cycles on the sharded path:
    ///
    ///     Free blocks count wrong for group #0 (14087, counted=14287)
    ///
    /// Drift exactly 200 over 200 cycles, matching the dir-over-dir rename leak
    /// one for one. So the divergence is NOT rename-specific: it lives in
    /// `release_inode_storage_deferring_writeback`, which both rename and rmdir
    /// use, and EVERY directory removal on the sharded path leaked its block.
    ///
    /// ✅ FIXED, and NOT where that reading predicted. The answer was not a
    /// sharded-aware free threaded through the extent walk: the walk frees
    /// against the single-lock array, which is the correct structure for it to
    /// use — what was missing is that the durability boundary never READ that
    /// array while the sharded path was active. `reconciled_group_stats` folds
    /// the single-lock array's delta into the flushed counts, which closes this
    /// case, the dir-over-dir rename case, and the retained-file OVER-count in
    /// one place instead of at three call sites.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn rmdir_of_a_sharded_allocated_directory_does_not_leak_blocks_bd_y2t0r() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        assert!(!fs.set_bhh0i_sharded_ops(true));

        const CYCLES: usize = 200;
        for cycle in 0..CYCLES {
            let name = format!("rd-{cycle:04}");
            fs.mkdir(&cx, root, OsStr::new(&name), 0o755, 0, 0)
                .unwrap_or_else(|e| panic!("mkdir {name}: {e}"));
            fs.rmdir(&cx, root, OsStr::new(&name))
                .unwrap_or_else(|e| panic!("rmdir {name}: {e}"));
        }

        fs.flush_mvcc_to_device(&cx).expect("flush");
        let image = tmp.path().join("rmdir-sharded.ext4");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return;
        };
        assert!(
            !output.contains("Free blocks count wrong"),
            "rmdir of a sharded-allocated directory leaked free BLOCKS over \
             {CYCLES} cycles — so the dir-block divergence is NOT rename-specific \
             and the fix belongs in the shared release path, not in rename \
             (bd-y2t0r):\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept the image after {CYCLES} mkdir/rmdir:\n{output}"
        );
    }

    /// bd-y2t0r: is the block-side divergence only about FREES, or does it cover
    /// single-lock ALLOCATIONS too?
    ///
    /// Every block-side observation banked on this bead so far came from a
    /// workload that allocated and freed the same blocks inside one mount, where
    /// a lost single-lock delta cancels itself and the descriptors come out
    /// exact. `ab757b85` measured 4 cycles x 300 files x 16 KiB with ZERO
    /// block-count errors and that result was read as "file data blocks do not
    /// diverge". A storm that DELETES everything it creates cannot distinguish
    /// "the two structures agree" from "both deltas were lost and happened to
    /// sum to zero".
    ///
    /// This workload keeps its files. With the sharded path active,
    /// `ext4_flush_group_descriptors` sources every descriptor from
    /// `sharded.snapshot_group_stats()`, while `ext4_write`'s data-block
    /// allocation debits the single-lock `alloc.groups` array through
    /// `alloc_blocks_persist`. If that debit never reaches the flushed
    /// descriptors, the image claims blocks are free while their bitmap bits are
    /// set — an OVER-count, the dangerous direction of this accounting error and
    /// the mirror of the dir-block leak (which under-counts).
    ///
    /// The single-lock control runs the identical workload, so a failure here is
    /// attributable to the sharded routing rather than to the write path.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn retained_file_data_blocks_reach_the_flushed_descriptors_bd_y2t0r() {
        retained_file_data_block_check_bd_y2t0r(true);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn retained_file_data_blocks_under_single_lock_keep_counters_exact_bd_y2t0r() {
        retained_file_data_block_check_bd_y2t0r(false);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn retained_file_data_block_check_bd_y2t0r(sharded: bool) {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        assert!(!fs.set_bhh0i_sharded_ops(sharded));

        // 200 files x 16 KiB = 800 data blocks that are NEVER freed, so a lost
        // single-lock debit cannot cancel against a lost credit.
        const FILES: usize = 200;
        let payload = vec![0xD7_u8; 16 * 1024];
        for index in 0..FILES {
            let name = format!("keep-{index:04}");
            let created = fs
                .create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                .unwrap_or_else(|error| panic!("create {name}: {error}"));
            fs.write(&cx, created.ino, 0, &payload)
                .unwrap_or_else(|error| panic!("write {name}: {error}"));
        }

        fs.flush_mvcc_to_device(&cx).expect("flush to device");
        let image = tmp.path().join("retained-file-data.ext4");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("Free blocks count wrong"),
            "retained file data blocks did not reach the flushed group descriptors \
             with sharded={sharded}: {FILES} files x 16 KiB were written and kept, so \
             the descriptors must account for every allocated block. A drift here is \
             an OVER-count — the descriptors claim free blocks whose bitmap bits are \
             set (bd-y2t0r):\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept the image after {FILES} retained 16 KiB files \
             (sharded={sharded}):\n{output}"
        );
    }

    /// bd-y2t0r: the composite gate for the block-side reconciliation — BOTH
    /// structures move, in BOTH directions, inside one mount.
    ///
    /// Each of the narrower tests on this bead can be passed by a fix that is
    /// wrong in a way the others do not probe: routing the directory-block free
    /// through the sharded records satisfies the rmdir and dir-rename cases while
    /// leaving retained file data over-counted; flushing the single-lock array
    /// instead satisfies the file cases while dropping every sharded create.
    /// This workload does all four things at once —
    ///
    ///   * `mkdir`  → sharded records debited (dir block + inode + `used_dirs`)
    ///   * `write`  → single-lock array debited (file data blocks)
    ///   * `rmdir`  → single-lock array credited (the dir's own block, via the
    ///     extent walk) AND sharded records credited (the inode)
    ///   * `unlink` → single-lock array credited (file data blocks)
    ///
    /// — and leaves live objects of both kinds behind, so nothing cancels. Only
    /// counts that carry every one of those deltas match the bitmaps e2fsck
    /// recomputes.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn mixed_directory_and_file_churn_keeps_every_counter_exact_bd_y2t0r() {
        mixed_churn_counter_check_bd_y2t0r(true);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn mixed_directory_and_file_churn_under_single_lock_keeps_every_counter_exact_bd_y2t0r() {
        mixed_churn_counter_check_bd_y2t0r(false);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn mixed_churn_counter_check_bd_y2t0r(sharded: bool) {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        assert!(!fs.set_bhh0i_sharded_ops(sharded));

        const ROUNDS: usize = 120;
        let payload = vec![0x5C_u8; 8 * 1024]; // 2 data blocks per file
        for round in 0..ROUNDS {
            let dir = format!("d-{round:04}");
            fs.mkdir(&cx, root, OsStr::new(&dir), 0o755, 0, 0)
                .unwrap_or_else(|error| panic!("mkdir {dir}: {error}"));

            let kept = format!("kept-{round:04}");
            let kept_ino = fs
                .create(&cx, root, OsStr::new(&kept), 0o644, 0, 0)
                .unwrap_or_else(|error| panic!("create {kept}: {error}"))
                .ino;
            fs.write(&cx, kept_ino, 0, &payload)
                .unwrap_or_else(|error| panic!("write {kept}: {error}"));

            let doomed = format!("doomed-{round:04}");
            let doomed_ino = fs
                .create(&cx, root, OsStr::new(&doomed), 0o644, 0, 0)
                .unwrap_or_else(|error| panic!("create {doomed}: {error}"))
                .ino;
            fs.write(&cx, doomed_ino, 0, &payload)
                .unwrap_or_else(|error| panic!("write {doomed}: {error}"));
            fs.unlink(&cx, root, OsStr::new(&doomed))
                .unwrap_or_else(|error| panic!("unlink {doomed}: {error}"));

            // Half the directories are removed, half survive, so neither the
            // sharded nor the single-lock delta nets out to zero.
            if round % 2 == 0 {
                fs.rmdir(&cx, root, OsStr::new(&dir))
                    .unwrap_or_else(|error| panic!("rmdir {dir}: {error}"));
            }
        }

        fs.flush_mvcc_to_device(&cx).expect("flush to device");
        let image = tmp.path().join("mixed-churn.ext4");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        for symptom in [
            "Free blocks count wrong",
            "Free inodes count wrong",
            "Directories count wrong",
        ] {
            assert!(
                !output.contains(symptom),
                "mixed directory+file churn drifted a counter ({symptom}) with \
                 sharded={sharded} over {ROUNDS} rounds. Every delta on BOTH \
                 structures must reach the flushed descriptors and the superblock \
                 totals (bd-y2t0r):\n{output}"
            );
        }
        assert!(
            clean,
            "e2fsck must accept the image after {ROUNDS} mixed rounds \
             (sharded={sharded}):\n{output}"
        );
    }

    /// A REAL defect found 2026-08-09, now FIXED. Renaming a DIRECTORY over an
    /// existing directory leaked a free BLOCK per rename on the sharded path.
    ///
    ///     200 dir-over-dir renames, sharded:
    ///       Free blocks count wrong for group #0 (13884, counted=14084)
    ///     the single-lock control on the identical workload: CLEAN
    ///
    /// Drift was exactly 200 over 200 renames — one block per clobbered
    /// directory, which is the target directory's own data block.
    ///
    /// MECHANISM. The directory's block is allocated by the sharded dir-growth
    /// allocator (`ext4_sharded_alloc_dir_block`, debiting the sharded records)
    /// and freed by `release_inode_storage_deferring_writeback` (crediting the
    /// single-lock array), while the descriptor flush read ONLY the sharded
    /// snapshot — so the credit landed in a structure nothing read. The fix folds
    /// the single-lock array's delta into the flushed counts
    /// (`PerGroupAlloc::reconciled_group_stats`) rather than re-routing the free,
    /// because the extent walk that performs it spans arbitrary groups and the
    /// single-lock array is the right structure for it to use.
    ///
    /// Kept as a PAIR with the file-target variant and with the single-lock
    /// control: a regression that hit only the directory branch, or only the
    /// sharded arm, stays attributable.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn rename_over_existing_directory_does_not_leak_a_block_bd_y2t0r() {
        rename_over_existing_counter_check_bd_y2t0r_inner(true, true);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn rename_over_existing_directory_under_single_lock_keeps_counters_exact_bd_y2t0r() {
        rename_over_existing_counter_check_bd_y2t0r_inner(false, true);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn rename_over_existing_counter_check_bd_y2t0r(sharded: bool) {
        rename_over_existing_counter_check_bd_y2t0r_inner(sharded, false);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn rename_over_existing_counter_check_bd_y2t0r_inner(sharded: bool, dirs_too: bool) {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        assert!(!fs.set_bhh0i_sharded_ops(sharded));

        // Each cycle creates a victim and a source, then renames source over
        // victim — freeing exactly one inode per cycle.
        const CYCLES: usize = 200;
        for cycle in 0..CYCLES {
            let victim = format!("victim-{cycle:04}");
            let source = format!("source-{cycle:04}");
            fs.create(&cx, root, OsStr::new(&victim), 0o644, 0, 0)
                .unwrap_or_else(|error| panic!("create {victim}: {error}"));
            fs.create(&cx, root, OsStr::new(&source), 0o644, 0, 0)
                .unwrap_or_else(|error| panic!("create {source}: {error}"));
            fs.rename(&cx, root, OsStr::new(&source), root, OsStr::new(&victim))
                .unwrap_or_else(|error| panic!("rename {source} -> {victim}: {error}"));

            if dirs_too {
                // DIRECTORY over DIRECTORY takes a different branch: `expect_dir`
                // routes through `ext4_dir_link_dec`, and freeing the target credits
                // `used_dirs` as well as the inode count. That is a SEPARATE
                // accounting field reached through the same sharded seam, and a defect
                // in it surfaces as an e2fsck directory-count error rather than a
                // free-inode drift — which the file-only version of this test could
                // not have detected.
                let dvictim = format!("dvictim-{cycle:04}");
                let dsource = format!("dsource-{cycle:04}");
                fs.mkdir(&cx, root, OsStr::new(&dvictim), 0o755, 0, 0)
                    .unwrap_or_else(|error| panic!("mkdir {dvictim}: {error}"));
                fs.mkdir(&cx, root, OsStr::new(&dsource), 0o755, 0, 0)
                    .unwrap_or_else(|error| panic!("mkdir {dsource}: {error}"));
                fs.rename(&cx, root, OsStr::new(&dsource), root, OsStr::new(&dvictim))
                    .unwrap_or_else(|error| panic!("rename dir {dsource} -> {dvictim}: {error}"));
            }
        }

        fs.flush_mvcc_to_device(&cx).expect("flush to device");
        let image = tmp.path().join("rename-over-existing.ext4");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");
        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("Directories count wrong"),
            "rename-over-existing-DIRECTORY drifted the per-group directory count \
             with sharded={sharded}: the sharded inode free must decrement used_dirs \
             for a directory target, exactly as the single-lock path does \
             (bd-y2t0r):\n{output}"
        );
        assert!(
            !output.contains("Free inodes count wrong"),
            "rename-over-existing leaked free-inode counters with sharded={sharded} \
             ({CYCLES} clobbering renames). The target inode's free must reach the \
             SAME structure that allocated it (bd-y2t0r / bd-pbyu0):\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept the image after {CYCLES} clobbering renames \
             (sharded={sharded}):\n{output}"
        );
    }

    /// bd-y2t0r: does the sharded path actually go FASTER now that deletes are
    /// routed? An in-process check, so a scarce quiet window is not spent finding
    /// out that it does not.
    ///
    /// This is NOT the acceptance row. That is the mounted parallel-metadata
    /// comparator against kernel ext4, and nothing here substitutes for it: no
    /// FUSE, no kernel arm, no A/A null, one run per arm. What it CAN do is
    /// falsify cheaply — the sharded path exists to remove a single
    /// `ext4_alloc_state.write()` that serialises 8 FUSE workers on create, so if
    /// it is not faster than the single lock on an 8-thread create/delete storm
    /// in process, the mounted row will not rescue it and the window is better
    /// spent elsewhere.
    ///
    /// Each arm builds its OWN filesystem. Sharing one would hand the second arm
    /// a warmed instance, which is exactly the confound that produced a withdrawn
    /// 30.9x on bd-5vis3.
    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    #[ignore = "bd-y2t0r: measurement, not a gate — 8-thread storm per arm"]
    fn sharded_vs_single_lock_parallel_metadata_in_process_bd_y2t0r() {
        let arm = |sharded: bool| -> Option<std::time::Duration> {
            let (fs, _dev, _tmp) = open_writable_ext4_mkfs_with_device(256)?;
            let cx = Cx::for_testing();
            let root = InodeNumber(2);
            assert!(!fs.set_bhh0i_sharded_ops(sharded));

            const THREADS: usize = 8;
            const FILES: usize = 64;
            const CYCLES: usize = 6;
            let dirs: Vec<InodeNumber> = (0..THREADS)
                .map(|w| {
                    fs.mkdir(&cx, root, OsStr::new(&format!("w{w}")), 0o755, 0, 0)
                        .expect("mkdir")
                        .ino
                })
                .collect();

            let fs = std::sync::Arc::new(fs);
            let start = std::time::Instant::now();
            std::thread::scope(|scope| {
                for (worker, dir) in dirs.iter().enumerate() {
                    let fs = std::sync::Arc::clone(&fs);
                    let dir = *dir;
                    scope.spawn(move || {
                        let cx = Cx::for_testing();
                        let fs: &OpenFs = fs.as_ref();
                        for cycle in 0..CYCLES {
                            for index in 0..FILES {
                                let name = format!("f{cycle:02}-{index:03}");
                                fs.create(&cx, dir, OsStr::new(&name), 0o644, 0, 0)
                                    .unwrap_or_else(|e| panic!("worker {worker} create: {e}"));
                            }
                            for index in 0..FILES {
                                let name = format!("f{cycle:02}-{index:03}");
                                fs.unlink(&cx, dir, OsStr::new(&name))
                                    .unwrap_or_else(|e| panic!("worker {worker} unlink: {e}"));
                            }
                        }
                    });
                }
            });
            Some(start.elapsed())
        };

        let Some(single) = arm(false) else {
            return; // e2fsprogs unavailable
        };
        let Some(shard) = arm(true) else {
            return;
        };
        let ratio = single.as_secs_f64() / shard.as_secs_f64().max(f64::MIN_POSITIVE);
        println!(
            "bd-y2t0r IN-PROCESS 8t create/delete storm (NOT the acceptance row)\n               single-lock: {single:?}\n  sharded    : {shard:?}\n  sharded is {ratio:.3}x              the single-lock throughput"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    fn concurrent_create_delete_counter_check_bd_y2t0r(sharded: bool) {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(256) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        assert!(
            !fs.set_bhh0i_sharded_ops(sharded),
            "the sharded toggle must default OFF (bd-pbyu0); this test sets it explicitly"
        );

        const THREADS: usize = 8;
        const FILES: usize = 64;
        const CYCLES: usize = 6;

        // Private per-worker directories, created before the threads start.
        let dirs: Vec<InodeNumber> = (0..THREADS)
            .map(|worker| {
                fs.mkdir(&cx, root, OsStr::new(&format!("w{worker}")), 0o755, 0, 0)
                    .unwrap_or_else(|error| panic!("mkdir w{worker}: {error}"))
                    .ino
            })
            .collect();

        // An FCW conflict reports only a BLOCK NUMBER, and every metadata block on
        // this path lives within a few blocks of every other, so a bare number is
        // not attributable to a structure without this map. Carrying it into the
        // panic turned a guess into a measurement once already (bd-y2t0r: the
        // conflict was read as the inode bitmap when it was in fact elsewhere), so
        // it stays in the test rather than being deleted after the fix.
        let layout = fs.ext4_sharded_alloc.as_ref().map_or_else(
            || "sharded alloc unavailable".to_owned(),
            |sharded| {
                let mut out = String::from("group layout (block numbers):");
                for gidx in 0..sharded.group_count().min(4) {
                    let stats = sharded.lock_group(gidx);
                    out.push_str(&format!(
                        "\n  group {gidx}: block_bitmap={} inode_bitmap={} inode_table={}",
                        stats.block_bitmap_block.0,
                        stats.inode_bitmap_block.0,
                        stats.inode_table_block.0,
                    ));
                }
                // Every unlink also writes its PARENT directory's inode, so the
                // parents' table blocks belong in the map as much as the group
                // layout does — a conflict on a parent's block is otherwise
                // indistinguishable from one on a deleted child's.
                if let Some(sb) = fs.ext4_superblock() {
                    let geo = FsGeometry::from_superblock(sb);
                    out.push_str("\n  worker dirs (the unlink PARENT inodes):");
                    for (worker, dir) in dirs.iter().enumerate() {
                        let block = sharded
                            .inode_location(*dir, &geo)
                            .map_or_else(|| "?".to_owned(), |loc| loc.block.0.to_string());
                        out.push_str(&format!(
                            "\n    w{worker}: ino={} table_block={block}",
                            dir.0
                        ));
                    }
                }
                out
            },
        );
        let layout = std::sync::Arc::new(layout);
        // bd-y2t0r: the leading suspect for the residual conflict is a plain
        // whole-block `write_block` discarding a slot-scoped proof another writer
        // established for the same inode-table block. Sampling the process-wide
        // downgrade counter across the workload answers that directly. A counter
        // rather than a log because the workers are threads inside a parallel test
        // suite, where a thread-scoped subscriber sees nothing and a global one
        // cannot be installed from a single test.
        // Reported from a Drop guard, not inline after the workload: a worker
        // panic propagates out of `thread::scope`, so any read placed after it is
        // skipped on exactly the runs whose number is wanted. Drop still runs
        // during unwind, so the count reaches the log on the failing path too.
        struct DowngradeReport(u64, u64);
        impl Drop for DowngradeReport {
            fn drop(&mut self) {
                let delta = ffs_mvcc::proof_downgrade_count().saturating_sub(self.0);
                let (refusals, last, reason) = ffs_mvcc::merge_refusal_report();
                println!(
                    "bd-y2t0r: merge-proof downgrades during this workload: {delta} \
                     (non-zero => some writer plain-write_blocks a proof-scoped block); \
                     merge refusals: {} (last: {last:?}, reason: {reason:?})",
                    refusals.saturating_sub(self.1)
                );
                // The refusal shape is the discriminator. base_len == 0 or short
                // means ancestor resolution failed; three full-length buffers
                // under a range proof means the declared ranges overlapped in
                // BYTE terms even though the inode slots were distinct. Both
                // counters are process-wide, so a parallel suite may attribute a
                // few from other tests.
            }
        }
        let _downgrade_report = DowngradeReport(
            ffs_mvcc::proof_downgrade_count(),
            ffs_mvcc::merge_refusal_report().0,
        );

        let fs = std::sync::Arc::new(fs);
        std::thread::scope(|scope| {
            for (worker, dir) in dirs.iter().enumerate() {
                let fs = std::sync::Arc::clone(&fs);
                let layout = std::sync::Arc::clone(&layout);
                let dir = *dir;
                scope.spawn(move || {
                    let cx = Cx::for_testing();
                    // `as_ref()` is load-bearing: `Arc<OpenFs>` implements `FsOps`
                    // itself, so a bare `fs.create(..)` binds to the TRAIT method
                    // (which takes a `RequestScope`) rather than the inherent
                    // scope-managing one this test means to exercise.
                    let fs: &OpenFs = fs.as_ref();
                    for cycle in 0..CYCLES {
                        for index in 0..FILES {
                            let name = format!("f{cycle:02}-{index:03}");
                            fs.create(&cx, dir, OsStr::new(&name), 0o644, 0, 0)
                                .unwrap_or_else(|error| {
                                    panic!("worker {worker} create {name}: {error}\n{layout}")
                                });
                        }
                        for index in 0..FILES {
                            let name = format!("f{cycle:02}-{index:03}");
                            fs.unlink(&cx, dir, OsStr::new(&name))
                                .unwrap_or_else(|error| {
                                    panic!("worker {worker} unlink {name}: {error}\n{layout}")
                                });
                        }
                    }
                });
            }
        });

        fs.flush_mvcc_to_device(&cx).expect("flush to device");
        let image = tmp.path().join("sharded-concurrent.ext4");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("Free inodes count wrong"),
            "sharded free-inode counters drifted under {THREADS} concurrent workers x \
             {CYCLES} cycles x {FILES} files (bd-y2t0r). The single-threaded repro passes, \
             so a failure here is a CONCURRENCY defect in the delete routing, not the \
             routing itself:\n{output}"
        );
        assert!(
            !output.contains("Free blocks count wrong"),
            "sharded block counters drifted under concurrency (bd-y2t0r):\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept the image after concurrent sharded create/delete \
             (bd-y2t0r):\n{output}"
        );
    }

    /// ⚠ **This test PASSES and `bd-pbyu0` is NOT fixed.** It is negative evidence,
    /// not a reproduction — do not read a green run here as the bug being closed.
    ///
    /// `bd-pbyu0`: the mounted comparator's `create-delete-storm` leaves BOTH
    /// FrankenFS arms `e2fsck`-dirty with 11 "Free inodes count wrong" errors each
    /// while both kernel arms are clean — ten whole groups claiming ZERO free
    /// inodes while all 8192 of each are free in the bitmap, a drift of exactly one
    /// per file deleted. On a smaller image the drift exhausts the descriptors and
    /// allocation starts failing ENOSPC on an empty filesystem.
    ///
    /// This test drives the same shape through the DIRECT in-process path —
    /// `OpenFs::unlink`, i.e. `with_latest_scope` — and the counters stay exact.
    ///
    /// Its sibling `request_scope_create_delete_cycles_..._bd_pbyu0` drives the
    /// identical workload through the per-request scope path the FUSE daemon uses,
    /// at 20,000 allocations across multiple inode groups, and is ALSO clean. So
    /// both in-process paths are correct at comparator-like volume, and whatever
    /// bd-pbyu0 is, it needs something only the mounted arm has — the live FUSE
    /// mount, the daemon's unmount/`flush_on_destroy` path, or the cloned-from-base
    /// image the comparator mounts rather than a freshly formatted one.
    ///
    /// Keep this test regardless of how `bd-pbyu0` is fixed: it pins that the
    /// direct path is correct, so a fix elsewhere cannot silently regress it.
    /// bd-pbyu0: the same create/delete cycles driven through the PER-REQUEST
    /// SCOPE path that the FUSE daemon uses, rather than `with_latest_scope`.
    ///
    /// The direct-path sibling test below is clean, which proved the leak is
    /// path-specific rather than scale-specific. This isolates the one structural
    /// difference between the two: `ffs-fuse`'s `unlink` handler wraps the same
    /// `FsOps::unlink` in `begin_request_scope` / `commit_request_scope` /
    /// `end_request_scope`, one scope per operation. Everything else — the same
    /// `ext4_unlink_impl`, `delete_inode`, `free_inode_persist` — is shared.
    ///
    /// ⚠ It does NOT reproduce, at 512 MiB / 40 cycles / 500 files = 20,000
    /// allocations. So the per-request scope commit is ELIMINATED as the cause,
    /// and so is scale. Kept as the second negative control: between them these
    /// two tests pin both in-process paths as correct at comparator-like volume.
    #[test]
    fn request_scope_create_delete_cycles_keep_free_inode_counters_exact_bd_pbyu0() {
        // 512 MiB gives ~4 inode groups. Size matters: the comparator's damage was
        // in groups #5-#13 driven to ZERO free, which can only happen once
        // allocation SWEEPS ACROSS groups, and a 64 MiB image is a single group so
        // it cannot express the condition at all.
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(512) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        // Enough allocations to walk past one group's worth of inodes even if
        // nothing is reused, which is the state the corrupt image was in.
        const FILES_PER_CYCLE: usize = 500;
        const CYCLES: usize = 40;

        // One scope per operation, opened and committed exactly as the FUSE
        // handlers do, so the only thing that differs from the direct-path test is
        // the scope lifecycle.
        let scoped = |op: RequestOp,
                      run: &mut dyn FnMut(&mut RequestScope) -> ffs_error::Result<()>|
         -> ffs_error::Result<()> {
            let mut scope = <OpenFs as FsOps>::begin_request_scope(&fs, &cx, op)?;
            let result = run(&mut scope).and_then(|()| {
                <OpenFs as FsOps>::commit_request_scope(&fs, &mut scope).map(|_| ())
            });
            let end = <OpenFs as FsOps>::end_request_scope(&fs, &cx, op, scope);
            result.and(end)
        };

        for cycle in 0..CYCLES {
            for index in 0..FILES_PER_CYCLE {
                let name = format!("scoped-{cycle:03}-{index:04}");
                scoped(RequestOp::Create, &mut |scope| {
                    <OpenFs as FsOps>::create(&fs, &cx, scope, root, OsStr::new(&name), 0o644, 0, 0)
                        .map(|_| ())
                })
                .unwrap_or_else(|error| {
                    panic!(
                        "scoped create {name} failed on cycle {cycle}: {error}. ENOSPC here \
                         on a filesystem this empty is the allocation-side face of the \
                         bd-pbyu0 counter drift."
                    )
                });
            }
            for index in 0..FILES_PER_CYCLE {
                let name = format!("scoped-{cycle:03}-{index:04}");
                scoped(RequestOp::Unlink, &mut |scope| {
                    <OpenFs as FsOps>::unlink(&fs, &cx, scope, root, OsStr::new(&name))
                })
                .unwrap_or_else(|error| panic!("scoped unlink {name} failed: {error}"));
            }
        }

        fs.flush_mvcc_to_device(&cx).expect("flush to device");
        let image = tmp.path().join("scoped-storm.ext4");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("Free inodes count wrong"),
            "group descriptor free-inode counters drifted from the bitmaps after \
             {CYCLES} x {FILES_PER_CYCLE} create/delete cycles driven through PER-REQUEST \
             SCOPES (bd-pbyu0). The direct-path sibling test is clean, so this isolates the \
             defect to per-request scope commit:\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept the image after request-scoped create/delete cycles \
             (bd-pbyu0):\n{output}"
        );
    }

    #[test]
    fn direct_path_create_delete_cycles_keep_free_inode_counters_exact_not_a_bd_pbyu0_repro() {
        let Some((fs, dev, tmp)) = open_writable_ext4_mkfs_with_device(64) else {
            return; // e2fsprogs unavailable
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        const FILES_PER_CYCLE: usize = 64;
        const CYCLES: usize = 12;

        for cycle in 0..CYCLES {
            for index in 0..FILES_PER_CYCLE {
                let name = format!("storm-{cycle:03}-{index:04}");
                fs.create(&cx, root, OsStr::new(&name), 0o644, 0, 0)
                    .unwrap_or_else(|error| {
                        panic!(
                            "create {name} failed on cycle {cycle}: {error}. A failure here \
                             (especially ENOSPC on a filesystem this empty) is the \
                             allocation-side face of the bd-pbyu0 counter drift."
                        )
                    });
            }
            for index in 0..FILES_PER_CYCLE {
                let name = format!("storm-{cycle:03}-{index:04}");
                fs.unlink(&cx, root, OsStr::new(&name))
                    .unwrap_or_else(|error| panic!("unlink {name} failed: {error}"));
            }
        }

        fs.flush_mvcc_to_device(&cx).expect("flush to device");
        let image = tmp.path().join("storm.ext4");
        std::fs::write(&image, dev.snapshot_bytes()).expect("write image");

        let Some((clean, output)) = run_e2fsck(&image) else {
            return; // e2fsck unavailable
        };
        assert!(
            !output.contains("Free inodes count wrong"),
            "the DIRECT path drifted its group free-inode counters after \
             {CYCLES} x {FILES_PER_CYCLE} create/delete cycles. This test is bd-pbyu0's \
             negative control: if it starts failing, the defect has spread to the direct \
             path too.\n{output}"
        );
        assert!(
            clean,
            "e2fsck must accept the image after repeated create/delete cycles on the \
             direct path (bd-pbyu0 negative control):\n{output}"
        );
    }

    fn reopen_ext4_after_crash(dev: &TestDevice) -> OpenFs {
        let cx = Cx::for_testing();
        let opts = OpenOptions {
            ext4_journal_replay_mode: Ext4JournalReplayMode::Apply,
            ..OpenOptions::default()
        };
        OpenFs::from_device(
            &cx,
            Box::new(TestDevice::from_vec(dev.snapshot_bytes())),
            &opts,
        )
        .expect("reopen ext4 after crash")
    }

    fn ext4_lookup_optional(fs: &OpenFs, cx: &Cx, name: &str) -> Option<InodeAttr> {
        fs.lookup(cx, InodeNumber(2), OsStr::new(name)).ok()
    }

    fn ext4_read_exact(fs: &OpenFs, cx: &Cx, ino: InodeNumber, size: u64) -> Vec<u8> {
        fs.read(cx, ino, 0, u32::try_from(size).expect("small test file"))
            .expect("read exact bytes")
    }

    fn ext4_block_mapping(
        fs: &OpenFs,
        cx: &Cx,
        ino: InodeNumber,
        logical_block: u32,
    ) -> ffs_extent::ExtentMapping {
        let inode = fs
            .read_inode(cx, ino)
            .expect("read inode for extent mapping");
        let root_bytes = OpenFs::extent_root(&inode);
        let block_dev = fs.block_device_adapter();
        let mut mappings =
            ffs_extent::map_logical_to_physical(cx, &block_dev, &root_bytes, logical_block, 1)
                .expect("map logical block");
        mappings.pop().expect("single logical block mapping")
    }

    fn ext4_move_ext_request(
        fs: &OpenFs,
        cx: &Cx,
        ino: InodeNumber,
        donor_fd: u32,
        orig_start: u64,
        donor_start: u64,
        len: u64,
    ) -> ffs_error::Result<u64> {
        let mut scope = fs
            .begin_request_scope(cx, RequestOp::IoctlWrite)
            .expect("begin ioctl write scope");
        let result = fs.move_ext(cx, &mut scope, ino, donor_fd, orig_start, donor_start, len);
        if result.is_ok() {
            fs.commit_request_scope(&mut scope)
                .expect("commit ioctl write scope");
        }
        fs.end_request_scope(cx, RequestOp::IoctlWrite, scope)
            .expect("end ioctl write scope");
        result
    }

    fn assert_ext4_crash_event(
        logs: &[Value],
        scenario_id: &str,
        crash_point: &str,
        outcome: &str,
    ) {
        let event = logs.iter().find(|entry| {
            entry.get("message").and_then(Value::as_str) == Some("CRASH_MATRIX_EVENT")
                && entry.get("scenario_id").and_then(Value::as_str) == Some(scenario_id)
        });
        assert!(
            event.is_some(),
            "missing crash-matrix event for {scenario_id}: {logs:?}"
        );
        let event = event.expect("crash-matrix event must be present after assert");

        assert_eq!(
            event.get("crash_point").and_then(Value::as_str),
            Some(crash_point)
        );
        assert_eq!(event.get("outcome").and_then(Value::as_str), Some(outcome));
    }

    fn enable_e2compr_for_inode(
        fs: &OpenFs,
        cx: &Cx,
        ino: InodeNumber,
        cluster_shift: u32,
        method_idx: u8,
    ) {
        let mut inode = fs.read_inode(cx, ino).expect("read inode for e2compr");
        inode.flags |= ffs_types::EXT4_COMPR_FL;
        inode.flags &= !ffs_types::EXT4_INLINE_DATA_FL;
        inode.flags &= !ffs_types::EXT4_EXTENTS_FL;
        inode.flags &= !((0x7_u32 << 23) | (0x1F_u32 << 26));
        inode.flags |= (cluster_shift & 0x7) << 23;
        inode.flags |= u32::from(method_idx & 0x1F) << 26;
        inode.extent_bytes.fill(0);
        fs.persist_ext4_inode_for_testing(cx, ino, &inode)
            .expect("persist e2compr inode flags");
    }

    fn persist_ext4_test_inode(fs: &OpenFs, cx: &Cx, ino: InodeNumber, inode: &Ext4Inode) {
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let csum_seed = sb.csum_seed();
        let block_dev = fs.block_device_adapter();
        let alloc_mutex = fs.require_alloc_state().expect("alloc state");
        let alloc = alloc_mutex.read();
        ffs_inode::write_inode(
            cx,
            &block_dev,
            &alloc.geo,
            &alloc.groups,
            ino,
            inode,
            csum_seed,
        )
        .expect("persist test inode");
    }

    #[test]
    fn write_create_and_read_roundtrip() {
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2); // ext4 root inode

        // Create a new file
        let attr = fs
            .create(&cx, root, OsStr::new("test_rw.txt"), 0o644, 1000, 1000)
            .expect("create");
        assert_eq!(attr.kind, FileType::RegularFile);
        assert_eq!(attr.perm, 0o644);
        assert_eq!(attr.uid, 1000);
        let ino = attr.ino;

        // Write data
        let payload = b"FrankenFS write test!";
        let written = fs.write(&cx, ino, 0, payload).expect("write");
        assert_eq!(written as usize, payload.len());

        // Read back
        let readback = fs.read(&cx, ino, 0, 4096).expect("read");
        assert_eq!(&readback[..payload.len()], payload);

        // Lookup should find it
        let looked_up = fs
            .lookup(&cx, root, OsStr::new("test_rw.txt"))
            .expect("lookup");
        assert_eq!(looked_up.ino, ino);
    }

    #[test]
    fn write_cross_block_boundary_preserves_data() {
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        let attr = fs
            .create(&cx, root, OsStr::new("cross_block.bin"), 0o644, 0, 0)
            .expect("create");
        let ino = attr.ino;

        // Write 6KB of distinct data starting at offset 0 to span two 4KB blocks.
        let mut payload = vec![0u8; 6144];
        for (idx, byte) in payload.iter_mut().enumerate() {
            *byte = u8::try_from(idx % 251).unwrap(); // prime modulus for pattern uniqueness
        }
        let written = fs.write(&cx, ino, 0, &payload).expect("write 6KB");
        assert_eq!(written as usize, 6144);

        // Now overwrite 2KB starting at offset 3072 (spanning the 4KB block boundary).
        let patch = vec![0xFF_u8; 2048];
        let written2 = fs.write(&cx, ino, 3072, &patch).expect("cross-block write");
        assert_eq!(written2 as usize, 2048);

        // Read back all 6KB and verify:
        // - [0..3072] should be original pattern
        // - [3072..5120] should be 0xFF
        // - [5120..6144] should be original pattern
        let readback = fs.read(&cx, ino, 0, 6144).expect("read");
        assert_eq!(readback.len(), 6144);
        assert_eq!(&readback[..3072], &payload[..3072], "prefix corrupted");
        assert!(
            readback[3072..5120].iter().all(|&b| b == 0xFF),
            "cross-block patch not applied correctly"
        );
        assert_eq!(&readback[5120..], &payload[5120..], "suffix corrupted");
    }

