    #[test]
    fn ext4_directory_is_empty_matches_read_dir_oracle() {
        // The early-exit emptiness check must agree with the exact predicate it
        // replaced (`read_dir(..).iter().any(non-dot)`) on every directory
        // shape — this is a data-safety invariant (a false "empty" would let
        // rmdir delete a populated directory).
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        let check = |dir_ino: InodeNumber, label: &str| -> bool {
            let inode = fs.read_inode(&cx, dir_ino).expect("read dir inode");
            let oracle_empty = !fs
                .read_dir(&cx, &inode)
                .expect("read_dir")
                .iter()
                .any(|e| e.name != b"." && e.name != b"..");
            let candidate_empty = fs
                .ext4_directory_is_empty(&cx, &RequestScope::empty(), &inode)
                .expect("is_empty");
            assert_eq!(
                candidate_empty, oracle_empty,
                "{label}: is_empty={candidate_empty} disagrees with read_dir oracle {oracle_empty}"
            );
            candidate_empty
        };

        // Fresh directory: only . and .. → empty.
        let empty_dir = fs
            .mkdir(&cx, root, OsStr::new("empty_d"), 0o755, 0, 0)
            .expect("mkdir");
        assert!(check(empty_dir.ino, "fresh mkdir"));

        // One child → non-empty (early-exits in block 0).
        let one_dir = fs
            .mkdir(&cx, root, OsStr::new("one_d"), 0o755, 0, 0)
            .expect("mkdir");
        fs.create(&cx, one_dir.ino, OsStr::new("a.txt"), 0o644, 0, 0)
            .expect("create");
        assert!(!check(one_dir.ino, "one child"));

        // Many children spanning multiple dir blocks → still non-empty.
        let many_dir = fs
            .mkdir(&cx, root, OsStr::new("many_d"), 0o755, 0, 0)
            .expect("mkdir");
        for i in 0..256u32 {
            fs.create(
                &cx,
                many_dir.ino,
                OsStr::new(&format!("f_{i:04}.txt")),
                0o644,
                0,
                0,
            )
            .expect("create");
        }
        assert!(!check(many_dir.ino, "many children"));

        // Populate then unlink every child → empty again (deleted-slot blocks).
        let drain_dir = fs
            .mkdir(&cx, root, OsStr::new("drain_d"), 0o755, 0, 0)
            .expect("mkdir");
        for i in 0..64u32 {
            fs.create(
                &cx,
                drain_dir.ino,
                OsStr::new(&format!("g_{i:04}.txt")),
                0o644,
                0,
                0,
            )
            .expect("create");
        }
        assert!(!check(drain_dir.ino, "before drain"));
        for i in 0..64u32 {
            fs.unlink(&cx, drain_dir.ino, OsStr::new(&format!("g_{i:04}.txt")))
                .expect("unlink");
        }
        assert!(check(drain_dir.ino, "after drain"));
        // The whole point: rmdir now succeeds on the drained directory.
        fs.rmdir(&cx, root, OsStr::new("drain_d"))
            .expect("rmdir drained");
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn ext4_persist_ctx_lockfree_matches_locked_bd_bhh0i() {
        // The sharded parallel-create path reads PersistCtx WITHOUT the alloc
        // write lock; it must equal the copy behind the lock (every field is
        // immutable + superblock-derived). This pins that invariant.
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let locked = fs
            .ext4_alloc_state
            .as_ref()
            .expect("alloc state present after enable_writes")
            .read()
            .persist_ctx
            .clone();
        let lf = fs
            .ext4_persist_ctx_lockfree()
            .expect("lock-free persist ctx");
        assert_eq!(lf.gdt_block, locked.gdt_block);
        assert_eq!(lf.desc_size, locked.desc_size);
        assert_eq!(lf.has_metadata_csum, locked.has_metadata_csum);
        assert_eq!(lf.csum_seed, locked.csum_seed);
        assert_eq!(lf.uuid, locked.uuid);
        assert_eq!(
            format!("{:?}", lf.group_desc_checksum_kind),
            format!("{:?}", locked.group_desc_checksum_kind)
        );
        assert_eq!(lf.blocks_per_group, locked.blocks_per_group);
        assert_eq!(lf.inodes_per_group, locked.inodes_per_group);
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn ext4_sharded_alloc_blocks_wrapper_allocates_bd_bhh0i() {
        // The OpenFs wrapper must derive geo+pctx lock-free and allocate like the
        // primitive: each call returns a block and debits total_free by one.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let dev = fs.block_device_adapter();
        let hint = AllocHint::default();
        let total_before = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under feature")
            .total_free()
            .blocks;
        for call in 0..3 {
            let alloc = fs
                .ext4_sharded_alloc_blocks(&cx, &dev, &hint, 1)
                .unwrap_or_else(|e| panic!("wrapper alloc call {call} errored: {e:?}"))
                .unwrap_or_else(|| panic!("wrapper alloc call {call} found no free block"));
            assert_eq!(alloc.count, 1, "call {call}: expected exactly one block");
        }
        let total_after = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .blocks;
        assert_eq!(
            total_after,
            total_before - 3,
            "wrapper allocs must debit total_free by exactly 3"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn ext4_sharded_free_blocks_wrapper_round_trips_bd_bhh0i() {
        // Free is the counterpart to alloc: allocating N blocks then freeing each
        // back through the lock-free wrapper must restore total_free EXACTLY and
        // actually clear the bitmap bits (proven by re-allocating a just-freed
        // block). Same real mkfs image + lock-free geo/pctx derivation as the alloc
        // wrapper test.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let dev = fs.block_device_adapter();
        let hint = AllocHint::default();
        let total_before = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under feature")
            .total_free()
            .blocks;

        let mut allocated = Vec::new();
        for call in 0..3 {
            let alloc = fs
                .ext4_sharded_alloc_blocks(&cx, &dev, &hint, 1)
                .unwrap_or_else(|e| panic!("alloc call {call} errored: {e:?}"))
                .unwrap_or_else(|| panic!("alloc call {call} found no free block"));
            assert_eq!(alloc.count, 1, "call {call}: expected exactly one block");
            allocated.push(alloc.start);
        }
        let total_after_alloc = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .blocks;
        assert_eq!(
            total_after_alloc,
            total_before - 3,
            "3 allocs must debit total_free by 3"
        );

        for (call, &start) in allocated.iter().enumerate() {
            fs.ext4_sharded_free_blocks(&cx, &dev, start, 1)
                .unwrap_or_else(|e| panic!("free call {call} errored: {e:?}"));
        }
        let total_after_free = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .blocks;
        assert_eq!(
            total_after_free, total_before,
            "freeing all 3 must restore total_free to the pre-alloc value"
        );

        // Re-allocating must now hand back one of the just-freed blocks — proving
        // the free actually cleared the bitmap bit (else first-fit would skip it).
        let realloc = fs
            .ext4_sharded_alloc_blocks(&cx, &dev, &hint, 1)
            .expect("realloc after free must not error")
            .expect("realloc after free must find a block");
        assert!(
            allocated.contains(&realloc.start),
            "a freed block must be re-allocatable: got {:?}, freed {:?}",
            realloc.start,
            allocated
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn sharded_tree_block_allocator_round_trips_bd_bhh0i() {
        // The extent-tree-node allocator drives ffs_btree::insert's BlockAllocator
        // trait through the sharded path. alloc_block must hand distinct blocks and
        // advance the contiguity hint; free_block must restore the free count —
        // proving the trait routes to ext4_sharded_alloc_blocks/free_blocks.
        use ffs_btree::BlockAllocator;
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let dev = fs.block_device_adapter();
        let total_before = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under feature")
            .total_free()
            .blocks;

        let mut ta = ShardedTreeBlockAllocator::new(&fs, &dev, AllocHint::default(), 12, 7)
            .expect("tree allocator builds on an ext4 fs");

        let b0 = ta.alloc_block(&cx).expect("first tree-node alloc");
        let b1 = ta.alloc_block(&cx).expect("second tree-node alloc");
        assert_ne!(b0, b1, "tree-node allocs must be distinct blocks");
        assert_eq!(
            ta.hint.goal_block,
            b1.0.checked_add(1).map(BlockNumber),
            "the contiguity hint must advance past the last allocated block"
        );
        let after_alloc = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .blocks;
        assert_eq!(
            after_alloc,
            total_before - 2,
            "2 tree-node allocs must debit total_free by 2"
        );

        ta.free_block(&cx, b0).expect("free first tree node");
        ta.free_block(&cx, b1).expect("free second tree node");
        let after_free = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .blocks;
        assert_eq!(
            after_free, total_before,
            "trait free_block must restore total_free to the pre-alloc value"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn sharded_tree_block_allocator_finalize_node_matches_direct_stamp_bd_bhh0i() {
        // finalize_node must stamp an external extent node EXACTLY like a direct
        // stamp_extent_block_checksum with the same (seed, ino, generation) key
        // (proving the key is threaded through) — and be a no-op on a non-csum fs.
        use ffs_btree::BlockAllocator;
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let dev = fs.block_device_adapter();
        let ta = ShardedTreeBlockAllocator::new(&fs, &dev, AllocHint::default(), 42, 99)
            .expect("tree allocator builds on an ext4 fs");

        let mut got = vec![0u8; 4096];
        let mut want = got.clone();
        ta.finalize_node(&mut got);
        if ta.has_metadata_csum {
            ffs_ondisk::ext4::stamp_extent_block_checksum(&mut want, ta.csum_seed, 42, 99);
            assert_eq!(
                got, want,
                "finalize_node must stamp identically to a direct keyed stamp"
            );
        } else {
            assert_eq!(
                got, want,
                "no-csum fs: finalize_node must leave the block unchanged"
            );
        }
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn sharded_tree_block_allocator_free_data_range_frees_blocks_bd_bhh0i() {
        // The TruncateBackend data-free surface (used by truncate_extents_with for
        // the physical blocks a removed extent mapped) must route through the
        // sharded free: alloc a run, free it via free_data_range, total_free
        // restored. This is the genuinely-new leaf method the sharded truncate adds.
        use ffs_extent::TruncateBackend;
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let dev = fs.block_device_adapter();
        let total_before = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under feature")
            .total_free()
            .blocks;

        let ba = fs
            .ext4_sharded_alloc_blocks(&cx, &dev, &AllocHint::default(), 3)
            .expect("alloc must not error")
            .expect("alloc must find a 3-block run");
        assert_eq!(ba.count, 3);
        let after_alloc = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .blocks;
        assert_eq!(
            after_alloc,
            total_before - 3,
            "alloc must debit total_free by 3"
        );

        let mut tree = ShardedTreeBlockAllocator::new(&fs, &dev, AllocHint::default(), 12, 7)
            .expect("tree allocator builds on an ext4 fs");
        tree.free_data_range(&cx, ba.start, ba.count)
            .expect("free_data_range must not error");
        let after_free = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .blocks;
        assert_eq!(
            after_free, total_before,
            "free_data_range must restore total_free to the pre-alloc value"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn bhh0i_toggle_routes_create_and_mkdir_to_sharded_bd_bhh0i() {
        // With the runtime toggle ON, the PUBLIC ext4_create/ext4_mkdir entry points
        // route to their lock-free twins: both created objects are findable on disk
        // AND the SHARDED allocator debited both inodes (the single-lock path would
        // leave the sharded structure untouched, so this proves the routing).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let sharded_inodes_before = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under feature")
            .total_free()
            .inodes;

        assert!(!fs.set_bhh0i_sharded_ops(true), "toggle defaults off");

        let mut scope = RequestScope::empty();
        fs.ext4_create(&cx, &mut scope, root, b"tf", 0o644, 0, 0)
            .expect("routed create must succeed");
        fs.ext4_mkdir(&cx, &mut scope, root, b"td", 0o755, 0, 0)
            .expect("routed mkdir must succeed");

        let root_after = fs.read_inode(&cx, root).expect("re-read root");
        assert!(
            fs.lookup_name(&cx, &root_after, b"tf")
                .expect("lookup")
                .is_some(),
            "routed-created file must be findable"
        );
        assert!(
            fs.lookup_name(&cx, &root_after, b"td")
                .expect("lookup")
                .is_some(),
            "routed-created dir must be findable"
        );

        let sharded_inodes_after = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .inodes;
        assert_eq!(
            sharded_inodes_after,
            sharded_inodes_before - 2,
            "toggle must route BOTH create + mkdir through the sharded allocator"
        );
    }

    /// Counts `write_block` calls so a test can assert that a flush issued no
    /// device write at all, not merely that it left the right bytes behind.
    struct WriteCountingBlockDevice<'a> {
        inner: &'a dyn BlockDevice,
        writes: AtomicUsize,
    }

    impl<'a> WriteCountingBlockDevice<'a> {
        fn new(inner: &'a dyn BlockDevice) -> Self {
            Self {
                inner,
                writes: AtomicUsize::new(0),
            }
        }
        fn writes(&self) -> usize {
            self.writes.load(AtomicOrdering::SeqCst)
        }
    }

    impl BlockDevice for WriteCountingBlockDevice<'_> {
        fn read_block(&self, cx: &Cx, block: BlockNumber) -> Result<BlockBuf, FfsError> {
            self.inner.read_block(cx, block)
        }
        fn write_block(&self, cx: &Cx, block: BlockNumber, data: &[u8]) -> Result<(), FfsError> {
            self.writes.fetch_add(1, AtomicOrdering::SeqCst);
            self.inner.write_block(cx, block, data)
        }
        fn block_size(&self) -> u32 {
            self.inner.block_size()
        }
        fn block_count(&self) -> u64 {
            self.inner.block_count()
        }
        fn sync(&self, cx: &Cx) -> Result<(), FfsError> {
            self.inner.sync(cx)
        }
    }

    /// bd-fv9tc. A durability boundary that changed no free count must not write
    /// the superblock. `fsync-journal-commit` is entirely such boundaries — it
    /// overwrites an existing 4 KiB at offset 0 and allocates nothing — yet block
    /// 0 was pushed on every fsync.
    ///
    /// THE THIRD ASSERTION IS THE POINT. Skipping is only safe if a boundary that
    /// DID change the totals still writes; a guard that is too eager silently
    /// leaves `s_free_blocks_count` stale, which is an e2fsck "free count wrong"
    /// and exactly the failure this path has regressed into before. So the test
    /// mutates the free count and demands the write come back.
    #[test]
    fn sync_superblock_free_totals_skips_an_unchanged_boundary_bd_fv9tc() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let base = fs.direct_block_device_adapter();

        // First call reconciles whatever mkfs left; it may or may not write.
        fs.ext4_sync_superblock_free_totals(&cx)
            .expect("initial superblock sync");

        // Second call with nothing changed: the lever.
        let quiet = WriteCountingBlockDevice::new(&base);
        fs.ext4_sync_superblock_free_totals_to(&cx, &quiet)
            .expect("unchanged superblock sync");
        assert_eq!(
            quiet.writes(),
            0,
            "a durability boundary that changed no free count must not write the \
             superblock — this is the whole lever"
        );

        // Now change the totals the function folds from, and demand a write.
        {
            let lock = fs
                .ext4_alloc_state
                .as_ref()
                .expect("writable ext4 has alloc state");
            let mut alloc = lock.write();
            alloc.groups[0].free_blocks -= 1;
        }
        let changed = WriteCountingBlockDevice::new(&base);
        fs.ext4_sync_superblock_free_totals_to(&cx, &changed)
            .expect("changed superblock sync");
        assert_eq!(
            changed.writes(),
            1,
            "a boundary that DID change the free totals must still write — an \
             over-eager skip leaves s_free_blocks_count stale, which e2fsck reports \
             as a wrong free count"
        );

        // And the skip must be stable: repeating after the write is quiet again.
        let quiet_again = WriteCountingBlockDevice::new(&base);
        fs.ext4_sync_superblock_free_totals_to(&cx, &quiet_again)
            .expect("re-sync after change");
        assert_eq!(
            quiet_again.writes(),
            0,
            "once persisted, the same totals must not be written again"
        );
    }

    /// bd-dm01m. The accumulating tree log is only safe because it refuses at one
    /// leaf's capacity, and that arithmetic decides whether an fsync succeeds via the
    /// log or falls back to a full commit. Both directions of error are expensive:
    /// over-estimating capacity admits a leaf that fails at `serialize` and takes the
    /// fsync with it; under-estimating forces needless full commits and discards the
    /// point of the fast path. So the boundary is pinned exactly, not approximately.
    #[test]
    fn tree_log_leaf_usage_pins_the_one_leaf_boundary_bd_dm01m() {
        let nodesize: u32 = 16384;
        let capacity = nodesize as usize - ffs_btrfs::BTRFS_HEADER_SIZE;

        // Empty log: no items, full capacity, and it must not refuse.
        let (needed, cap) = OpenFs::tree_log_leaf_usage(nodesize, &[]);
        assert_eq!((needed, cap), (0, capacity));

        let item = |len: usize| BtrfsTreeItem {
            key: BtrfsKey {
                objectid: 256,
                item_type: 1,
                offset: 0,
            },
            data: vec![0_u8; len].into(),
        };

        // One item costs its slot PLUS its data, not just its data — the slot is the
        // half an accounting bug would drop.
        let (needed, _) = OpenFs::tree_log_leaf_usage(nodesize, &[item(100)]);
        assert_eq!(needed, ffs_btrfs::BTRFS_ITEM_SIZE + 100);

        // EXACTLY full must FIT: the check is `needed` strictly greater than
        // `capacity`, so a leaf filled to the byte is usable and must not trigger a
        // full-commit fallback.
        let exact = capacity - ffs_btrfs::BTRFS_ITEM_SIZE;
        let (needed, cap) = OpenFs::tree_log_leaf_usage(nodesize, &[item(exact)]);
        assert_eq!(
            needed, cap,
            "a leaf filled to the byte must report needed == capacity"
        );
        assert!(
            needed <= cap,
            "exactly-full must not be treated as overflow"
        );

        // One byte past a full leaf must NOT fit. This is the assertion that catches an
        // off-by-one in either the header or the slot accounting.
        let (needed, cap) = OpenFs::tree_log_leaf_usage(nodesize, &[item(exact + 1)]);
        assert!(
            cap < needed,
            "one byte past a full leaf must overflow: needed={needed} capacity={cap}"
        );

        // Many items accumulate, which is the bd-dm01m behaviour being bounded.
        let items: Vec<BtrfsTreeItem> = (0..10).map(|_| item(64)).collect();
        let (needed, _) = OpenFs::tree_log_leaf_usage(nodesize, &items);
        assert_eq!(needed, 10 * (ffs_btrfs::BTRFS_ITEM_SIZE + 64));

        // A nodesize smaller than the header is nonsensical; capacity must saturate to
        // 0 so every non-empty log refuses, rather than wrapping to a huge capacity.
        let (needed, cap) = OpenFs::tree_log_leaf_usage(8, &[item(1)]);
        assert_eq!(cap, 0, "a sub-header nodesize must report zero capacity");
        assert!(cap < needed, "and must therefore refuse rather than wrap");
    }

    /// bd-jhuob. Two log nodes must BOTH be durable before the superblock names
    /// either of them.
    ///
    /// The kernel's log shape needs two blocks per fsync — the subvolume's log
    /// tree and the log root tree pointing at it — and the superblock addresses
    /// only the second. If the first can still be in the page cache when the
    /// superblock lands, a crash leaves a log root tree pointing at a log tree
    /// that does not exist, which is bd-sv7ql's failure one level deeper.
    ///
    /// The assertion is that the barrier comes after BOTH writes, and that there
    /// is only ONE: a barrier between the nodes would be pure cost on the fsync
    /// path, because no node points at another until the superblock points at the
    /// root tree.
    #[test]
    fn btrfs_publish_tree_log_barriers_after_all_nodes_bd_jhuob() {
        #[derive(Debug, PartialEq, Eq)]
        enum DevOp {
            Write(u64),
            Sync,
        }
        struct OrderRecordingDevice {
            ops: Mutex<Vec<DevOp>>,
        }
        impl ByteDevice for OrderRecordingDevice {
            // Same value the sibling OrderRecordingDevice a few tests below
            // reports; this impl was added without it and the trait has required
            // it since 76475cb5a, so the crate did not build. Taken from the
            // sibling rather than chosen, so the two fakes cannot disagree about
            // how big they claim to be.
            fn len_bytes(&self) -> u64 {
                1 << 30
            }
            fn read_exact_at(
                &self,
                _cx: &Cx,
                _off: ByteOffset,
                _buf: &mut [u8],
            ) -> ffs_error::Result<()> {
                Ok(())
            }
            fn write_all_at(
                &self,
                _cx: &Cx,
                off: ByteOffset,
                _buf: &[u8],
            ) -> ffs_error::Result<()> {
                self.ops.lock().unwrap().push(DevOp::Write(off.0));
                Ok(())
            }
            fn sync(&self, _cx: &Cx) -> ffs_error::Result<()> {
                self.ops.lock().unwrap().push(DevOp::Sync);
                Ok(())
            }
        }

        let dev = OrderRecordingDevice {
            ops: Mutex::new(Vec::new()),
        };
        let cx = Cx::for_testing();
        let log_tree = ByteOffset(0x40_0000);
        let log_root_tree = ByteOffset(0x41_0000);
        let sb_offset = ByteOffset(u64::try_from(BTRFS_SUPER_INFO_OFFSET).expect("sb offset"));

        OpenFs::btrfs_publish_tree_log(
            &dev,
            &cx,
            &[(log_tree, &[0xAB; 64]), (log_root_tree, &[0xBC; 64])],
            sb_offset,
            &[0xCD; 64],
        )
        .expect("publish two-node tree log");

        let ops = dev.ops.lock().unwrap();
        assert_eq!(
            *ops,
            vec![
                DevOp::Write(log_tree.0),
                DevOp::Write(log_root_tree.0),
                DevOp::Sync,
                DevOp::Write(sb_offset.0),
            ],
            "both nodes, then ONE barrier, then the superblock"
        );
    }

    /// bd-sv7ql. The tree-log publish must put a BARRIER between the log node and
    /// the superblock that points at it.
    ///
    /// Before the fix these were two adjacent `write_all_at` calls relying on the
    /// caller's trailing sync, so a crash could land the superblock — which
    /// publishes `log_root` — while the node it addresses was still only in the page
    /// cache. `replay_tree_log` then fails its read and mount merely `warn!`s, so an
    /// fsync that already RETURNED SUCCESS loses its data silently. That is the same
    /// shape as bd-73bi2, which was a P0.
    ///
    /// The assertion is on ORDER, not on content: a test that only checked the final
    /// bytes would pass against the broken version, because the broken version writes
    /// exactly the same bytes. Order is the entire property.
    #[test]
    fn btrfs_publish_tree_log_barriers_between_node_and_superblock_bd_sv7ql() {
        #[derive(Debug, PartialEq, Eq)]
        enum DevOp {
            Write(u64),
            Sync,
        }

        struct OrderRecordingDevice {
            ops: Mutex<Vec<DevOp>>,
        }

        impl ByteDevice for OrderRecordingDevice {
            fn len_bytes(&self) -> u64 {
                1 << 30
            }
            fn read_exact_at(
                &self,
                _cx: &Cx,
                _offset: ByteOffset,
                buf: &mut [u8],
            ) -> ffs_error::Result<()> {
                buf.fill(0);
                Ok(())
            }
            fn write_all_at(
                &self,
                _cx: &Cx,
                offset: ByteOffset,
                _buf: &[u8],
            ) -> ffs_error::Result<()> {
                self.ops.lock().unwrap().push(DevOp::Write(offset.0));
                Ok(())
            }
            fn sync(&self, _cx: &Cx) -> ffs_error::Result<()> {
                self.ops.lock().unwrap().push(DevOp::Sync);
                Ok(())
            }
        }

        let dev = OrderRecordingDevice {
            ops: Mutex::new(Vec::new()),
        };
        let cx = Cx::for_testing();
        let node_offset = ByteOffset(0x40_0000);
        let sb_offset = ByteOffset(u64::try_from(BTRFS_SUPER_INFO_OFFSET).expect("sb offset"));

        OpenFs::btrfs_publish_tree_log(
            &dev,
            &cx,
            &[(node_offset, &[0xAB; 64])],
            sb_offset,
            &[0xCD; 64],
        )
        .expect("publish tree log");

        let ops = dev.ops.lock().unwrap();
        assert_eq!(
            *ops,
            vec![
                DevOp::Write(node_offset.0),
                DevOp::Sync,
                DevOp::Write(sb_offset.0),
            ],
            "the log node must be made durable BEFORE the superblock publishes \
             log_root; without the intervening sync an fsync that returned success \
             can lose its data (bd-sv7ql, same shape as bd-73bi2)"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn sync_superblock_free_totals_folds_from_sharded_when_active_bd_bhh0i() {
        // e2fsck-critical: after sharded creates, the PERSISTED superblock free-inode
        // count must fold from the sharded total_free (the single-lock groups are
        // stale), or it diverges from the sharded-updated group descriptors.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        fs.set_bhh0i_sharded_ops(true);

        let mut scope = RequestScope::empty();
        for i in 0..3u32 {
            let name = format!("f{i}");
            fs.ext4_create(&cx, &mut scope, root, name.as_bytes(), 0o644, 0, 0)
                .expect("routed sharded create");
        }
        let sharded_free_inodes = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .inodes;

        fs.ext4_sync_superblock_free_totals(&cx)
            .expect("superblock free-total sync");

        // Re-read the on-disk superblock free-inode count (offset 0x10 within the sb).
        let (sb_block, sb_off) = fs.ext4_superblock_location();
        let dev = fs.direct_block_device_adapter();
        let block = dev
            .read_block(&cx, sb_block)
            .expect("read superblock")
            .into_inner();
        let on_disk_free_inodes = u32::from_le_bytes([
            block[sb_off + 0x10],
            block[sb_off + 0x11],
            block[sb_off + 0x12],
            block[sb_off + 0x13],
        ]);

        assert_eq!(
            u64::from(on_disk_free_inodes),
            sharded_free_inodes,
            "synced superblock free-inode count must fold from the sharded total_free"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn flush_group_descriptors_from_sharded_persists_debited_counts_bd_bhh0i() {
        // e2fsck-critical (per-group): the deferred-GDT flush must source group
        // descriptors from the SHARDED records, not the stale single-lock groups. So
        // after sharded creates + flush, the summed on-disk GD free-inode count must
        // equal the sharded total (debited). Without the fix the flush would write
        // the stale FULL counts (the single-lock array is untouched by sharded
        // creates) → this sum would exceed the sharded total → e2fsck free-count wrong.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        fs.set_bhh0i_sharded_ops(true);

        let mut scope = RequestScope::empty();
        for i in 0..5u32 {
            let name = format!("g{i}");
            fs.ext4_create(&cx, &mut scope, root, name.as_bytes(), 0o644, 0, 0)
                .expect("routed sharded create");
        }
        let sharded_free_inodes = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .inodes;

        fs.ext4_flush_group_descriptors(&cx)
            .expect("deferred-GDT flush");

        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let geo = FsGeometry::from_superblock(sb);
        let pctx = fs.ext4_persist_ctx_lockfree().expect("persist ctx");
        let dev = fs.direct_block_device_adapter();
        let gdt = dev
            .read_block(&cx, pctx.gdt_block)
            .expect("read GDT block")
            .into_inner();
        let ds = usize::from(pctx.desc_size);
        let mut sum = 0_u64;
        for g in 0..geo.group_count as usize {
            let off = g * ds;
            let gd = ffs_ondisk::ext4::Ext4GroupDesc::parse_from_bytes(&gdt[off..], pctx.desc_size)
                .expect("parse group descriptor");
            sum += u64::from(gd.free_inodes_count);
        }
        assert_eq!(
            sum, sharded_free_inodes,
            "on-disk GD free-inode sum must equal the sharded total after flush"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn ext4_mkdir_sharded_creates_findable_dir_bd_bhh0i() {
        // Sharded mkdir (no write guard): the new directory must be findable, be a
        // valid S_IFDIR with links_count 2, and its own data block must carry a
        // well-formed '.'/'..' (proving the dir-block alloc + init + extent map +
        // inode write all went through the sharded path).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let parent_inode = fs.read_inode(&cx, root).expect("read root inode");
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let csum_seed = sb.csum_seed();

        fs.ext4_mkdir_sharded(
            &cx,
            root,
            &parent_inode,
            b"shardeddir",
            0o755,
            0,
            0,
            csum_seed,
            0,
            0,
        )
        .expect("sharded mkdir must succeed");

        let root_after = fs.read_inode(&cx, root).expect("re-read root inode");
        let entry = fs
            .lookup_name(&cx, &root_after, b"shardeddir")
            .expect("lookup must not error")
            .expect("sharded-created dir must be findable on disk");
        let created = fs
            .read_inode(&cx, InodeNumber(u64::from(entry.inode)))
            .expect("read created dir inode");
        assert_eq!(
            created.mode & 0xF000,
            0x4000,
            "created inode must be a directory (S_IFDIR)"
        );
        assert_eq!(created.links_count, 2, "new dir has '.' + parent links");

        // The new dir's own block carries '.' (→ itself) and '..' (→ parent).
        let dot = fs
            .lookup_name(&cx, &created, b".")
            .expect("lookup . ok")
            .expect("'.' present");
        assert_eq!(dot.inode, entry.inode, "'.' points to the dir itself");
        let dotdot = fs
            .lookup_name(&cx, &created, b"..")
            .expect("lookup .. ok")
            .expect("'..' present");
        assert_eq!(u64::from(dotdot.inode), root.0, "'..' points to the parent");
    }

