    fn ext4_create_sharded_creates_findable_file_bd_bhh0i() {
        // First END-TO-END sharded create: no write guard, inode via the sharded
        // allocator, dir entry via ShardedDirAlloc. The file must be findable via a
        // fresh on-disk lookup and be a valid regular inode, and the sharded
        // allocator must have debited exactly one inode.
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let parent_inode = fs.read_inode(&cx, root).expect("read root inode");
        let sb = fs.ext4_superblock().expect("ext4 superblock");
        let csum_seed = sb.csum_seed();
        let inodes_free_before = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under feature")
            .total_free()
            .inodes;

        fs.ext4_create_sharded(
            &cx,
            root,
            &parent_inode,
            b"shardedfile",
            0o644,
            0,
            0,
            csum_seed,
            0,
            0,
        )
        .expect("sharded create must succeed");

        // Findable via a fresh on-disk lookup (dir entry + inode both persisted).
        let root_after = fs.read_inode(&cx, root).expect("re-read root inode");
        let entry = fs
            .lookup_name(&cx, &root_after, b"shardedfile")
            .expect("lookup must not error")
            .expect("sharded-created file must be findable on disk");
        let created = fs
            .read_inode(&cx, InodeNumber(u64::from(entry.inode)))
            .expect("read created inode");
        assert_eq!(
            created.mode & 0xF000,
            0x8000,
            "created inode must be a regular file (S_IFREG)"
        );

        let inodes_free_after = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .inodes;
        assert_eq!(
            inodes_free_after,
            inodes_free_before - 1,
            "exactly one inode allocated through the sharded path"
        );
    }

    #[cfg(feature = "bhh0i_sharded_alloc")]
    #[test]
    fn ext4_sharded_free_inode_wrapper_round_trips_bd_bhh0i() {
        // Free is the rollback counterpart to alloc: allocating an inode then
        // freeing it through the lock-free wrapper must restore total_free().inodes
        // exactly (the sharded create path uses this to undo the inode alloc when a
        // subsequent dir-entry insert fails).
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(16) else {
            return;
        };
        let cx = Cx::for_testing();
        let dev = fs.block_device_adapter();
        let total_before = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present under feature")
            .total_free()
            .inodes;

        let alloc = fs
            .ext4_sharded_alloc_inode(&cx, &dev, GroupNumber(0), false)
            .expect("alloc must not error")
            .expect("alloc must find a free inode");
        let after_alloc = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .inodes;
        assert_eq!(
            after_alloc,
            total_before - 1,
            "alloc must debit total_free().inodes by 1"
        );

        fs.ext4_sharded_free_inode(&cx, &dev, alloc.ino, false)
            .expect("free_inode must not error");
        let after_free = fs
            .ext4_sharded_alloc
            .as_ref()
            .expect("sharded allocator present")
            .total_free()
            .inodes;
        assert_eq!(
            after_free, total_before,
            "free_inode must restore total_free().inodes to the pre-alloc value"
        );
    }

