    #[test]
    fn write_symlink_readlink_slow_path_ext4() {
        // A target longer than the inline capacity forces the SLOW symlink path:
        // the target is written to a data block and read back via read_file_data
        // (read_symlink's `inode.size`-bounded slow branch + NUL trim). The
        // existing roundtrip only exercises the fast/inline path.
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        let long_target = "/".to_string() + &"abcdefghijklmnopqrst/".repeat(6) + "final";
        assert!(
            long_target.len() > ffs_types::EXT4_FAST_SYMLINK_MAX,
            "target must exceed inline capacity ({} bytes) to hit the slow path",
            ffs_types::EXT4_FAST_SYMLINK_MAX
        );

        let attr = fs
            .symlink(
                &cx,
                root,
                OsStr::new("slow_sym"),
                Path::new(&long_target),
                0,
                0,
            )
            .expect("slow symlink create");
        assert_eq!(attr.kind, FileType::Symlink);

        let read_back = fs.readlink(&cx, attr.ino).expect("readlink slow");
        assert_eq!(
            read_back,
            long_target.as_bytes(),
            "slow symlink target must round-trip byte-identically"
        );
    }

    #[test]
    fn read_symlink_caps_slow_path_allocation_at_path_max() {
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let long_target = "/".to_string() + &"abcdefghijklmnopqrst/".repeat(6) + "final";
        let attr = fs
            .symlink(
                &cx,
                root,
                OsStr::new("slow_sym"),
                Path::new(&long_target),
                0,
                0,
            )
            .expect("slow symlink create");

        // Corrupt the inode size to a value that would drive a multi-terabyte
        // allocation in the uncapped slow path (bd-xmh5g.286).
        let mut inode = fs.read_inode(&cx, attr.ino).expect("read inode");
        inode.size = 1 << 40; // 1 TiB

        // read_symlink must cap the allocation at PATH_MAX, not the corrupt size,
        // so this returns a bounded target rather than OOM-ing.
        let target = fs
            .with_latest_scope(|scope| fs.read_symlink(&cx, scope, &inode))
            .expect("read_symlink");
        assert!(target.len() <= 4096, "got {} bytes", target.len());
        assert!(target.starts_with(b"/abcdefgh"));
    }

    #[test]
    fn write_symlink_readlink_rejects_encrypted_targets() {
        let Some(fs) = open_writable_ext4() else {
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let slow_target = "/var/lib/frankenfs/some/really/long/path/that/exceeds/sixty/bytes/for/slow/symlink-target.txt";

        let fast = fs
            .symlink(
                &cx,
                root,
                OsStr::new("enc_fast"),
                Path::new("hello.txt"),
                0,
                0,
            )
            .expect("create fast symlink");
        let slow = fs
            .symlink(
                &cx,
                root,
                OsStr::new("enc_slow"),
                Path::new(slow_target),
                0,
                0,
            )
            .expect("create slow symlink");

        for (label, ino) in [("fast", fast.ino), ("slow", slow.ino)] {
            let mut inode = fs.read_inode(&cx, ino).expect("read test symlink inode");
            inode.flags |= 0x0000_0800;
            persist_ext4_test_inode(&fs, &cx, ino, &inode);

            let err = fs
                .readlink(&cx, ino)
                .expect_err("encrypted symlink should require fscrypt context");
            assert!(
                matches!(err, FfsError::UnsupportedFeature(_)),
                "expected UnsupportedFeature for {label} symlink, got {err:?}"
            );
            assert_eq!(err.to_errno(), libc::EOPNOTSUPP);
        }
    }

