    #[test]
    fn btrfs_write_link_invalid_name_rolls_back_nlink() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("link_src.txt"),
                0o644,
                0,
                0,
            )
            .expect("create source");
        assert_eq!(attr.nlink, 1);

        let err = ops
            .link(
                &cx,
                &mut RequestScope::empty(),
                attr.ino,
                InodeNumber(1),
                OsStr::from_bytes(b"bad/link"),
            )
            .expect_err("link with slash should fail");
        assert!(matches!(err, FfsError::Format(_)));

        let updated = ops
            .getattr(&cx, &mut RequestScope::empty(), attr.ino)
            .expect("getattr after failed link");
        assert_eq!(updated.nlink, 1, "failed link must not bump nlink");

        let err = ops
            .link(
                &cx,
                &mut RequestScope::empty(),
                attr.ino,
                InodeNumber(1),
                OsStr::from_bytes(b"bad\0link"),
            )
            .expect_err("link with NUL should fail");
        assert!(matches!(err, FfsError::Format(_)));

        let updated = ops
            .getattr(&cx, &mut RequestScope::empty(), attr.ino)
            .expect("getattr after failed NUL-name link");
        assert_eq!(updated.nlink, 1, "failed link must not bump nlink");

        for name in [b".".as_slice(), b"..".as_slice()] {
            let err = ops
                .link(
                    &cx,
                    &mut RequestScope::empty(),
                    attr.ino,
                    InodeNumber(1),
                    OsStr::from_bytes(name),
                )
                .expect_err("link with reserved dot component should fail");
            assert!(matches!(err, FfsError::Format(_)));

            let updated = ops
                .getattr(&cx, &mut RequestScope::empty(), attr.ino)
                .expect("getattr after failed reserved-name link");
            assert_eq!(updated.nlink, 1, "failed link must not bump nlink");
        }
    }

