    #[test]
    fn btrfs_write_fallocate_punch_hole_with_zero_range_rejects_without_mutation() {
        let _guard = log_contract_guard();
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("ph_zr_conflict.bin"),
                0o644,
                0,
                0,
            )
            .unwrap();
        ops.write(
            &cx,
            &mut RequestScope::empty(),
            attr.ino,
            0,
            &[0xCD_u8; 4096],
        )
        .expect("seed file before invalid punch+zero mode");

        // PUNCH_HOLE | ZERO_RANGE is mutually exclusive -> EINVAL. Without the
        // guard, btrfs would fall into the shared punch_hole||zero_range branch
        // and silently run ZERO_RANGE logic instead of rejecting. KEEP_SIZE is
        // set so the punch-without-keep-size check does not fire first — this
        // isolates the mutual-exclusion guard.
        let err = ops
            .fallocate(
                &cx,
                &mut RequestScope::empty(),
                attr.ino,
                0,
                4096,
                libc::FALLOC_FL_PUNCH_HOLE | libc::FALLOC_FL_ZERO_RANGE | libc::FALLOC_FL_KEEP_SIZE,
            )
            .expect_err("PUNCH_HOLE | ZERO_RANGE should be rejected");
        assert_eq!(err.to_errno(), libc::EINVAL);

        // The seeded data must survive the rejected, side-effect-free call.
        let data = ops
            .read(&cx, &mut RequestScope::empty(), attr.ino, 0, 4096)
            .expect("read after reject");
        assert!(
            data.iter().all(|&b| b == 0xCD),
            "rejected fallocate must not have mutated the file"
        );
    }

    #[test]
    fn btrfs_write_fallocate_rejection_log_contract() {
        let _guard = log_contract_guard();
        let buffer = SharedLogBuffer::default();
        let _sub = install_json_subscriber(&buffer);
        let err = {
            let (fs, cx) = open_writable_btrfs();
            let ops: &dyn FsOps = &fs;

            let attr = ops
                .create(
                    &cx,
                    &mut RequestScope::empty(),
                    InodeNumber(1),
                    OsStr::new("reject_log.bin"),
                    0o644,
                    0,
                    0,
                )
                .expect("create file for rejection log test");

            // Mode 0x02 is PUNCH_HOLE. Without KEEP_SIZE (0x01), it should be rejected.
            ops.fallocate(&cx, &mut RequestScope::empty(), attr.ino, 0, 4096, 0x02)
                .expect_err("punch-hole without KEEP_SIZE should be rejected")
        };
        assert_eq!(err.to_errno(), libc::EINVAL);

        let logs = parse_json_logs(&buffer);
        let rejected = logs.iter().find(|entry| {
            entry.get("message").and_then(Value::as_str) == Some("btrfs_fallocate_rejected")
                && entry.get("error_class").and_then(Value::as_str)
                    == Some("invalid_punch_hole_mode")
        });
        assert!(
            rejected.is_some(),
            "expected btrfs_fallocate_rejected log for invalid punch-hole mode. Logs: {logs:?}"
        );
        let rejected = rejected.expect("btrfs_fallocate_rejected log must be present after assert");

        assert_eq!(
            rejected.get("outcome").and_then(Value::as_str),
            Some("rejected")
        );
    }

