    /// POSIX: renaming a file onto one of its own hard links (old and new
    /// resolve to the same inode via different names) is a no-op: vfs_rename
    /// short-circuits `if (source == target) return 0`, leaving both names and
    /// the link count untouched. btrfs_rename only guarded the same-*path* case,
    /// so it removed the source name and decremented nlink, silently destroying
    /// a hard link. Regression for bd-f7q6k.
    #[test]
    fn btrfs_rename_onto_own_hardlink_is_noop_keeps_both_names() {
        let (fs, cx) = open_writable_btrfs();
        let root = InodeNumber(u64::from(BTRFS_FIRST_FREE_OBJECTID));
        let a = fs
            .create(&cx, root, OsStr::new("a"), 0o644, 0, 0)
            .expect("create a");
        fs.link(&cx, a.ino, root, OsStr::new("b"))
            .expect("hard-link b -> a");
        assert_eq!(
            fs.lookup(&cx, root, OsStr::new("b"))
                .expect("b exists")
                .nlink,
            2,
            "precondition: a and b are two links to one inode"
        );

        // rename(a, b): a and b are the same inode -> POSIX no-op.
        fs.rename(&cx, root, OsStr::new("a"), root, OsStr::new("b"))
            .expect("same-inode rename must succeed as a no-op");

        let la = fs
            .lookup(&cx, root, OsStr::new("a"))
            .expect("a must still exist after a same-inode rename");
        let lb = fs
            .lookup(&cx, root, OsStr::new("b"))
            .expect("b must still exist after a same-inode rename");
        assert_eq!(la.ino, a.ino, "a still points at the original inode");
        assert_eq!(lb.ino, a.ino, "b still points at the original inode");
        assert_eq!(
            la.nlink, 2,
            "both hard links must survive a same-inode rename (no link destroyed)"
        );
    }

    /// Same POSIX same-inode no-op rule as the btrfs test, on ext4: renaming a
    /// file onto its own hard link must leave both names and the link count
    /// intact (bd-f7q6k). ext4_rename only guarded the same-path case.
    #[test]
    fn ext4_rename_onto_own_hardlink_is_noop_keeps_both_names() {
        let Some(fs) = open_writable_ext4() else {
            return; // no ext4 fixture / mkfs available
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);
        let a = fs
            .create(&cx, root, OsStr::new("hl_a"), 0o644, 0, 0)
            .expect("create hl_a");
        fs.link(&cx, a.ino, root, OsStr::new("hl_b"))
            .expect("hard-link hl_b -> hl_a");
        assert_eq!(
            fs.lookup(&cx, root, OsStr::new("hl_b"))
                .expect("hl_b exists")
                .nlink,
            2,
            "precondition: hl_a and hl_b are two links to one inode"
        );

        fs.rename(&cx, root, OsStr::new("hl_a"), root, OsStr::new("hl_b"))
            .expect("same-inode rename must succeed as a no-op");

        let la = fs
            .lookup(&cx, root, OsStr::new("hl_a"))
            .expect("hl_a must still exist after a same-inode rename");
        let lb = fs
            .lookup(&cx, root, OsStr::new("hl_b"))
            .expect("hl_b must still exist after a same-inode rename");
        assert_eq!(la.ino, a.ino);
        assert_eq!(lb.ino, a.ino);
        assert_eq!(
            la.nlink, 2,
            "both hard links must survive a same-inode rename"
        );
    }

    /// POSIX: adding a hard link is a status change for the TARGET inode, so its
    /// ctime must be marked for update (ext4_link does this via touch_ctime).
    /// btrfs routed through btrfs_adjust_nlink, which only bumped nlink — leaving
    /// the target ctime stale (bd-ypyxq). The link op stamps the target ctime and
    /// the parent's mtime from the SAME timestamp snapshot, so after a link they
    /// must be exactly equal (before the fix the target ctime stayed at its
    /// distinct creation time).
    #[test]
    fn btrfs_link_updates_target_ctime_bd_ypyxq() {
        let (fs, cx) = open_writable_btrfs();
        let root = InodeNumber(u64::from(BTRFS_FIRST_FREE_OBJECTID));
        let a = fs
            .create(&cx, root, OsStr::new("a"), 0o644, 0, 0)
            .expect("create a");
        fs.link(&cx, a.ino, root, OsStr::new("b"))
            .expect("hard-link b -> a");

        let target = fs.getattr(&cx, a.ino).expect("getattr target");
        let parent = fs.getattr(&cx, root).expect("getattr parent");
        assert_eq!(target.nlink, 2, "the link must have been added");
        assert_eq!(
            target.ctime, parent.mtime,
            "adding a hard link must stamp the target inode's ctime with the op time"
        );
    }

    /// Removing one of an inode's hard links is likewise a status change for the
    /// surviving inode: its ctime must be updated (ext4 does this on the
    /// surviving child). Pairs with btrfs_link_updates_target_ctime (bd-ypyxq).
    #[test]
    fn btrfs_link_removal_updates_surviving_inode_ctime_bd_ypyxq() {
        let (fs, cx) = open_writable_btrfs();
        let root = InodeNumber(u64::from(BTRFS_FIRST_FREE_OBJECTID));
        let a = fs
            .create(&cx, root, OsStr::new("keep"), 0o644, 0, 0)
            .expect("create keep");
        fs.link(&cx, a.ino, root, OsStr::new("drop"))
            .expect("hard-link drop -> keep");

        // Remove the "drop" name; the inode survives via "keep" (nlink 2 -> 1).
        fs.unlink(&cx, root, OsStr::new("drop"))
            .expect("remove the drop link");

        let survivor = fs.getattr(&cx, a.ino).expect("getattr survivor");
        let parent = fs.getattr(&cx, root).expect("getattr parent");
        assert_eq!(survivor.nlink, 1, "one link must remain");
        assert_eq!(
            survivor.ctime, parent.mtime,
            "removing a hard link must stamp the surviving inode's ctime"
        );
    }

    #[test]
    fn btrfs_rename_rejects_malformed_target_lookup_without_moving_source() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;
        let source_name = b"rename_source.txt";
        // The rename TARGET is the entry whose DIR_ITEM we corrupt. With the
        // hash-keyed lookup (bd-a9wot) a malformed entry only fails lookups of
        // its OWN name — matching the kernel, which never scans unrelated
        // entries — so the target lookup is what must fail closed, leaving the
        // (valid) source untouched.
        let broken_name = b"rename_broken_target.txt".as_slice();

        let source = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::from_bytes(source_name),
                0o644,
                0,
                0,
            )
            .expect("create rename source");
        ops.create(
            &cx,
            &mut RequestScope::empty(),
            InodeNumber(1),
            OsStr::from_bytes(broken_name),
            0o644,
            0,
            0,
        )
        .expect("create sibling with malformed DIR_ITEM");

        let root_oid = fs.btrfs_canonical_inode(InodeNumber(1)).unwrap();
        corrupt_btrfs_dir_item_payload(&fs, root_oid, broken_name, &[0xAA, 0xBB]);

        let err = ops
            .rename(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::from_bytes(source_name),
                InodeNumber(1),
                OsStr::from_bytes(broken_name),
            )
            .expect_err("rename to a malformed target must fail closed");
        // The corruption is surfaced by whichever preflight step first parses the
        // target's (now hash-keyed) DIR_ITEM bucket — insert-preflight,
        // same-inode check, or rename-target preflight — so the exact detail is
        // not pinned; what matters is that it fails closed with Corruption before
        // the source is removed (asserted below).
        assert!(
            matches!(err, FfsError::Corruption { .. }),
            "rename to a malformed target must fail closed with Corruption: {err:?}"
        );

        let source_key = BtrfsKey {
            objectid: root_oid,
            item_type: BTRFS_ITEM_DIR_ITEM,
            offset: u64::from(ffs_btrfs::btrfs_name_hash(source_name)),
        };
        let alloc_mutex = fs.require_btrfs_alloc_state().unwrap();
        let source_entries = alloc_mutex
            .read()
            .fs_tree
            .range(&source_key, &source_key)
            .expect("source dir item lookup");
        let parsed_source =
            parse_dir_items(&source_entries[0].1).expect("source dir item remains parseable");
        assert!(
            parsed_source
                .iter()
                .any(|entry| entry.name == source_name && entry.child_objectid == source.ino.0),
            "source entry should remain after failed rename: {parsed_source:?}"
        );
    }

    #[test]
    fn btrfs_write_hard_link_unlink_preserves_data() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("original.txt"),
                0o644,
                0,
                0,
            )
            .unwrap();
        ops.write(&cx, &mut RequestScope::empty(), attr.ino, 0, b"shared data")
            .unwrap();

        // Create a hard link.
        ops.link(
            &cx,
            &mut RequestScope::empty(),
            attr.ino,
            InodeNumber(1),
            OsStr::new("link.txt"),
        )
        .unwrap();
        let link_attr = ops
            .lookup(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("link.txt"),
            )
            .unwrap();
        assert_eq!(link_attr.nlink, 2);

        // Unlink the original — nlink goes to 1, inode should NOT be purged.
        ops.unlink(
            &cx,
            &mut RequestScope::empty(),
            InodeNumber(1),
            OsStr::new("original.txt"),
        )
        .unwrap();

        // The inode should still be accessible via the link.
        let after = ops
            .getattr(&cx, &mut RequestScope::empty(), attr.ino)
            .unwrap();
        assert_eq!(after.nlink, 1);
        let data = ops
            .read(&cx, &mut RequestScope::empty(), attr.ino, 0, 4096)
            .unwrap();
        assert_eq!(data, b"shared data");

        // Unlink the last reference — now it should be purged.
        ops.unlink(
            &cx,
            &mut RequestScope::empty(),
            InodeNumber(1),
            OsStr::new("link.txt"),
        )
        .unwrap();
        assert!(
            ops.getattr(&cx, &mut RequestScope::empty(), attr.ino)
                .is_err()
        );
    }

    #[test]
    fn btrfs_write_hard_links_same_parent_preserve_all_inode_refs() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("original.txt"),
                0o644,
                0,
                0,
            )
            .unwrap();
        ops.link(
            &cx,
            &mut RequestScope::empty(),
            attr.ino,
            InodeNumber(1),
            OsStr::new("link_a.txt"),
        )
        .unwrap();
        ops.link(
            &cx,
            &mut RequestScope::empty(),
            attr.ino,
            InodeNumber(1),
            OsStr::new("link_b.txt"),
        )
        .unwrap();

        let alloc = fs.btrfs_alloc_state.as_ref().unwrap().read();
        let ref_key = BtrfsKey {
            objectid: attr.ino.0,
            item_type: BTRFS_ITEM_INODE_REF,
            offset: 256,
        };
        let payload = alloc.fs_tree.range(&ref_key, &ref_key).unwrap();
        let refs = OpenFs::btrfs_parse_inode_ref_payload(&payload.first().unwrap().1).unwrap();
        drop(alloc);

        let mut names: Vec<_> = refs
            .iter()
            .map(|(_, name)| String::from_utf8_lossy(name).into_owned())
            .collect();
        names.sort();
        assert_eq!(names, vec!["link_a.txt", "link_b.txt", "original.txt"]);

        ops.unlink(
            &cx,
            &mut RequestScope::empty(),
            InodeNumber(1),
            OsStr::new("link_a.txt"),
        )
        .unwrap();

        let alloc = fs.btrfs_alloc_state.as_ref().unwrap().read();
        let payload = alloc.fs_tree.range(&ref_key, &ref_key).unwrap();
        let refs = OpenFs::btrfs_parse_inode_ref_payload(&payload.first().unwrap().1).unwrap();
        drop(alloc);

        let mut names: Vec<_> = refs
            .iter()
            .map(|(_, name)| String::from_utf8_lossy(name).into_owned())
            .collect();
        names.sort();
        assert_eq!(names, vec!["link_b.txt", "original.txt"]);
    }

    #[test]
    fn btrfs_write_hard_links_same_parent_readdir_shows_all_names() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("original.txt"),
                0o644,
                0,
                0,
            )
            .unwrap();
        ops.link(
            &cx,
            &mut RequestScope::empty(),
            attr.ino,
            InodeNumber(1),
            OsStr::new("link_a.txt"),
        )
        .unwrap();
        ops.link(
            &cx,
            &mut RequestScope::empty(),
            attr.ino,
            InodeNumber(1),
            OsStr::new("link_b.txt"),
        )
        .unwrap();

        let entries = ops
            .readdir(&cx, &mut RequestScope::empty(), InodeNumber(1), 0)
            .unwrap();
        let mut names: Vec<_> = entries
            .iter()
            .map(|entry| String::from_utf8_lossy(&entry.name).into_owned())
            .filter(|name| name != "." && name != "..")
            .collect();
        names.sort();
        assert!(
            names.contains(&"original.txt".to_string())
                && names.contains(&"link_a.txt".to_string())
                && names.contains(&"link_b.txt".to_string()),
            "expected all hard-link names in readdir, got: {names:?}"
        );

        ops.unlink(
            &cx,
            &mut RequestScope::empty(),
            InodeNumber(1),
            OsStr::new("link_a.txt"),
        )
        .unwrap();

        let entries = ops
            .readdir(&cx, &mut RequestScope::empty(), InodeNumber(1), 0)
            .unwrap();
        let mut names: Vec<_> = entries
            .iter()
            .map(|entry| String::from_utf8_lossy(&entry.name).into_owned())
            .filter(|name| name != "." && name != "..")
            .collect();
        names.sort();
        assert!(
            names.contains(&"original.txt".to_string())
                && names.contains(&"link_b.txt".to_string())
                && !names.contains(&"link_a.txt".to_string()),
            "expected surviving hard-link names after unlink, got: {names:?}"
        );
    }

    #[test]
    fn btrfs_write_unlink_missing_inode_ref_reports_corruption() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("missing_ref.txt"),
                0o644,
                0,
                0,
            )
            .unwrap();

        {
            let alloc_mutex = fs.btrfs_alloc_state.as_ref().unwrap();
            let mut alloc = alloc_mutex.write();
            let ref_key = BtrfsKey {
                objectid: attr.ino.0,
                item_type: BTRFS_ITEM_INODE_REF,
                offset: 256,
            };
            alloc
                .fs_tree
                .delete(&ref_key)
                .expect("delete inode_ref key");
        }

        let err = ops
            .unlink(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("missing_ref.txt"),
            )
            .unwrap_err();
        assert!(matches!(err, FfsError::Corruption { .. }));

        let looked_up = ops
            .lookup(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("missing_ref.txt"),
            )
            .expect("failed unlink must leave directory entry intact");
        assert_eq!(looked_up.ino, attr.ino);
    }

    #[test]
    fn btrfs_write_unlink_zero_nlink_reports_corruption() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("bad_nlink.txt"),
                0o644,
                0,
                0,
            )
            .unwrap();

        {
            let alloc_mutex = fs.btrfs_alloc_state.as_ref().unwrap();
            let mut alloc = alloc_mutex.write();
            let mut inode = fs
                .btrfs_read_inode_from_tree(&alloc, attr.ino.0)
                .expect("read child inode");
            inode.nlink = 0;
            let key = BtrfsKey {
                objectid: attr.ino.0,
                item_type: BTRFS_ITEM_INODE_ITEM,
                offset: 0,
            };
            alloc
                .fs_tree
                .update(&key, &inode.to_bytes())
                .expect("corrupt inode nlink");
        }

        let err = ops
            .unlink(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("bad_nlink.txt"),
            )
            .expect_err("unlink should fail on zero nlink corruption");
        assert!(matches!(err, FfsError::Corruption { .. }));

        let looked_up = ops
            .lookup(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("bad_nlink.txt"),
            )
            .expect("failed unlink must leave directory entry intact");
        assert_eq!(looked_up.ino, attr.ino);
    }

    #[test]
    fn btrfs_link_at_max_links_returns_emlink_without_mutation() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;

        let attr = ops
            .create(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("maxlink.bin"),
                0o644,
                0,
                0,
            )
            .unwrap();

        // Drive the inode's nlink up to the btrfs cap (BTRFS_LINK_MAX = 65535)
        // so the next link would exceed it. Injecting the count directly avoids
        // 65k real link() calls.
        {
            let alloc_mutex = fs.btrfs_alloc_state.as_ref().unwrap();
            let mut alloc = alloc_mutex.write();
            let mut inode = fs
                .btrfs_read_inode_from_tree(&alloc, attr.ino.0)
                .expect("read target inode");
            inode.nlink = 65_535;
            let key = BtrfsKey {
                objectid: attr.ino.0,
                item_type: BTRFS_ITEM_INODE_ITEM,
                offset: 0,
            };
            alloc
                .fs_tree
                .update(&key, &inode.to_bytes())
                .expect("pin nlink at the link cap");
        }

        let err = ops
            .link(
                &cx,
                &mut RequestScope::empty(),
                attr.ino,
                InodeNumber(1),
                OsStr::new("maxlink_overflow.bin"),
            )
            .expect_err("link at BTRFS_LINK_MAX must be rejected with EMLINK");
        assert_eq!(err.to_errno(), libc::EMLINK);

        // No partial mutation: the rejected link created no new directory entry
        // and left the link count unchanged.
        assert!(
            ops.lookup(
                &cx,
                &mut RequestScope::empty(),
                InodeNumber(1),
                OsStr::new("maxlink_overflow.bin"),
            )
            .is_err(),
            "rejected link must not create the new name"
        );
        let after = ops
            .getattr(&cx, &mut RequestScope::empty(), attr.ino)
            .expect("getattr after rejected link");
        assert_eq!(after.nlink, 65_535, "rejected link must not bump nlink");
    }

    #[test]
    fn btrfs_link_to_immutable_or_append_is_eperm_bd_69ich() {
        let (fs, cx) = open_writable_btrfs();
        let ops: &dyn FsOps = &fs;
        let parent = InodeNumber(1);

        // vfs_link forbids a hard link to an immutable OR append-only file
        // (EPERM). btrfs_link previously checked neither (bd-69ich).
        for (name, flag) in [
            ("imm.bin", BTRFS_INODE_IMMUTABLE),
            ("app.bin", BTRFS_INODE_APPEND),
        ] {
            let attr = ops
                .create(
                    &cx,
                    &mut RequestScope::empty(),
                    parent,
                    OsStr::new(name),
                    0o644,
                    0,
                    0,
                )
                .unwrap();
            {
                let alloc_mutex = fs.btrfs_alloc_state.as_ref().unwrap();
                let mut alloc = alloc_mutex.write();
                let mut inode = fs
                    .btrfs_read_inode_from_tree(&alloc, attr.ino.0)
                    .expect("read target inode");
                inode.flags |= flag;
                let key = BtrfsKey {
                    objectid: attr.ino.0,
                    item_type: BTRFS_ITEM_INODE_ITEM,
                    offset: 0,
                };
                alloc
                    .fs_tree
                    .update(&key, &inode.to_bytes())
                    .expect("pin attribute flag");
            }
            let link_name = format!("{name}.link");
            let err = ops
                .link(
                    &cx,
                    &mut RequestScope::empty(),
                    attr.ino,
                    parent,
                    OsStr::new(&link_name),
                )
                .expect_err("link to an immutable/append-only file must be rejected");
            assert_eq!(
                err.to_errno(),
                libc::EPERM,
                "{name} hard link must be EPERM"
            );
            // No partial mutation: the rejected link created no new name.
            assert!(
                ops.lookup(
                    &cx,
                    &mut RequestScope::empty(),
                    parent,
                    OsStr::new(&link_name)
                )
                .is_err(),
                "rejected link must not create the new name for {name}"
            );
        }
    }

