    #[test]
    fn mvcc_wal_replays_committed_data() {
        use ffs_mvcc::wal::{self, WalCommit, WalHeader, WalWrite};
        use ffs_types::{BlockNumber, CommitSeq, TxnId};

        // Build a WAL file with 2 commits.
        let tmp = tempfile::NamedTempFile::new().expect("create temp file");
        let wal_path = tmp.path().to_path_buf();
        {
            let header = WalHeader::default();
            let c1 = WalCommit {
                commit_seq: CommitSeq(1),
                txn_id: TxnId(1),
                writes: vec![WalWrite {
                    block: BlockNumber(10),
                    data: vec![0xAA; 16],
                }],
            };
            let c2 = WalCommit {
                commit_seq: CommitSeq(2),
                txn_id: TxnId(2),
                writes: vec![WalWrite {
                    block: BlockNumber(20),
                    data: vec![0xBB; 16],
                }],
            };
            let mut bytes = Vec::from(wal::encode_header(&header));
            bytes.extend_from_slice(&wal::encode_commit(&c1).unwrap());
            bytes.extend_from_slice(&wal::encode_commit(&c2).unwrap());
            std::fs::write(&wal_path, &bytes).expect("write WAL");
        }

        let image = build_ext4_image(1);
        let dev = TestDevice::from_vec(image);
        let cx = Cx::for_testing();
        let opts = OpenOptions {
            skip_validation: true,
            mvcc_wal_path: Some(wal_path),
            ..OpenOptions::default()
        };
        let fs = OpenFs::from_device(&cx, Box::new(dev), &opts).expect("open");

        // Verify recovery report.
        let report = fs.mvcc_wal_recovery().expect("should have recovery report");
        assert_eq!(report.commits_replayed, 2);
        assert_eq!(report.versions_replayed, 2);
        assert_eq!(report.records_discarded, 0);
        assert!(report.outcome.is_clean());

        // Verify replayed data is visible.
        let snap = fs.current_snapshot();
        let data10 = fs.mvcc_read_visible(BlockNumber(10), snap);
        let data20 = fs.mvcc_read_visible(BlockNumber(20), snap);
        let expected10 = [0xAA; 16];
        let expected20 = [0xBB; 16];
        assert_eq!(data10.as_deref(), Some(&expected10[..]));
        assert_eq!(data20.as_deref(), Some(&expected20[..]));
    }

    #[test]
    fn mvcc_wal_truncated_tail_tolerant_policy() {
        use ffs_mvcc::wal::{self, WalCommit, WalHeader, WalWrite};
        use ffs_types::{BlockNumber, CommitSeq, TxnId};

        let tmp = tempfile::NamedTempFile::new().expect("create temp file");
        let wal_path = tmp.path().to_path_buf();
        {
            let c1 = WalCommit {
                commit_seq: CommitSeq(1),
                txn_id: TxnId(1),
                writes: vec![WalWrite {
                    block: BlockNumber(1),
                    data: vec![1; 32],
                }],
            };
            let c2 = WalCommit {
                commit_seq: CommitSeq(2),
                txn_id: TxnId(2),
                writes: vec![WalWrite {
                    block: BlockNumber(2),
                    data: vec![2; 32],
                }],
            };
            let mut bytes = Vec::from(wal::encode_header(&WalHeader::default()));
            bytes.extend_from_slice(&wal::encode_commit(&c1).unwrap());
            bytes.extend_from_slice(&wal::encode_commit(&c2).unwrap());
            // Truncate last 10 bytes.
            bytes.truncate(bytes.len() - 10);
            std::fs::write(&wal_path, &bytes).expect("write WAL");
        }

        let image = build_ext4_image(1);
        let dev = TestDevice::from_vec(image);
        let cx = Cx::for_testing();
        let opts = OpenOptions {
            skip_validation: true,
            mvcc_wal_path: Some(wal_path),
            mvcc_replay_policy: ffs_mvcc::wal_replay::TailPolicy::TruncateToLastGood,
            ..OpenOptions::default()
        };
        let fs = OpenFs::from_device(&cx, Box::new(dev), &opts).expect("open");

        let report = fs.mvcc_wal_recovery().expect("should have recovery report");
        assert_eq!(report.commits_replayed, 1);
        assert_eq!(report.records_discarded, 1);
        assert!(!report.outcome.is_clean());
    }

    #[test]
    fn mvcc_wal_fail_fast_falls_back_to_empty_store() {
        use ffs_mvcc::wal::{self, WalCommit, WalHeader, WalWrite};
        use ffs_types::{BlockNumber, CommitSeq, TxnId};

        let tmp = tempfile::NamedTempFile::new().expect("create temp file");
        let wal_path = tmp.path().to_path_buf();
        {
            let c1 = WalCommit {
                commit_seq: CommitSeq(1),
                txn_id: TxnId(1),
                writes: vec![WalWrite {
                    block: BlockNumber(1),
                    data: vec![1; 32],
                }],
            };
            let mut bytes = Vec::from(wal::encode_header(&WalHeader::default()));
            bytes.extend_from_slice(&wal::encode_commit(&c1).unwrap());
            // Truncate to make it corrupt.
            bytes.truncate(bytes.len() - 5);
            std::fs::write(&wal_path, &bytes).expect("write WAL");
        }

        let image = build_ext4_image(1);
        let dev = TestDevice::from_vec(image);
        let cx = Cx::for_testing();
        let opts = OpenOptions {
            skip_validation: true,
            mvcc_wal_path: Some(wal_path),
            mvcc_replay_policy: ffs_mvcc::wal_replay::TailPolicy::FailFast,
            ..OpenOptions::default()
        };
        // Should NOT error — falls back to empty store.
        let fs = OpenFs::from_device(&cx, Box::new(dev), &opts).expect("open with FailFast");

        let report = fs.mvcc_wal_recovery().expect("should have recovery report");
        // Store is empty due to FailFast fallback.
        let snap = fs.current_snapshot();
        assert_eq!(fs.mvcc_version_count(), 0);
        assert!(fs.mvcc_read_visible(BlockNumber(1), snap).is_none());
        assert!(!report.outcome.is_clean());
    }

    /// Regression test: create enough files in a subdirectory to force a
    /// second directory block allocation, then verify all can be looked up
    /// and unlinked.  Uses `mkfs.ext4` for a realistic image.
    ///
    /// This exercises the checksum-tail initialisation fix for newly
    /// allocated directory blocks.  Without the fix, `parse_dir_block`
    /// misinterprets trailing zero bytes as an entry with
    /// `rec_len = block_size` (because `rec_len_from_disk(0, bs) = bs`),
    /// causing a "directory entry extends past block boundary" parse error
    /// that silently hides all entries in the new block.
    #[test]
    fn create_many_files_across_dir_block_boundary_mkfs() {
        let Some((fs, _tmp)) = open_writable_ext4_mkfs(64) else {
            eprintln!("mkfs.ext4 not available, skipping");
            return;
        };
        let cx = Cx::for_testing();
        let root = InodeNumber(2);

        let dir_attr = fs
            .mkdir(&cx, root, OsStr::new("bulk_dir"), 0o755, 0, 0)
            .expect("mkdir bulk_dir");

        let count = 250_u32;
        for i in 0..count {
            let name = format!("file_{i:04}.txt");
            let create_result = fs.create(&cx, dir_attr.ino, OsStr::new(&name), 0o644, 0, 0);
            assert!(create_result.is_ok(), "create {name}: {create_result:?}");
            let lookup_result = fs.lookup(&cx, dir_attr.ino, OsStr::new(&name));
            assert!(
                lookup_result.is_ok(),
                "lookup after create {name}: {lookup_result:?}"
            );
        }

        // Verify readdir returns all entries.
        let entries = fs.readdir(&cx, dir_attr.ino, 0).expect("readdir");
        let real = entries
            .iter()
            .filter(|e| e.name != b"." && e.name != b"..")
            .count();
        assert_eq!(
            real, count as usize,
            "readdir should see all {count} files, saw {real}"
        );

        for i in 0..count {
            let name = format!("file_{i:04}.txt");
            let lookup_result = fs.lookup(&cx, dir_attr.ino, OsStr::new(&name));
            assert!(lookup_result.is_ok(), "lookup {name}: {lookup_result:?}");
            let unlink_result = fs.unlink(&cx, dir_attr.ino, OsStr::new(&name));
            assert!(unlink_result.is_ok(), "unlink {name}: {unlink_result:?}");
        }
    }

